/*
 * The dashboard.
 *
 * Everything comes from api.php. Nothing here decides what may be seen: the
 * server sends masked names to a signed-out caller and never sends the real
 * ones, so there is nothing in this file to bypass.
 */

const API = "./api.php";

let reportingClientProblem = false;

function reportClientProblem(message, stack = "") {
  if (reportingClientProblem) return;
  reportingClientProblem = true;
  const body = new URLSearchParams({
    action: "client-problem",
    csrf: state?.csrf ?? "",
    message: String(message || "Unknown browser error").slice(0, 4000),
    stack: String(stack || "").slice(0, 4000),
  });
  fetch(API, {
    method: "POST",
    body,
    credentials: "same-origin",
    keepalive: true,
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
  }).catch(() => {}).finally(() => { reportingClientProblem = false; });
}

window.addEventListener("error", event => {
  reportClientProblem(event.message, event.error?.stack || `${event.filename}:${event.lineno}`);
});
window.addEventListener("unhandledrejection", event => {
  const reason = event.reason;
  reportClientProblem(reason?.message || reason, reason?.stack || "");
});

/**
 * The colours a chart draws its series in, in order.
 *
 * Up here rather than inside drawLineChart because the legend has to agree with
 * it. It used to be a local in the drawing code and the legend was three
 * hand-written spans with no colour on them at all, so every swatch came out
 * the inherited grey and matched nothing on the chart.
 */
/** How long a confirmation survives the refresh that its own action triggered. */
const NOTICE_KEEP_SECONDS = 10;

const SERIES_COLORS = ["#73b7ff", "#ffb86b", "#75d58a", "#d5a6ff", "#ff7f9f",
  "#50d3c4", "#f0cf63", "#9fb0ff", "#e98bc3", "#9ad26f"];
const seriesColor = i => SERIES_COLORS[i % SERIES_COLORS.length];

/** How often the page refreshes itself, awake and in live mode. */
const IDLE_POLL_MS = 30000;
const LIVE_POLL_MS = 10000;
/** While a scan is running, so its finishing is noticed promptly. */
const SCAN_POLL_MS = 5000;
const BUILD_POLL_MS = 60000;

/*
 * How soon to look again when something is expected and has not arrived.
 *
 * Short enough that a collector running a little late is picked up promptly,
 * long enough not to hammer the server while waiting for a job that may be
 * minutes away. Also the floor for the synchronised schedule - see pollInterval.
 */
const CATCHUP_POLL_MS = 5000;

/*
 * The longest this will ever sleep between requests.
 *
 * Only reached when both collectors run on very long intervals. Alerts, a
 * finished scan and a signed-out session all change without either of them
 * writing a reading, so the page still looks up from time to time.
 */
const MAX_POLL_MS = 10 * 60 * 1000;

/*
 * The pause after a collector is due before asking for its result.
 *
 * A reading written at the top of the minute is not in the database until the
 * collector has finished writing it, and asking at the exact due moment reliably
 * fetches the previous one - then waits a whole interval to notice.
 */
const POLL_GRACE_SECONDS = 2;

const state = {
  signedIn: false,
  csrf: null,
  access: null,
  // Which account this runs as, so the process lists can mark its own rows.
  account: null,
  range: 86400,
  capabilities: null,
  view: "overview",
  rendered: new Set(),
  frozenAt: null,
  overview: null,
  live: false,
  timer: null,
  historyPathId: null,
  deletable: [],
  viewable: [],
  scanRunning: false,
  categories: [],
  log: { pathId: null, page: 0, needle: "" },
  schedule: null,
  scheduleDirty: false,
  units: "bytes",
  uptime: null,
  totals: {},
  emptied: {},
  noticeAt: 0,
  noticeOk: false,
  restarts: [],
  hostMetric: "pss",
  hostCharted: [],
  busy: false,
};

const BUILD_IDENTITY_STORAGE_KEY = "zogograph.build.identity";
const BUILD_UPDATE_STORAGE_KEY = "zogograph.build.update";
const buildState = { current: null, announced: null, update: null, checking: false };
const disabledCoreRoutes = new Set();

const $ = id => document.getElementById(id);
const escapeRegex = text => String(text).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/*
 * Screenshot privacy is a browser-session view, not an access-control layer:
 * the API still withholds IPs where it can. This catches addresses embedded in
 * free prose, chart labels, and a future view that forgot to use a structured
 * address field. It only runs when the user deliberately enters privacy mode,
 * so ordinary polling never disturbs selection or scroll position.
 */
const IPV4_TEXT = /(?<![\w.])(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}(?![\w.])/g;
/* A clock such as 12:34:56 is not IPv6. Full addresses have 3+ colons;
 * shorter valid forms necessarily carry ::. */
const IPV6_TEXT = /(?<![A-Fa-f0-9:])(?:(?:[A-Fa-f0-9]{1,4}:){3,7}[A-Fa-f0-9]{0,4}|(?:[A-Fa-f0-9]{1,4}:){0,6}[A-Fa-f0-9]{0,4}::(?:[A-Fa-f0-9]{1,4}:){0,5}[A-Fa-f0-9]{0,4})(?![A-Fa-f0-9:])/g;
const IP_HOST_TEXT = /(?<![\w.-])(?:(?:[A-Za-z][\w-]*-)?(?:\d{1,3}[-.]){3}\d{1,3})(?:\.[A-Za-z][\w-]*)+(?![\w.-])/g;
let ipPrivacyObserver = null;
let accountPrivacyObserver = null;

function redactIpText(text) {
  return text.replace(IP_HOST_TEXT, "[IP host hidden]")
    .replace(IPV4_TEXT, "[IP hidden]").replace(IPV6_TEXT, "[IP hidden]");
}

function redactIpNodes(root) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) {
    const parent = walker.currentNode.parentElement;
    if (parent && !["SCRIPT", "STYLE", "TEXTAREA", "OPTION"].includes(parent.tagName)) {
      nodes.push(walker.currentNode);
    }
  }
  for (const node of nodes) {
    const redacted = redactIpText(node.data);
    if (redacted !== node.data) node.data = redacted;
  }
}

function syncIpPrivacy() {
  if (!state.access?.ip_privacy || ipPrivacyObserver) return;
  redactIpNodes(document.body);
  ipPrivacyObserver = new MutationObserver(records => {
    for (const record of records) {
      for (const node of record.addedNodes) {
        if (node.nodeType === Node.TEXT_NODE) {
          node.data = redactIpText(node.data);
        } else if (node.nodeType === Node.ELEMENT_NODE) {
          redactIpNodes(node);
        }
      }
    }
  });
  ipPrivacyObserver.observe(document.body, { childList: true, subtree: true });
}

/* Account privacy is presentation-only, like IP privacy. Structured rows and
 * paths already carry richer treatment; this catches prose, labels, and future
 * surfaces that otherwise forget the choice. */
function redactAccountNodes(root) {
  const account = state.account;
  /* Mutation records can retain a text node after its parent was replaced by
   * this very redactor. A detached text node has no parentElement; do not hand
   * that null through to createTreeWalker on the next observer turn. */
  if (!account || !(root instanceof Node)) return;
  const token = new RegExp(`\\b(${escapeRegex(account)}|root)\\b`, "g");
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) {
    const parent = walker.currentNode.parentElement;
    if (parent && !["SCRIPT", "STYLE", "TEXTAREA", "OPTION"].includes(parent.tagName)
      && !parent.closest(".user-me, .user-root")) nodes.push(walker.currentNode);
  }
  for (const node of nodes) {
    const source = node.data;
    token.lastIndex = 0;
    if (!token.test(source)) continue;
    const fragment = document.createDocumentFragment();
    let at = 0;
    token.lastIndex = 0;
    let match;
    while ((match = token.exec(source))) {
      fragment.append(source.slice(at, match.index));
      const span = document.createElement("span");
      const mine = match[1] === account;
      span.className = mine ? "user-me" : "user-root";
      span.title = mine ? "This account — the one this dashboard runs as." : "root";
      span.textContent = mine && state.access?.account_privacy ? "[self]" : match[1];
      fragment.append(span);
      at = match.index + match[0].length;
    }
    fragment.append(source.slice(at));
    node.replaceWith(fragment);
  }
}

function syncAccountPrivacy() {
  if (!state.account || accountPrivacyObserver) return;
  redactAccountNodes(document.body);
  accountPrivacyObserver = new MutationObserver(records => {
    for (const record of records) {
      for (const node of record.addedNodes) {
        if (node.nodeType === Node.TEXT_NODE) redactAccountNodes(node.parentElement);
        else if (node.nodeType === Node.ELEMENT_NODE) redactAccountNodes(node);
      }
    }
  });
  accountPrivacyObserver.observe(document.body, { childList: true, subtree: true });
}

/* ----------------------------------------------------------------- format -- */

function humanBytes(value, digits) {
  if (value == null || !Number.isFinite(Number(value))) return "—";
  let n = Number(value);
  const sign = n < 0 ? "-" : "";
  n = Math.abs(n);
  const units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
  let i = 0;
  while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
  const places = digits ?? (i === 0 ? 0 : n >= 100 ? 0 : n >= 10 ? 1 : 2);
  const localized = new Intl.NumberFormat(document.documentElement.lang || undefined, {
    minimumFractionDigits: places,
    maximumFractionDigits: places,
  }).format(n);
  return `${sign}${localized} ${units[i]}`;
}

function humanCount(value) {
  if (value == null || !Number.isFinite(Number(value))) return "—";
  return new Intl.NumberFormat(document.documentElement.lang || undefined).format(Number(value));
}

/**
 * A length of time as at most two parts.
 *
 * "3411 days" is arithmetically correct and unreadable - nobody carries a
 * sense of how long three thousand days is, and everybody knows what nine
 * years is. The units follow the size: years and months for a decade, weeks
 * and days for a fortnight. Two parts, never three: the third is noise, and
 * anybody who cares about the exact day is reading a date, not a span.
 *
 * The twin of plainSpan() in lib/spans.php. Both exist because some of these
 * spans are written into alert emails by the cron, which has no browser.
 */
const SPAN_MINUTE = 60;
const SPAN_HOUR = 3600;
const SPAN_DAY = 86400;
const SPAN_WEEK = 604800;
// The average kind of month and year. Wrong for any particular span and right
// for describing one - "9y 4m" is not a claim about which day.
const SPAN_MONTH = 2629746;
const SPAN_YEAR = 31556952;

function humanSpanUnit(value, unit, long) {
  return new Intl.NumberFormat(document.documentElement.lang || undefined, {
    style: "unit",
    unit,
    unitDisplay: long ? "long" : "short",
  }).format(value);
}

function humanSpan(seconds, long = false) {
  if (!Number.isFinite(seconds)) return "—";
  const total = Math.round(Math.abs(seconds));
  if (total < 1) return humanSpanUnit(0, "second", long);

  // Threshold, the unit at that size, and the unit that fills the second slot.
  const ladder = [
    [SPAN_YEAR, SPAN_YEAR, SPAN_MONTH, "year", "month"],
    [2 * SPAN_MONTH, SPAN_MONTH, SPAN_DAY, "month", "day"],
    [SPAN_WEEK, SPAN_WEEK, SPAN_DAY, "week", "day"],
    [SPAN_DAY, SPAN_DAY, SPAN_HOUR, "day", "hour"],
    [SPAN_HOUR, SPAN_HOUR, SPAN_MINUTE, "hour", "minute"],
    [SPAN_MINUTE, SPAN_MINUTE, 1, "minute", "second"],
  ];

  for (const [at, big, small, bigUnit, smallUnit] of ladder) {
    if (total < at) continue;

    const whole = Math.floor(total / big);
    const rest = Math.floor((total % big) / small);
    const said = humanSpanUnit(whole, bigUnit, long);
    return rest > 0 ? `${said} ${humanSpanUnit(rest, smallUnit, long)}` : said;
  }

  return humanSpanUnit(total, "second", long);
}

/** The same span with its direction said out loud, because a minus sign is missable. */
function humanWhen(seconds, long = false) {
  if (!Number.isFinite(seconds)) return "—";
  const magnitude = Math.abs(seconds);
  const [unit, divisor] = magnitude >= SPAN_YEAR
    ? ["year", SPAN_YEAR]
    : magnitude >= SPAN_MONTH
      ? ["month", SPAN_MONTH]
      : magnitude >= SPAN_WEEK
        ? ["week", SPAN_WEEK]
        : magnitude >= SPAN_DAY
          ? ["day", SPAN_DAY]
          : magnitude >= SPAN_HOUR
            ? ["hour", SPAN_HOUR]
            : magnitude >= SPAN_MINUTE
              ? ["minute", SPAN_MINUTE]
              : ["second", 1];
  return new Intl.RelativeTimeFormat(document.documentElement.lang || undefined, {
    numeric: "auto",
    style: long ? "long" : "short",
  }).format(Math.round(seconds / divisor), unit);
}

function humanDuration(seconds) {
  if (!Number.isFinite(seconds) || seconds < 0) return "—";
  const [value, unit] = seconds < 90
    ? [Math.round(seconds), "second"]
    : seconds < 5400
      ? [Math.round(seconds / 60), "minute"]
      : seconds < 172800
        ? [Number((seconds / 3600).toFixed(1)), "hour"]
        : [Number((seconds / 86400).toFixed(1)), "day"];
  return ZogographI18n.t(
    "duration.value",
    { value, valueUnit: unit, valueUnitDisplay: "short" },
    "{{value, unit}}",
  );
}

function humanTime(epoch) {
  if (!epoch) return "—";
  return new Date(epoch * 1000).toLocaleString(document.documentElement.lang || undefined);
}

/**
 * A moment, written with only the parts that are not obvious.
 *
 * Four forms, because the year is noise on something that happened this morning
 * and essential on something from two years ago:
 *
 *   today            14:23
 *   within a week    Tue 14:23
 *   within a year    25 Aug 14:23
 *   older            25 Aug 2024 14:23
 *
 * No seconds anywhere. A second is never the thing being decided on when
 * looking down a column of events, and six extra characters on every row is
 * what pushes a table into overlapping its neighbour - which is how this got
 * reported.
 *
 * Boundaries are calendar boundaries, not multiples of 86400: something at
 * 23:58 last night is yesterday, not "today, twenty minutes ago".
 */
function whenLabel(epoch) {
  if (!epoch) return "—";

  const at = new Date(epoch * 1000);
  const now = new Date();

  const midnight = new Date(now);
  midnight.setHours(0, 0, 0, 0);

  const clock = at.toLocaleTimeString(document.documentElement.lang || undefined, { hour: "2-digit", minute: "2-digit" });

  if (at >= midnight) return clock;

  const weekAgo = new Date(midnight);
  weekAgo.setDate(weekAgo.getDate() - 6);

  if (at >= weekAgo) {
    return `${at.toLocaleDateString(document.documentElement.lang || undefined, { weekday: "short" })} ${clock}`;
  }

  const day = at.toLocaleDateString(document.documentElement.lang || undefined, { day: "numeric", month: "short" });

  return at.getFullYear() === now.getFullYear()
    ? `${day} ${clock}`
    : `${day} ${at.getFullYear()} ${clock}`;
}

/**
 * Two moments, written with the same granularity.
 *
 * whenLabel drops whatever is obvious from context, which is right for a single
 * moment in a column and wrong for the two ends of a range: "Aug 19 12:38 AM to
 * 12:38 AM" is what happens when one end is old enough to need a date and the
 * other is not. Both ends take the longer of the two forms.
 */
function whenRange(from, to) {
  const a = whenLabel(from);
  const b = whenLabel(to);
  const fromDate = new Date(from * 1000);
  const toDate = new Date(to * 1000);

  // A translated label's length says nothing about how much calendar detail it
  // contains. Keep the compact form only when both values are on one local day.
  if (fromDate.toDateString() === toDate.toDateString()) {
    return `${a} ${ZogographI18n.t("time.range_to", {}, "to")} ${b}`;
  }

  const wordy = at => {
    const when = new Date(at * 1000);
    const day = when.toLocaleDateString(document.documentElement.lang || undefined, { day: "numeric", month: "short" });
    const clock = when.toLocaleTimeString(document.documentElement.lang || undefined, { hour: "2-digit", minute: "2-digit" });
    return when.getFullYear() === new Date().getFullYear()
      ? `${day} ${clock}`
      : `${day} ${when.getFullYear()} ${clock}`;
  };

  return `${wordy(from)} ${ZogographI18n.t("time.range_to", {}, "to")} ${wordy(to)}`;
}

/**
 * Everything about a moment, for a tooltip.
 *
 * Three forms, because the three are wanted by three different people: the
 * local string for a human, the ISO string for pasting into anything else, and
 * the epoch second for a query. Having to convert between them by hand is a
 * small tax paid over and over.
 */
function whenTitle(epoch) {
  if (!epoch) return "";

  const at = new Date(epoch * 1000);

  return [
    at.toLocaleString(),
    at.toISOString(),
    `${epoch}`,
  ].join("\n");
}

/**
 * A span of text showing a moment, with the full detail on hover.
 *
 * Returns an element rather than a string, because the tooltip is half the
 * point and a string cannot carry one.
 */
function whenSpan(epoch) {
  const span = document.createElement("span");
  span.className = "when";
  span.textContent = whenLabel(epoch);
  return withWhenBubble(span, epoch);
}

/**
 * Everything about a moment, as a small table.
 *
 * A `title` was doing this, which is to say it appeared after about a second
 * and then only as one run of text. A second is long enough for somebody to
 * decide nothing is going to happen. This shows on contact, and since it is
 * built rather than concatenated it can lay the formats out as names and
 * values instead of three lines the reader has to work out for themselves.
 *
 * How long ago is first, because it is the question the other four are being
 * consulted to answer.
 */
function whenBubble(epoch) {
  const at = new Date(epoch * 1000);
  const now = Date.now() / 1000;

  const table = document.createElement("table");
  table.className = "when-detail";
  table.dataset.helpKey = `when:${epoch}`;

  const rows = [
    [
      epoch > now ? "From now" : "Ago",
      humanSpan(Math.abs(now - epoch)),
    ],
    ["Local", at.toLocaleString()],
    ["Date", at.toLocaleDateString(undefined, {
      weekday: "long", day: "numeric", month: "long", year: "numeric",
    })],
    ["Time", at.toLocaleTimeString()],
    ["ISO", at.toISOString()],
    ["Unix", String(epoch)],
  ];

  const body = table.createTBody();
  for (const [name, value] of rows) {
    const row = body.insertRow();

    const label = row.insertCell();
    label.className = "when-name";
    label.textContent = name;

    const said = row.insertCell();
    // Monospace for the two that get copied into something else, so a digit
    // can be counted rather than guessed at.
    said.className = ["ISO", "Unix"].includes(name) ? "when-value cmd" : "when-value";
    said.textContent = value;
  }

  return table;
}

/**
 * Attaches the rich bubble to anything showing a moment.
 *
 * Kept separate from whenSpan because dates are drawn in a dozen places that
 * build their own element - a billing row, a chart caption - and every one of
 * them should behave the same way when pointed at.
 */
function withWhenBubble(element, epoch) {
  if (!epoch) return element;

  const key = `when:${epoch}`;
  const build = () => whenBubble(epoch);

  /*
   * No `title` alongside it.
   *
   * The browser's own tooltip would arrive a second later and sit on top of
   * this one saying the same thing in a worse format. The accessible name
   * carries the detail instead, which is what a screen reader reads anyway.
   */
  element.setAttribute("aria-label", `${whenLabel(epoch)} — ${whenTitle(epoch).replace(/\n/g, ", ")}`);
  element.tabIndex = 0;

  element.addEventListener("pointerenter", () => {
    if (helpBubble?.dataset.pinned !== "yes") showHelp(element, build(), false);
  });
  element.addEventListener("pointerleave", () => {
    if (helpBubble?.dataset.pinned !== "yes") hideHelp();
  });
  element.addEventListener("focus", () => showHelp(element, build(), false));
  element.addEventListener("blur", () => {
    if (helpBubble?.dataset.pinned !== "yes") hideHelp();
  });

  element.addEventListener("click", event => {
    event.stopPropagation();
    const open = helpBubble && !helpBubble.hidden && helpBubble.dataset.pinned === "yes";
    if (open && helpBubble.dataset.key === key) hideHelp();
    else showHelp(element, build(), true);
  });

  return element;
}


function ago(epoch) {
  if (!epoch) return "";
  return `${humanDuration(Date.now() / 1000 - epoch)} ago`;
}

/* -------------------------------------------------------------------- api -- */

async function api(action, params = {}) {
  /*
   * Accepts a plain object or a URLSearchParams.
   *
   * Spreading URLSearchParams into an object literal yields nothing - it has no
   * own enumerable properties - so a caller passing one would silently send a
   * bare action and get an answer to a different question. Repeated keys, which
   * `names[]` needs, are only expressible the second way.
   */
  const query = params instanceof URLSearchParams
    ? params
    : new URLSearchParams(params);
  query.set("action", action);
  const response = await fetch(`${API}?${query}`, {
    cache: "no-store",
    credentials: "same-origin",
  });
  const body = await response.json().catch(() => ({
    error: `The server returned ${response.status} with something that is not JSON.`,
  }));
  if (!response.ok) throw new Error(withReference(body, response.status));
  return body;
}

async function post(action, fields = {}) {
  const body = new URLSearchParams({ action, csrf: state.csrf ?? "", ...fields });
  const response = await fetch(API, {
    method: "POST",
    body,
    credentials: "same-origin",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
  });
  const parsed = await response.json().catch(() => ({
    error: `The server returned ${response.status} with something that is not JSON.`,
  }));
  if (!response.ok) throw new Error(withReference(parsed, response.status));
  return parsed;
}

async function postForm(action, form) {
  form.set("action", action); form.set("csrf", state.csrf ?? "");
  const response = await fetch(API, { method: "POST", body: form, credentials: "same-origin" });
  const parsed = await response.json().catch(() => ({ error: `The server returned ${response.status} with something that is not JSON.` }));
  if (!response.ok) throw new Error(withReference(parsed, response.status));
  return parsed;
}

/**
 * The message to show for a failed request.
 *
 * The reference is the point of it. The server will not put the real error in a
 * response - it names paths and sometimes SQL - so the reference is what ties
 * what you saw on screen to the entry in the problem log.
 */
function withReference(body, status) {
  const parts = [body.error || `HTTP ${status}`];
  if (body.reference) parts.push(`(reference ${body.reference})`);
  return parts.join(" ");
}

function notice(message, ok = false) {
  const el = $("notice");
  el.textContent = message ?? "";
  el.className = ok ? "ok" : "";
  // Remembered so a refresh can tell a confirmation it should leave alone from
  // a stale error it should tidy away.
  state.noticeAt = message ? Math.floor(Date.now() / 1000) : 0;
  state.noticeOk = Boolean(message) && ok;
}

/**
 * Clears the notice after a refresh, but not one that just said something.
 *
 * Every action that changes anything finishes by refreshing, and the refresh
 * used to end by blanking the notice - so "Deleted 8.58 MiB." was wiped by the
 * reload it had itself started, and deleting a file gave no confirmation at
 * all. The message it replaced was the whole feedback for the action.
 *
 * Errors are still cleared: a failure that has since been fixed should not stay
 * on screen. A success is kept briefly and then goes on its own.
 */
function clearStaleNotice() {
  const age = Math.floor(Date.now() / 1000) - (state.noticeAt || 0);
  if (state.noticeOk && age < NOTICE_KEEP_SECONDS) {
    return;
  }
  notice("");
}

/* ----------------------------------------------------------- application -- */

function buildIdentity(build) {
  return [build?.commit, build?.runId, build?.createdAt].filter(Boolean).join(":");
}

function buildStorageGet(key) {
  try { return sessionStorage.getItem(key); } catch { return null; }
}

function buildStorageSet(key, value) {
  try { sessionStorage.setItem(key, value); } catch { /* Storage is optional. */ }
}

function buildStorageRemove(key) {
  try { sessionStorage.removeItem(key); } catch { /* Storage is optional. */ }
}

function rememberedBuildUpdate() {
  try {
    const saved = JSON.parse(buildStorageGet(BUILD_UPDATE_STORAGE_KEY) || "null");
    return saved && typeof saved === "object" && buildIdentity(saved.build) === saved.identity ? saved.build : null;
  } catch { return null; }
}

function rememberBuildUpdate(build) {
  const identity = buildIdentity(build);
  if (identity) buildStorageSet(BUILD_UPDATE_STORAGE_KEY, JSON.stringify({ identity, build }));
}

function showBuildUpdate(build) {
  const banner = $("updateBanner");
  if (!banner) return;
  const required = build.browserRefreshRequired === true;
  const message = required
    ? ZogographI18n.t("update.compatibility", {}, "A compatibility update is ready. Reload before continuing so this browser uses the matching dashboard.")
    : ZogographI18n.t("update.available", {}, "A newer Zogograph update is available. Reload when you want to see it.");
  banner.replaceChildren();
  const text = document.createElement("span"); text.textContent = message;
  const reload = document.createElement("button"); reload.type = "button"; reload.textContent = ZogographI18n.t("action.reload", {}, "Reload now");
  reload.addEventListener("click", () => {
    buildStorageSet(BUILD_IDENTITY_STORAGE_KEY, buildIdentity(build));
    buildStorageRemove(BUILD_UPDATE_STORAGE_KEY);
    location.reload();
  });
  banner.append(text, reload);
  banner.hidden = false;
}

async function checkForBuildUpdate() {
  if (document.hidden || buildState.checking) return;
  buildState.checking = true;
  try {
    const response = await fetch(`./build.json?at=${Date.now()}`, {
      cache: "no-store", credentials: "same-origin",
    });
    if (!response.ok) return;
    const build = await response.json();
    const identity = buildIdentity(build);
    if (!identity) return;
    if (buildState.current === null) {
      buildState.current = identity;
      buildStorageSet(BUILD_IDENTITY_STORAGE_KEY, identity);
      return;
    }
    if (buildState.current !== identity && buildState.announced !== identity) {
      buildState.announced = identity;
      buildState.update = build;
      rememberBuildUpdate(build);
      showBuildUpdate(build);
    }
  } catch {
    // Deployment metadata is optional and must never interrupt monitoring.
  } finally {
    buildState.checking = false;
  }
}

/* ------------------------------------------------------------------ cards -- */

function setCard(id, value, sub, level = "") {
  const card = $(id);
  // The gauges took several of these over, and a caller that still computes a
  // figure for one is not a fault - it is just no longer drawn here.
  if (!card) return;
  card.querySelector(".value").textContent = value;
  card.querySelector(".sub").textContent = sub ?? "";
  card.className = `card ${level}`.trim();
}

/*
 * The dials at the top of the landing page.
 *
 * Everything here is already in the cards below, and that is the point: a card
 * is a number you have to know the thresholds for, and an arc is a position you
 * can read from across the room. Somebody opening this at eight in the morning
 * wants "is anything red", not eight figures to compare against remembered
 * limits.
 *
 * Each gauge names its band as well as colouring it. Red and green are the same
 * shape to a colour-blind reader, and this is the one screen where the whole
 * message is carried by the colour.
 */
function bandOf(value, warn, crit) {
  if (value == null || !Number.isFinite(value)) return null;
  return value >= crit ? "crit" : value >= warn ? "warn" : "ok";
}

const BAND_COLOR = { ok: "#56c98a", warn: "#f0a35e", crit: "#f2616b" };

function gaugeBandWord(band) {
  return ZogographI18n.t(`gauge.band_${band}`, {}, ({
    ok: "healthy", warn: "watch", crit: "urgent",
  })[band]);
}

/*
 * The processor, from the same host reading the memory page uses.
 *
 * Two figures that answer different questions and are constantly conflated:
 * how busy the machine is, and how much of its own allowance this account is
 * using. Inside CageFS the second can sit at the ceiling while the first is
 * idle, which is not a contradiction - it is what being throttled looks like.
 */
/* -------------------------------------------------------------- processor -- */

/*
 * The five pages under CPU, from one reading.
 *
 * They exist because "the processor is at 90%" is where an investigation used
 * to start and also where it stopped. That one number is the same for a machine
 * compiling something, a machine waiting on a failing disk, a machine drowning
 * in network interrupts, and a machine whose hypervisor has taken the cores
 * away - four situations with nothing in common but the reading, and four
 * different things to do about them.
 *
 * One request feeds all five, the same way one host reading feeds the memory
 * pages: the differencing is the expensive part and doing it once is the
 * difference between five polls a minute and one.
 */
const CPU_PANELS = ["cpuPanel", "cpuTimePanel", "cpuCoresPanel", "cpuProcsPanel",
  "cpuQueuePanel", "cpuLimitsPanel"];
const CPU_BODIES = ["cpuBody", "cpuTimeBody", "cpuCoresBody", "cpuProcsBody",
  "cpuQueueBody", "cpuLimitsBody"];
const CPU_CONTENTS = ["cpuContent", "cpuTimeContent", "cpuCoresContent", "cpuProcsContent",
  "cpuQueueContent", "cpuLimitsContent"];

async function refreshCpu() {
  if (!WHAT_IS.loaded) await loadWhatIs();

  for (const id of CPU_BODIES) {
    const el = $(id);
    if (el && !el.childElementCount) el.replaceChildren(spinner(ZogographI18n.t("cpu.reading_collector", {}, "Reading the host collector…")));
  }

  const show = hidden => CPU_CONTENTS.forEach(id => { const el = $(id); if (el) el.hidden = hidden; });
  const sayAll = text => CPU_BODIES.forEach(id => {
    const el = $(id);
    if (el) el.replaceChildren(Object.assign(document.createElement("p"),
      { className: "muted", textContent: text }));
  });

  if (!state.signedIn) {
    for (const id of CPU_PANELS) {
      const el = $(id);
      if (el) el.hidden = true;
    }
    return;
  }
  for (const id of CPU_PANELS) {
    const el = $(id);
    if (el) el.hidden = false;
  }

  let data;
  try {
    const to = Math.floor(Date.now() / 1000);
    data = await api("cpu", { from: to - state.range, to });
  } catch (error) {
    sayAll(String(error.message || error));
    show(true);
    return;
  }

  if (!data.available) {
    sayAll(data.reason || ZogographI18n.t("cpu.no_host_readings", {}, "No host readings."));
    // The instruction goes on the page somebody is most likely to have opened
    // first, once, rather than five times down the sidebar.
    collectorInstructions($("cpuBody"), data);
    show(true);
    return;
  }

  CPU_BODIES.forEach(id => { const el = $(id); if (el) el.textContent = ""; });
  show(false);

  renderCoreCardPackage(ZogographCpuGaugesCard, "core-cpu-gauges", {
    sample: data.sample, accountVitals: state.overview?.vitals ?? {},
  }, {
    target: $("cpuGauges"), buildGauge, count, i18n: ZogographI18n,
  });
  renderCoreCardPackage(ZogographCpuFindingsCard, "core-cpu-findings", data.findings ?? [], {
    target: $("cpuFindings"), findingRow, i18n: ZogographI18n,
  });
  drawLineChart($("cpuBusyChart"), data.series ?? [], [
    { key: "busy", label: ZogographI18n.t("cpu.busy", {}, "Busy") },
    { key: "monitoring_cpu_percent", label: ZogographI18n.t("cpu.monitoring_tree", {}, "Monitoring tree") },
    { key: "workload_cpu_percent", label: ZogographI18n.t("cpu.workload_excluding_monitor", {}, "Workload (excl. monitor)") },
    { key: "user", label: ZogographI18n.t("cpu.userland", {}, "Userland") },
    { key: "system", label: ZogographI18n.t("cpu.kernel", {}, "Kernel") },
    { key: "iowait", label: ZogographI18n.t("cpu.waiting_for_storage", {}, "Waiting for storage") },
    { key: "steal", label: ZogographI18n.t("cpu.stolen_by_host", {}, "Stolen by the host") },
  ], {
    axis: percentAxis, zeroBased: true, max: 100,
    empty: cpuEmptyWhy(data),
  });

  renderCpuTime(data);
  renderCpuCores(data);
  renderCpuProcs(data);
  renderCpuQueue(data);
  renderCpuLimits(data);
}

/**
 * Why a processor chart is empty, which is two different situations.
 *
 * A collector that has run once and a collector that has not run since the
 * breakdown was added produce the same blank canvas, and only one of them is
 * something to go and fix.
 */
function cpuEmptyWhy(data) {
  /*
   * The upgrade window first, because it is the only one of the three that is
   * somebody's to act on.
   *
   * The two halves of this install are upgraded separately - these pages by
   * uploading them, the columns behind them by root's cron running once - so
   * between the two there is a real interval where the charts are empty and
   * nothing is wrong.
   */
  if (data.schema_reason) return data.schema_reason;

  if (!data.series?.length && Number(data.sample_count ?? 0) > 1) {
    return ZogographI18n.t("cpu.no_breakdown", {}, "No processor breakdown in this range yet — the collector records it from the version that added these pages onward");
  }
  return ZogographI18n.t("cpu.only_one_reading", {}, "Only one reading so far — a percentage needs two");
}

/**
 * The crontab line, on the one page most likely to be open.
 *
 * Shared with the memory pages, which cannot set themselves up either: this
 * needs a cron entry for a user the dashboard is not running as, and "no
 * readings yet" without the line to paste leaves somebody to go and find out
 * how.
 */
function collectorInstructions(holder, data) {
  if (!holder || !data.cron) return;

  holder.appendChild(Object.assign(document.createElement("p"), {
    className: "muted small",
    textContent: ZogographI18n.t("cpu.add_root_cron", {}, "As root — ssh in or use WHM's Terminal — add this to root's crontab with crontab -e:"),
  }));
  const pre = document.createElement("pre");
  pre.className = "paste";
  pre.textContent = data.cron;
  holder.appendChild(pre);
  holder.appendChild(Object.assign(document.createElement("p"), {
    className: "muted small",
    textContent: ZogographI18n.t("cpu.run_root_once", { command: data.command }, "Then run it once by hand to see what it finds: {{command}}"),
  }));
}

/* ------------------------------------------------ where the time goes -- */

/**
 * The eight states, now and averaged over the range.
 *
 * Both, because they answer different questions and a page showing one of them
 * gets asked for the other immediately. 40% steal right now is an emergency;
 * 40% steal averaged over a day is a hosting decision.
 */
function renderCpuTime(data) {
  const now = data.now;
  const states = data.states ?? {};
  const holder = $("cpuTimeCards");
  if (!holder) return;
  holder.replaceChildren();

  if (!now) {
    $("cpuTimeNote").textContent = cpuEmptyWhy(data) + ".";
  } else {
    renderCoreCardPackage(ZogographCpuTimeCard, "core-cpu-time", { now, states, series: data.series ?? [] }, {
      setCard: (label, value, sub, level = "") => setHostCard(label, value, sub, level, "", "cpuTimeCards"),
      bandOf, cpuStateLabel, i18n: ZogographI18n,
    });

    $("cpuTimeNote").textContent = cpuTimeVerdict(now, Number(data.sample?.cpu_cores) || 0);
  }

  drawLineChart($("cpuStateChart"), data.series ?? [],
    Object.entries(states)
      // Idle is left off deliberately: it is 100 minus everything else, so
      // plotting it adds a line that carries no information and dominates the
      // chart on any machine that is not in trouble.
      .filter(([key]) => key !== "idle")
      .map(([key, meta]) => ({ key, label: cpuStateLabel(meta) })),
    { axis: percentAxis, zeroBased: true, empty: cpuEmptyWhy(data) });

  renderTable("cpuStateTable", Object.entries(states).map(([key, meta]) => ({
    key,
    label: cpuStateLabel(meta),
    now: now ? Number(now[key]) : null,
    what: cpuStateMeaning(meta),
  })), [
    { label: ZogographI18n.t("cpu.state", {}, "State"), render: r => r.label },
    { label: ZogographI18n.t("cpu.in_proc_stat", {}, "In /proc/stat"), className: "cmd", render: r => r.key },
    {
      label: ZogographI18n.t("cpu.now", {}, "Now"),
      className: "size",
      render: r => (r.now == null || !Number.isFinite(r.now) ? "—" : `${r.now.toFixed(1)}%`),
    },
    { label: ZogographI18n.t("cpu.what_it_means", {}, "What it means"), render: r => r.what },
  ]);
}

function cpuStateLabel(meta) {
  const key = String(meta?.short || "").trim();
  return key ? ZogographI18n.t(`cpu.state_label.${key}`, {}, meta.label) : meta.label;
}

function cpuStateMeaning(meta) {
  const key = String(meta?.short || "").trim();
  return key ? ZogographI18n.t(`cpu.state_meaning.${key}`, {}, meta.what) : meta.what;
}

/** One sentence saying which state the busy time actually went to. */
function cpuTimeVerdict(now, cores) {
  const busy = Number(now.busy);
  const spread = ZogographI18n.t("cpu.time_verdict_spread", {
    cores: cores ? count(cores, "core") : ZogographI18n.t("cpu.cores_unknown", {}, "cores unknown"),
  }, "Percentages are of all {{cores}} together, so 100% would be the whole machine occupied.");

  if (busy < 5) {
    return ZogographI18n.t("cpu.time_verdict_idle", { busy: busy.toFixed(1), spread },
      "The machine is idle — {{busy}}% busy over the last reading. {{spread}}");
  }

  const parts = [["user", "ordinary work in userland"], ["nice", "low-priority work"],
    ["system", "kernel work on behalf of processes"], ["iowait", "waiting for storage"],
    ["steal", "time the hypervisor took away"], ["softirq", "deferred interrupt work"],
    ["irq", "hardware interrupts"]]
    .map(([key, fallback]) => [key, ZogographI18n.t(`cpu.time_verdict_state.${key}`, {}, fallback)]);

  const ranked = parts
    .map(([key, words]) => [Number(now[key]) || 0, words])
    .sort((a, b) => b[0] - a[0]);

  const [top, topWords] = ranked[0];
  const [second, secondWords] = ranked[1];

  const next = second >= top / 3
    ? ZogographI18n.t("cpu.time_verdict_second", { state: secondWords, percent: second.toFixed(1) }, ", then {{state}} ({{percent}}%)")
    : "";
  return ZogographI18n.t("cpu.time_verdict_busy", {
    busy: busy.toFixed(0), state: topWords, percent: top.toFixed(1), next, spread,
  }, "{{busy}}% busy, and most of it is {{state}} ({{percent}}%){{next}}. {{spread}}");
}

/* ---------------------------------------------------------- each core -- */

function renderCpuCores(data) {
  const spread = data.spread ?? {};
  renderCoreCardPackage(ZogographCpuCoresCard, "core-cpu-cores", data.cores ?? [], {
    target: $("cpuCoreGrid"), buildGauge, cpuCoreShare, i18n: ZogographI18n,
  });

  $("cpuSpreadNote").textContent = cpuSpreadVerdict(spread);

  drawLineChart($("cpuSpreadChart"), data.spread_series ?? [], [
    { key: "hottest", label: ZogographI18n.t("cpu.busiest_core", {}, "Busiest core") },
    { key: "mean", label: ZogographI18n.t("cpu.average_core", {}, "Average core") },
    { key: "coolest", label: ZogographI18n.t("cpu.quietest_core", {}, "Quietest core") },
    // On the other axis with its own scale: a count of cores forced onto a
    // percentage scale would be a flat line along the bottom, and pinning the
    // percentage axis to 100 would drag the core count up with it.
    { key: "pinned", label: ZogographI18n.t("cpu.cores_at_90", {}, "Cores at 90%+"), axis: "right" },
  ], { axis: percentAxis, rightAxis: countAxis, zeroBased: true, empty: cpuEmptyWhy(data) });
}

/**
 * What one core has spent its whole life on, as a hint under the bar.
 *
 * Lifetime shares rather than the last minute: the per-core counters are kept
 * but only the busy percentage is differenced, and inventing a second
 * difference here to fill a caption would cost a query per core. Labelled
 * "since boot" so it cannot be read as the bar's own breakdown.
 */
function cpuCoreShare(core) {
  const total = Number(core.total_ticks) || 0;
  if (!total) return "";

  const share = key => (Number(core[key]) || 0) / total * 100;
  const steal = share("steal_ticks");
  const iowait = share("iowait_ticks");

  // Only the two that mean something is wrong, and only when they are visible.
  if (steal >= 1) return ZogographI18n.t("cpu.stolen_since_boot", { percent: steal.toFixed(1) }, "{{percent}}% stolen since boot");
  if (iowait >= 5) return ZogographI18n.t("cpu.iowait_since_boot", { percent: iowait.toFixed(0) }, "{{percent}}% iowait since boot");
  return ZogographI18n.t("cpu.user_since_boot", { percent: share("user_ticks").toFixed(0) }, "{{percent}}% user since boot");
}

function cpuSpreadVerdict(spread) {
  if (!spread || !spread.measured) {
    return ZogographI18n.t("cpu.spread_not_measured", {}, "No per-core percentages yet. Each one is a difference between two readings, so the first collection after this feature was added has nothing to compare against.");
  }

  if (spread.measured === 1) {
    return ZogographI18n.t("cpu.spread_one_core", {}, "One core, so there is no distribution to look at — the whole-machine figure is the core's figure.");
  }

  const shape = ZogographI18n.t("cpu.spread_shape", {
    busiest: Math.round(spread.max), quietest: Math.round(spread.min),
    average: Math.round(spread.mean), cores: spread.measured,
  }, "Busiest core {{busiest, number}}%, quietest {{quietest, number}}%, {{average, number}}% on average across {{cores, number}} cores.");

  if (spread.pinned === spread.measured) {
    return ZogographI18n.t("cpu.spread_all_pinned", { shape }, "{{shape}} Every core is pinned: the machine has no processor headroom at all. Unlike a single busy core this does respond to more cores — but it is worth checking first that the work is work you wanted done.");
  }

  if (spread.pinned > 0 && spread.mean < 50 && spread.idle >= spread.measured / 2) {
    return ZogographI18n.t("cpu.spread_single_threaded", { shape }, "{{shape}} That is the shape of a single-threaded bottleneck: one piece of work that cannot be split, holding things up while the machine looks mostly free. The whole-machine percentage will never look alarming however stuck it gets, and more cores would not move it.");
  }

  if (spread.spread < 25) {
    return ZogographI18n.t("cpu.spread_even", { shape }, "{{shape}} The work is spreading evenly, so the only question left is how much of it there is.");
  }

  return ZogographI18n.t("cpu.spread_uneven", { shape }, "{{shape}} Uneven, but not one core carrying everything — normal on a machine running a mixture of jobs, and worth a second look if the gap keeps widening.");
}

/* ------------------------------------------------- what is burning it -- */

/** Scheduler states, in words. A letter in a column is a lookup, not a reading. */
const CPU_STATE_WORDS = {
  R: "running",
  S: "sleeping",
  D: "waiting on I/O",
  Z: "zombie",
  T: "stopped",
  I: "idle kernel thread",
};

function cpuProcessStateWord(state) {
  const fallback = CPU_STATE_WORDS[state] ?? state;
  return CPU_STATE_WORDS[state]
    ? ZogographI18n.t(`cpu.process_state.${state}`, {}, fallback)
    : fallback;
}

function renderCpuProcs(data) {
  const rows = data.processes ?? [];
  const cores = Number(data.sample?.cpu_cores) || 0;

  const accounted = rows.reduce((sum, r) => sum + (Number(r.cpu_percent) || 0), 0);
  const busy = data.now ? Number(data.now.busy) : null;

  $("cpuProcsNote").textContent = !rows.length
    ? ZogographI18n.t("cpu.no_measurable_process", {}, "No process has used measurable processor time between two readings.")
    : ZogographI18n.t("cpu.process_summary", {
      processes: rows.length, percent: Math.round(accounted),
      machine: cores
        ? ZogographI18n.t("cpu.process_summary_machine", { percent: Math.round(accounted / cores) }, " — about {{percent, number}}% of the machine")
        : "",
      busy: busy == null
        ? ""
        : ZogographI18n.t("cpu.process_summary_busy", { percent: Math.round(busy) }, ", against {{percent, number}}% measured across all cores"),
    }, "{{processes, number}} processes using the processor, adding up to {{percent, number}}% of one core{{machine}}{{busy}}.");

  renderTable("cpuProcs", rows, [
    { label: ZogographI18n.t("cpu.pid", {}, "PID"), className: "size", render: r => r.pid },
    { label: ZogographI18n.t("cpu.user", {}, "User"), render: r => userCell(r.user) },
    { label: ZogographI18n.t("cpu.process", {}, "Process"), render: r => namedThing("process", r.name) },
    {
      label: ZogographI18n.t("cpu.now_one_core", {}, "CPU now (of one core)"),
      className: "size",
      render: r => (r.cpu_percent == null ? "—" : `${Number(r.cpu_percent).toFixed(1)}%`),
    },
    {
      // The `ps` figure beside the `top` figure, which is the whole reason the
      // two tools appear to disagree about the same process.
      label: ZogographI18n.t("cpu.average_since_started", {}, "Average since it started"),
      className: "size",
      render: r => (r.cpu_lifetime_percent == null
        ? "—"
        : `${Number(r.cpu_lifetime_percent).toFixed(1)}%`),
    },
    {
      label: ZogographI18n.t("cpu.state", {}, "State"),
      render: r => (r.state ? cpuProcessStateWord(r.state) : "—"),
    },
    { label: ZogographI18n.t("cpu.threads", {}, "Threads"), className: "size", render: r => r.threads ?? "—" },
    {
      label: ZogographI18n.t("cpu.running_for", {}, "Running for"),
      className: "size",
      render: r => (r.elapsed_seconds == null ? "—" : humanDuration(r.elapsed_seconds)),
    },
    { label: ZogographI18n.t("cpu.resident", {}, "Resident"), className: "size", render: r => humanBytes(r.rss_bytes) },
    { label: ZogographI18n.t("cpu.command", {}, "Command"), className: "cmd", render: r => r.command },
  ]);
}

/* --------------------------------------------------- waiting to run -- */

function renderCpuQueue(data) {
  const now = data.now;
  const sample = data.sample ?? {};
  const cores = Number(sample.cpu_cores) || 0;

  const holder = $("cpuQueueCards");
  if (holder) holder.replaceChildren();
  const load = sample.load1 == null ? null : Number(sample.load1);
  renderCoreCardPackage(ZogographCpuQueueCard, "core-cpu-queue", { now, sample }, {
    setCard: (label, value, sub, level = "") => setHostCard(label, value, sub, level, "", "cpuQueueCards"),
    humanCount, i18n: ZogographI18n,
  });

  $("cpuQueueNote").textContent = cpuQueueVerdict(now, load, cores);

  drawLineChart($("cpuQueueChart"), data.series ?? [], [
    { key: "procs_running", label: ZogographI18n.t("cpu.wanting_to_run", {}, "Wanting to run") },
    { key: "procs_blocked", label: ZogographI18n.t("cpu.blocked_on_io", {}, "Blocked on I/O") },
    { key: "load1", label: ZogographI18n.t("cpu.load_one_minute", {}, "Load, one minute") },
    { key: "cpu_pressure_some", label: ZogographI18n.t("cpu.waiting_for_core_percent", {}, "Waiting for a core (%)"), axis: "right" },
  ], { axis: countAxis, rightAxis: percentAxis, zeroBased: true, empty: cpuEmptyWhy(data) });

  drawLineChart($("cpuRateChart"), data.series ?? [], [
    { key: "ctxt_rate", label: ZogographI18n.t("cpu.context_switches_second", {}, "Context switches/s") },
    { key: "intr_rate", label: ZogographI18n.t("cpu.interrupts_second", {}, "Interrupts/s") },
    // Two or three orders of magnitude below the other two, so it gets the
    // other axis or it is a flat line along the bottom of its own chart.
    { key: "fork_rate", label: ZogographI18n.t("cpu.new_processes_second", {}, "New processes/s"), axis: "right" },
  ], { axis: countAxis, rightAxis: countAxis, zeroBased: true, empty: cpuEmptyWhy(data) });
}

/**
 * The sentence that stops somebody buying a faster processor for a disk fault.
 *
 * A high load average with an empty run queue and a pile of blocked tasks is
 * storage, every time, and it is the single most common misreading of any of
 * these numbers.
 */
function cpuQueueVerdict(now, load, cores) {
  if (!now) {
    return ZogographI18n.t("cpu.queue_verdict_waiting", {}, "Nothing to compare yet — the queue is read from two consecutive collections.");
  }

  const running = Number(now.procs_running);
  const blocked = Number(now.procs_blocked);

  if (load != null && cores > 0 && load > cores && Number.isFinite(blocked) && blocked >= 2
    && Number.isFinite(running) && running <= cores) {
    return ZogographI18n.t("cpu.queue_verdict_storage", {
      load: load.toFixed(2), cores: count(cores, "core"), running,
      blocked: count(blocked, "task"),
    }, "Load is {{load}} on {{cores}}, but only {{running}} task(s) want a core and {{blocked}} are blocked in the kernel. That load is storage, not processor: blocked tasks count towards it and use no CPU at all. A faster processor would change nothing here.");
  }

  if (Number.isFinite(running) && cores > 0 && running > cores * 2) {
    return ZogographI18n.t("cpu.queue_verdict_runnable", { running: count(running, "task"), cores: count(cores, "core") },
      "{{running}} runnable across {{cores}}. Nothing is stalled — everything gets a turn — but each turn is shorter, and every job takes longer than it would on an idle machine. This is what “slow but nothing is broken” looks like from underneath.");
  }

  if (Number.isFinite(blocked) && blocked >= 4) {
    return ZogographI18n.t("cpu.queue_verdict_blocked", { blocked: count(blocked, "task") },
      "{{blocked}} in uninterruptible sleep. They are waiting on I/O, cannot be killed while they wait, and are inflating the load average without touching the processor.");
  }

  return ZogographI18n.t("cpu.queue_verdict_clear", {
    running: Number.isFinite(running) ? running : ZogographI18n.t("cpu.queue_unknown_count", {}, "an unknown number of"),
    cores: cores ? ZogographI18n.t("cpu.across_cores", { count: cores }, "across {{count, number}} cores") : "",
    blocked: Number.isFinite(blocked) ? blocked : ZogographI18n.t("cpu.queue_unknown_count", {}, "an unknown number of"),
  }, "Nothing is queueing: {{running}} tasks runnable {{cores}}, {{blocked}} blocked.");
}

/* --------------------------------------------- ceilings and throttling -- */

function renderCpuLimits(data) {
  // The same comparison the limits panel draws, in its own frame here: the
  // question "why is my CPU pinned while the server is idle" is a CPU question
  // and sending somebody to another page to have it answered loses them.
  renderLimits(data.limits, "cpuLimitsTable", "cpuLimitsWhen");

  const mine = data.vitals?.cpu_percent == null ? null : Number(data.vitals.cpu_percent);
  const host = data.sample?.cpu_percent == null ? null : Number(data.sample.cpu_percent);
  const faults = (data.lve ?? []).reduce((sum, r) => sum + (Number(r.faults_cpu) || 0), 0);

  $("cpuLimitsNote").textContent = cpuLimitVerdict(mine, host, faults, data.lve ?? []);

  const wrap = $("cpuLveWrap");
  if (wrap) wrap.hidden = !(data.lve ?? []).length;

  if ((data.lve ?? []).length) {
    renderTable("cpuLve", data.lve, [
      { label: ZogographI18n.t("cpu.account", {}, "Account"), render: r => r.user },
      {
        label: ZogographI18n.t("cpu.cpu_faults", {}, "CPU faults"),
        className: "size",
        render: r => humanCount(r.faults_cpu),
      },
      { label: ZogographI18n.t("cpu.memory_faults", {}, "Memory faults"), className: "size", render: r => humanCount(r.faults_mem) },
      { label: ZogographI18n.t("cpu.process_faults", {}, "Process faults"), className: "size", render: r => humanCount(r.faults_procs) },
      {
        label: ZogographI18n.t("cpu.cpu_in_use", {}, "CPU in use"),
        className: "size",
        render: r => (r.cpu_percent == null ? "—" : `${Number(r.cpu_percent).toFixed(0)}%`),
      },
    ]);

    drawLineChart($("cpuLveChart"), data.lve_series ?? [], [
      { key: "faults_cpu", label: ZogographI18n.t("cpu.cpu_faults", {}, "CPU faults") },
      { key: "faults_mem", label: ZogographI18n.t("cpu.memory_faults", {}, "Memory faults") },
    ], { axis: countAxis, zeroBased: true, empty: ZogographI18n.t("cpu.no_lve_readings", {}, "No LVE readings in this range") });
  }
}

function cpuLimitVerdict(mine, host, faults, rows) {
  const both = mine != null && host != null;

  if (faults > 0) {
    return ZogographI18n.t("cpu.limit_faults", { faults, accounts: rows.length },
      "{{faults, number}} CPU fault(s) recorded at the last reading across {{accounts, number}} account(s). A fault is an account asking for more processor than its LVE allows and being held back — this is being throttled now, not being near a limit. A throttled account's own percentage sits calmly at its ceiling, which is why the fault count is the figure to watch and not the percentage.");
  }

  if (both && mine >= 85 && host < 50) {
    return ZogographI18n.t("cpu.limit_throttled", { account: Math.round(mine), host: Math.round(host) },
      "This account is at {{account, number}}% of its own allowance while the machine is {{host, number}}% busy. That is not a contradiction: the two percentages have different denominators. It is the ordinary shape of hitting a limit, and it is felt as a slow site even though the server has plenty of processor left.");
  }

  if (both) {
    return ZogographI18n.t("cpu.limit_comparison", { account: Math.round(mine), host: Math.round(host) },
      "This account is using {{account, number}}% of what it is allowed; the machine as a whole is {{host, number}}% busy. Neither number is a share of the other, and dividing them produces nothing meaningful.");
  }

  return ZogographI18n.t("cpu.limit_missing_side", {},
    "Both halves of this comparison need a reading — one from this account and one from the host collector running as root.");
}


function buildGauge(dial) {
  const box = document.createElement("div");
  box.className = "gauge";

  const canvas = document.createElement("canvas");
  box.appendChild(canvas);

  const label = document.createElement("div");
  label.className = "gauge-label";
  label.textContent = dial.label;
  box.appendChild(label);

  const band = dial.plain != null ? null : bandOf(dial.value, dial.warn, dial.crit);
  const state = document.createElement("div");
  state.className = "gauge-band " + (band ? `band-${band}` : "muted");
  state.textContent = band
    ? gaugeBandWord(band)
    : (dial.plain != null
      ? ZogographI18n.t("gauge.no_ceiling", {}, "no ceiling to measure against")
      : ZogographI18n.t("gauge.not_measured", {}, "not measured"));
  box.appendChild(state);

  /*
   * A strip of history under the dial.
   *
   * The gauge says where this is now, which on its own is half a fact: 88% is
   * fine if it has been 88% all year and alarming if it was 60% on Tuesday.
   * No numbers and no axis - the five full charts are one click away for that.
   * This exists to answer "is it moving, and has it been bad recently" at a
   * glance, which is the question somebody opening the overview actually has.
   */
  if (dial.series && dial.series.length > 1) {
    const spark = document.createElement("canvas");
    spark.className = "gauge-spark";
    box.appendChild(spark);

    requestAnimationFrame(() => drawSparkline(spark, dial));
    rememberDraw(spark, () => drawSparkline(spark, dial));
  }

  const sub = document.createElement("div");
  sub.className = "gauge-sub";
  sub.textContent = dial.sub;
  box.appendChild(sub);

  if (dial.overlay != null && Number.isFinite(dial.overlay)) {
    const detail = document.createElement("div");
    detail.className = "gauge-sub muted";
    detail.textContent = dial.overlayLabel || `Monitoring: ${dial.overlay}`;
    box.appendChild(detail);
  }

  // Drawn after the node is in the document, or clientWidth is zero and the
  // remembered redraw is the only thing that ever paints it.
  requestAnimationFrame(() => drawGauge(canvas, dial, band));
  rememberDraw(canvas, () => drawGauge(canvas, dial, bandOf(dial.value, dial.warn, dial.crit)));

  return box;
}

/**
 * One measurement over the selected range, in a strip the width of the gauge.
 *
 * The background is banded by health rather than the line being coloured: a
 * coloured line says "this point was critical", which is true but hard to see
 * at two pixels; a coloured background says "this period was critical", which
 * is the shape of the answer somebody wants. It also survives a line that
 * crosses a threshold repeatedly, where colouring segments produces a dashed
 * mess.
 *
 * Deliberately nothing else. No axis, no ticks, no numbers - anything more and
 * it stops being readable at a glance, which is the only reason it is here
 * rather than being the chart on the next page.
 */
function drawSparkline(canvas, dial) {
  const width = canvas.clientWidth;
  if (!width) return;

  const dpr = window.devicePixelRatio || 1;
  const height = 32;
  canvas.width = Math.round(width * dpr);
  canvas.height = Math.round(height * dpr);
  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);

  const points = dial.series.filter(point => point.value != null);
  if (points.length < 2) return;

  const t0 = points[0].at;
  const t1 = points[points.length - 1].at;
  const span = Math.max(1, t1 - t0);

  /*
   * The scale runs to the critical threshold, not to the highest reading.
   *
   * Scaling to the data makes a quiet week look as dramatic as a bad one -
   * a line wobbling between 3% and 4% would fill the strip. Against the
   * threshold, flat and low reads as flat and low.
   */
  const ceiling = Math.max(
    dial.max ?? 100,
    ...points.map(point => Number(point.value))
  );

  const x = at => ((at - t0) / span) * width;
  const y = value => height - (Math.min(value, ceiling) / ceiling) * (height - 3) - 1.5;

  /*
   * Bands drawn as spans, from one reading to the next.
   *
   * Per-point rectangles leave gaps where readings are sparse and overlap
   * where they are dense; a span between consecutive readings is what the
   * measurement actually covers.
   */
  for (let i = 0; i < points.length - 1; i++) {
    const band = bandOf(Number(points[i].value), dial.warn, dial.crit);
    if (!band || band === "ok") continue;
    const from = x(points[i].at);
    const to = x(points[i + 1].at);

    if (band === "crit") {
      ctx.fillStyle = "rgba(242, 97, 107, 0.22)";
      ctx.fillRect(from, 0, Math.max(1, to - from), height);
    } else {
      // Warning is a lower-half band, leaving the quiet upper half clear so
      // amber does not visually merge into a critical red background.
      ctx.fillStyle = "rgba(240, 163, 94, 0.18)";
      ctx.fillRect(from, height / 2, Math.max(1, to - from), height / 2);
    }
  }

  ctx.beginPath();
  points.forEach((point, i) => {
    const at = x(point.at);
    const value = y(Number(point.value));
    if (i === 0) ctx.moveTo(at, value);
    else ctx.lineTo(at, value);
  });
  ctx.strokeStyle = "rgba(140, 180, 235, 0.9)";
  ctx.lineWidth = 1.5;
  ctx.lineJoin = "round";
  ctx.stroke();

  /*
   * A dot on the last reading, tying the strip to the dial above it.
   *
   * Without it the right-hand end is just where the line stops, and on a
   * collector that has been quiet for an hour that is not the same place as
   * "now" - which is exactly the case worth noticing.
   */
  const last = points[points.length - 1];
  ctx.beginPath();
  ctx.arc(x(last.at), y(Number(last.value)), 2, 0, Math.PI * 2);
  ctx.fillStyle = "rgba(200, 220, 245, 0.95)";
  ctx.fill();
}

/**
 * Readings for one gauge, as {at, value} pairs over the selected range.
 *
 * Reads the same series the full charts draw, so the strip and the chart can
 * never disagree - which they would within a week if this had its own idea of
 * how to turn a reading into a percentage.
 */
function gaugeSeries(rows, pick) {
  if (!Array.isArray(rows)) return [];

  return rows
    .map(row => ({ at: Number(row.taken_at), value: pick(row) }))
    .filter(point => Number.isFinite(point.at) && point.value != null
      && Number.isFinite(Number(point.value)));
}

/*
 * A three-quarter arc, because a full circle has no beginning.
 *
 * The gap at the bottom is what tells you which end is empty; a ring with no
 * gap is read as a pie and the eye looks for the second slice.
 */
function drawGauge(canvas, dial, band) {
  const width = canvas.clientWidth;
  if (!width) return;

  const dpr = window.devicePixelRatio || 1;
  const height = Math.round(width * 0.62);
  canvas.width = Math.round(width * dpr);
  canvas.height = Math.round(height * dpr);
  canvas.style.height = height + "px";

  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);

  const max = dial.max || 100;
  const cx = width / 2;
  const cy = height * 0.78;
  const radius = Math.min(width / 2, cy) - 12;
  const thickness = Math.max(8, radius * 0.22);

  const start = Math.PI * 0.75;
  const sweep = Math.PI * 1.5;

  ctx.lineCap = "round";
  ctx.lineWidth = thickness;

  ctx.strokeStyle = "#232d3a";
  ctx.beginPath();
  ctx.arc(cx, cy, radius, start, start + sweep);
  ctx.stroke();

  if (dial.value != null && Number.isFinite(dial.value)) {
    const share = Math.max(0, Math.min(1, dial.value / max));
    if (share > 0) {
      ctx.strokeStyle = BAND_COLOR[band] || "#4c9aff";
      ctx.beginPath();
      ctx.arc(cx, cy, radius, start, start + sweep * share);
      ctx.stroke();
    }
  }

  // A narrow darker arc is part of the total, not a second total. It exposes
  // monitoring cost without claiming that an unsafe subtraction is workload.
  if (dial.overlay != null && Number.isFinite(dial.overlay)) {
    const share = Math.max(0, Math.min(1, dial.overlay / max));
    if (share > 0) {
      ctx.strokeStyle = "#243a58";
      ctx.lineWidth = Math.max(3, thickness * 0.42);
      ctx.beginPath();
      ctx.arc(cx, cy, radius, start, start + sweep * share);
      ctx.stroke();
      ctx.lineWidth = thickness;
    }
  }

  /*
   * A count in the middle where there is no percentage to draw.
   *
   * Some of these quantities have no ceiling - open connections, listening
   * ports - so an arc would need an invented denominator. The ring stays empty
   * and the number is the whole reading, which is honest about there being no
   * scale rather than implying one.
   */
  const middle = dial.plain != null
    ? dial.plain
    : (dial.value == null ? "—" : `${Math.round(dial.value)}%`);

  ctx.fillStyle = dial.value == null && dial.plain == null ? "#66717f" : "#e6edf3";
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";

  // Long counts have to shrink to fit inside the ring.
  const size = Math.round(radius * (middle.length > 4 ? 0.34 : 0.52));
  ctx.font = `600 ${size}px system-ui, sans-serif`;
  ctx.fillText(middle, cx, cy + radius * 0.12);
}

/*
 * The account's readings against the machine's.
 *
 * Every row shows both numbers and then says what the pair means, because the
 * pair is the finding: two cores out of thirty-two is not a fact about this
 * account's CPU use, it is the reason its CPU use looks the way it does.
 */
function renderLimits(limits, bodyId = "limitsBody", whenId = "limitsWhen") {
  const body = $(bodyId);
  // The processor page shows the same comparison without a timestamp beside a
  // heading of its own, so the element is optional rather than assumed.
  const when = $(whenId);

  if (!limits || !limits.available) {
    if (when) when.textContent = "";
    body.replaceChildren(Object.assign(document.createElement("p"), {
      className: "muted",
      textContent: limits?.reason || ZogographI18n.t("cpu.limit_unavailable"),
    }));
    return;
  }

  if (when) {
    when.textContent = limits.host_at
      ? ZogographI18n.t("cpu.limit_host_reading", { time: humanTime(limits.host_at) })
      : "";
  }

  const format = (value, unit) => {
    if (value == null) return ZogographI18n.t("cpu.limit_not_measured");
    if (unit === "bytes") return humanBytes(value);
    if (unit === "percent") return `${Number(value).toFixed(0)}%`;
    return String(Number(value) % 1 === 0 ? value : Number(value).toFixed(2));
  };

  body.replaceChildren(...limits.rows.map(row => {
    const div = document.createElement("div");
    div.className = "limit-row";

    const name = document.createElement("div");
    name.className = "limit-name";
    name.textContent = row.name;
    div.appendChild(name);

    for (const [side, value] of [[ZogographI18n.t("cpu.limit_account_sees"), row.account], [ZogographI18n.t("cpu.limit_machine_has"), row.host]]) {
      const pair = document.createElement("div");
      pair.className = "limit-pair";

      const heading = document.createElement("div");
      heading.className = "muted";
      heading.textContent = side;
      pair.appendChild(heading);

      const figure = document.createElement("div");
      figure.textContent = format(value, row.unit);
      if (row.verdict === "capped" && side === ZogographI18n.t("cpu.limit_account_sees")) {
        figure.className = "band-warn";
      }
      pair.appendChild(figure);

      div.appendChild(pair);
    }

    const note = document.createElement("div");
    note.className = "limit-note";
    note.textContent = row.note;
    div.appendChild(note);

    return div;
  }));
}

/* Core card packages receive only the helpers they explicitly declare. This is
 * the internal contract mirrored by the data-only signed package renderer. */
function renderCoreCardPackage(cardPackage, id, input, helpers) {
  const manifest = cardPackage?.manifest;
  if (!manifest || manifest.id !== id || typeof cardPackage.render !== "function"
      || !Array.isArray(manifest.locales) || manifest.locales.length === 0
      || !manifest.locales.every(prefix => typeof prefix === "string" && /^[a-z][\\w-]*\.$/i.test(prefix))
      || !Array.isArray(manifest.helpers)
      || !manifest.helpers.every(name => typeof name === "string" && name in helpers)) {
    console.error(`Core card package ${id} has an invalid manifest.`);
    return;
  }
  cardPackage.render(input, helpers);
}

function renderCards(overview, vitalRows) {
  renderCoreCardPackage(ZogographOverviewVitalsCards, "core-overview-vitals", overview, {
    setCard, humanBytes, humanCount, humanDuration, projectedDate, i18n: ZogographI18n,
  });
}

/**
 * When the disk is projected to fill, as a date.
 *
 * A duration is the harder thing to act on: "1095.1 days" has to be converted
 * to something a calendar understands before it means anything, and at that
 * range the decimal is spurious precision on an estimate that is really "some
 * time in 2029". A date is the same information already converted.
 *
 * The year appears only past a month. Inside that, the day and month are
 * unambiguous and the year is noise; beyond it, leaving the year off would make
 * next August and August three years from now look identical.
 */
function projectedDate(secondsLeft) {
  const when = new Date((Math.floor(Date.now() / 1000) + secondsLeft) * 1000);

  return when.toLocaleDateString([], secondsLeft > 30 * 86400
    ? { year: "numeric", month: "numeric", day: "numeric" }
    : { month: "numeric", day: "numeric" });
}

/* ----------------------------------------------------------------- charts -- */

/**
 * Writes the legend for a chart, from the series it was actually given.
 *
 * Kept next to the canvas and rebuilt on every draw, so a series that is added,
 * removed or reordered cannot leave the key behind saying something else.
 */
function drawLegend(canvas, series) {
  let el = canvas.nextElementSibling;
  if (!el || !el.classList.contains("legend")) {
    el = document.createElement("div");
    el.className = "legend";
    canvas.after(el);
  }

  el.replaceChildren(...series.map((s, i) => {
    const span = document.createElement("span");
    span.textContent = s.label;
    span.style.setProperty("--dot", seriesColor(i));
    return span;
  }));

  /*
   * The marker key, only when there are markers.
   *
   * An amber square on a chart is unexplained until somebody hovers something,
   * and canvas has nothing to hover. Naming it in the legend costs one word and
   * removes the question - but only on the charts that have one, or every chart
   * carries a key to marks it does not show.
   */
  if (typeof noteState !== "undefined" && canvas.id && marksForChart(canvas.id).length) {
    const span = document.createElement("span");
    span.className = "legend-note";
    span.textContent = ZogographI18n.t("chart.your_notes", {}, "Your notes");
    span.title = marksForChart(canvas.id).map(mark => mark.label).join("\n\n");
    el.appendChild(span);
  }
}

/**
 * Tick values on round numbers covering a range.
 *
 * The old chart divided the range into four and printed whatever fell out,
 * which on a nearly-full disk produced five ticks all reading "71.8 GiB" while
 * the line visibly moved between them. Two things were wrong: the steps were
 * arbitrary fractions of an arbitrary range, and the labels were rounded to
 * fewer digits than it took to tell them apart.
 *
 * Steps of 1, 2 or 5 times a power of ten fix the first - they are the numbers
 * people can read differences off without doing arithmetic. `tickPrecision`
 * below fixes the second.
 */
function niceTicks(min, max, target = 5, floorAtZero = false) {
  if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min) {
    return { ticks: [min, max], step: Math.max(1e-9, max - min), min, max };
  }

  const rough = (max - min) / Math.max(1, target - 1);
  const magnitude = 10 ** Math.floor(Math.log10(rough));
  const normalised = rough / magnitude;
  const step = (normalised <= 1 ? 1 : normalised <= 2 ? 2 : normalised <= 5 ? 5 : 10) * magnitude;

  let first = Math.floor(min / step) * step;
  const last = Math.ceil(max / step) * step;
  // A load average of -1, or -500 MiB free, is not a thing. Rounding the bottom
  // of the range down to a round number is right until it crosses zero.
  if (floorAtZero && first < 0) first = 0;

  const ticks = [];
  // Counted rather than accumulated, because adding a float to itself thirty
  // times lands on 0.30000000000000004 and prints as its own tick label.
  for (let i = 0; first + i * step <= last + step * 1e-9; i += 1) {
    ticks.push(first + i * step);
  }

  return { ticks, step, min: first, max: last };
}

/**
 * How many decimals a label needs for neighbouring ticks to differ.
 *
 * The reason "82,701,000 / 82,700,999 / 82,700,999" happened: two ticks a
 * thousandth of a percent apart, printed to the same width, come out identical
 * and the axis looks broken. Given the step, this works out what it takes to
 * show the difference - and if that is more digits than anybody wants to read,
 * the caller should be showing a delta instead.
 */
function tickPrecision(step, scale = 1) {
  const shown = step / scale;
  if (!Number.isFinite(shown) || shown <= 0) return 0;
  return Math.max(0, Math.min(4, Math.ceil(-Math.log10(shown)) + 1));
}

/**
 * Bytes, with the unit chosen by the size of the numbers and the number of
 * decimals chosen by the distance between them.
 *
 * Those are two different questions and picking the unit from the step gets the
 * first one wrong: on a disk with 72 GiB free changing by 50 MiB an hour, a
 * step-sized unit labels the axis "73671 MiB", which is the right precision
 * expressed in a unit nobody thinks in. Magnitude picks GiB; step then says it
 * needs two decimals, and the label is "71.94 GiB".
 */
function bytesAxis(step, magnitude = step) {
  const units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
  let scale = 1;
  let i = 0;
  while (Math.abs(magnitude) / scale >= 1024 && i < units.length - 1) { scale *= 1024; i++; }
  const digits = tickPrecision(step, scale);
  return {
    scale,
    unit: units[i],
    format: v => `${(v / scale).toFixed(digits)} ${units[i]}`,
  };
}

/**
 * Plain counts, shortened only when shortening does not cost readability.
 *
 * Inodes run to eight digits and change by tens, so "82.70100M" is a worse
 * label than "82,701,000" - the abbreviation is supposed to save you reading
 * digits and there it adds two. Past two decimals it gives up and groups.
 */
/*
 * An axis in milliseconds, which is neither bytes nor a plain count.
 *
 * Without this the response-time chart came out labelled "15.0 KiB", because
 * drawLineChart defaults to bytes - a number formatted in the wrong unit is
 * more misleading than one with no unit at all, since it reads as a fact.
 */
function msAxis(step, magnitude = step) {
  if (Math.abs(magnitude) >= 2000) {
    return {
      scale: 1000,
      unit: "s",
      format: v => `${(v / 1000).toFixed(v / 1000 >= 10 ? 0 : 1)}s`,
    };
  }
  return {
    scale: 1,
    unit: "ms",
    format: v => `${Math.round(v)} ms`,
  };
}

/** A bare number, for anything whose unit is whatever the page says it is. */
function plainAxis(step, magnitude = step) {
  return {
    scale: 1,
    unit: "",
    format: v => new Intl.NumberFormat().format(
      Math.abs(v) >= 100 ? Math.round(v) : Number(v.toFixed(2))
    ),
  };
}

function countAxis(step, magnitude = step) {
  const units = [["", 1], ["K", 1e3], ["M", 1e6], ["B", 1e9]];
  let at = 0;
  while (at < units.length - 1 && Math.abs(magnitude) / units[at + 1][1] >= 1) at++;
  const [suffix, scale] = units[at];
  const digits = tickPrecision(step, scale);

  if (digits > 2) {
    return {
      scale: 1,
      unit: "",
      format: v => new Intl.NumberFormat().format(Math.round(v)),
    };
  }

  return {
    scale,
    unit: suffix,
    format: v => `${(v / scale).toFixed(digits)}${suffix}`,
  };
}

function percentAxis(step) {
  const digits = Math.min(1, tickPrecision(step));
  return { scale: 1, unit: "%", format: v => `${v.toFixed(digits)}%` };
}

function rateAxis(step, magnitude = step) {
  const inner = bytesAxis(step, magnitude);
  return { ...inner, format: v => `${inner.format(v)}/s` };
}

/**
 * A line chart of one or more series against time.
 *
 * `rows` carry their own x in `xKey` (a unix timestamp) rather than being
 * evenly spaced by index. That matters here: readings are a minute apart until
 * somebody turns on live updates and then they are ten seconds apart, and
 * spacing them evenly would draw the busy period as though it took hours.
 */
/*
 * Charts remember how to redraw themselves.
 *
 * A canvas inside a hidden view has a clientWidth of zero, so its backing
 * store gets sized for a 300px clamp and CSS then stretches it to the panel's
 * real width - four times over, which is why the category chart came out
 * blurry with wide letters. It happened because the data for that chart is
 * fetched by one view while the canvas lives in another.
 *
 * Rather than police which view fetches what, every draw is remembered and
 * replayed when the canvas actually has a layout: on becoming visible, and on
 * resize. The draw while hidden is skipped rather than done wrongly.
 */
function rememberDraw(canvas, redraw) {
  canvas.__redraw = redraw;
}

function redrawCharts(root = document) {
  const dpr = window.devicePixelRatio || 1;

  for (const canvas of root.querySelectorAll("canvas")) {
    if (canvas.clientWidth === 0) continue;

    if (canvas.__redraw) {
      canvas.__redraw();
      continue;
    }

    /*
     * A canvas nothing ever drew into.
     *
     * It keeps the HTML default backing store of 300x150 while CSS stretches
     * it to the panel's width, and the browser scales that empty bitmap to
     * fit - the same blurry, letters-too-wide look, arrived at from the other
     * direction. Sizing it to its own box makes an undrawn chart blank rather
     * than smeared.
     */
    canvas.width = Math.round(canvas.clientWidth * dpr);
    canvas.height = Math.round((canvas.clientHeight || 260) * dpr);
  }
}

/* ------------------------------------------------------------- time axis -- */

/*
 * Where the marks go along the bottom of a chart, and what they say.
 *
 * The old rule was three labels - start, middle, end - each a full date-time.
 * That is wrong in both directions at once. Over an hour, all three said the
 * same date and differed only in the minutes, so two thirds of every label was
 * noise. Over a year they were arbitrary instants: "14 Mar 09:22" is not a
 * place on a calendar, it is wherever the range happened to begin, and reading
 * a yearly chart against it means doing arithmetic for every point.
 *
 * A time axis should land on boundaries a person recognises - the hour, midnight,
 * the first of the month - and say only the part that distinguishes one from the
 * next. So: pick the largest sensible unit that still gives enough marks, step
 * along real calendar boundaries, and choose the wording from the step rather
 * than from the span.
 *
 * Calendar boundaries, not epoch arithmetic. A day is not always 86400 seconds
 * where clocks change, and stepping by that number puts every mark after a
 * spring forward an hour off midnight - visibly wrong, and wrong in a way that
 * looks like a data problem rather than an axis problem.
 */

/**
 * The steps this will consider, coarsest last.
 *
 * `every` is in whichever unit `unit` names. Fixed-length steps are in seconds;
 * days, months and years are stepped through the calendar.
 */
const TIME_STEPS = [
  { unit: "second", every: 1, approx: 1 },
  { unit: "second", every: 5, approx: 5 },
  { unit: "second", every: 15, approx: 15 },
  { unit: "second", every: 30, approx: 30 },
  { unit: "minute", every: 1, approx: 60 },
  { unit: "minute", every: 5, approx: 300 },
  { unit: "minute", every: 15, approx: 900 },
  { unit: "minute", every: 30, approx: 1800 },
  { unit: "hour", every: 1, approx: 3600 },
  { unit: "hour", every: 3, approx: 10800 },
  { unit: "hour", every: 6, approx: 21600 },
  { unit: "hour", every: 12, approx: 43200 },
  { unit: "day", every: 1, approx: 86400 },
  { unit: "day", every: 7, approx: 604800 },
  { unit: "month", every: 1, approx: 2629746 },
  { unit: "month", every: 3, approx: 7889238 },
  { unit: "month", every: 6, approx: 15778476 },
  { unit: "year", every: 1, approx: 31556952 },
  { unit: "year", every: 2, approx: 63113904 },
  { unit: "year", every: 5, approx: 157784760 },
  { unit: "year", every: 10, approx: 315569520 },
];

/**
 * Marks along a time axis, chosen to fit the width available.
 *
 * Returns `{at, label, ends}` for each. `ends` marks the two added for the
 * start and end of the range itself - they are drawn as ticks whatever
 * happens, because the range is a fact about the chart, but their labels are
 * the first to be dropped when something has to give.
 *
 * @return {{ticks: Array, step: Object}}
 */
function timeTicks(t0, t1, plotW, measure) {
  const span = Math.max(1, t1 - t0);

  /*
   * How wide a label needs to be, measured rather than guessed.
   *
   * The formats here range from "09:22" to "Wed 14:00", and a fixed guess
   * either wastes half the axis on the short ones or overlaps the long ones.
   * Plus a gap, so neighbours do not touch.
   */
  const widthOf = text => (measure ? measure(text) : text.length * 7) + 18;

  let chosen = TIME_STEPS[TIME_STEPS.length - 1];
  let marks = [];

  for (const step of TIME_STEPS) {
    // Four or fewer over the whole span is not an axis, it is three labels
    // again - so a step that coarse is skipped unless nothing finer fits.
    const at = stepThrough(t0, t1, step);
    if (at.length < 2) continue;

    const format = timeFormatFor(step, t0, t1);
    const needed = at.reduce((sum, when) => sum + widthOf(format(when)), 0);

    if (needed <= plotW) {
      chosen = step;
      marks = at;
      break;
    }
  }

  if (marks.length === 0) {
    // Nothing fits, which happens on a very narrow panel. One mark in the
    // middle beats a row of overlapping ones.
    chosen = TIME_STEPS[TIME_STEPS.length - 1];
    marks = [Math.round((t0 + t1) / 2)];
  }

  const format = timeFormatFor(chosen, t0, t1);
  const x = when => ((when - t0) / span) * plotW;

  const ticks = marks.map(when => ({
    at: when,
    label: format(when),
    ends: false,
    x: x(when),
  }));

  /*
   * The ends of the range, always ticked and sometimes labelled.
   *
   * "This chart covers 03:27 to 15:17" is a different fact from "here are the
   * hours in it", and both are wanted. The label goes only if it fits without
   * crowding the neighbour it would sit beside.
   */
  /*
   * The stepped marks as they were, before either end is added.
   *
   * Searching `ticks` while appending to it found the start tick as the end
   * tick's nearest neighbour - it sits at x=0 but was pushed on last, and a
   * reversed find walks insertion order rather than position. The result was
   * an end label compared against the wrong label, so "Aug 25" printed twice.
   */
  const inner = [...ticks];

  for (const [when, edge] of [[t0, "start"], [t1, "end"]]) {
    const label = timeFormatFor(chosen, t0, t1, true)(when);
    const mine = x(when);

    const neighbour = edge === "start"
      ? inner.find(tick => tick.x > mine)
      : [...inner].reverse().find(tick => tick.x < mine);

    const room = neighbour === undefined
      ? plotW
      : Math.abs(neighbour.x - mine);

    /*
     * Dropped when it will not fit, and also when it says nothing new.
     *
     * A range ending at 15:17 on the 25th, next to a daily mark reading "Aug
     * 25", would print "Aug 25" twice in a row - which looks like a rendering
     * fault rather than the two different facts it actually is.
     */
    const fits = room >= (widthOf(label) + widthOf(neighbour?.label ?? "")) / 2;
    const repeats = neighbour !== undefined && neighbour.label === label;

    ticks.push({
      at: when,
      label: fits && !repeats ? label : "",
      ends: true,
      x: mine,
    });
  }

  ticks.sort((a, b) => a.x - b.x);
  return { ticks, step: chosen };
}

/**
 * Walks the calendar from t0 to t1 in steps of one unit.
 *
 * Starts at the first boundary at or after t0, so the marks land on the hour
 * and on midnight rather than wherever the range happened to begin.
 */
function stepThrough(t0, t1, step) {
  const out = [];
  const at = new Date(t0 * 1000);

  // Zero everything below the step's own unit, then round up to the next
  // multiple of it.
  if (step.unit !== "second") at.setSeconds(0, 0);
  if (step.unit === "hour" || step.unit === "day" || step.unit === "month"
      || step.unit === "year") {
    at.setMinutes(0);
  }
  if (step.unit === "day" || step.unit === "month" || step.unit === "year") {
    at.setHours(0);
  }
  if (step.unit === "month" || step.unit === "year") at.setDate(1);
  if (step.unit === "year") at.setMonth(0);

  const round = (value, every) => Math.ceil(value / every) * every;

  if (step.unit === "second") at.setSeconds(round(at.getSeconds(), step.every), 0);
  if (step.unit === "minute") at.setMinutes(round(at.getMinutes(), step.every));
  if (step.unit === "hour") at.setHours(round(at.getHours(), step.every));
  if (step.unit === "month") at.setMonth(round(at.getMonth(), step.every));
  if (step.unit === "year") {
    at.setFullYear(Math.ceil(at.getFullYear() / step.every) * step.every);
  }

  // A bound on the loop as well as on the time: a step of one second across a
  // decade would otherwise try to build three hundred million marks.
  for (let guard = 0; guard < 400; guard++) {
    const when = Math.round(at.getTime() / 1000);
    if (when > t1) break;
    if (when >= t0) out.push(when);

    switch (step.unit) {
      case "second": at.setSeconds(at.getSeconds() + step.every); break;
      case "minute": at.setMinutes(at.getMinutes() + step.every); break;
      case "hour": at.setHours(at.getHours() + step.every); break;
      case "day": at.setDate(at.getDate() + step.every); break;
      case "month": at.setMonth(at.getMonth() + step.every); break;
      default: at.setFullYear(at.getFullYear() + step.every); break;
    }
  }

  return out;
}

/**
 * How a mark at this step should read.
 *
 * The step decides, not the span. A mark every hour says the hour; a mark every
 * month says the month. The exceptions are where the coarser part changes
 * inside the range - a range crossing midnight needs the weekday on its hourly
 * marks, or two marks read "14:00" and mean different days.
 *
 * `full` asks for the version used on the range's own two ends, which carry a
 * little more because there is nothing either side of them for context.
 */
function timeFormatFor(step, t0, t1, full = false) {
  const span = t1 - t0;
  const sameDay = new Date(t0 * 1000).toDateString() === new Date(t1 * 1000).toDateString();
  const sameYear = new Date(t0 * 1000).getFullYear() === new Date(t1 * 1000).getFullYear();

  const at = when => new Date(when * 1000);

  switch (step.unit) {
    case "second":
      return when => at(when).toLocaleTimeString([],
        { hour: "2-digit", minute: "2-digit", second: "2-digit" });

    case "minute":
    case "hour":
      /*
       * Within one day the date is the same on every mark, so it is the part
       * to drop - including on the ends.
       *
       * `full` exists to give the range's own ends the context the inner marks
       * get from their neighbours. Where there is no context to give, it must
       * not invent any: a fifteen-minute range labelled "Tue 03:02 PM" at one
       * end and "03:05 PM" at the next reads as two different kinds of thing.
       */
      if (sameDay) {
        return when => at(when).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      }
      if (span <= 8 * 86400) {
        // Weekday and hour: over a few days, "Wed 14:00" places a mark better
        // than a numeric date does.
        return when => at(when).toLocaleString([],
          { weekday: "short", hour: "2-digit", minute: "2-digit" });
      }
      return when => at(when).toLocaleString([],
        { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });

    case "day":
      if (full && !sameYear) {
        return when => at(when).toLocaleDateString([],
          { year: "numeric", month: "short", day: "numeric" });
      }
      return when => at(when).toLocaleDateString([], { month: "short", day: "numeric" });

    case "month":
      /*
       * The month alone, unless the range crosses a year.
       *
       * Twelve marks reading Jan to Dec need no year on any of them. A range
       * from October to March needs it on all of them, or the two halves are
       * indistinguishable.
       */
      if (sameYear) {
        return when => at(when).toLocaleDateString([], { month: "short" });
      }
      return when => at(when).toLocaleDateString([], { month: "short", year: "numeric" });

    default:
      return when => String(at(when).getFullYear());
  }
}

/**
 * Draws the time axis: a faint line and a tick at each mark, label beneath.
 *
 * The vertical lines are what make a chart readable across a wide panel -
 * without them the eye has to travel from a point down to the axis with nothing
 * to follow. Faint, because they are scaffolding rather than data.
 */
function drawTimeAxis(ctx, ticks, pad, plotW, h, cssH) {
  ctx.save();

  for (const tick of ticks) {
    const at = pad.left + tick.x;

    // Faint vertical, skipped on the range's own ends where the plot border
    // already draws one.
    if (!tick.ends) {
      ctx.strokeStyle = "rgba(255, 255, 255, 0.05)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(at, pad.top);
      ctx.lineTo(at, pad.top + h);
      ctx.stroke();
    }

    // The tick itself, below the plot.
    ctx.strokeStyle = tick.ends ? "rgba(255, 255, 255, 0.35)" : "rgba(255, 255, 255, 0.18)";
    ctx.beginPath();
    ctx.moveTo(at, pad.top + h);
    ctx.lineTo(at, pad.top + h + (tick.ends ? 6 : 4));
    ctx.stroke();

    if (!tick.label) continue;

    ctx.fillStyle = tick.ends ? "#8b98a8" : "#66717f";
    ctx.textAlign = "center";
    ctx.fillText(tick.label, at, cssH - 8);
  }

  ctx.textAlign = "left";
  ctx.restore();
}

function drawLineChart(canvas, rows, series, options = {}) {
  rememberDraw(canvas, () => drawLineChart(canvas, rows, series, options));

  /*
   * Nothing is drawn into a canvas with no width.
   *
   * Drawing anyway produces a backing store sized for a box that is not the
   * one it will be shown in, and the result is stretched the moment it becomes
   * visible. The remembered redraw above puts it right.
   */
  if (canvas.clientWidth === 0) {
    return;
  }

  drawLegend(canvas, series);

  const dpr = window.devicePixelRatio || 1;
  const cssW = Math.max(300, canvas.clientWidth);
  const cssH = canvas.clientHeight || 260;
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);

  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, cssW, cssH);
  ctx.font = "12px system-ui";
  ctx.fillStyle = "#9a9a9a";
  ctx.strokeStyle = "#333";
  ctx.lineWidth = 1;

  const xKey = options.xKey || "taken_at";
  const pad = { left: 78, right: 16, top: 14, bottom: 34 };
  const h = cssH - pad.top - pad.bottom;

  const usable = rows.filter(r => series.some(s => Number.isFinite(Number(r[s.key]))));
  if (!usable.length) {
    /*
     * An empty chart shrinks rather than reserving its full height.
     *
     * A 440-pixel canvas holding one line of grey text is most of a screen of
     * nothing, and a page of those reads as broken rather than as quiet - which
     * is exactly how it was reported. The class takes the height down to the
     * message; removing it again on the next draw is what puts it back.
     */
    canvas.classList.add("chart-empty");
    ctx.fillText(options.empty || "Nothing collected for this range yet", pad.left, pad.top + 20);
    return;
  }

  canvas.classList.remove("chart-empty");

  /*
   * One scale per axis.
   *
   * A series says which side it belongs to. That is what lets disk space and
   * inodes share a chart: they are both "how much room is left" but one is
   * bytes and the other is a count, and forcing them onto one scale makes
   * whichever is smaller a flat line along the bottom.
   */
  const sides = ["left", "right"];
  const scales = {};
  for (const side of sides) {
    const mine = series.filter(s => (s.axis || "left") === side);
    if (!mine.length) continue;

    const values = [];
    for (const s of mine) {
      for (const r of usable) {
        const v = Number(r[s.key]);
        if (Number.isFinite(v)) values.push(v);
      }
    }
    if (!values.length) continue;

    let lo = Math.min(...values);
    let hi = Math.max(...values);

    /*
     * Scaled to the bulk of the readings, not to the worst one.
     *
     * This is the difference between a useful chart of changes and a flat line
     * with one spike on it. A twenty-gigabyte upload is four hundred times a
     * steady loss of fifty megabytes, so on a full-range axis the thing you are
     * looking for is a pixel high. Trimming the extremes puts the ordinary
     * readings back on a readable scale; the outliers are still drawn, clipped
     * at the edge, and counted underneath so nothing is hidden.
     */
    if (options.trim) {
      const sorted = [...values].sort((a, b) => a - b);
      const cut = Math.floor(sorted.length * options.trim);
      if (cut > 0 && sorted.length - cut > cut) {
        const trimmedLo = sorted[cut];
        const trimmedHi = sorted[sorted.length - 1 - cut];
        // Only worth doing when the extremes really are extreme; otherwise it
        // just crops a chart that was fine.
        if ((hi - lo) > (trimmedHi - trimmedLo) * 4) {
          lo = trimmedLo;
          hi = trimmedHi;
        }
      }
    }

    /*
     * Not pinned to zero unless asked.
     *
     * On a disk that is 92% full and losing a gigabyte a day, a zero-based axis
     * draws a flat line across the top of the one chart whose whole purpose is
     * to show the slope.
     */
    if (options.zeroBased) { lo = Math.min(0, lo); hi = Math.max(hi, options.max ?? hi); }

    /*
     * A chart of changes always shows zero.
     *
     * Zero is the reference the whole reading depends on - above it is space
     * coming back, below it is space going - and an axis that happens to
     * exclude it turns "steadily losing 85 MiB" into a flat line in the middle
     * of nowhere. It also stops a perfectly constant series collapsing to a
     * zero-height range whose tick labels are all the same number.
     */
    if (options.zeroLine) {
      lo = Math.min(0, lo);
      hi = Math.max(0, hi);
    }

    if (hi === lo) hi = lo + Math.max(1, Math.abs(lo) * 0.01);

    const axisFor = (side === "right" ? options.rightAxis : options.axis) || bytesAxis;
    const magnitude = Math.max(Math.abs(lo), Math.abs(hi));

    /*
     * Ticks picked in the unit they will be printed in.
     *
     * niceTicks rounds to 1, 2 or 5 times a power of ten, which is only nice if
     * the label is written in tens. Bytes are not: five billion is a perfectly
     * round decimal step and prints as "4.7 GiB", and a column of 0.0 / 4.7 /
     * 9.3 / 14.0 GiB is the kind of axis you have to decode rather than read.
     *
     * So the axis is asked what unit these numbers will be shown in, the range
     * is divided by it, and the ticks are chosen among those - 0, 5, 10, 15 GiB
     * rather than the same positions rendered awkwardly. Two passes because the
     * unit depends on a step and the step depends on the unit; the first guess
     * is only used to ask the question, and when the unit turns out to be 1 -
     * percentages, load averages - the guess was already the answer.
     */
    const guess = niceTicks(lo, hi, 5, Boolean(options.zeroBased));
    const unit = axisFor(guess.step, magnitude).scale || 1;
    const nice = unit === 1
      ? guess
      : niceTicks(lo / unit, hi / unit, 5, Boolean(options.zeroBased));

    const step = nice.step * unit;
    // The axis is told how big the numbers are as well as how far apart the
    // ticks are: the first picks the unit, the second picks the decimals.
    scales[side] = {
      ticks: nice.ticks.map(tick => tick * unit),
      step,
      min: nice.min * unit,
      max: nice.max * unit,
      ...axisFor(step, magnitude),
    };
  }

  if (!scales.left && !scales.right) {
    // Shrunk to the message; see the note in drawLineChart.
    canvas.classList.add("chart-empty");
    ctx.fillText(options.empty || "Nothing collected for this range yet", pad.left, pad.top + 20);
    return;
  }

  if (scales.right) pad.right = 76;
  const plotW = cssW - pad.left - pad.right;

  const t0 = Number(usable[0][xKey]);
  const t1 = Number(usable[usable.length - 1][xKey]);
  const single = t1 <= t0;
  const span = single ? 1 : t1 - t0;

  // A single reading has no time axis to speak of. Drawn at the left edge it
  // looks like a bug and its three identical date labels look like another, so
  // it goes in the middle with one label under it.
  const x = t => single
    ? pad.left + plotW / 2
    : pad.left + ((Number(t) - t0) / span) * plotW;
  const yOn = (side, v) => {
    const scale = scales[side] || scales.left;
    return pad.top + h - ((v - scale.min) / (scale.max - scale.min)) * h;
  };

  /*
   * Stretches with no readings, shaded before anything is drawn over them.
   *
   * Without this a gap is invisible: the line simply joins the reading before
   * to the reading after, which draws a confident straight edge across hours
   * that were never measured. Red for a restart, grey for a stretch the
   * collector missed while the machine kept running - the same distinction the
   * analysis makes, because they call for different responses.
   */
  for (const band of options.outages || []) {
    const x0 = x(Math.max(band.from, t0));
    const x1 = x(Math.min(band.to, t1));
    if (!(x1 > x0)) continue;

    ctx.save();
    ctx.fillStyle = band.kind === "restart"
      ? "rgba(220, 60, 60, 0.22)"
      : "rgba(150, 150, 150, 0.14)";
    ctx.fillRect(x0, pad.top, Math.max(1.5, x1 - x0), h);
    ctx.restore();
  }

  /*
   * Known restarts, as a line rather than a band.
   *
   * A reboot need not leave a measurable hole: if the collector resumes within
   * a minute, the gap is under the threshold and there is nothing to shade -
   * yet the machine did restart, and that is exactly the moment somebody
   * scanning a chart wants marked. A band of near-zero width would be
   * invisible, so these are drawn as a line at the instant itself.
   *
   * They come from `last` on the host, which knows about restarts the readings
   * cannot show - including any that happened before boot times were being
   * recorded at all.
   */
  /*
   * Restart marks default to whatever the page knows about, deliberately.
   *
   * Passing them per call meant five charts had them and four did not, which is
   * not a decision anybody made - it is the list nobody finished. A chart that
   * plots time against anything should say when the machine restarted, so the
   * default is "yes" and a caller that genuinely does not want them can pass an
   * empty array. This couples a drawing function to page state, which is a real
   * cost; the alternative is every future chart starting out wrong.
   */
  const restartsAt = options.marks ?? state.restarts ?? [];

  /*
   * Three kinds of mark, kept apart because they mean three different things.
   *
   *   restarts  the machine went away and came back
   *   found     the tool noticed something change - a watched value moved
   *   written   a person wrote down what they knew at the time
   *
   * The last two were briefly the same layer, which meant a chart passing its
   * own found-marks silently lost every human note on it. They are separate
   * arrays and drawn differently, so a chart can have both and a reader can
   * tell which is which.
   */
  const written = typeof noteState !== "undefined" && canvas.id
    ? marksForChart(canvas.id)
    : [];

  for (const at of restartsAt) {
    if (at < t0 || at > t1) continue;
    const mx = x(at);

    ctx.save();
    ctx.strokeStyle = "rgba(230, 90, 90, 0.85)";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 3]);
    ctx.beginPath();
    ctx.moveTo(mx, pad.top);
    ctx.lineTo(mx, pad.top + h);
    ctx.stroke();
    ctx.restore();

    // A solid cap at the top, so a dashed line crossing a busy chart still
    // reads as a marker rather than as another series.
    ctx.save();
    ctx.fillStyle = "rgba(230, 90, 90, 0.95)";
    ctx.fillRect(mx - 3, pad.top, 6, 3);
    ctx.restore();
  }

  /*
   * Something the tool noticed: a watched value moving, most often.
   *
   * Deliberately not the restart colour. A restart is the machine going away
   * and coming back; a noticed change is somebody else's software becoming a
   * different version underneath you. Both explain a chart bending, and
   * drawing them identically would make one look like the other.
   */
  for (const mark of options.notes ?? []) {
    const at = Number(mark.at ?? mark);
    if (at < t0 || at > t1) continue;
    const mx = x(at);

    ctx.save();
    ctx.strokeStyle = "rgba(120, 170, 255, 0.8)";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([2, 4]);
    ctx.beginPath();
    ctx.moveTo(mx, pad.top);
    ctx.lineTo(mx, pad.top + h);
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.fillStyle = "rgba(120, 170, 255, 0.95)";
    ctx.beginPath();
    ctx.moveTo(mx, pad.top);
    ctx.lineTo(mx - 4, pad.top + 6);
    ctx.lineTo(mx + 4, pad.top + 6);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    /*
     * What it changed to, on the chart.
     *
     * A dashed line says when something changed and nothing else, which leaves
     * the reader scrolling to a table to find out what - and then scrolling
     * back. The value goes on the mark. Ten characters, because that is enough
     * to tell 1.22.0 from 1.23.1 and short enough that four of them in a row
     * are still readable.
     *
     * Solid black behind it with a border rather than a tint: this sits on top
     * of plotted lines, and a label you have to read through a chart is worse
     * than no label.
     */
    if (mark.label) {
      const short = String(mark.label).slice(0, 10)
        + (String(mark.label).length > 10 ? "…" : "");

      ctx.save();
      ctx.font = "10px ui-monospace, SFMono-Regular, Menlo, monospace";
      const width = ctx.measureText(short).width + 8;

      // Flipped to the left of the line when it would run off the right edge.
      const left = mx + width > pad.left + plotW
        ? mx - width - 2
        : mx + 2;

      ctx.fillStyle = "#000";
      ctx.fillRect(left, pad.top + 8, width, 14);
      ctx.strokeStyle = "rgba(120, 170, 255, 0.9)";
      ctx.lineWidth = 1;
      ctx.strokeRect(left + .5, pad.top + 8.5, width - 1, 13);

      ctx.fillStyle = "rgba(190, 215, 255, 1)";
      ctx.textAlign = "left";
      ctx.textBaseline = "middle";
      ctx.fillText(short, left + 4, pad.top + 15);
      ctx.restore();
    }
  }

  /*
   * Something a person wrote down, in a third colour with a square cap.
   *
   * Drawn last so it sits on top: on a chart where somebody has explained the
   * bend, their explanation is the most important thing on it.
   */
  for (const mark of written) {
    const at = Number(mark.at);
    if (at < t0 || at > t1) continue;
    const mx = x(at);

    ctx.save();
    ctx.strokeStyle = "rgba(240, 190, 110, 0.75)";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([1, 3]);
    ctx.beginPath();
    ctx.moveTo(mx, pad.top);
    ctx.lineTo(mx, pad.top + h);
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.fillStyle = "rgba(240, 190, 110, 0.95)";
    ctx.fillRect(mx - 3, pad.top, 6, 6);
    ctx.restore();
  }

  // Gridlines follow the left axis; the right one only gets labels, or two
  // sets of lines cross each other and the chart turns into a net.
  const gridding = scales.left || scales.right;
  const gridSide = scales.left ? "left" : "right";
  for (const value of gridding.ticks) {
    const yy = yOn(gridSide, value);
    if (yy < pad.top - 1 || yy > pad.top + h + 1) continue;
    ctx.beginPath();
    ctx.moveTo(pad.left, yy);
    ctx.lineTo(pad.left + plotW, yy);
    ctx.stroke();
  }

  /*
   * A brighter line at zero when the values can be negative.
   *
   * On a chart of changes the sign is the whole message, and telling above from
   * below by reading the axis labels is work the chart should be doing.
   */
  if (options.zeroLine && gridding.min < 0 && gridding.max > 0) {
    const zero = yOn(gridSide, 0);
    ctx.save();
    ctx.strokeStyle = "#6a6a6a";
    ctx.beginPath();
    ctx.moveTo(pad.left, zero);
    ctx.lineTo(pad.left + plotW, zero);
    ctx.stroke();
    ctx.restore();
  }

  ctx.textAlign = "right";
  if (scales.left) {
    for (const value of scales.left.ticks) {
      const yy = yOn("left", value);
      if (yy < pad.top - 1 || yy > pad.top + h + 1) continue;
      ctx.fillText(scales.left.format(value), pad.left - 8, yy + 4);
    }
  }
  ctx.textAlign = "left";
  if (scales.right) {
    for (const value of scales.right.ticks) {
      const yy = yOn("right", value);
      if (yy < pad.top - 1 || yy > pad.top + h + 1) continue;
      ctx.fillText(scales.right.format(value), pad.left + plotW + 8, yy + 4);
    }
  }

  /*
   * The time axis: marks on calendar boundaries, worded to suit the step.
   *
   * See timeTicks. The short version is that "start, middle, end" was three
   * arbitrary instants, and an axis should land on places a person recognises -
   * the hour, midnight, the first of the month.
   */
  if (single) {
    ctx.textAlign = "center";
    ctx.fillStyle = "#8b98a8";
    ctx.fillText(
      new Date(t0 * 1000).toLocaleString([],
        { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }),
      pad.left + plotW / 2,
      cssH - 8
    );
    ctx.textAlign = "left";
  } else {
    const axis = timeTicks(t0, t1, plotW, text => ctx.measureText(text).width);
    drawTimeAxis(ctx, axis.ticks, pad, plotW, h, cssH);
  }

  /*
   * The lines stay inside the plot.
   *
   * Without this a value below the axis floor - a load average the axis has
   * clamped at zero, a spike past the top between two redraws - is drawn over
   * the date labels and the legend, which looks like a rendering fault rather
   * than data out of range.
   */
  ctx.save();
  ctx.beginPath();
  ctx.rect(pad.left, pad.top - 2, plotW, h + 4);
  ctx.clip();

  series.forEach((s, si) => {
    const side = (s.axis || "left") in scales ? (s.axis || "left") : Object.keys(scales)[0];
    ctx.strokeStyle = seriesColor(si);
    ctx.fillStyle = seriesColor(si);
    ctx.lineWidth = 2;
    // A dashed line for the right-hand axis, so which series belongs to which
    // set of numbers survives being printed, or being looked at quickly.
    ctx.setLineDash(side === "right" ? [5, 4] : []);
    ctx.beginPath();

    let started = false;
    for (const r of usable) {
      const v = Number(r[s.key]);
      if (!Number.isFinite(v)) { started = false; continue; }
      const xx = x(r[xKey]);
      const yy = yOn(side, v);
      if (started) ctx.lineTo(xx, yy); else ctx.moveTo(xx, yy);
      started = true;
    }
    ctx.stroke();
    ctx.setLineDash([]);

    if (usable.length <= 80) {
      for (const r of usable) {
        const v = Number(r[s.key]);
        if (!Number.isFinite(v)) continue;
        ctx.beginPath();
        ctx.arc(x(r[xKey]), yOn(side, v), 2.2, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  });

  ctx.restore();
}

/* -------------------------------------------------------------------- pie -- */

/*
 * A palette wide enough for every slice.
 *
 * The line-chart palette holds five, which is plenty for five lines and wrong
 * for a pie: at six slices the sixth is handed the first colour again, and two
 * identical wedges make the labels look shuffled. Ten distinct hues, because
 * the pie draws at most ten named slices before folding the rest away.
 */
const PIE_COLORS = [
  "#73b7ff", "#ffb86b", "#75d58a", "#d5a6ff", "#ff7f9f",
  "#4fd6d2", "#f5d76e", "#a0a8ff", "#ff9d6b", "#8fd67a",
];

/** The most named slices before the rest are folded into one. */
const PIE_MAX_SLICES = 10;

/** Text on a coloured wedge, dark or light by how bright the wedge is. */
function inkOn(hex) {
  const n = parseInt(hex.slice(1), 16);
  // Rec. 601 luma: green carries most of perceived brightness, blue least.
  const luma = (((n >> 16) & 255) * 299 + ((n >> 8) & 255) * 587 + (n & 255) * 114) / 1000;
  return luma > 140 ? "#111" : "#f0f0f0";
}

/**
 * A pie of memory by service, with the long tail as one slice.
 *
 * **Drawn from PSS, and it has to be.** A pie asserts that its slices make up a
 * whole, and resident memory cannot: a page shared by ten processes is counted
 * ten times, so the parts add up to more than the machine has and every
 * percentage is inflated by an amount that varies per slice. Proportional set
 * size divides shared pages among their holders, which is exactly the property
 * a pie needs.
 *
 * Slices large enough to hold text carry their own share and size, so the list
 * beside the circle only has to name things. The ones too narrow to write in
 * keep their figures in the list instead - nothing is only ever readable in one
 * place.
 */
function drawPieChart(canvas, slices, options = {}) {
  /*
   * Remembered like every other chart.
   *
   * Without this, redrawCharts treats the canvas as one nothing ever drew into
   * and resizes it to its box - which clears it. The pie was painting
   * correctly and then being wiped by the tidy-up pass a moment later.
   */
  rememberDraw(canvas, () => drawPieChart(canvas, slices, options));
  if (canvas.clientWidth === 0) return;

  const dpr = window.devicePixelRatio || 1;
  const cssW = Math.max(240, canvas.clientWidth);
  const cssH = canvas.clientHeight || 300;
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);

  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, cssW, cssH);
  ctx.font = "12px system-ui";
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";

  const total = slices.reduce((sum, s) => sum + Math.max(0, s.value), 0);
  if (!slices.length || total <= 0) {
    ctx.fillStyle = "#9a9a9a";
    ctx.fillText(options.empty || "Nothing to show yet", 12, 24);
    drawLegend(canvas, []);
    return;
  }

  const shareOf = slice => Math.max(0, slice.value) / total;
  const percentText = share => `${share >= 0.1 ? (share * 100).toFixed(0) : (share * 100).toFixed(1)}%`;

  /*
   * The circle and its list are centred as one block.
   *
   * Sizing the circle against half the canvas and starting at the left edge
   * leaves the whole right side empty on a wide panel, which reads as a chart
   * that failed to fill its space.
   */
  const radius = Math.max(40, Math.min(cssW / 3, cssH) / 2 - 10);
  const labelGap = 20;

  /*
   * A second measurement of the same whole, drawn inside the first.
   *
   * Used where two partitions overlap and cannot honestly share one set of
   * wedges - file types and watched categories count the same log file twice.
   * As two concentric rings against the same total, each ring is internally
   * correct and the eye can still compare a category against the disk it sits
   * on, which is the actual question.
   */
  const inner = (options.inner || []).filter(slice => slice.value > 0);
  const hole = inner.length ? radius * 0.56 : 0;

  /*
   * A slice writes inside itself only if the text actually fits.
   *
   * A share threshold alone is a guess about pixels: at 8% two neighbouring
   * wedges are each narrower than the words placed in them, and the labels
   * collide across the boundary. The wedge's width at the text's radius is a
   * chord - 2r·sin(θ/2) - so it can simply be measured against the widest of
   * the two lines, and the answer holds at any canvas size.
   */
  /*
   * Text goes in the middle of the band it labels.
   *
   * With a hole punched for the inner ring, 0.62r is inside the hole - so every
   * outer label drifted off its own wedge and sat over the ring below it. The
   * band runs from `hole` to `radius`, and its midpoint is where the words
   * belong. Set after `hole` is known, which is why this is not a constant.
   */
  const textRadius = hole > 0 ? (hole + radius) / 2 : radius * 0.62;

  // "both" writes the share and the size, "percent" only the share, "none"
  // leaves both to the list. Degrading through the middle case labels a good
  // many more wedges than an all-or-nothing test at the same width.
  const inside = slices.map(slice => {
    const share = shareOf(slice);
    if (share < 0.04) {
      return "none";
    }

    const sweep = share * Math.PI * 2;
    // The chord at the text's own radius, which is where the words will sit.
    const available = 2 * textRadius * Math.sin(Math.min(sweep, Math.PI) / 2);

    // A ring is only so thick; two lines of text will not fit in a thin band
    // however wide the wedge is.
    const band = hole > 0 ? radius - hole : radius;

    ctx.font = "bold 13px system-ui";
    const percentWidth = ctx.measureText(percentText(share)).width;
    ctx.font = "11px system-ui";
    const sizeWidth = ctx.measureText(humanBytes(slice.value)).width;
    ctx.font = "12px system-ui";

    if (band >= 30 && available >= Math.max(percentWidth, sizeWidth) + 8) return "both";
    if (available >= percentWidth + 8) return "percent";
    return "none";
  });

  // What the list has to say for each slice, given what the wedge already does.
  const listText = slices.map((slice, i) => {
    if (inside[i] === "both") return slice.label;
    if (inside[i] === "percent") return `${slice.label} — ${humanBytes(slice.value)}`;
    return `${slice.label} — ${humanBytes(slice.value)} (${percentText(shareOf(slice))})`;
  });

  const widest = listText.reduce(
    (wide, text) => Math.max(wide, ctx.measureText(text).width + 16),
    0
  );

  const left = Math.max(0, (cssW - (radius * 2 + labelGap + widest)) / 2);
  const cx = left + radius;
  const cy = cssH / 2;

  let angle = -Math.PI / 2;
  slices.forEach((slice, i) => {
    const share = shareOf(slice);
    const sweep = share * Math.PI * 2;
    const color = slice.color || PIE_COLORS[i % PIE_COLORS.length];

    ctx.beginPath();
    if (hole > 0) {
      // A ring rather than a wedge, leaving room for the second measurement
      // in the middle. Same angles, so the two rings stay comparable.
      ctx.arc(cx, cy, radius, angle, angle + sweep);
      ctx.arc(cx, cy, hole, angle + sweep, angle, true);
    } else {
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, radius, angle, angle + sweep);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();

    /*
     * A hairline between slices, in the panel's own background.
     *
     * Two adjacent colours of similar lightness read as one wedge without it,
     * which is how a pie quietly under-reports the number of things in it.
     */
    ctx.strokeStyle = "#161616";
    ctx.lineWidth = 1.5;
    ctx.stroke();

    if (inside[i] !== "none") {
      const mid = angle + sweep / 2;
      const tx = cx + Math.cos(mid) * textRadius;
      const ty = cy + Math.sin(mid) * textRadius;
      const both = inside[i] === "both";

      ctx.save();
      ctx.textAlign = "center";
      ctx.fillStyle = inkOn(color);
      ctx.font = "bold 13px system-ui";
      ctx.fillText(percentText(share), tx, both ? ty - 1 : ty + 4);
      if (both) {
        ctx.font = "11px system-ui";
        ctx.fillText(humanBytes(slice.value), tx, ty + 13);
      }
      ctx.restore();
    }

    angle += sweep;
  });

  // The list runs down the right in slice order, so the eye can follow it round.
  const labelX = cx + radius + labelGap;
  const lineHeight = 18;
  const startY = cy - ((slices.length + inner.length) * lineHeight) / 2;

  slices.forEach((slice, i) => {
    const y = startY + i * lineHeight;
    if (y < 12 || y > cssH - 4) return;

    const color = slice.color || PIE_COLORS[i % PIE_COLORS.length];
    ctx.fillStyle = color;
    ctx.fillRect(labelX, y - 8, 10, 10);

    ctx.fillStyle = "#ddd";
    ctx.fillText(listText[i], labelX + 16, y + 1);
  });

  if (inner.length) {
    /*
     * The inner ring shares the outer ring's denominator.
     *
     * Rescaling it to its own sum would make three categories covering a tenth
     * of the disk fill the whole circle - which is precisely the exaggeration
     * this panel exists to avoid. What is left over is drawn in the panel's own
     * background so it reads as absence rather than as another category.
     */
    let innerAngle = -Math.PI / 2;
    const named = inner.reduce((sum, slice) => sum + slice.value, 0);
    const parts = [...inner, {
      label: ZogographI18n.t("chart.everything_else"), value: Math.max(0, total - named), quiet: true,
    }];

    for (const slice of parts) {
      const sweep = (slice.value / total) * Math.PI * 2;
      if (sweep <= 0) continue;

      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, hole - 3, innerAngle, innerAngle + sweep);
      ctx.closePath();
      /*
       * The remainder is drawn, not left out.
       *
       * In the panel background it read as a hole in the page rather than as a
       * measured quantity, and a hole invites the eye to look through it. A
       * muted fill of its own says "this is the part none of these cover",
       * which is what it is.
       */
      ctx.fillStyle = slice.quiet ? "#2b3542" : (slice.color || "#8899aa");
      ctx.fill();

      ctx.strokeStyle = "#161616";
      ctx.lineWidth = 1.5;
      ctx.stroke();

      innerAngle += sweep;
    }

    let y = startY + slices.length * lineHeight + 6;
    for (const slice of parts) {
      if (y > cssH - 4) break;
      ctx.fillStyle = slice.quiet ? "#2b3542" : (slice.color || "#8899aa");
      ctx.fillRect(labelX, y - 8, 10, 10);
      ctx.fillStyle = "#ddd";
      ctx.fillText(
        `${slice.label} — ${humanBytes(slice.value)} `
          + `(${percentText(slice.value / total)})`,
        labelX + 16, y + 1
      );
      y += lineHeight;
    }
  }

  // The canvas carries its own labels, so the shared legend would repeat them.
  drawLegend(canvas, []);
}

/**
 * Slices for the memory pie: the biggest few, then one slice for all the rest.
 *
 * Capped by count as well as by share. A machine running thirty things each
 * taking two percent would otherwise produce thirty wedges, none of which can
 * be told apart or written in, which is a picture of nothing.
 */
function memorySlices(services, measuredTotal, options = {}) {
  const threshold = options.threshold ?? 0.01;
  const most = options.most ?? PIE_MAX_SLICES;

  const rows = services
    .map(s => ({ label: s.name, value: Number(s.pss_bytes) || 0 }))
    .filter(s => s.value > 0)
    .sort((a, b) => b.value - a.value);

  /*
   * The denominator is the measured total, not the sum of these rows.
   *
   * Only the biggest services are recorded, and PSS itself is measured for the
   * biggest processes, so summing the visible rows would quietly rescale every
   * percentage to make the visible part look like the whole machine.
   */
  const total = measuredTotal > 0 ? measuredTotal : rows.reduce((sum, r) => sum + r.value, 0);
  if (total <= 0) return [];

  const big = rows.filter(r => r.value / total >= threshold).slice(0, most);
  const rest = total - big.reduce((sum, r) => sum + r.value, 0);

  const slices = big.slice();
  if (rest > 0) {
    const hidden = rows.length - big.length;
    slices.push({
      label: hidden > 0 ? `Everything else (${count(hidden, "service")})` : "Everything else",
      value: rest,
      // Deliberately grey: it is the part with no answer in it, and colouring
      // it like a service invites reading it as one.
      color: "#4a4a4a",
    });
  }

  return slices;
}

/* ------------------------------------------------------------------ table -- */

/** How many rows of a table are drawn before "show more" appears. */
const TABLE_PAGE = 25;

/*
 * Turns whatever a column renders into something a spreadsheet can hold.
 *
 * The render functions return DOM nodes as often as strings - a struck-through
 * size, a link, a tooltip - and an export that wrote "[object HTMLSpanElement]"
 * would be worse than no export. textContent is what the reader actually saw.
 */
function cellText(column, row) {
  const value = column.render ? column.render(row) : row[column.key] ?? "";
  if (value instanceof Node) return value.textContent ?? "";
  return String(value ?? "");
}

function downloadFile(name, text, type) {
  const blob = new Blob([text], { type });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = name;
  document.body.appendChild(link);
  link.click();
  link.remove();
  // Revoked on the next turn of the loop: revoking immediately races the
  // download in some browsers and silently produces an empty file.
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/*
 * Exports what is on screen, not what the server holds.
 *
 * Deliberately: the table has already had filters, a range and a sort applied,
 * and an export that quietly returned something else would be a different
 * answer wearing the same name.
 */
function exportRows(target, rows, columns, format) {
  const headers = columns.map(c => c.label).filter(Boolean);
  const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-");
  const name = `zogograph-${target}-${stamp}.${format}`;

  if (format === "json") {
    const out = rows.map(row => {
      const item = {};
      for (const column of columns) {
        if (!column.label) continue;
        item[column.label] = cellText(column, row);
      }
      return item;
    });
    downloadFile(name, JSON.stringify(out, null, 2), "application/json");
    return;
  }

  const quote = value => `"${String(value).replace(/"/g, '""')}"`;
  const lines = [headers.map(quote).join(",")];
  for (const row of rows) {
    lines.push(columns.filter(c => c.label).map(c => quote(cellText(c, row))).join(","));
  }
  // A BOM, so Excel opens UTF-8 as UTF-8 rather than as mojibake.
  downloadFile(name, "\uFEFF" + lines.join("\r\n"), "text/csv;charset=utf-8");
}

/*
 * How far each table has been unfolded, by the id it renders into.
 *
 * Outside renderTable because renderTable is called afresh every poll: state
 * kept inside it lives exactly as long as the table it is meant to outlive.
 */
const TABLE_SHOWN = new Map();

/*
 * What each table last drew, so an unchanged poll can leave it alone.
 *
 * Rebuilding a table that has not changed destroys the reader's text selection,
 * scroll position inside it and any focus in it - every few seconds, for as
 * long as they sit on the page. Since the rows are plain data from the server,
 * "has it changed" is a comparison rather than a guess.
 */
const TABLE_DREW = new Map();

/*
 * The rows each table last drew, so a changed one can be patched rather than
 * rebuilt. Parallel to TABLE_DREW, which answers "did anything change at all".
 */
const TABLE_STATE = new Map();

/*
 * Rewrites the cells of an existing table, leaving the table itself alone.
 *
 * For the panels whose numbers move every poll - disk rates, process I/O - the
 * data genuinely changes, so the "nothing changed" skip cannot help and the
 * table was being torn down and rebuilt every couple of seconds. That is what
 * the flicker and the jumping were: not the numbers moving, but the whole
 * element being replaced under the reader.
 *
 * Only safe when these are the same rows in the same order, which is what `key`
 * decides. When a process appears or disappears the identity changes and a real
 * rebuild happens - at that point the table genuinely is different, and
 * pretending otherwise would put one process's rate against another's pid.
 *
 * Returns false when it cannot be done, so the caller falls back.
 */
function patchTable(target, rows, columns, key, rowClass) {
  const previous = TABLE_STATE.get(target);
  if (!previous || !previous.keys || !key) return false;

  const el = $(target);
  const body = el.querySelector("tbody");
  if (!body) return false;

  const keys = rows.map(key);
  if (keys.length !== previous.keys.length) return false;
  if (previous.labels.join("\u0000") !== columns.map(c => c.label).join("\u0000")) return false;
  if (keys.some((k, i) => k !== previous.keys[i])) return false;

  // Only the rows actually on screen; the rest are drawn when unfolded.
  const drawn = body.rows.length;
  if (drawn > rows.length) return false;

  for (let i = 0; i < drawn; i++) {
    const tr = body.rows[i];
    const row = rows[i];
    if (tr.cells.length !== columns.length) return false;

    if (rowClass) {
      const wanted = rowClass(row);
      if (tr.className !== wanted) tr.className = wanted;
    }

    for (let c = 0; c < columns.length; c++) {
      const col = columns[c];
      const td = tr.cells[c];
      const content = col.render ? col.render(row) : row[col.key] ?? "";

      if (content instanceof Node) {
        /*
         * A rendered node is compared by what it reads as.
         *
         * Replacing a cell whose text is identical is the same flicker one cell
         * at a time, and it would throw away a checkbox the reader had just
         * ticked. Text equality is not a perfect test, but a cell whose text is
         * unchanged and whose meaning is not is a cell this table cannot draw
         * usefully anyway.
         */
        if (td.childElementCount && td.textContent === content.textContent) continue;
        td.replaceChildren(content);
        continue;
      }

      const text = String(content);
      if (td.textContent !== text) td.textContent = text;
    }
  }

  TABLE_STATE.set(target, { keys, labels: columns.map(c => c.label) });
  return true;
}

function renderTable(target, rows, columns, onRowClick, rowClass, key) {
  const el = $(target);
  if (!rows || !rows.length) {
    if (TABLE_DREW.get(target) !== "empty") {
      TABLE_DREW.set(target, "empty");
      el.replaceChildren(Object.assign(document.createElement("p"), {
        className: "muted", textContent: ZogographI18n.t("table.nothing_to_show", {}, "Nothing to show."),
      }));
    }
    return;
  }

  /*
   * The signature covers the data and the shape, not the rendered nodes.
   *
   * The column list is part of it because the same target is reused with
   * different columns - the offender table changes its columns with the view -
   * and identical rows under different headings are a different table.
   */
  /*
   * The data and the shape, and deliberately not how far it is unfolded.
   *
   * Folding the row count in seemed right and was wrong: the count is set by
   * draw() *after* the signature is taken, so the first render stored 0 and
   * every render after it computed 25 - a guaranteed mismatch that made the
   * comparison useless without ever failing visibly. Unfolding further sets
   * TABLE_DREW to null explicitly, which is the honest way to say "this one
   * really has changed".
   */
  const signature = JSON.stringify([rows, columns.map(c => c.label)]);
  if (TABLE_DREW.get(target) === signature && el.querySelector("table")) {
    return;
  }

  // Same rows, different numbers: rewrite the cells rather than the table.
  if (patchTable(target, rows, columns, key, rowClass)) {
    TABLE_DREW.set(target, signature);
    return;
  }

  TABLE_DREW.set(target, signature);

  const tools = document.createElement("div");
  tools.className = "table-tools";

  const counter = document.createElement("span");
  tools.appendChild(counter);

  const spacer = document.createElement("span");
  spacer.className = "spacer";
  tools.appendChild(spacer);

  for (const format of ["csv", "json"]) {
    const button = document.createElement("button");
    button.className = "link";
    button.textContent = format.toUpperCase();
    button.title = ZogographI18n.t("table.download_rows", { count: rows.length, format: format.toUpperCase() }, "Download {{count, number}} rows as {{format}}");
    button.addEventListener("click", () => exportRows(target, rows, columns, format));
    tools.appendChild(button);
  }

  const table = document.createElement("table");
  const head = table.createTHead().insertRow();
  for (const col of columns) {
    const th = document.createElement("th");
    if (col.onSort) {
      const button = document.createElement("button");
      button.className = "link table-sort";
      button.textContent = col.label + (col.sortMark || "");
      button.title = ZogographI18n.t("table.sort_by", { label: col.label }, "Sort by {{label}}");
      button.addEventListener("click", col.onSort);
      th.appendChild(button);
    } else th.textContent = col.label;
    if (col.className) th.className = col.className;
    head.appendChild(th);
  }

  const body = table.createTBody();
  let shown = 0;

  const addRow = row => {
    const tr = body.insertRow();
    // A row can say something about itself - read or unread, healthy or not -
    // without that being a column of its own.
    if (rowClass) tr.className = rowClass(row);
    if (onRowClick) {
      tr.classList.add("clickable");
      tr.addEventListener("click", event => {
        if (event.target.closest("button")) return;
        onRowClick(row);
      });
    }
    for (const col of columns) {
      const td = tr.insertCell();
      if (col.className) td.className = col.className;
      const content = col.render ? col.render(row) : row[col.key] ?? "";
      if (content instanceof Node) td.appendChild(content);
      else td.textContent = content;
    }
  };

  const more = document.createElement("button");
  more.className = "table-more";

  const draw = () => {
    const next = rows.slice(shown, shown + TABLE_PAGE);
    next.forEach(addRow);
    shown += next.length;
    // Remembered against the table's id, so the next poll can put it back.
    TABLE_SHOWN.set(target, shown);

    counter.textContent = shown >= rows.length
      ? ZogographI18n.t("table.rows_total", { count: rows.length }, "{{count, number}} rows")
      : ZogographI18n.t("table.rows_shown", { shown, total: rows.length }, "Showing {{shown, number}} of {{total, number}} rows");

    more.hidden = shown >= rows.length;
    more.textContent = ZogographI18n.t("table.show_more", { count: Math.min(TABLE_PAGE, rows.length - shown) }, "Show {{count, number}} more");
  };

  /*
   * However far it was unfolded before, again.
   *
   * The poll rebuilds every table from scratch, which threw away how many rows
   * were on screen - so "Show 25 more" expanded and then collapsed a second
   * later when the next refresh landed. Restoring the count rather than the
   * rows keeps it correct when the data underneath has changed.
   */
  const wanted = Math.min(TABLE_SHOWN.get(target) || 0, rows.length);
  do { draw(); } while (shown < wanted && shown < rows.length);

  const remember = () => TABLE_STATE.set(target, {
    keys: key ? rows.map(key) : null,
    labels: columns.map(c => c.label),
  });
  remember();

  more.addEventListener("click", () => {
    draw();
    remember();
    /*
     * Only a click invalidates the signature.
     *
     * Doing it inside draw() meant every render - including the first - wiped
     * the record of what had just been drawn, so the "nothing changed" test
     * could never once succeed and every poll rebuilt every table.
     */
    TABLE_DREW.set(target, null);
  });

  el.replaceChildren(tools, table, more);

  // Whether this one needs to scroll sideways can only be known once it is in
  // the document with a width.
  markWideTables(el.parentElement ?? document);
}

/**
 * The Scan now button, and what it says about a scan in flight.
 *
 * A scan takes minutes, so the button has to show that something is happening -
 * otherwise the only feedback is a table that changes some time later, and
 * people press it again.
 */
function syncScanButton(overview) {
  const button = $("scanNow");
  if (!state.signedIn) {
    button.hidden = true;
    return;
  }
  button.hidden = false;

  const running = overview.scan_running;
  button.disabled = Boolean(running);
  button.textContent = running
    ? ZogographI18n.t("storage.scanning", { elapsed: humanDuration(Date.now() / 1000 - running.started_at) }, "Scanning… ({{elapsed}})")
    : ZogographI18n.t("storage.scan_now", {}, "Scan now");
}

/** Keeps the category filter in step with the rules the server is using. */
function syncCategoryOptions() {
  const select = $("offCategory");
  const wanted = ["", ...state.categories];
  const have = [...select.options].map(o => o.value);
  if (have.length === wanted.length && have.every((v, i) => v === wanted[i])) {
    return;
  }

  const chosen = select.value;
  select.replaceChildren(...wanted.map(value => {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = value === ""
      ? ZogographI18n.t("filter.all", {}, "All")
      : value.charAt(0).toUpperCase() + value.slice(1);
    return option;
  }));
  if (wanted.includes(chosen)) select.value = chosen;
}

/** First-run guidance vanishes only once the underlying evidence exists. */
function renderOnboarding(overview) {
  const panel = $("onboarding");
  const body = $("onboardingBody");
  const missingVitals = !overview.vitals;
  const missingScan = !overview.scan;
  panel.hidden = !missingVitals && !missingScan;
  if (panel.hidden) return;

  const intro = document.createElement("p");
  intro.className = "muted small";
  intro.textContent = ZogographI18n.t("onboarding.intro", {}, "Zogograph is configured but does not yet have enough local evidence to show its full dashboard.");
  const list = document.createElement("ol");
  list.className = "onboarding-list";
  const step = (text, href, label) => {
    const item = document.createElement("li");
    item.append(document.createTextNode(text));
    const link = document.createElement("a");
    link.href = href;
    link.textContent = label;
    item.appendChild(link);
    list.appendChild(item);
  };
  if (missingVitals) {
    step(
      ZogographI18n.t("onboarding.vitals_missing", {}, "Set up or run the account collector for its first vital reading."),
      "./setup.php?section=schedule",
      ZogographI18n.t("onboarding.open_schedule", {}, "Open Setup schedule"),
    );
  } else {
    step(
      ZogographI18n.t("onboarding.vitals_ready", {}, "Vital readings are arriving. Keep the collector scheduled so charts can build history."),
      "./setup.php?section=schedule",
      ZogographI18n.t("onboarding.review_schedule", {}, "Review Setup schedule"),
    );
  }
  if (missingScan) {
    step(
      ZogographI18n.t("onboarding.scan_missing", {}, "Run the first storage scan to identify what uses space."),
      "#/storage",
      ZogographI18n.t("onboarding.open_storage", {}, "Open Storage"),
    );
  } else {
    step(
      ZogographI18n.t("onboarding.scan_ready", {}, "The first storage scan is complete. Review the largest items and set alerts when ready."),
      "#/storage-files",
      ZogographI18n.t("onboarding.review_storage", {}, "Review storage"),
    );
  }
  body.replaceChildren(intro, list);
}

/* ------------------------------------------------------------------ views -- */

/*
 * The parts every view needs, whichever one is on screen.
 *
 * Session state drives the sign-in button, the alert count drives the
 * navigation badges, and both are visible from everywhere - so they refresh
 * with the poll regardless of which view asked for it. Everything else belongs
 * to a view and is fetched only when that view is showing.
 */
async function refreshShared() {
  const overview = await api("overview");

  state.signedIn = overview.signed_in;
  ZogographI18n.setBrand(overview.brand);
  state.csrf = overview.csrf;
  state.access = overview.access || null;
  state.account = overview.account ?? state.account;
  state.deletable = overview.deletable || [];
  state.deletableScope = overview.deletable_scope || "account";
  state.totals = overview.totals || {};
  state.emptied = overview.emptied || {};
  state.viewable = overview.viewable || [];
  state.categories = overview.categories ?? [];
  applyCoreFeatureVisibility(overview.core_features);

  /*
   * The newest summary, on the front page.
   *
   * Drawn from the shared refresh so it is there whichever page somebody
   * opens on - and hidden entirely when there is none, rather than leaving an
   * empty panel to explain.
   */
  renderLatestReport(overview.report ?? null);

  const wasScanning = state.scanRunning;
  state.scanRunning = Boolean(overview.scan_running);

  applySignedInChrome();
  syncRangeAccess();
  syncLiveAvailability();
  syncCategoryOptions();
  syncScanButton(overview);
  renderOnboarding(overview);

  state.overview = overview;
  state.lastReadingAt = overview.vitals ? Number(overview.vitals.taken_at) : null;
  renderLastSeen();
  renderBroadcasts(overview.broadcasts || []);

  /*
   * The name in the menu, before anybody opens the chat.
   *
   * The portrait is deliberately not carried here - it is a URL nobody needs
   * until the panel is open, and this call is made by every page on every
   * poll.
   */
  if (overview.who) {
    chatState.who.name = overview.who.name;
    chatState.who.emoji = overview.who.emoji;
    renderChatIdentity();
  }
  // Once per session; the definitions come from the server so the names the
  // user sees and the names the model is given cannot drift.
  loadChartNames().catch(() => {});

  /*
   * The host collector's clock, and whether anything it owes has arrived.
   *
   * Done here rather than per page because both belong to every page: the ring
   * is in the top bar, and a result you asked for twenty minutes ago should
   * announce itself wherever you happen to be standing when it lands.
   */
  const clock = overview.host_clock || {};
  const showHostClock = benefitsFromCollector("host");
  const showAccountClock = benefitsFromCollector("account");
  const arrived = hostClock.lastAt !== null
    && clock.last_at !== null
    && Number(clock.last_at) > hostClock.lastAt;

  hostClock.lastAt = showHostClock && clock.last_at !== null ? Number(clock.last_at) : null;
  hostClock.interval = showHostClock && clock.interval !== null ? Number(clock.interval) : null;
  accountClock.lastAt = showAccountClock && clock.account_last_at !== null ? Number(clock.account_last_at) : null;
  accountClock.interval = showAccountClock && clock.account_interval !== null ? Number(clock.account_interval) : null;
  drawPoll();

  // Announced before the list is replaced, so it can see what has just gone.
  if (showHostClock && arrived) noticeHostArrival();
  renderPending(showHostClock ? (clock.pending || []) : []);

  if (wasScanning && !state.scanRunning) {
    notice("Scan finished.", true);
    // A finished scan changes what Storage shows, wherever you are standing.
    state.rendered.delete("storage");
    if (state.view === "storage") await VIEWS.storage.refresh();
  }

  await refreshBadges();
}

/*
 * The counts behind the navigation badges.
 *
 * Deliberately small queries. The whole point of one view at a time is not
 * paying for the other seven, and a badge that cost a full panel refresh would
 * put all of it back.
 */
async function refreshBadges() {
  if (disabledCoreRoutes.has("alerts")) {
    alertState.rows = [];
    setBadge("alerts", 0);
    renderAlertBanner([]);
  } else try {
    const alerts = await api("alerts", { limit: 200 });
    alertState.rows = alerts.rows;

    /*
     * Unread, not "raised in the last day".
     *
     * A badge counting the last day counts the same alert every time you look
     * at it, so the only way to clear it is to wait. That teaches people to
     * ignore the number, which is the one thing a badge must not do.
     */
    const unread = alerts.rows.filter(r => !r.acknowledged_at);
    const critical = unread.filter(r => r.severity === "critical" && !r.silenced).length;
    const silenced = unread.filter(r => r.silenced).length;

    /*
     * Silenced alerts are still unread and still counted.
     *
     * Deliberately: something the assistant held back is still something that
     * happened, and a count that quietly excluded them would make the badge
     * lie about how much there is to look at. What changes is the colour - a
     * badge made red by alerts nobody was woken for is a badge that cries wolf.
     */
    setBadge("alerts", unread.length, critical ? "crit" : "warn");

    const badge = document.querySelector('[data-badge="alerts"]');
    if (badge && silenced) {
      badge.title = `${count(unread.length, "unread alert")}, `
        + `${silenced} of which ${silenced === 1 ? "was" : "were"} held back by `
        + `${chatState.who.name}.`;
    }
    renderAlertBanner(unread);
  } catch {
    setBadge("alerts", 0);
  }

  if (!state.signedIn) {
    setBadge("system", 0);
    return;
  }

  if (disabledCoreRoutes.has("sys-problems")) {
    setBadge("system", 0);
    setBadge("sys-problems", 0);
    return;
  }

  try {
    const problems = await api("problems", { limit: 1 });
    const total = Number(problems.total || 0);
    const [tone, icon, meaning] = PROBLEM_MARKS[problems.worst] ?? ["warn", "", ""];

    setBadge("system", total, tone, icon);
    // And on the page itself, which is where somebody goes to act on it.
    setBadge("sys-problems", total, tone, icon);

    for (const view of ["system", "sys-problems"]) {
      const el = document.querySelector(`[data-badge="${view}"]`);
      if (el && total) {
        el.title = `${count(total, "kind of problem", "kinds of problem")} in the log`
          + (meaning ? `, the worst being ${meaning}` : "")
          + (problems.by_level
            ? `.\n${Object.entries(problems.by_level)
                .map(([name, n]) => `${n} ${name}`).join(", ")}`
            : ".");
      }
    }
  } catch {
    setBadge("system", 0);
    setBadge("sys-problems", 0);
  }
}

/*
 * The overview: cards and the vitals charts.
 *
 * Uptime is fetched alongside rather than after, because the charts need its
 * restart marks at the moment they draw. Fetched later, the marks were simply
 * absent on load and appeared at some subsequent refresh, which looks exactly
 * like the feature not working.
 */
async function refreshVitals() {
  const to = state.frozenAt || Math.floor(Date.now() / 1000);
  const from = to - state.range;

  const [vitals, uptime] = await Promise.all([
    api("vitals", { from, to, limit: 900 }),
    api("uptime", { from, to }),
  ]);

  const overview = state.overview || await api("overview");
  overview.trend = vitals.trend;
  state.limits = overview.limits;
  // Kept so a redraw - a resize, a theme change - can rebuild the sparklines
  // without a second fetch.
  state.vitalRows = vitals.rows;
  renderCoreCardPackage(ZogographOverviewGaugesCard, "core-overview-gauges", {
    overview, rows: vitals.rows,
  }, {
    target: $("gauges"), buildGauge, gaugeSeries, humanBytes, i18n: ZogographI18n,
  });
  renderLimits(overview.limits);
  renderCards(overview, vitals.rows);

  state.uptime = uptime;
  // The analysis from the vitals payload covers exactly the rows returned, so
  // the shading and the line can never describe different windows.
  state.uptime.analysis = vitals.uptime;
  state.restarts = restartMarks(uptime, from, to);
  state.uptimeWindow = { from, to };

  renderUptime();
  showCompactionNote(vitals);
  renderVitalCharts(vitals.rows, vitals.uptime);
}

/** The category chart, which belongs to Storage rather than to the overview. */
async function refreshScans() {
  const to = state.frozenAt || Math.floor(Date.now() / 1000);
  const from = to - state.range;

  const scans = await api("scans", { from, to });
  state.scans = scans;

  syncScanButton(scans);
  renderScanFacts(scans);
  renderCategoryChart(scans.rows, scans.categories ?? state.categories);
  renderFileTypes(scans);
  renderTypeGrowth(scans);
}

/** Kept so that anything still calling it refreshes the view on screen. */
async function refreshAll() {
  await refreshCurrent();
}

/*
 * What the last scan cost and what it found.
 *
 * The button on its own says nothing about whether pressing it is worth it. A
 * scan that takes four minutes and last ran twenty minutes ago is one you
 * should probably not start again, and only these figures can say so.
 */
function renderScanFacts(scans) {
  renderCoreCardPackage(ZogographScanFactCards, "core-scan-facts", scans, {
    facts: $("scanFacts"), note: $("scanNote"), humanTime, humanDuration,
    humanBytes, humanCount, i18n: ZogographI18n,
  });
}

/*
 * A colour per type, fixed rather than positional.
 *
 * The order of the slices follows the sizes, so it changes between scans. If
 * the colours followed the order too, "the green one" would be images this week
 * and video the next, and every card would change colour when one of them grew.
 */
const TYPE_COLORS = {
  images: "#4c9aff", video: "#f2616b", audio: "#c07ce0", archives: "#f0a35e",
  web: "#56c98a", documents: "#5ecbd6", code: "#e0c05c", databases: "#8f8ce0",
  logs: "#e08a8a", executables: "#b5895e", other: "#6f7d8c",
};

/*
 * The watched categories, in colours no type uses.
 *
 * Deliberately outside the type palette: on a chart carrying both, a category
 * that happened to borrow the colour of a type would read as the same series.
 */
const CATEGORY_COLORS = {
  trash: "#b06fb0", logs: "#d98f4a", temp: "#4a9fb0", errors: "#d05a5a",
};

/** The fixed colour for a type, wherever it is drawn. */
const typeColor = type => TYPE_COLORS[type] || "#6f7d8c";

function renderFileTypes(scans) {
  const types = scans.file_types ?? [];
  const cards = $("typeCards");

  if (!types.length) {
    /*
     * Nothing measured is not the same as nothing there.
     *
     * The tally starts at the first scan after this was installed, so an
     * account whose newest scan predates it has no rows - and drawing an empty
     * pie would say the disk is empty.
     */
    cards.replaceChildren(Object.assign(document.createElement("p"), {
      className: "muted",
      textContent: (scans.rows ?? []).length
        ? ZogographI18n.t("storage.types_not_measured", {}, "The last scan ran before this was measured. The next one will fill it in.")
        : ZogographI18n.t("storage.no_scan_in_range", {}, "No completed scan in this range."),
    }));
    // A large empty chart says the scan failed even when it simply predates
    // type collection. Keep the reason near the scan facts, not in a blank
    // dashboard-sized hole.
    $("typePieSection").hidden = true;
    renderOtherExtensions([]);
    $("typeWhen").textContent = "";
    $("pieNote").textContent = "";
    return;
  }

  $("typePieSection").hidden = false;

  const total = types.reduce((sum, t) => sum + Number(t.bytes || 0), 0);
  const files = types.reduce((sum, t) => sum + Number(t.files || 0), 0);

  const frag = document.createDocumentFragment();
  for (const type of types) {
    const bytes = Number(type.bytes || 0);
    const card = document.createElement("div");
    card.className = "card";

    const label = document.createElement("div");
    label.className = "label";
    label.style.setProperty("--dot", typeColor(type.type));
    label.textContent = type.type;
    card.appendChild(label);

    const value = document.createElement("div");
    value.className = "value";
    value.textContent = humanBytes(bytes);
    card.appendChild(value);

    const sub = document.createElement("div");
    sub.className = "sub muted";
    sub.textContent = `${total ? ((bytes / total) * 100).toFixed(1) : "0"}% \u00b7 `
      + count(Number(type.files || 0), "file");
    card.appendChild(sub);

    frag.appendChild(card);
  }
  cards.replaceChildren(frag);

  renderTypePie(scans, total);
  renderOtherExtensions(scans.other_extensions ?? []);

  const scan = (scans.rows ?? []).find(row => row.id === scans.file_types_scan_id);
  $("typeWhen").textContent = scan
    ? ZogographI18n.t("storage.types_measured", { bytes: humanBytes(total), files: count(files, "file"), when: humanTime(scan.finished_at || scan.started_at) }, `${humanBytes(total)} in ${count(files, "file")}, measured ${humanTime(scan.finished_at || scan.started_at)}`)
    : ZogographI18n.t("storage.types_total", { bytes: humanBytes(total), files: count(files, "file") }, `${humanBytes(total)} in ${count(files, "file")}`);
}

/*
 * The pie, optionally with the watched categories beside the types.
 *
 * These are two different partitions of the same disk and they overlap: a
 * `.log` inside a log directory is counted once under `logs` the type and again
 * under `logs` the category. Drawn as one pie that would be nonsense - the
 * slices would sum past the total. Drawn as two rings on one canvas they answer
 * the question actually being asked, which is "has one of the watched things
 * got out of hand compared with everything else".
 *
 * So the categories go in as slices measured against the same whole, and the
 * note says plainly that they are a second view of the same bytes rather than
 * extra ones.
 */
function renderTypePie(scans, total) {
  const withCategories = $("pieShowCategories").checked;
  const types = scans.file_types ?? [];

  const slices = types.map(t => ({
    label: t.type,
    value: Number(t.bytes || 0),
    color: typeColor(t.type),
  }));

  const latest = (scans.rows ?? []).find(r => r.id === scans.file_types_scan_id)
    || (scans.rows ?? [])[scans.rows.length - 1];

  const categories = [];
  if (withCategories && latest) {
    for (const name of scans.categories ?? []) {
      const bytes = Number(latest[`${name}_bytes`] || 0);
      if (bytes > 0) categories.push({ name, bytes });
    }
  }

  if (categories.length) {
    drawPieChart($("typePie"), slices, {
      empty: ZogographI18n.t("storage.not_measured_yet", {}, "Not measured yet"),
      inner: categories.map(c => ({
        label: ZogographI18n.t("storage.watched_category", { name: c.name }, `${c.name} (watched)`),
        value: c.bytes,
        color: CATEGORY_COLORS[c.name] || "#8899aa",
      })),
    });

    $("pieNote").textContent = ZogographI18n.t("storage.types_categories_help", {}, "Outer ring: every file by type, each counted once, so it is the whole "
      + "account. Inner ring: the categories the alert rules watch, against that "
      + "same total \u2014 the dark remainder is everything they do not cover. The "
      + "two rings measure some of the same bytes twice, since a log file is in "
      + "both, so read each ring against the whole rather than against the other.");
    return;
  }

  drawPieChart($("typePie"), slices, { empty: ZogographI18n.t("storage.not_measured_yet", {}, "Not measured yet") });
  $("pieNote").textContent = ZogographI18n.t("storage.types_help", {}, "Every file counted once, so the slices are the whole account.");
}

/*
 * What fell into `other`, as a table rather than more slices.
 *
 * Forty extensions is forty wedges nobody can tell apart, and the useful form
 * is sortable and readable: name, size, count, and what share of the account it
 * is. The point is to be able to say "so *that* is what .bkup is doing here".
 */
function renderOtherExtensions(rows) {
  renderCoreCardPackage(ZogographOtherExtensionsCard, "core-other-extensions", rows, {
    target: $("otherExtensions"), renderTable, humanBytes, humanCount, i18n: ZogographI18n,
  });
}

/*
 * Each type over time.
 *
 * Total size answers "what is growing"; change per scan answers "what grew
 * *this hour*", which a total hides completely - a type sitting at 40 GiB and
 * one climbing through 40 GiB draw the same flat-looking line at that scale.
 */
function renderTypeGrowth(scans) {
  renderCoreCardPackage(ZogographTypeGrowthCard, "core-type-growth", scans, {
    canvas: $("typeGrowthChart"), mode: $("typeGrowthMode").value,
    drawLineChart, bytesAxis, typeColor, i18n: ZogographI18n,
  });
}

/**
 * Disk and inodes on one chart, because they are the same question.
 *
 * "How much room is left" has two answers on a Unix filesystem and either can
 * run out on its own - a disk with plenty of gigabytes and no inodes refuses to
 * create a file, which looks exactly like a disk that is full.
 *
 * In percent they share one axis and can be read against each other directly.
 * In absolute terms they cannot: bytes and a count of inodes have no common
 * scale, so inodes move to the right-hand axis and get a dashed line.
 */
/**
 * Disk and inodes over time, in whichever of three readings is wanted.
 *
 * Absolute answers "how much is left", percent answers "how close to the edge",
 * and change answers "what is actually happening" - which the other two hide.
 * Fifty megabytes an hour is invisible on an axis running to a terabyte and
 * obvious the moment it is drawn as a difference, and only the difference shows
 * the sign: whether a directory is filling or a cleanup is working.
 */
function renderRoomChart(rows) {
  const mode = state.units;

  /*
   * How long a bar of "change" covers.
   *
   * Per reading is what you want over an hour and useless over a month: at a
   * reading a minute, thirty days is forty thousand points drawn into eight
   * hundred pixels, and what reaches the screen is noise. Totalling the change
   * over a longer bucket keeps the same information at a scale that fits.
   *
   * Summed, not averaged. The total bytes lost in an hour is a real quantity
   * you can reason about; the mean of the steps inside it is a smaller number
   * that means nothing on its own. And an average would not help with spikes
   * anyway - the mean is precisely the statistic one outlier moves furthest.
   * Spikes are handled by trimming the axis and by the median-based trend.
   */
  const bucket = state.units === "delta" ? deltaBucket(state.range) : 0;

  const prepared = rows.map((row, i) => {
    const previous = rows[i - 1];
    const seconds = previous ? Number(row.taken_at) - Number(previous.taken_at) : 0;

    return {
      ...row,
      disk_free_percent: row.disk_total_bytes
        ? (Number(row.disk_free_bytes) / Number(row.disk_total_bytes)) * 100
        : null,
      inodes_free_percent: row.inodes_total
        ? (Number(row.inodes_free) / Number(row.inodes_total)) * 100
        : null,
      // The first reading has nothing to differ from, so it is a gap rather
      // than a zero - a drawn zero would read as "nothing changed".
      disk_delta: delta(previous?.disk_free_bytes, row.disk_free_bytes, seconds),
      inodes_delta: delta(previous?.inodes_free, row.inodes_free, seconds),
    };
  });

  const shapes = {
    bytes: {
      series: [
        { key: "disk_free_bytes", label: ZogographI18n.t("storage.chart_disk_free") },
        { key: "inodes_free", label: ZogographI18n.t("storage.chart_inodes_free_right"), axis: "right" },
      ],
      options: { axis: bytesAxis, rightAxis: countAxis },
      note: "Disk space and inodes. Either can run out on its own \u2014 a disk with "
        + "free gigabytes and no inodes still refuses to create a file.",
    },
    percent: {
      series: [
        { key: "disk_free_percent", label: ZogographI18n.t("storage.chart_disk_free_percent") },
        { key: "inodes_free_percent", label: ZogographI18n.t("storage.chart_inodes_free_percent") },
      ],
      options: { axis: percentAxis, zeroBased: true, max: 100 },
      note: "How close to the edge each one is. Both on one scale, so they can be "
        + "read against each other.",
    },
    delta: {
      series: [
        { key: "disk_delta", label: ZogographI18n.t("storage.chart_disk_change") },
        { key: "inodes_delta", label: ZogographI18n.t("storage.chart_inode_change_right"), axis: "right" },
      ],
      options: { axis: bytesAxis, rightAxis: countAxis, zeroLine: true, trim: 0.02 },
      note: "What changed between one reading and the next. Below the line is space "
        + "being consumed, above it is space coming back \u2014 small, steady losses are "
        + "what a leak looks like, and one deep spike is a file being written.",
    },
  };

  const bucketed = bucket > 0 ? bucketDeltas(prepared, bucket) : prepared;
  const shape = shapes[mode] ?? shapes.bytes;
  let note = shape.note;

  if (mode === "delta" && bucket > 0) {
    const per = bucket === 86400 ? "day"
      : bucket === 3600 ? "hour"
      : `${Math.round(bucket / 3600)} hours`;

    shape.series = shape.series.map(entry => ({
      ...entry,
      label: entry.label.replace("change", `change per ${per}`),
    }));
    note += ` Totalled per ${per} over this range, because a reading a minute is`
      + " more points than there are pixels to draw them in.";
  }

  if (mode === "delta") {
    const biggest = bucketed.reduce((worst, row) => {
      const v = Number(row.disk_delta);
      return Number.isFinite(v) && Math.abs(v) > Math.abs(worst) ? v : worst;
    }, 0);
    if (biggest) {
      note += ` Largest single change: ${humanBytes(biggest)}.`;
    }
  }

  $("roomNote").textContent = note;
  drawLineChart($("roomChart"), mode === "delta" ? bucketed : prepared,
    shape.series, { ...shape.options, outages: outageBands(state.uptime) });
}

/** The change between two readings, or null when there is nothing to compare. */
function delta(before, after, seconds) {
  if (before == null || after == null || seconds <= 0) return null;
  return Number(after) - Number(before);
}

/** How long each bar of change should cover, for the range being shown. */
function deltaBucket(rangeSeconds) {
  if (rangeSeconds <= 21600) return 0;        // up to 6 hours: every reading
  if (rangeSeconds <= 172800) return 3600;    // up to 2 days: per hour
  if (rangeSeconds <= 2678400) return 21600;  // up to a month: per 6 hours
  return 86400;                               // longer: per day
}

/**
 * Adds the changes up within each bucket.
 *
 * Summed rather than averaged: "this hour cost 1.2 GiB" is a quantity, and the
 * mean of the steps that made it up is a smaller number nobody asked about.
 * Buckets are aligned to the clock rather than to the first reading, so the
 * boundaries land on the hour and two ranges of the same data agree.
 */
function bucketDeltas(rows, seconds) {
  const buckets = new Map();

  for (const row of rows) {
    const at = Math.floor(Number(row.taken_at) / seconds) * seconds;
    const into = buckets.get(at) ?? { taken_at: at, disk_delta: null, inodes_delta: null };

    for (const key of ["disk_delta", "inodes_delta"]) {
      const value = row[key];
      if (value == null) continue;
      into[key] = (into[key] ?? 0) + Number(value);
    }

    buckets.set(at, into);
  }

  return [...buckets.values()].sort((a, b) => a.taken_at - b.taken_at);
}

/**
 * CPU and memory, where only one of the two has an absolute form.
 *
 * A percentage is the only way to say "CPU", so switching the page to Absolute
 * cannot do anything to that line. Memory has both, and the byte figure is the
 * one worth having: "83%" is a number you have to already know the machine to
 * act on, and "13.3 GiB of 16 GiB" is not. So in Absolute the memory series
 * becomes bytes consumed and moves to the right-hand axis, for the same reason
 * inodes sit opposite disk space on the chart above - two quantities in
 * different units forced onto one scale leave whichever is smaller as a flat
 * line along the bottom.
 *
 * Consumed rather than available, because that is the direction the question
 * runs: memory is *used up* by something, and a chart that climbs when things
 * get worse needs no explaining. It is derived here rather than stored, since
 * the collector already keeps total and available and a third column would be
 * a way for the three to disagree.
 */
function renderCpuChart(rows) {
  const absolute = state.units === "bytes";

  const prepared = absolute
    ? rows.map(row => ({
        ...row,
        mem_used_bytes: row.mem_total_bytes == null || row.mem_available_bytes == null
          ? null
          : Number(row.mem_total_bytes) - Number(row.mem_available_bytes),
      }))
    : rows;

  const series = [{ key: "cpu_percent", label: "CPU %" }];
  series.push(absolute
    ? { key: "mem_used_bytes", label: "Memory used (right)", axis: "right" }
    : { key: "mem_used_percent", label: "Memory %" });

  drawLineChart($("cpuChart"), prepared, series, {
    outages: outageBands(state.uptime),
    axis: percentAxis,
    rightAxis: absolute ? bytesAxis : undefined,
    zeroBased: true,
    // Caps the percentage axis. Harmless on the byte axis beside it, which is
    // already orders of magnitude past a hundred.
    max: 100,
  });

  // The last reading that actually had a memory figure, so the note can say how
  // much of the machine that is. A host with no /proc/meminfo has none at all.
  const latest = [...prepared].reverse().find(row => row.mem_total_bytes != null);

  /*
   * "Share of the machine" was the wrong words, and they mattered.
   *
   * Inside a cage this is the share of what the account is *allowed*, not of
   * the server, and a chart at 95% next to an idle machine has been the single
   * most misleading thing on this page. The limits panel carries the
   * comparison; the note only has to stop claiming the wrong denominator.
   */
  const cap = state.limits?.available ? " See what the host allows, above." : "";
  $("cpuNote").textContent = absolute && latest
    ? `Share of what this account may use, since the previous reading. Memory is `
      + `bytes consumed on the right, out of ${humanBytes(latest.mem_total_bytes)} `
      + `available to this account.${cap}`
    : `Share of what this account may use, since the previous reading.${cap}`;
}

/**
 * Disk I/O, with the account's own traffic shown against the device's.
 *
 * Two lines that answer two different questions, and the gap between them is
 * the useful part. Inside CageFS the device figures are the *host's* disk -
 * every account on the machine together - so a busy line there says the disk is
 * working, never that this account is the reason. The own-traffic lines are
 * summed from the processes this user can see, which inside a cage is exactly
 * its own, and that is the number worth acting on.
 *
 * Utilisation is drawn on the right in percent, because bytes per second and a
 * percentage share no scale, and because a disk can move very little data and
 * still be saturated if the requests are small and scattered.
 */
function renderIoChart(rows) {
  const has = key => rows.some(r => r[key] != null);

  const series = [];
  if (has("own_read_rate")) series.push({ key: "own_read_rate", label: "This account, read" });
  if (has("own_write_rate")) series.push({ key: "own_write_rate", label: "This account, written" });
  if (has("io_read_rate")) series.push({ key: "io_read_rate", label: "Device read" });
  if (has("io_write_rate")) series.push({ key: "io_write_rate", label: "Device written" });
  if (has("io_util_percent")) {
    series.push({ key: "io_util_percent", label: "Device busy % (right)", axis: "right" });
  }

  drawLineChart($("ioChart"), rows, series, {
    outages: outageBands(state.uptime),
    axis: rateAxis,
    rightAxis: percentAxis,
    zeroBased: true,
    empty: series.length
      ? "Nothing collected for this range yet"
      : "No disk I/O readings — neither /proc/diskstats nor /proc/<pid>/io could be read",
  });

  const latest = [...rows].reverse().find(r => r.io_util_percent != null || r.own_read_rate != null);
  const parts = ["Bytes actually reaching a disk, not bytes served from cache."];

  /*
   * Which halves are here and which are not, said plainly.
   *
   * On a caged account the device lines are simply absent, and a chart with two
   * lines where the text describes four leaves the reader wondering whether
   * something is broken. Nothing is: /proc/diskstats is filtered out, and the
   * host collector has it.
   */
  if (!has("io_read_rate")) {
    parts.push("The device lines are missing because /proc/diskstats is not readable "
      + "from this account — see the host panel, which reads it as root.");
  }
  if (!has("own_read_rate")) {
    parts.push("This account's own traffic is missing too: /proc/<pid>/io could not be "
      + "read for any process here.");
  }
  // Only worth saying when those lines are actually on the chart. Explaining
  // what the device lines cover, immediately after saying there are none, reads
  // as a contradiction.
  if (has("io_read_rate") && has("own_read_rate")) {
    parts.push("The device lines cover every account on the machine; only the "
      + "\u201cthis account\u201d lines are yours.");
  }

  if (latest && latest.io_util_percent != null) {
    parts.push(`The device was busy ${Number(latest.io_util_percent).toFixed(0)}% of the `
      + `last interval.`);
  }
  if (latest && latest.io_pressure_full != null) {
    /*
     * Pressure, where the kernel offers it, because utilisation alone is a poor
     * proxy for harm: a disk can sit at 100% pushing background writeback and
     * bother nobody. This measures the opposite thing - time spent *waiting*.
     */
    parts.push(`Tasks were stalled waiting on the disk `
      + `${Number(latest.io_pressure_some).toFixed(1)}% of the time, and nothing at all `
      + `could run for ${Number(latest.io_pressure_full).toFixed(1)}%.`);
  }
  $("ioNote").textContent = parts.join(" ");
}

function renderVitalCharts(rows, uptime) {
  renderRoomChart(rows);
  renderCpuChart(rows);

  renderIoChart(rows);

  /*
   * Load average is not a percentage, which is the single most common thing to
   * get wrong about it, so the chart says what it is in the panel subtitle and
   * draws a line at one-per-core - the level above which work is queueing.
   */
  const bands = outageBands({ analysis: uptime });

  drawLineChart($("loadChart"), rows,
    [
      { key: "load1", label: "1 min" },
      { key: "load5", label: "5 min" },
      { key: "load15", label: "15 min" },
    ],
    { axis: step => ({ scale: 1, unit: "", format: v => v.toFixed(tickPrecision(step)) }),
      zeroBased: true, outages: bands });

  drawLineChart($("netChart"), rows,
    [{ key: "net_rx_rate", label: "In" }, { key: "net_tx_rate", label: "Out" }],
    { axis: rateAxis, zeroBased: true, outages: bands,
      empty: "No network counters here — /proc/net/dev is not readable" });
}

function renderCategoryChart(rows, categories) {
  // Built from the categories the server actually has rules for, so adding one
  // to the config puts it on the chart rather than collecting it invisibly.
  const series = (categories ?? []).map(name => ({
    key: `${name}_bytes`,
    label: name.charAt(0).toUpperCase() + name.slice(1),
  }));

  drawLineChart($("categoryChart"), rows, series, {
    xKey: "started_at",
    axis: bytesAxis,
    zeroBased: true,
    empty: "No scan has finished in this range yet",
  });
}

async function refreshOffenders() {
  const view = $("offSort").value;
  const params = { limit: 30, view };
  if ($("offCategory").value) params.category = $("offCategory").value;
  if ($("offKind").value) params.kind = $("offKind").value;

  const data = await api("offenders", params);
  state.offenders = data;
  $("maskNote").hidden = state.signedIn || !data.rows.length;

  /*
   * What was actually measured, said out loud.
   *
   * Scans are periodic and a window rarely lines up with one, so "the last
   * hour" can easily be six hours of growth. The server works out the real
   * span; printing it is the difference between a number and a misleading one.
   */
  $("offNote").textContent = data.note ?? "";

  const columns = [
    { label: ZogographI18n.t("storage.path"), className: "name", render: row => row.display },
    {
      label: ZogographI18n.t("storage.kind"),
      render: row => row.kind === "dir"
        ? ZogographI18n.t("storage.directory")
        : ZogographI18n.t("storage.file"),
    },
    { label: ZogographI18n.t("storage.category"), render: row => row.category ?? "—" },
    { label: ZogographI18n.t("storage.files"), className: "size", render: row => (row.kind === "dir" ? humanCount(row.files) : "") },
    {
      /*
       * Size, and a warning when the size is shared.
       *
       * A file with two directory entries occupies its bytes once. Deleting
       * this path frees nothing while the other link survives, so the number
       * beside it is not the number you would get back - and that is worth
       * knowing before pressing Delete rather than after.
       */
      label: view === "deleted"
        ? ZogographI18n.t("storage.size_when_last_seen", {}, "Size when last seen")
        : ZogographI18n.t("table.size", {}, "Size"),
      className: "size",
      render: row => {
        const links = Number(row.links ?? 1);
        if (links <= 1) {
          if (!row.deleted_at && !row.gone) return humanBytes(row.bytes);
          // Struck through: the size was real when the scan ran and is not now.
          const was = document.createElement("span");
          was.className = "struck-through";
          was.textContent = humanBytes(row.bytes);
          return was;
        }

        const box = document.createElement("span");
        box.appendChild(document.createTextNode(humanBytes(row.bytes)));
        const note = document.createElement("span");
        note.className = "muted small";
        note.textContent = ZogographI18n.t("storage.link_count", { count: links }, " · {{count, number}} links");
        note.title = ZogographI18n.t(
          "storage.link_count_help",
          { count: links },
          "This file has {{count, number}} names. Removing one frees nothing until the last one goes.",
        );
        box.appendChild(note);
        return box;
      },
    },
  ];

  if (view === "deleted") {
    /*
     * What happened to it, which the scan list alone cannot say.
     *
     * A scan records only the largest paths, so a file missing from the latest
     * one may have been deleted or may just have been pushed off the list by
     * something else growing. The server settles it by asking the filesystem;
     * this reports which answer came back rather than flattening both into
     * "deleted".
     */
    columns.push({
      label: ZogographI18n.t("storage.what_happened", {}, "What happened"),
      render: row => {
        const span = document.createElement("span");
        if (!row.gone) {
          span.className = "muted";
          span.textContent = ZogographI18n.t("storage.still_on_disk", {}, "Still on disk — no longer among the largest");
          span.title = ZogographI18n.t(
            "storage.still_on_disk_help",
            {},
            "The file has not gone anywhere. Something else grew past it, so it dropped out of the paths this scan records.",
          );
        } else if (row.deleted_at) {
          span.className = "shrank";
          span.textContent = ZogographI18n.t(
            "storage.deleted_here",
            { at: humanTime(row.deleted_at) },
            "Deleted from here {{at}}",
          );
          span.title = ZogographI18n.t("storage.deleted_here_help", {}, "Deleted through this dashboard, from the action log.");
        } else {
          span.className = "shrank";
          span.textContent = ZogographI18n.t("storage.gone", {}, "Gone");
          span.title = ZogographI18n.t(
            "storage.gone_help",
            {},
            "Not on disk any more, and not deleted through this dashboard — so something else removed it: log rotation, a cron job, or a person.",
          );
        }
        return span;
      },
    });
  } else if (view === "new") {
    columns.push({
      label: ZogographI18n.t("storage.first_seen", {}, "First seen"),
      render: row => {
        const span = document.createElement("span");
        if (row.never_seen_before) {
          span.className = "grew";
          span.textContent = ZogographI18n.t("storage.new", {}, "New");
          span.title = ZogographI18n.t("storage.new_help", {}, "This path has never been recorded before.");
        } else {
          span.className = "muted";
          span.textContent = ZogographI18n.t("storage.back_in_list", {}, "Back in the list");
          span.title = ZogographI18n.t(
            "storage.back_in_list_help",
            {},
            "Recorded before, absent from the previous scan, and back now — it grew past the size that gets a path recorded rather than being created.",
          );
        }
        return span;
      },
    });
  } else {
    columns.push({
      label: ZogographI18n.t("table.change", {}, "Change"),
      className: "size",
      render: row => growthCell(Number(row.growth || 0)),
    });
  }

  /*
   * The last line, for the rows that have one.
   *
   * "Is it still throwing the same error" is answered by one line and does not
   * need the viewer opened - which for a two-gigabyte log is the difference
   * between a glance and a decision.
   */
  columns.push({
    label: ZogographI18n.t("storage.last_line", {}, "Last line"),
    className: "cmd",
    render: row => lastLineCell(row),
  });

  // A file that is gone has nothing to press. The deleted view is a report.
  if (view !== "deleted") {
    columns.push({ label: "", className: "size", render: row => rowButtons(row) });

    /*
     * A picker, for clearing several things in one go.
     *
     * Put first so the checkboxes line up down the left where the eye expects
     * them, and only where deleting is possible at all - a column of boxes that
     * arm a button nobody may press is furniture.
     */
    if (state.signedIn) {
      columns.unshift({ label: "", render: row => offenderPicker(row) });
    }
  }

  renderTable("offenders", data.rows, columns, row => showHistory(row.path_id));
  syncOffenderTools(data.rows);
  fetchLastLines(data.rows);
}

/*
 * A change in size, with which way it went shown as well as said.
 *
 * The arrow is the direction and the colour is the judgement, and on a disk
 * monitor those point opposite ways: a file that gained four gigabytes went
 * *up*, and that is the bad one. Colouring growth green because green means up
 * elsewhere would be reading a share price, not a disk.
 */
function growthCell(growth) {
  const span = document.createElement("span");

  if (!growth) {
    span.className = "muted";
    span.textContent = "\u2014";
    span.title = ZogographI18n.t(
      "storage.no_measurable_change",
      {},
      "No measurable change since the previous scan.",
    );
    return span;
  }

  const up = growth > 0;
  span.className = up ? "grew" : "shrank";
  span.textContent = `${up ? "\u25b2" : "\u25bc"} ${humanBytes(Math.abs(growth))}`;
  span.title = up
    ? ZogographI18n.t(
      "storage.grew_since_scan",
      { bytes: humanBytes(growth) },
      "Grew by {{bytes}} since the previous scan — this is taking space.",
    )
    : ZogographI18n.t(
      "storage.shrank_since_scan",
      { bytes: humanBytes(-growth) },
      "Shrank by {{bytes}} since the previous scan — this gave space back.",
    );
  return span;
}

/*
 * The most recent line of every readable log in the table.
 *
 * One request for all of them rather than one each, and only for the rows the
 * server has already said are readable - asking about the other forty would be
 * forty refusals to no purpose. The result is cached by path so paging through
 * a table does not re-read the same files every time the poll comes round.
 */
const lastLines = new Map();

async function fetchLastLines(rows) {
  const wanted = rows
    .filter(r => r.viewable && r.path_id && !lastLines.has(r.path_id))
    .map(r => r.path_id);

  if (!wanted.length) {
    paintLastLines();
    return;
  }

  try {
    const data = await api("last-lines", { path_ids: wanted.join(",") });
    for (const row of data.rows) {
      lastLines.set(row.path_id, row);
    }
  } catch {
    // Not worth a notice: the table is complete without this, and the column
    // simply stays empty rather than the page reporting a failure nobody asked
    // for.
    for (const id of wanted) lastLines.set(id, { line: null, error: null });
  }

  paintLastLines();
}

/*
 * Written into the cells after the fact, rather than by re-rendering.
 *
 * Re-rendering the table when the lines arrive would undo the reader's
 * selection and scroll - the thing this session has been fixing everywhere
 * else. The cells are placeholders that get filled.
 */
function paintLastLines() {
  for (const cell of document.querySelectorAll("[data-lastline]")) {
    const row = lastLines.get(Number(cell.dataset.lastline));
    if (!row) continue;

    if (row.error) {
      cell.className = "lastline muted";
      cell.textContent = row.error;
      cell.title = row.error;
      continue;
    }
    if (!row.line) {
      cell.className = "lastline muted";
      cell.textContent = ZogographI18n.t("storage.last_line_empty", {}, "Empty");
      continue;
    }

    cell.className = "lastline";
    cell.textContent = row.line;
    cell.title = ZogographI18n.t(
      "storage.last_line_number",
      { number: row.line_number, line: row.line },
      "Line {{number, number}}: {{line}}",
    );
  }
}

function lastLineCell(row) {
  if (!row.viewable || !row.path_id) return "";

  const span = document.createElement("span");
  span.className = "lastline muted";
  span.dataset.lastline = String(row.path_id);

  const known = lastLines.get(row.path_id);
  span.textContent = known
    ? (known.line ?? known.error ?? ZogographI18n.t("storage.last_line_empty", {}, "Empty"))
    : "\u2026";
  return span;
}

/*
 * Which rows are ticked, by path.
 *
 * By path rather than by position, because the table re-sorts and re-filters
 * under the selection - ticking the third row and then changing the sort order
 * should not silently arm a different file.
 */
const offenderPicked = new Set();

function offenderPicker(row) {
  if (!mayDelete(row)) return "";

  const box = document.createElement("input");
  box.type = "checkbox";
  box.checked = offenderPicked.has(row.path);
  box.setAttribute("aria-label", ZogographI18n.t(
    "storage.select_row",
    { name: row.display },
    "Select {{name}}",
  ));
  box.addEventListener("click", event => event.stopPropagation());
  box.addEventListener("change", () => {
    box.checked ? offenderPicked.add(row.path) : offenderPicked.delete(row.path);
    syncOffenderTools();
  });
  return box;
}

function syncOffenderTools(rows) {
  if (rows) {
    // Anything no longer in the table cannot stay armed behind the button.
    const live = new Set(rows.map(r => r.path));
    for (const path of [...offenderPicked]) {
      if (!live.has(path)) offenderPicked.delete(path);
    }
  }

  const button = $("offenderDelete");
  if (!button) return;

  const picked = offenderPicked.size;
  button.hidden = !state.signedIn;
  button.disabled = !picked;
  button.textContent = picked
    ? ZogographI18n.t("storage.delete_selected_count", { count: picked }, "Delete {{count, number}} selected")
    : ZogographI18n.t("storage.delete_selected", {}, "Delete selected");
}

/*
 * Removes everything ticked, one request at a time.
 *
 * Sequential rather than parallel: each one is a deletion, the failures matter
 * individually, and firing twenty concurrent writes at a shared host to save a
 * second is a poor trade. Directories go through the recursive action and files
 * through the single-file one, decided per row rather than per batch.
 */
async function deletePicked() {
  const rows = (state.offenders?.rows || []).filter(r => offenderPicked.has(r.path));
  if (!rows.length) return;

  const bytes = rows.reduce((sum, r) => sum + Number(r.bytes || 0), 0);
  const dirs = rows.filter(r => r.kind === "dir").length;

  const question = ZogographI18n.t("storage.delete_permanently", { count: rows.length }, "Delete {{count, number}} permanently?") + "\n\n"
    + rows.slice(0, 12).map(r => `${r.kind === "dir" ? "[dir] " : ""}${r.display}`).join("\n")
    + (rows.length > 12 ? "\n" + ZogographI18n.t("storage.delete_more", { count: rows.length - 12 }, "…and {{count, number}} more") : "")
    + "\n\n" + ZogographI18n.t("storage.delete_size", { bytes: humanBytes(bytes) }, "That is {{bytes}}")
    + (dirs ? ", " + ZogographI18n.t("storage.delete_recursive", { count: dirs }, "and {{count, number}} will be emptied recursively") : "")
    + ". " + ZogographI18n.t("storage.cannot_undo", {}, "This cannot be undone.");

  if (!(await confirmDialog(question, "Delete"))) return;

  const button = $("offenderDelete");
  button.disabled = true;

  let freed = 0;
  let done = 0;
  const failed = [];

  for (const row of rows) {
    try {
      const result = row.kind === "dir"
        ? await post("delete-dir", { path: row.path })
        : await post("delete-file", { path: row.path });
      freed += Number(result.bytes ?? result.bytes_freed ?? 0);
      done++;
      offenderPicked.delete(row.path);
      closeLogIfShowing(row.path, row.path_id);
    } catch (error) {
      failed.push(`${row.display}: ${error.message || error}`);
    }
  }

  notice(
    ZogographI18n.t("storage.removed", { count: done, bytes: humanBytes(freed) }, "Removed {{count, number}}, freeing {{bytes}}.")
      + (failed.length ? " " + ZogographI18n.t("storage.remove_failed", { count: failed.length, detail: failed[0] }, "{{count, number}} could not be removed: {{detail}}") : ""),
    !failed.length
  );

  await refreshAll();
}

/** The buttons for one row: view a log, delete a file, or neither. */
function rowButtons(row) {
  /*
   * Nothing to offer on a path that is gone.
   *
   * Handled here rather than in each button so there is one marker rather than
   * two, and so a control added later cannot forget: View had the same problem
   * as Delete - it stayed live, and pressing it answered "no such file" from a
   * row the table was still showing.
   *
   * The row itself stays, because the table is what the last scan saw and that
   * remains true. Clicking it still opens the size history, which is a record
   * and does not need the file to exist.
   */
  if (row.kind === "file" && row.deleted_at) {
    const gone = document.createElement("span");
    gone.className = "muted small";
    gone.textContent = ZogographI18n.t("storage.deleted", {}, "deleted");
    gone.title = ZogographI18n.t("storage.deleted_row_help", { at: humanTime(row.deleted_at) },
      "Deleted {{at}}. Still listed because the last scan found it; the next scan will drop it.");
    return gone;
  }

  const holder = document.createElement("span");
  holder.style.display = "inline-flex";
  holder.style.gap = "6px";

  /*
   * The server decides whether a row is readable, not the category.
   *
   * A rotated log is still in the logs category and still cannot be shown - it
   * is a gzip stream, and the viewer would print the last few kilobytes of it
   * as text. Only the server can tell, so it says.
   */
  if (row.viewable) {
    const view = document.createElement("button");
    view.textContent = ZogographI18n.t("action.view", {}, "View");
    view.addEventListener("click", () => showLog(row.path_id));
    holder.appendChild(view);
  }

  const remove = deleteButton(row);
  if (remove !== "") holder.appendChild(remove);

  return holder.childElementCount ? holder : "";
}

/**
 * The delete button for one row, or nothing.
 *
 * Only rendered when the server has said this session may delete and the row is
 * in a category the config allows. The server checks all of it again anyway -
 * this is about not offering something that will be refused.
 */
/*
 * Whether the interface should offer to delete this row.
 *
 * The server decides for real - resolveDeletable is the authority and this
 * cannot grant anything it refuses. This only decides whether to draw a button
 * that would work, because a Delete that always answers "not allowed" is worse
 * than no Delete at all.
 */
function mayDelete(row) {
  if (!state.signedIn || row.deleted_at) return false;
  if (state.deletableScope === "account") return true;
  return state.deletable.includes(row.category);
}

function deleteButton(row) {
  if (!mayDelete(row)) {
    return "";
  }

  // The deleted case is handled by rowButtons, which owns the whole cell.
  if (row.deleted_at) {
    return "";
  }

  const button = document.createElement("button");
  button.className = "danger";
  button.textContent = ZogographI18n.t("action.delete", {}, "Delete");
  button.addEventListener("click", async () => {
    const directory = row.kind === "dir";
    const question = directory
      ? `Delete this directory and everything inside it?\n\n${row.display}\n`
        + `${humanBytes(row.bytes)} in ${count(row.files || 0, "file")}\n\nThis cannot be undone.`
      : `Delete this file permanently?\n\n${row.display}\n${humanBytes(row.bytes)}`;
    if (!(await confirmDialog(question, "Delete"))) return;
    button.disabled = true;
    try {
      const result = directory
        ? await post("delete-dir", { path: row.path })
        : await post("delete-file", { path: row.path });

      closeLogIfShowing(row.path, row.path_id);

      if (directory) {
        notice(
          `Removed ${humanBytes(result.bytes)} in ${count(result.files, "file")}`
            + (result.skipped?.length
              ? `. ${count(result.skipped.length, "path")} could not be removed.`
              : "."),
          !result.skipped?.length
        );
        await refreshAll();
        return;
      }
      notice(
        result.bytes_freed > 0
          ? `Deleted ${humanBytes(result.bytes_freed)}.`
          : `Deleted, but nothing was freed: ${count(result.links, "other name")} still `
            + `point at those ${humanBytes(result.bytes)}.`,
        true
      );
      await refreshAll();
    } catch (error) {
      notice(String(error.message || error));
      button.disabled = false;
    }
  });
  return button;
}

/**
 * One card per emptyable category: how much is in it, then the button.
 *
 * A bare "Empty trash" asks for a decision without supplying the fact the
 * decision turns on. Putting the size above the button means the question being
 * answered is "is 1.2 GiB across 4,312 files worth reclaiming", which is a
 * question, rather than "do you want to delete an unknown quantity of things",
 * which is a dare.
 */
function renderEmptyButtons() {
  const holder = $("emptyButtons");
  if (!state.signedIn || !state.deletable.length) {
    holder.replaceChildren();
    return;
  }

  holder.replaceChildren(...state.deletable.map(category => {
    const totals = (state.totals || {})[category] || { bytes: 0, files: 0 };
    const emptiedAt = (state.emptied || {})[category];

    const card = document.createElement("div");
    card.className = "card empty-card";

    const label = document.createElement("div");
    label.className = "label";
    label.textContent = category.charAt(0).toUpperCase() + category.slice(1);
    card.appendChild(label);

    const value = document.createElement("div");
    value.className = "value";
    value.textContent = humanBytes(totals.bytes);
    // Struck through once emptied: the figure was true when the scan ran.
    if (emptiedAt) value.classList.add("struck-through");
    card.appendChild(value);

    const sub = document.createElement("div");
    sub.className = "sub muted";
    sub.textContent = totals.files
      ? count(totals.files, "file")
      : ZogographI18n.t("storage.nothing_counted", {}, "nothing counted here");
    if (emptiedAt) sub.classList.add("struck-through");
    card.appendChild(sub);

    if (emptiedAt) {
      /*
       * Emptied already, so no button - the same reasoning as a deleted row,
       * and the same shape: the figures struck through because they were true
       * when the scan ran, and one line saying what happened. The card stays
       * because the category still exists and will fill up again.
       */
      const done = document.createElement("div");
      done.className = "muted small";
      done.textContent = ZogographI18n.t("storage.emptied_at", { at: humanTime(emptiedAt) }, "emptied {{at}}");
      done.title = ZogographI18n.t("storage.emptied_help", {}, "The next scan will show what is in it now.");
      card.appendChild(done);
      return card;
    }

    const button = document.createElement("button");
    button.className = "danger small";
    button.textContent = ZogographI18n.t("storage.empty", {}, "Empty");
    button.disabled = !totals.bytes && !totals.files;

    button.addEventListener("click", async () => {
      if (!(await confirmDialog(
        `Delete every file counted as ${category}?\n\n`
        + `${humanBytes(totals.bytes)} across ${count(totals.files, "file")}, `
        + `as of the last scan.\n\nThis cannot be undone.`
      ))) return;

      button.disabled = true;
      try {
        const result = await post("empty", { category });
        notice(
          `Emptied ${category}: ${humanCount(result.files_removed)} files, `
          + `${humanBytes(result.bytes_freed)} freed`
          + (result.still_linked
            ? `. ${count(result.still_linked, "file")} had another name, so freed nothing`
            : "")
          + (result.failed ? `, ${result.failed} could not be removed.` : "."),
          true
        );
        await refreshAll();
      } catch (error) {
        notice(String(error.message || error));
        button.disabled = false;
      }
    });

    card.appendChild(button);
    return card;
  }));
}

async function showHistory(pathId, quiet = false) {
  if (!pathId) return;
  state.historyPathId = pathId;

  const to = Math.floor(Date.now() / 1000);
  const data = await api("history", { path_id: pathId, from: to - state.range, to });

  $("historyPanel").hidden = false;
  $("historyTitle").textContent = data.path.display;
  // Size on the left in bytes, file count on the right: a directory holding
  // ten thousand small files and one holding a single huge one are different
  // problems, and on one axis the count is a flat line along the bottom.
  drawLineChart($("historyChart"), data.rows,
    [
      { key: "bytes", label: "Size" },
      { key: "files", label: "Files (right)", axis: "right" },
    ],
    { xKey: "started_at", axis: bytesAxis, rightAxis: countAxis, zeroBased: true,
      empty: "This path has only been seen in one scan so far" });

  if (!quiet) $("historyPanel").scrollIntoView({ behavior: "smooth", block: "nearest" });
}

/**
 * Shows the end of a log file.
 *
 * `page` counts backwards from the end, so 0 is the newest lines and paging
 * "older" walks back through the file. With a search, it walks back through
 * matches instead - which is the only way to page through the interesting lines
 * of a file too big to read.
 */
/*
 * Shuts the log viewer if it is showing a file that has just gone.
 *
 * The viewer used to stay open on a deleted file, empty, reporting that the
 * file was deleted - which is true and is not what anybody wants left on the
 * screen. Matched on both the id and the path, because a log can be opened
 * either way and only one of the two will be set.
 */
function closeLogIfShowing(path, pathId = null) {
  const showing = (path && state.log.path === path)
    || (pathId && state.log.pathId === pathId);
  if (!showing) return;

  state.log = { pathId: null, path: null, page: 0, needle: "" };
  $("logPanel").hidden = true;
  $("logBody").replaceChildren();
  $("logStatus").textContent = "";
}

/** Opens a log named by a raw path - the treemap and the host list. */
function showLogPath(path, quiet = false) {
  if (!path) return Promise.resolve();
  if (path !== state.log.path) {
    state.log = { pathId: null, path, page: 0, needle: $("logSearch").value.trim() };
  }
  return showLog(null, quiet);
}

async function showLog(pathId, quiet = false) {
  if (pathId) {
    if (pathId !== state.log.pathId) {
      state.log = { pathId, path: null, page: 0, needle: $("logSearch").value.trim() };
    }
  } else if (!state.log.path) {
    return;
  }

  const panel = $("logPanel");
  const body = $("logBody");

  let data;
  try {
    data = await api("tail", {
      ...(state.log.pathId ? { path_id: state.log.pathId } : { path: state.log.path }),
      lines: $("logLines").value,
      page: state.log.page,
      q: state.log.needle,
    });
  } catch (error) {
    const said = String(error.message || error);

    /*
     * A file that is gone closes the viewer rather than reporting itself empty.
     *
     * The three delete buttons close it directly, but this also catches the
     * cases they cannot: emptying a whole category, a deletion from another
     * tab, or the file being removed by something else entirely while the
     * panel sat open. An empty viewer explaining that its file no longer exists
     * is a true statement nobody wants left on the screen.
     */
    if (/was deleted|no such file/i.test(said)) {
      state.log = { pathId: null, path: null, page: 0, needle: "" };
      panel.hidden = true;
      body.replaceChildren();
      $("logStatus").textContent = "";
      if (!quiet) notice(said);
      return;
    }

    panel.hidden = false;
    $("logTitle").textContent = ZogographI18n.t("storage.log", {}, "Log");
    $("logStatus").textContent = said;
    body.replaceChildren();
    return;
  }

  panel.hidden = false;
  $("logTitle").textContent = data.path;

  const shown = data.lines.length;
  const parts = [];
  if (state.log.needle) {
    parts.push(`${data.matched} match${data.matched === 1 ? "" : "es"} found`);
  }
  parts.push(`${shown} line${shown === 1 ? "" : "s"}`);
  if (state.log.page > 0) parts.push(`page ${state.log.page + 1} back from the end`);
  parts.push(`file is ${humanBytes(data.size)}`);
  parts.push(`read ${humanBytes(data.scanned)} of it`);
  if (data.truncated) {
    parts.push("stopped searching before the start of the file — narrow the search or look at the file directly");
  } else if (data.reached_start) {
    parts.push("this is the beginning of the file");
  }
  $("logStatus").textContent = parts.join(" · ");

  /*
   * Built as nodes rather than a string of HTML.
   *
   * A log file is the least trustworthy text on the machine - it is full of
   * whatever was sent to the server, which is exactly where somebody would put
   * a script tag hoping an admin tool would render it.
   */
  body.replaceChildren(...data.lines.map(line => {
    const row = document.createElement("div");
    const number = document.createElement("span");
    number.className = "num";
    number.textContent = String(line.n);
    row.appendChild(number);
    row.append(...highlightMatches(line.text, state.log.needle));
    return row;
  }));

  if (!shown) {
    body.textContent = state.log.needle ? "No matching lines here." : "Nothing to show.";
  }

  $("logNewer").disabled = state.log.page === 0;
  $("logOlder").disabled = data.reached_start && shown === 0;

  if (!quiet) panel.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

/*
 * Splits a line around the search term, so the match can be marked.
 *
 * Named for what it highlights. There was a second `highlight` further down
 * that outlines a treemap rectangle, and a function declaration does not care
 * which of the two you meant - the later one simply won for the whole file, so
 * opening a log called the canvas version and died on `ctx.strokeRect`.
 */
function highlightMatches(text, needle) {
  if (!needle) return [document.createTextNode(text)];

  const out = [];
  const haystack = text.toLowerCase();
  const found = needle.toLowerCase();
  let at = 0;

  for (;;) {
    const next = haystack.indexOf(found, at);
    if (next === -1) break;
    if (next > at) out.push(document.createTextNode(text.slice(at, next)));
    const mark = document.createElement("mark");
    mark.textContent = text.slice(next, next + needle.length);
    out.push(mark);
    at = next + needle.length;
  }

  out.push(document.createTextNode(text.slice(at)));
  return out;
}

/**
 * How far through the wait for the next reading this collector is.
 *
 * A number of seconds since the last run is a fact that needs arithmetic before
 * it means anything - is four minutes fine? It depends entirely on whether this
 * one runs every minute or every hour. The ring does that arithmetic: three
 * quarters round is three quarters of the way to the next one, whatever the
 * interval happens to be.
 *
 * Three states, because they call for three different reactions:
 *
 *   filling   ordinary. The next one is coming.
 *   pulsing   full. One is due about now, and this is the second before you
 *             would start wondering.
 *   dashed    nothing is arriving, or nothing ever has. Grey and broken rather
 *             than a full red ring, because a full ring means "due" and a
 *             collector that stopped last Tuesday is not due, it is gone.
 *
 * The interval is measured from the gaps between the last few runs, never read
 * from a crontab - this account usually cannot see root's. So when there is no
 * interval there is no ring, rather than a ring against an invented schedule.
 */
function collectorDial(collector) {
  const size = 46;
  const stroke = 5;
  const radius = (size - stroke) / 2;

  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", `0 0 ${size} ${size}`);
  svg.setAttribute("width", String(size));
  svg.setAttribute("height", String(size));
  svg.setAttribute("class", "dial");
  svg.setAttribute("aria-hidden", "true");

  const ring = (cls) => {
    const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
    circle.setAttribute("cx", String(size / 2));
    circle.setAttribute("cy", String(size / 2));
    circle.setAttribute("r", String(radius));
    circle.setAttribute("fill", "none");
    circle.setAttribute("stroke-width", String(stroke));
    circle.setAttribute("class", cls);
    svg.appendChild(circle);
    return circle;
  };

  ring("dial-track");
  const progress = ring("dial-value");
  // Twelve o'clock rather than three, which is where everybody reads a dial from.
  progress.setAttribute("transform", `rotate(-90 ${size / 2} ${size / 2})`);

  const said = document.createElementNS("http://www.w3.org/2000/svg", "title");
  svg.appendChild(said);

  /*
   * What it needs to redraw itself, kept on the element.
   *
   * The ring used to be painted once from an age the server had calculated,
   * which meant it sat perfectly still between polls and then jumped. A dial
   * that does not move is not read as "waiting", it is read as broken - which
   * is exactly the report this came from. Everything below is derived from the
   * last run time and the browser's own clock, so the ticker can advance it
   * every second without asking the server anything.
   */
  svg.dataset.at = String(collector.last_at || 0);
  svg.dataset.every = String(collector.interval || 0);
  svg.dataset.state = String(collector.state || "");

  paintDial(svg);
  return svg;
}

/**
 * Redraws one dial from the clock.
 *
 * Three states, and the distinction between the last two is the point:
 *
 *   waiting   part-filled, quiet
 *   due       full, pulsing - the run is expected about now
 *   stopped   grey and dashed, still - this is not late, it has stopped
 *
 * A ring that filled twenty minutes ago on a one-minute collector has not been
 * "due" for twenty minutes, and leaving it pulsing would say the next one is
 * imminent when nothing is coming.
 */
function paintDial(svg) {
  const size = 46;
  const radius = (size - 5) / 2;
  const circumference = 2 * Math.PI * radius;

  const at = Number(svg.dataset.at || 0);
  const interval = Number(svg.dataset.every || 0);
  const progress = svg.querySelector(".dial-value");
  const said = svg.querySelector("title");

  /*
   * No interval, or nothing has ever arrived: a broken grey ring.
   *
   * Two readings is not a schedule, and drawing a confident ring from one gap
   * would be inventing the thing this whole panel exists to report on.
   */
  if (!at || interval <= 0) {
    svg.classList.remove("is-due");
    svg.classList.add("is-dead");
    progress.setAttribute("class", "dial-value dial-dead");
    progress.setAttribute("stroke-dasharray", "4 5");
    progress.removeAttribute("stroke-dashoffset");
    said.textContent = at
      ? "Not enough runs yet to know how often this should happen."
      : "This has never run.";
    return;
  }

  const age = Math.max(0, Math.floor(Date.now() / 1000) - at);
  const stopped = svg.dataset.state === "stopped" || age > interval * 2;
  const due = age >= interval;

  svg.classList.toggle("is-dead", stopped);
  svg.classList.toggle("is-due", due && !stopped);

  if (stopped) {
    progress.setAttribute("class", "dial-value dial-dead");
    progress.setAttribute("stroke-dasharray", "4 5");
    progress.removeAttribute("stroke-dashoffset");
    said.textContent = `Nothing for ${humanSpan(age)}, on something that usually runs `
      + `every ${humanSpan(interval)}.`;
    return;
  }

  progress.setAttribute("class", due ? "dial-value dial-due" : "dial-value");
  progress.setAttribute("stroke-dasharray", String(circumference));
  progress.setAttribute(
    "stroke-dashoffset",
    String(circumference * (1 - Math.min(1, age / interval)))
  );
  said.textContent = due
    ? `Due now — nothing for ${humanSpan(age)}.`
    : `Next one in about ${humanSpan(interval - age)}.`;
}

/* ------------------------------------------------------- forms being used -- */

/**
 * Remembers what a form looked like when it was drawn.
 *
 * Every field is stamped with the value it was rendered with, so "has somebody
 * changed this" can be answered later without keeping a copy of the form
 * anywhere.
 */
function markFormRendered(container) {
  if (!container) return;

  for (const field of container.querySelectorAll("input, select, textarea")) {
    field.dataset.rendered = field.type === "checkbox" || field.type === "radio"
      ? String(field.checked)
      : String(field.value);
  }
}

/**
 * Is somebody part-way through filling this in?
 *
 * The question that matters before redrawing a settings page. `manual: true`
 * keeps the poll timer off a view, and that turned out to be half the problem:
 * the range picker in the top bar rewrites the route, the route redraws the
 * current view, and the redraw is not a poll - so an API key half typed
 * vanished when somebody changed the range out of habit. Measured, with a
 * script that typed into every box and then changed the dropdown: eight fields
 * in, zero fields out.
 *
 * Compares against what was stamped at render time rather than against the
 * defaults, so a field that has always been empty is not mistaken for one
 * somebody has just cleared.
 */
function formIsDirty(container) {
  if (!container) return false;

  for (const field of container.querySelectorAll("input, select, textarea")) {
    if (field.dataset.rendered === undefined) continue;

    const now = field.type === "checkbox" || field.type === "radio"
      ? String(field.checked)
      : String(field.value);

    if (now !== field.dataset.rendered) return true;
  }

  return false;
}

/**
 * Redraws a settings panel unless somebody is using it.
 *
 * The refusal is said out loud rather than silent: a page that quietly stops
 * updating is its own kind of confusing, and "this is not refreshing while you
 * are editing" is a promise as much as a warning.
 */
function keepIfEditing(containerId, draw) {
  const container = $(containerId);

  if (container && formIsDirty(container)) {
    let said = container.querySelector(".form-held");
    if (!said) {
      said = document.createElement("p");
      said.className = "form-held muted small";
      said.textContent = ZogographI18n.t("setup.form_held", {}, "Not refreshed while you are editing. Save, or move away and come back, to see what is stored.");
      container.prepend(said);
    }
    return false;
  }

  draw();
  markFormRendered(container);
  return true;
}

/**
 * Advances every dial on screen, once a second.
 *
 * One timer for all of them rather than one each, and it does nothing at all
 * when the tab is hidden or there are no dials drawn - a page in a background
 * tab has no reason to be recalculating geometry nobody is looking at.
 */
function startDialTicker() {
  setInterval(() => {
    if (document.hidden) return;

    for (const svg of document.querySelectorAll("svg.dial[data-every]")) {
      // offsetParent is null for anything inside a hidden view.
      if (svg.parentElement?.offsetParent === null) continue;
      paintDial(svg);
    }

    /*
     * And the "3 seconds ago" beside it, for the same reason.
     *
     * A dial that advances next to a number frozen at whatever it said when
     * the page last polled is worse than either on its own.
     */
    /*
     * The terminal's own countdown, which is a deadline rather than an age.
     *
     * Same ticker, because a second timer for one number on one page would be
     * a second thing to remember to stop.
     */
    for (const spot of document.querySelectorAll("[data-until-from]")) {
      if (spot.offsetParent === null) continue;
      const left = Number(spot.dataset.untilFrom || 0) - Math.floor(Date.now() / 1000);

      if (left <= 0) {
        spot.textContent = ZogographI18n.t("terminal.locked_again", {}, "It has locked itself again.");
        // Redrawn once, so the unlock form replaces the countdown.
        if (!spot.dataset.saidSo) {
          spot.dataset.saidSo = "1";
          refreshTerminal().catch(() => {});
        }
      } else {
        spot.textContent = ZogographI18n.t("terminal.open_for", { duration: humanSpan(left, true) }, "Open for another {{duration}}.");
        if (left < 120) spot.className = "band-crit small";
      }
    }

    for (const spot of document.querySelectorAll("[data-ago-from]")) {
      if (spot.offsetParent === null) continue;
      const at = Number(spot.dataset.agoFrom || 0);
      if (at > 0) {
        spot.textContent = `${humanDuration(
          Math.max(0, Math.floor(Date.now() / 1000) - at)
        )} ago`;
      }
    }
  }, 1000);
}

/* --------------------------------------------------------- setting lookout -- */

const aiSetState = { data: null };
const aiSettingsText = (key, fallback, values = {}) =>
  ZogographI18n.t(`ai.settings.${key}`, values, fallback);

/** Every container the settings are split across. */
const AI_SETTING_PAGES = [
  "aiIdentityBody", "aiProvidersBody", "aiModelBody", "aiLimitsBody", "aiImagesBody",
];

async function refreshAiSettings() {
  const bodies = AI_SETTING_PAGES.map(id => $(id)).filter(Boolean);

  if (!state.signedIn) {
    for (const body of bodies) body.replaceChildren(note(aiSettingsText("sign_in_required", "Sign in to see these settings.")));
    return;
  }

  /*
   * Fetched only if it is going to be used.
   *
   * Asking the server for settings that are about to be thrown away is a round
   * trip for nothing, and on this page it is a round trip whose answer would
   * have wiped what somebody was typing. Any of the four pages being edited
   * holds all four back, because they are one form and one Save.
   */
  if (bodies.some(body => formIsDirty(body))) {
    for (const id of AI_SETTING_PAGES) keepIfEditing(id, () => {});
    await refreshAiSessions();
    return;
  }

  try {
    const data = await api("ai-settings");
    renderAiSettings(data);
    await refreshAiSessions();
  } catch (error) {
    for (const body of bodies) body.replaceChildren(note(String(error.message || error)));
  }
}

function renderAiSettings(data) {
  aiSetState.data = data;

  const parts = [];

  if (!data.writable) {
    parts.push(note(aiSettingsText("config_read_only",
      "lib/config.php is not writable by the web server, so this page can show the settings but not change them.")));
  } else if (!data.can_change) {
    parts.push(note(aiSettingsText("role_read_only",
      "Your signed-in role can use the assistant but cannot change its configuration. Sign in with an administrator account to save provider credentials or model settings.")));
  }

  if (data.enabled && !data.ready) {
    parts.push(note(`Not ready: ${data.why}`));
  }

  const form = document.createElement("div");
  form.className = "settings";

  form.appendChild(fieldRow(aiSettingsText("enabled_label", `Use ${chatState.who.name}`, { assistant: chatState.who.name }), (() => {
    const box = document.createElement("input");
    box.type = "checkbox";
    box.id = "aiEnabled";
    box.checked = data.enabled;
    return box;
  })(),
    aiSettingsText("enabled_help", `Off means ${chatState.who.name} is unavailable and nothing is ever sent anywhere. `
    + "Turning it on does not send anything by itself — only asking it something does.", { assistant: chatState.who.name })));

  const provider = document.createElement("select");
  provider.id = "aiProvider";
  const providerNote = document.createElement("div");
  providerNote.className = "muted small";

  for (const [key, meta] of Object.entries(data.providers)) {
    const option = document.createElement("option");
    option.value = key;
    option.textContent = meta.label;
    option.selected = data.provider === key;
    provider.appendChild(option);
  }
  form.appendChild(fieldRow(aiSettingsText("provider_label", "Provider"), provider, ""));
  form.appendChild(providerNote);

  const base = document.createElement("input");
  base.type = "text";
  base.id = "aiBase";
  base.className = "wide-field";
  base.value = data.base_url || "";
  form.appendChild(fieldRow(aiSettingsText("address_label", "Address"), base,
    aiSettingsText("address_help", "Leave blank for the provider's own. Point it elsewhere for a gateway, a proxy, or a model running on this machine.")));

  const model = document.createElement("select");
  model.id = "aiModel";
  model.className = "wide-field";
  model.value = data.model || "";

  const key = document.createElement("input");
  key.type = "password";
  key.id = "aiKey";
  key.className = "wide-field";
  key.autocomplete = "off";
  key.placeholder = data.has_key ? "•".repeat(24) + " (unchanged)" : "";
  form.appendChild(fieldRow(aiSettingsText("api_key_label", "API key"), key,
    data.has_key
      ? aiSettingsText("api_key_set_help", "A key is set. It is never sent back to this page, so leaving this blank keeps the existing one — type a new one to replace it.")
      : aiSettingsText("api_key_empty_help", "Stored in lib/config.php, which is outside the web root. A local model needs none.")));

  const selected = document.createElement("div"); selected.className = "settings";
  const selectedProvider = provider.cloneNode(true); selectedProvider.id = "aiSelectedProvider";
  selected.appendChild(fieldRow(aiSettingsText("provider_label", "Provider"), selectedProvider,
    aiSettingsText("selected_provider_help", "Choose which provider's models to show.")));
  selected.appendChild(fieldRow(aiSettingsText("available_model_label", "Available model"), model,
    aiSettingsText("available_model_help", "Models supplied by the provider or added on Available Models.")));

  /*
   * How hard a reasoning model should think, where the endpoint takes one.
   *
   * Only shown for the Responses provider: on chat completions the same models
   * refuse function tools whenever this is set to anything but none, which is
   * the error that led to that endpoint being spoken at all.
   */
  const effort = document.createElement("select");
  effort.id = "aiEffort";
  for (const [value, label] of [
    ["", aiSettingsText("effort_default", "the provider's default")],
    ["minimal", aiSettingsText("effort_minimal", "minimal")],
    ["low", aiSettingsText("effort_low", "low")],
    ["medium", aiSettingsText("effort_medium", "medium")],
    ["high", aiSettingsText("effort_high", "high")],
  ]) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    option.selected = (data.reasoning_effort || "") === value;
    effort.appendChild(option);
  }
  const effortRow = fieldRow(aiSettingsText("reasoning_label", "How hard to think"), effort,
    aiSettingsText("reasoning_help", "Reasoning models charge for the thinking as output tokens, so this is the setting that moves the bill most. Higher is worth it for a knotty problem and wasted on “is the disk full?”."));
  form.appendChild(effortRow);

  if (data.has_key) {
    const forget = document.createElement("button");
    forget.type = "button";
    forget.className = "link danger";
    forget.textContent = ZogographI18n.t("ai.forget_key", {}, "Forget the key");
    forget.addEventListener("click", async () => {
      if (!(await confirmDialog(aiSettingsText("forget_key_confirm", "Remove the stored API key? The assistant will stop working until another is set."),
        aiSettingsText("forget_key_title", "Forget key")))) return;
      await saveAiSettings({ forget_key: "1" });
    });
    form.appendChild(fieldRow("", forget, ""));
  }

  /*
   * Six pages from one fetch.
   *
   * They are six questions - who it is, which model, what it may spend, what it
   * may draw, what it may do, and what it has cost - but one set of settings and
   * one Save. Every section is built whether or not its page is on screen,
   * because the save reads the fields by id: rendering only the visible page
   * would mean saving from Identity silently blanked everything on Model.
   */
  const pages = {
    identity: [],
    providers: [],
    model: [],
    limits: [],
    images: [],
  };

  // Whatever the page said about being read-only belongs on all of them.
  for (const key of Object.keys(pages)) pages[key].push(...parts.map(node => node.cloneNode(true)));

  pages.identity.push(section(aiSettingsText("identity_title", "Identity"), personaFields(data)));
  pages.providers.push(section(aiSettingsText("provider_connection", "Provider connection"), form));
  pages.model.push(section(aiSettingsText("which_model", "Which model"), selected));

  /*
   * A test before any of it is used in anger.
   *
   * Half the ways this can be misconfigured only show up once tools are
   * involved - a reasoning model on the wrong endpoint answers ordinary
   * messages perfectly and refuses the moment a function is offered - so the
   * test sends one, and says so.
   */
  const testing = document.createElement("div");
  testing.className = "inspect-actions";

  const test = document.createElement("button");
  test.type = "button";
  test.id = "aiTest";
  test.textContent = ZogographI18n.t("ai.test_connection", {}, "Test the connection");
  test.title = ZogographI18n.t("ai.test_connection_title", {}, "One real request, with a tool attached, using whatever is in the boxes above — including a key you have typed but not saved");
  testing.appendChild(test);

  const testResult = document.createElement("span");
  testResult.id = "aiTestResult";
  testResult.className = "muted small";
  testing.appendChild(testResult);

  pages.model.push(testing);
  pages.model.push(note(aiSettingsText("test_help", "The test asks the model one trivial question with one tool attached. It costs a few hundred tokens and tells you four things at once: the address answers, the key is accepted, the model exists, and it will take tools.")));

  /* ---- money ---- */

  const money = document.createElement("div");
  money.className = "settings";

  for (const [id, labelKey, label, value, hintKey, hint] of [
    ["aiPriceIn", "price_input_label", "Input, per million", data.price_in,
      "price_input_help", "In cents. From the provider's pricing page."],
    ["aiPriceOut", "price_output_label", "Output, per million", data.price_out,
      "price_output_help", "In cents. Usually several times the input price."],
    ["aiPriceCached", "price_cached_label", "Cached input, per million", data.price_cached,
      "price_cached_help", "In cents. Usually about a tenth of the input price. On a conversation that "
      + "re-sends a long prompt every turn this is most of the bill, so leaving it at "
      + "the input price overstates the cost considerably."],
  ]) {
    const input = document.createElement("input");
    input.type = "number";
    input.id = id;
    input.min = "0";
    input.step = "0.01";
    input.className = "days";
    input.value = String(value || 0);
    money.appendChild(fieldRow(aiSettingsText(labelKey, label), input, aiSettingsText(hintKey, hint)));
  }

  pages.model.push(section(aiSettingsText("prices_title", "Prices, if you want a cost"), money));
  pages.model.push(note(aiSettingsText("prices_help", "Leave these at zero and sessions report token counts and no money. That is the "
    + "honest default — a wrong price is worse than no price, so nothing is guessed "
    + "from the model name. Prices you set here are remembered against this provider and "
    + "model, so changing the model and changing back does not lose them.")));

  /* ---- limits ---- */

  const limits = document.createElement("div");
  limits.className = "settings";

  const seconds = document.createElement("select");
  seconds.id = "aiMaxSeconds";
  for (const [value, label] of [
    [0, aiSettingsText("limit_none", "no limit")], [900, aiSettingsText("limit_15_minutes", "15 minutes")], [3600, aiSettingsText("limit_hour", "an hour")],
    [14400, aiSettingsText("limit_4_hours", "four hours")], [86400, aiSettingsText("limit_day", "a day")],
  ]) {
    const option = document.createElement("option");
    option.value = String(value);
    option.textContent = label;
    option.selected = Number(data.max_seconds) === value;
    seconds.appendChild(option);
  }
  limits.appendChild(fieldRow(aiSettingsText("stop_after_label", "Stop a conversation after"), seconds,
    aiSettingsText("stop_after_help", "Measured from when it started, not from the last message. A conversation left open "
    + "overnight cannot quietly resume in the morning and carry on spending.")));

  const cents = document.createElement("input");
  cents.type = "number";
  cents.id = "aiMaxCents";
  cents.min = "0";
  cents.step = "1";
  cents.className = "days";
  cents.value = String(data.max_cents || 0);
  limits.appendChild(fieldRow(aiSettingsText("spend_limit_label", "Or after spending (cents)"), cents,
    aiSettingsText("spend_limit_help", "Checked before each request rather than after, so the limit stops the next call "
    + "rather than being noticed once the money is gone. Zero means no limit — "
    + "which, with prices set, means no limit on the bill either.")));

  const turns = document.createElement("input");
  turns.type = "number";
  turns.id = "aiMaxTurns";
  turns.min = "0";
  turns.max = "500";
  turns.className = "days";
  turns.value = String(data.max_turns || 0);
  limits.appendChild(fieldRow(aiSettingsText("turn_limit_label", "Or after this many turns"), turns,
    aiSettingsText("turn_limit_help", "One turn is one request to the model. A conversation that needs forty is usually "
    + "one that has gone in a circle, so this is the limit most likely to catch a "
    + "problem rather than a long investigation.")));

  for (const [id, labelKey, label, value, noteKey, note_] of [
    ["aiDailyCents", "daily_spend_label", "Shared daily spend (cents)", data.daily_cents, "daily_spend_help", "Across every conversation and automated alert investigation. Zero means no daily cap."],
    ["aiSharedMonthlyCents", "monthly_spend_label", "Shared monthly spend (cents)", data.monthly_cents, "monthly_spend_help", "UTC calendar month, across every conversation and automated alert investigation. Zero means no monthly cap."],
  ]) {
    const input = document.createElement("input");
    input.type = "number";
    input.id = id;
    input.min = "0";
    input.step = "1";
    input.className = "days";
    input.value = String(value || 0);
    limits.appendChild(fieldRow(aiSettingsText(labelKey, label), input, aiSettingsText(noteKey, note_)));
  }
  const shared = data.shared_budget || {};
  const sharedUsage = ["daily", "monthly"].flatMap(period => {
    const budget = shared[period];
    if (!budget || !Number(budget.limit_millicents)) return [];
    return [`${period}: ${(Number(budget.used_millicents) / 1000).toFixed(2)} of ${(Number(budget.limit_millicents) / 1000).toFixed(2)} cents`];
  });
  if (sharedUsage.length) limits.appendChild(note(aiSettingsText("shared_usage", `Shared AI usage — ${sharedUsage.join("; ")}.`, { usage: sharedUsage.join("; ") })));

  pages.limits.push(section(aiSettingsText("limits_title", "Conversation and shared limits"), limits));

  /* ---- how much it can hold ---- */

  const room = document.createElement("div");
  room.className = "settings";

  const window_ = document.createElement("input");
  window_.type = "number";
  window_.id = "aiContextTokens";
  window_.min = "4000";
  window_.step = "1000";
  window_.className = "days";
  window_.value = String(data.context_tokens ?? 128000);
  room.appendChild(fieldRow(aiSettingsText("context_window_label", "Context window (tokens)"), window_,
    aiSettingsText("context_window_help", "How much the chosen model can hold at once. It is a fact about the model, not "
    + "something the API will tell us, so it is typed in — check the model's own "
    + "documentation. Guessing high is the worse mistake: the provider rejects the "
    + "request outright, which ends the conversation.")));

  const at = document.createElement("input");
  at.type = "number";
  at.id = "aiCompactAt";
  at.min = "30";
  at.max = "85";
  at.className = "days";
  at.value = String(data.compact_at ?? 70);
  room.appendChild(fieldRow(aiSettingsText("compact_at_label", "Summarise at (%)"), at,
    aiSettingsText("compact_at_help", "How full it gets before the older part of a conversation is replaced with a summary. "
    + "Deliberately not near 100: summarising means sending the part being summarised, so "
    + "a limit that fires when the window is already full is a limit that cannot act.")));

  const auto = document.createElement("input");
  auto.type = "checkbox";
  auto.id = "aiCompactAuto";
  auto.checked = data.compact_automatically !== false;
  room.appendChild(fieldRow(aiSettingsText("compact_automatically_label", "Summarise automatically"), auto,
    aiSettingsText("compact_automatically_help", "On, it happens on the next turn after the mark is passed. Off, the ring in the chat "
    + "window goes amber and waits for you to click it — and the conversation will "
    + "eventually be refused by the provider if you never do.")));

  const explain = document.createElement("input");
  explain.type = "checkbox";
  explain.id = "aiExplain";
  explain.checked = data.explain_commands !== false;
  room.appendChild(fieldRow(aiSettingsText("explain_commands_label", "Explain its commands"), explain,
    aiSettingsText("explain_commands_help", "When it suggests a terminal command, it comments each part, says what the output "
    + "should look like, and links to the documentation. Worth leaving on: somebody "
    + "pasting a command they have not understood is the thing this is meant to prevent. "
    + "Turn it off if you read shell fluently and find the commentary noise.")));

  const hostCommands = document.createElement("input");
  hostCommands.type = "checkbox";
  hostCommands.id = "aiHostCommands";
  hostCommands.checked = data.host_commands === true;
  room.appendChild(fieldRow(aiSettingsText("host_commands_label", "Let it see what only root can run"), hostCommands,
    aiSettingsText("host_commands_help", "The host collector already records which programs exist and which this account can "
    + "reach. With this on, the assistant can see the difference and may suggest asking "
    + "your host to run one and send back the output — which is an ordinary support "
    + "request and often the fastest route to an answer. It is told to suggest reading "
    + "only, never changes to a shared server. Off by default because it changes the kind "
    + "of advice you get.")));

  pages.limits.push(section(aiSettingsText("context_title", "How much it can hold"), room));

  /* ---- what it does without being asked ---- */

  const unattended = document.createElement("div");
  unattended.className = "settings";

  const mode = document.createElement("select");
  mode.id = "aiAlertMode";
  for (const [value, labelKey, label] of [
    ["off", "alert_mode_off", "nothing — alerts behave exactly as they always have"],
    ["comment", "alert_mode_comment", "read each alert and write a note on it"],
    ["look", "alert_mode_look", "…and look things up first, so the note is informed"],
    ["decide", "alert_mode_decide", "…and may conclude one did not warrant sending"],
  ]) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = aiSettingsText(labelKey, label);
    option.selected = (data.alerts?.mode ?? "off") === value;
    mode.appendChild(option);
  }
  unattended.appendChild(fieldRow(aiSettingsText("alert_mode_label", "When an alert fires"), mode,
    aiSettingsText("alert_mode_help", "This runs from cron with nobody watching, so it only ever gets the read-only tools "
    + "that need no permission. Anything it cannot do — reach the model, parse an answer "
    + "— leaves the alert exactly as it would have been, because a thing standing between "
    + "a machine noticing a problem and you being told has one acceptable failure mode.")));

  const floor = document.createElement("select");
  floor.id = "aiAlertFloor";
  for (const [value, labelKey, label] of [
    ["error", "alert_floor_error", "never for error or critical"],
    ["warning", "alert_floor_warning", "never for warning and above"],
    ["critical", "alert_floor_critical", "never for critical"],
    ["none", "alert_floor_none", "any of them, including critical"],
  ]) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = aiSettingsText(labelKey, label);
    option.selected = (data.alerts?.never_above ?? "error") === value;
    floor.appendChild(option);
  }
  unattended.appendChild(fieldRow(aiSettingsText("alert_floor_label", "Except"), floor,
    aiSettingsText("alert_floor_help", "A critical alert is the one case where a delay and a model's opinion are both worse "
    + "than a plain fast message. Left at the default it never touches those.")));

  const perRun = document.createElement("input");
  perRun.type = "number";
  perRun.id = "aiAlertPerRun";
  perRun.min = "1";
  perRun.max = "20";
  perRun.className = "days";
  perRun.value = String(data.alerts?.per_run ?? 5);
  unattended.appendChild(fieldRow(aiSettingsText("alert_per_run_label", "At most, per run"), perRun,
    aiSettingsText("alert_per_run_help", "A disk filling up trips several rules at once. This is what stops a storm becoming "
    + "a bill.")));

  for (const [id, key, labelKey, label] of [
    ["aiDaily", "daily", "daily_summary", "Write a daily summary"],
    ["aiWeekly", "weekly", "weekly_summary", "…a weekly one"],
    ["aiMonthly", "monthly", "monthly_summary", "…a monthly one"],
  ]) {
    const box = document.createElement("input");
    box.type = "checkbox";
    box.id = id;
    box.checked = data.alerts?.[key] === true;
    unattended.appendChild(fieldRow(aiSettingsText(labelKey, label), box, ""));
  }

  const reportTo = document.createElement("input");
  reportTo.type = "text";
  reportTo.id = "aiReportTo";
  reportTo.className = "wide-field";
  reportTo.value = data.alerts?.report_to ?? "";
  reportTo.placeholder = aiSettingsText("report_to_placeholder", "leave blank to use the alert addresses");
  unattended.appendChild(fieldRow(aiSettingsText("report_to_label", "Send summaries to"), reportTo,
    aiSettingsText("report_to_help", "Semicolon-separated. A summary and an alert are different kinds of message and may "
    + "reasonably go to different places — but requiring a second address before the "
    + "feature works at all would be a needless step, so blank means the alert "
    + "addresses.")));

  pages.limits.push(section(aiSettingsText("unattended_title", "What it does without being asked"), unattended));
  pages.limits.push(note(aiSettingsText("unattended_help", "Everything in this section costs money on a schedule, with nobody watching. The "
    + "per-conversation limits above do not apply to it — those are about one "
    + "conversation, and this is not one.")));
  pages.images.push(pictureFields(data));

  /*
   * Where the transcripts are is not repeated here.
   *
   * That page exists, in full, under the assistant's own data - with the table
   * sizes, what it is keeping and the buttons to clear it out. Two places
   * saying the same number is two places to get it wrong.
   */

  /*
   * A Save on every page that has something to save.
   *
   * All four write the same settings, because they are one form split across
   * four pages - so pressing Save on Thresholds also saves a name typed on
   * Identity, and that is deliberate: the alternative is somebody losing work
   * by navigating away from it.
   */
  for (const [key, id] of [
    ["identity", "aiIdentityBody"],
    ["providers", "aiProvidersBody"],
    ["model", "aiModelBody"],
    ["limits", "aiLimitsBody"],
    ["images", "aiImagesBody"],
  ]) {
    const holder = $(id);
    if (!holder) continue;

    const actions = document.createElement("div");
    actions.className = "inspect-actions";

    const save = document.createElement("button");
    save.type = "submit";
    save.textContent = ZogographI18n.t("ai.save_settings", {}, "Save these settings");
    save.disabled = !data.writable || !data.can_change;
    /*
     * A compatible endpoint deliberately needs no credential.  Keep the
     * reason this button is unavailable separate from connection validation:
     * otherwise an administrator sees a disabled Save after choosing Ollama
     * and reasonably assumes the empty key is the problem.
     */
    if (!data.writable) {
      save.title = aiSettingsText("config_read_only",
        "lib/config.php is not writable by the web server, so this page can show the settings but not change them.");
    } else if (!data.can_change) {
      save.title = aiSettingsText("role_read_only",
        "Your signed-in role can use the assistant but cannot change its configuration. Sign in with an administrator account to save provider credentials or model settings.");
    } else if (key === "providers") {
      save.title = aiSettingsText("compatible_keyless_save_help",
        "An Ollama or OpenAI-compatible connection can be saved without an API key.");
    }
    actions.appendChild(save);

    const said = document.createElement("span");
    said.className = "muted small";
    if (key === "providers" && !data.writable) {
      said.textContent = aiSettingsText("provider_save_unavailable_config",
        "Connection saving is unavailable because PHP cannot write the configuration store.");
    } else if (key === "providers" && !data.can_change) {
      said.textContent = aiSettingsText("provider_save_unavailable_role",
        "Connection saving is unavailable for your current account. An administrator can save it.");
    } else if (key === "providers") {
      said.textContent = aiSettingsText("provider_save_ready",
        "This connection can be saved without an API key. Saving also keeps the settings on the other Assistant pages.");
    } else {
      said.textContent = ZogographI18n.t("ai.save_all_pages", {}, "Saves everything on all of these pages.");
    }
    actions.appendChild(said);

    holder.replaceChildren(...pages[key], actions);
    markFormRendered(holder);
  }

  renderAiPrices(data);
  renderAiTry(data);

  const syncProvider = () => {
    const meta = data.providers[provider.value];
    const saved = data.connections?.[provider.value] ?? {};
    providerNote.textContent = meta?.note ?? "";
    selectedProvider.value = provider.value;

    // Only one endpoint takes it, and offering it elsewhere would suggest it
    // does something.
    effortRow.hidden = provider.value !== "openai-responses";
    const wantedModel = model.value || (provider.value === data.provider ? data.model : "");
    const available = new Set(meta?.models ?? []);
    for (const price of data.price_book ?? []) if (price.provider === provider.value) available.add(price.model);
    if (provider.value === data.provider && data.model) available.add(data.model);
    model.replaceChildren(...[...available].sort().map(name => {
      const option = document.createElement("option");
      option.value = name;
      option.textContent = name;
      return option;
    }));
    if (!model.options.length) {
      const option = document.createElement("option");
      option.value = "";
      option.textContent = aiSettingsText("no_available_models", "No available models yet — add one on Available Models");
      model.appendChild(option);
    }
    model.value = wantedModel;
    if (model.value === "" && model.options.length) model.selectedIndex = 0;

    base.value = saved.base_url || (provider.value === data.provider ? data.base_url : "");
    base.placeholder = meta?.base ?? "";
    key.value = "";
    const hasKey = saved.has_key || (provider.value === data.provider && data.has_key);
    key.placeholder = hasKey ? "•".repeat(24) + " (unchanged)" : "No key required for Ollama";
  };
  provider.addEventListener("change", syncProvider);
  selectedProvider.addEventListener("change", () => { provider.value = selectedProvider.value; syncProvider(); });
  syncProvider();

  renderAiTools(data);
}

/** Every tool, what it does, and whether it may. */
/**
 * What each group of tools is called on its tab.
 *
 * The catalogue's own keys are lower-case single words because they are keys.
 * These are what a person reads.
 */
const TOOL_GROUP_NAMES = {
  diagnostic: "Diagnostic",
  navigation: "Navigation",
  terminal: "Terminal",
  host: "Host",
  memory: "Memory",
  pictures: "Pictures",
};

/*
 * Which group of tools the page is showing.
 *
 * Kept outside the render so that ticking a box, which re-renders the whole
 * table, does not throw somebody back to the first tab.
 */
let toolTab = "diagnostic";

function renderAiTools(data) {
  const body = $("aiToolsBody");
  const parts = [];

  /*
   * A tab per group, because thirty-nine rows is a list nobody reads.
   *
   * Grouped the way the catalogue already groups them rather than by some new
   * arrangement invented here: "navigation" and "terminal" are what the tools
   * say about themselves, and a second taxonomy over the top of the first is
   * how the two stop agreeing.
   *
   * The count is on the tab. A group with nothing in it - pictures, on an
   * install with no key - still gets a tab, because a missing tab reads as a
   * missing feature, which is the exact confusion this page keeps causing.
   */
  const groups = new Map();
  for (const tool of data.tools) {
    if (!groups.has(tool.group)) groups.set(tool.group, []);
    groups.get(tool.group).push(tool);
  }

  if (!groups.has(toolTab)) toolTab = groups.keys().next().value ?? "diagnostic";

  const tabs = document.createElement("div");
  tabs.className = "seg-row";

  for (const [group, list] of groups) {
    const tab = document.createElement("button");
    tab.type = "button";
    tab.className = group === toolTab ? "seg on" : "seg";
    tab.textContent = `${TOOL_GROUP_NAMES[group] ?? group} (${list.length})`;

    // How many of this group are switched on, so a group that is entirely off
    // says so from the tab rather than only once it is opened.
    const on = list.filter(t => t.enabled).length;
    tab.title = on === list.length
      ? "All of these are switched on."
      : `${on} of ${list.length} switched on.`;

    tab.addEventListener("click", () => {
      toolTab = group;
      renderAiTools(data);
    });
    tabs.appendChild(tab);
  }

  parts.push(tabs);

  const presets = document.createElement("div");
  presets.className = "panel-tools";
  const presetPick = document.createElement("select");
  for (const set of data.toolsets || []) {
    const option = document.createElement("option");
    option.value = set.name;
    option.textContent = set.label + (set.builtin ? "" : " (saved)");
    presetPick.appendChild(option);
  }
  const applyPreset = document.createElement("button");
  applyPreset.type = "button";
  applyPreset.textContent = ZogographI18n.t("ai.apply_toolset", {}, "Apply toolset");
  applyPreset.disabled = !data.writable;
  applyPreset.addEventListener("click", () => {
    const set = (data.toolsets || []).find(one => one.name === presetPick.value);
    if (!set) return;
    for (const [name, setting] of Object.entries(set.tools || {})) {
      const enabled = body.querySelector(`.tool-on[data-tool="${name}"]`);
      const ask = body.querySelector(`.tool-ask[data-tool="${name}"]`);
      if (enabled) enabled.checked = Boolean(setting.enabled);
      if (ask) ask.checked = Boolean(setting.permission);
    }
    notice(ZogographI18n.t("ai.toolset_applied", { label: set.label }, "Applied {{label}}. Save these settings to make it active."), true);
  });
  presets.append(presetPick, applyPreset);
  parts.push(presets);

  const table = document.createElement("table");
  table.className = "retention";

  const head = table.createTHead().insertRow();
  for (const [key, fallback] of [
    ["ai.tool_column", "Tool"],
    ["ai.runs_column", "Runs"],
    ["ai.may_use_column", "May use it"],
    ["ai.ask_first_column", "Ask me first"],
    ["", ""],
  ]) {
    const th = document.createElement("th");
    th.textContent = key ? ZogographI18n.t(key, {}, fallback) : fallback;
    head.appendChild(th);
  }

  const tbody = table.createTBody();

  /*
   * Every tool is in the table; the tabs only hide rows.
   *
   * Rendering just the chosen group looked identical and was not: the save
   * reads the tick boxes out of the page, so a table holding one group's rows
   * would have saved that group and switched off all thirty-odd others. The
   * style list on the Images page carries the same warning for the same reason,
   * and I walked into it anyway two pages later.
   *
   * Hidden rather than filtered out, so nothing about what is saved depends on
   * which tab happens to be open.
   */
  for (const tool of data.tools) {
    const row = tbody.insertRow();
    row.hidden = tool.group !== toolTab;

    const what = row.insertCell();
    what.className = "name";
    what.appendChild(document.createTextNode(tool.summary.replace(/\.$/, "")));

    const name = document.createElement("div");
    name.className = "muted small";
    name.textContent = tool.name;
    what.appendChild(name);

    const where = row.insertCell();
    where.className = "muted small";
    where.textContent = {
      server: ZogographI18n.t("ai.tool_where_server", {}, "here"),
      browser: ZogographI18n.t("ai.tool_where_browser", {}, "in your browser"),
      ask: ZogographI18n.t("ai.tool_where_acts", {}, "changes something"),
    }[tool.where] ?? tool.where;
    where.title = {
      server: ZogographI18n.t("ai.tool_where_server_title", {}, "Answered from the databases on this server. Read-only."),
      browser: ZogographI18n.t("ai.tool_where_browser_title", {}, "Only your browser can do it — moving you to a page, or capturing what you can see."),
      ask: ZogographI18n.t("ai.tool_where_acts_title", {}, "This one acts rather than reads."),
    }[tool.where] ?? "";

    const on = row.insertCell();
    const enabled = document.createElement("input");
    enabled.type = "checkbox";
    enabled.className = "tool-on";
    enabled.dataset.tool = tool.name;
    enabled.checked = tool.enabled;
    enabled.disabled = !data.writable;
    on.appendChild(enabled);

    /*
     * A tick that is not reaching the model says so.
     *
     * The picture tools need a key, reactions need a search key, and both of
     * those live on another page - so a tool could be ticked here and still be
     * one the assistant had never heard of. It then says it has no such tool,
     * which reads as a fault in the assistant rather than a setting somewhere
     * else.
     */
    if (tool.enabled && tool.offered === false) {
      const why = document.createElement("div");
      why.className = "band-warn small";
      why.textContent = ZogographI18n.t("ai.tool_not_in_use", {}, "not in use");
      why.title = tool.not_offered_because ?? "";
      on.appendChild(why);
    }

    const gate = row.insertCell();

    /*
     * A tool whose whole job is asking has nothing to ask permission for.
     *
     * offer_choices and ask_the_user do not read anything, change anything or
     * send anything anywhere - they put a question on the screen and wait. A
     * tick box called "ask me first" beside them offers to interrupt somebody
     * to find out whether they may be asked something, which is a question
     * about a question. Worse, ticking it would produce two prompts in a row
     * for one interaction.
     *
     * Marked as not applicable rather than hidden: an empty cell in a column
     * of tick boxes reads as an oversight, and the whole point of listing every
     * tool on this page is that nothing looks missing.
     */
    if (tool.asks_by_design) {
      const said = document.createElement("span");
      said.className = "muted small";
      said.textContent = ZogographI18n.t("ai.tool_asks_anyway", {}, "it asks you anyway");
      said.title = ZogographI18n.t("ai.tool_asks_anyway_title", {}, "This tool exists to put a question to you. There is nothing it could do that you would want warning of.");
      gate.appendChild(said);
    } else {
      const ask = document.createElement("input");
      ask.type = "checkbox";
      ask.className = "tool-ask";
      ask.dataset.tool = tool.name;
      ask.checked = tool.permission;
      ask.disabled = !data.writable;
      gate.appendChild(ask);

      if (tool.recommends_permission) {
        const said = document.createElement("span");
        said.className = "muted small";
        said.textContent = " " + ZogographI18n.t("ai.recommended", {}, "recommended");
        gate.appendChild(said);
      }
    }

    const detail = row.insertCell();
    const show = document.createElement("button");
    show.type = "button";
    show.className = "link";
    show.textContent = ZogographI18n.t("ai.tool_description", {}, "What it is told");
    show.title = ZogographI18n.t("ai.tool_description_title", {}, "The exact description the model is given for this tool");
    show.addEventListener("click", () => {
      const pre = document.createElement("pre");
      pre.className = "paste";
      pre.textContent = tool.description;
      showListDialog(tool.name, [pre], ZogographI18n.t("ai.tool_description_help", {}, "This is what the model reads before deciding whether to use it. The “do not use this when…” half is what stops a confident wrong call."));
    });
    detail.appendChild(show);
  }

  parts.push(table);

  /*
   * A conversation should begin with a small diagnostic surface. When it has
   * established that the question is about a particular subject, this gives
   * the operator one deliberate step to extend that subject rather than asking
   * them to recognise and tick every individual capability.
   */
  const extension = document.createElement("div");
  extension.className = "tool-extension";
  const extensionText = document.createElement("span");
  extensionText.className = "muted small";
  const inactive = groups.get(toolTab)?.filter(tool => !tool.enabled).length ?? 0;
  const groupLabel = TOOL_GROUP_NAMES[toolTab] ?? toolTab;
  extensionText.textContent = inactive
    ? ZogographI18n.t("ai.tool_subject_intro", { assistant: chatState.who.name, group: groupLabel }, "{{assistant}} starts with diagnostic tools. Enable {{group}} tools if this conversation needs that subject.")
    : ZogographI18n.t("ai.tool_subject_all_enabled", { assistant: chatState.who.name, group: groupLabel }, "All {{group}} tools are enabled for {{assistant}}.");
  extension.appendChild(extensionText);
  if (inactive && data.writable) {
    const enableGroup = document.createElement("button");
    enableGroup.type = "button";
    enableGroup.className = "link";
    enableGroup.textContent = ZogographI18n.t("ai.enable_subject", { count: inactive }, "Enable this subject ({{count}})");
    enableGroup.addEventListener("click", () => {
      for (const tool of groups.get(toolTab) ?? []) {
        const toggle = body.querySelector(`.tool-on[data-tool="${tool.name}"]`);
        if (toggle) toggle.checked = true;
      }
      enableGroup.disabled = true;
      enableGroup.textContent = ZogographI18n.t("ai.subject_enabled_save", {}, "Subject enabled — save settings");
      extensionText.textContent = ZogographI18n.t("ai.tool_subject_available_after_save", { group: groupLabel }, "{{group}} tools will be available after you save these settings.");
    });
    extension.appendChild(enableGroup);
  }
  parts.push(extension);

  /*
   * A Save, on the page the ticks are on.
   *
   * This page had none: ticking a tool did nothing until you happened to visit
   * one of the four pages that did have one and pressed Save there. The other
   * pages are inside a form and this one was not, which is the whole of why -
   * a setting you can change and cannot save is worse than one you cannot
   * change.
   */
  const actions = document.createElement("div");
  actions.className = "inspect-actions";

  const save = document.createElement("button");
  save.type = "submit";
  save.textContent = ZogographI18n.t("ai.save_settings", {}, "Save these settings");
  save.disabled = !data.writable;
  actions.appendChild(save);

  const said = document.createElement("span");
  said.className = "muted small";
  said.textContent = ZogographI18n.t("ai.save_assistant_pages", { assistant: data.who?.name ?? "the assistant" }, "Saves everything on all of {{assistant}}'s pages, including the tools on the other tabs.");
  actions.appendChild(said);

  const savePreset = document.createElement("button");
  savePreset.type = "button";
  savePreset.textContent = ZogographI18n.t("ai.save_as_toolset", {}, "Save as toolset");
  savePreset.disabled = !data.writable;
  savePreset.addEventListener("click", async () => {
    const name = await askTextDialog(
      ZogographI18n.t("ai.toolset_title", {}, "Save toolset"),
      ZogographI18n.t("ai.toolset_short_name", {}, "Short preset name"),
      "",
      ZogographI18n.t("ai.toolset_name_hint", {}, "Use lowercase letters, numbers, - or _."));
    if (!name) return;
    const label = await askTextDialog(
      ZogographI18n.t("ai.toolset_title", {}, "Save toolset"),
      ZogographI18n.t("ai.toolset_label", {}, "Label"),
      name,
      ZogographI18n.t("ai.toolset_label_hint", {}, "This is the name people see in the list."));
    if (label === null) return;
    try {
      const on = [...body.querySelectorAll("input.tool-on:checked")].map(box => box.dataset.tool).join(",");
      const ask = [...body.querySelectorAll("input.tool-ask:checked")].map(box => box.dataset.tool).join(",");
      renderAiSettings(await post("ai-toolset-save", { name, label, tools_on: on, tools_ask: ask }));
      notice(ZogographI18n.t("ai.toolset_saved", {}, "Toolset saved."), true);
    } catch (error) {
      notice(String(error.message || error));
    }
  });
  actions.appendChild(savePreset);

  const removePreset = document.createElement("button");
  removePreset.type = "button";
  removePreset.className = "link danger";
  removePreset.textContent = ZogographI18n.t("ai.delete_toolset", {}, "Delete saved toolset");
  removePreset.disabled = !data.writable;
  removePreset.addEventListener("click", async () => {
    const set = (data.toolsets || []).find(one => one.name === presetPick.value);
    if (!set || set.builtin) {
      notice(ZogographI18n.t("ai.builtin_toolset", {}, "Built-in toolsets cannot be deleted."));
      return;
    }
    if (!(await confirmDialog(
      ZogographI18n.t("ai.delete_toolset_confirm", { label: set.label }, "Delete toolset “{{label}}”?"),
      ZogographI18n.t("ai.delete_toolset_title", {}, "Delete toolset")))) return;
    try {
      renderAiSettings(await post("ai-toolset-delete", { name: set.name }));
      notice(ZogographI18n.t("ai.toolset_deleted", {}, "Toolset deleted."), true);
    } catch (error) {
      notice(String(error.message || error));
    }
  });
  actions.appendChild(removePreset);

  parts.push(actions);
  body.replaceChildren(...parts);
}

/**
 * Name, emoji and character.
 *
 * All three are the operator's, and all three are resettable - a personality
 * somebody has rewritten into a corner is worse than no personality, and the
 * way out has to be one button rather than "delete this text and remember what
 * was there before".
 */
function personaFields(data) {
  const wrap = document.createDocumentFragment();
  const who = data.who;

  const form = document.createElement("div");
  form.className = "settings";

  /*
   * The name first, then the emoji.
   *
   * The name is what everything else here is named after and what appears in
   * the menu; the emoji is a decoration on it. Asking for the decoration first
   * put the more important field second, which is not what the eye does with a
   * form.
   */
  const name = document.createElement("input");
  name.type = "text";
  name.id = "aiName";
  name.value = who.name;
  name.size = 24;
  name.maxLength = 40;
  form.appendChild(fieldRow(aiSettingsText("identity_name_label", "Name"), name,
    aiSettingsText("identity_name_help", "What it calls itself, and what this page and the menu call it.")));

  const emoji = document.createElement("input");
  emoji.type = "text";
  emoji.id = "aiEmoji";
  emoji.value = who.emoji;
  emoji.size = 4;
  emoji.maxLength = 8;
  form.appendChild(fieldRow(aiSettingsText("identity_emoji_label", "Emoji"), emoji,
    aiSettingsText("identity_emoji_help", "Shown beside the name everywhere it appears, including in the menu.")));

  const personality = document.createElement("textarea");
  personality.id = "aiPersonality";
  personality.rows = 24;
  personality.className = "wide-field persona-box";
  personality.spellcheck = false;
  personality.value = who.personality;

  /*
   * The character box gets the room the character needs.
   *
   * It holds a page of instructions and was a four-line slot, so editing it
   * meant scrolling a box to read a paragraph. Everything else on this page is
   * one line; this is the one field that is a document.
   */
  form.appendChild(fieldRow(aiSettingsText("identity_character_label", "Character"), personality,
    aiSettingsText("identity_character_help", "Sent with every single request, so length here is a cost on every turn. It cannot "
    + "override the rules that keep the answers honest — never state a cause you have "
    + "not measured, say when a tool returned nothing — which are added after it and "
    + "say so.")));

  /*
   * The picker is built after the boxes because it writes into them.
   *
   * It replaced a "put the character back" link: that restored one particular
   * character, which was the only one there was. With a list of them, going
   * back to the default is choosing the default.
   */
  wrap.appendChild(personalityPicker(data, { name, emoji, personality }));

  if (who.portrait) {
    const face = document.createElement("div");
    face.className = "portrait-block";

    const image = document.createElement("img");
    image.className = "portrait";
    image.src = who.portrait.url;
    image.alt = ZogographI18n.t("image.portrait_alt", { name: who.name }, `${who.name}, as it describes itself`);
    face.appendChild(image);

    const said = document.createElement("div");
    said.className = "muted small";
    said.textContent = ZogographI18n.t("image.portrait_caption", { elapsed: ago(who.portrait.at), description: who.portrait.as }, `Drawn ${ago(who.portrait.at)}, from: "${who.portrait.as}"`);
    face.appendChild(said);

    const clear = document.createElement("button");
    clear.type = "button";
    clear.className = "link danger";
    clear.textContent = ZogographI18n.t("ai.clear_portrait", {}, "Clear this portrait");
    clear.addEventListener("click", async () => {
      const yes = await askFirst(ZogographI18n.t("ai.clear_portrait_title", {}, "Clear the portrait?"), [
        ZogographI18n.t("ai.clear_portrait_hide", {}, "The picture stops being shown and the emoji takes its place until it draws another one."),
        ZogographI18n.t("ai.clear_portrait_retention", {}, "The record of it stays in the image log — it was generated and it cost something, and that is worth keeping whether or not the picture is shown."),
      ], ZogographI18n.t("notes.clear", {}, "Clear it"), true);
      if (!yes) return;

      try {
        renderAiSettings(await post("ai-portrait-clear", {}));
        notice(ZogographI18n.t("ai.portrait_cleared", {}, "Cleared."), true);
      } catch (error) {
        notice(String(error.message || error));
      }
    });
    face.appendChild(clear);

    form.appendChild(fieldRow(aiSettingsText("identity_portrait_label", "Portrait"), face,
      aiSettingsText("identity_portrait_help", "It drew this itself, the last time it was asked to. Turning off self-portraits "
      + "below stops it drawing another; this one stays until it does.")));
  }

  wrap.appendChild(form);
  return wrap;
}

/**
 * Choosing a character, saving one, and throwing one away.
 *
 * Choosing fills the boxes and does not save - the same as every other setting
 * on this page, which is only written when Save is pressed. Somebody trying one
 * on can read it, change their mind and leave without having changed anything.
 */
function personalityPicker(data, boxes) {
  const list = data.personalities ?? [];

  const wrap = document.createElement("div");
  wrap.className = "persona-picker";

  const row = document.createElement("div");
  row.className = "pattern-row";

  const pick = document.createElement("select");
  pick.id = "aiPersonalityPick";

  /*
   * "Something of your own" is first and is what an edited character selects.
   *
   * Without it, a character somebody has written themselves would leave the
   * dropdown showing whichever preset it least resembled, which is a lie about
   * what is in force.
   */
  const own = document.createElement("option");
  own.value = "";
  own.textContent = ZogographI18n.t("ai.personality_own", {}, "— your own wording —");
  pick.appendChild(own);

  const built = document.createElement("optgroup");
  built.label = ZogographI18n.t("ai.built_in", {}, "Built in");
  const mine = document.createElement("optgroup");
  mine.label = ZogographI18n.t("ai.yours", {}, "Yours");

  for (const entry of list) {
    const option = document.createElement("option");
    option.value = entry.key;
    option.textContent = `${entry.emoji} ${entry.name}`;
    option.selected = entry.in_use;
    (entry.mine ? mine : built).appendChild(option);
  }

  pick.appendChild(built);
  if (mine.childElementCount) pick.appendChild(mine);
  row.appendChild(pick);

  const said = document.createElement("span");
  said.className = "muted small";
  row.appendChild(said);

  wrap.appendChild(row);

  const chosen = () => list.find(entry => entry.key === pick.value) ?? null;

  const sync = () => {
    const entry = chosen();
    said.textContent = entry
      ? entry.who
      : ZogographI18n.t("ai.personality_unsaved", {}, "The boxes below are not one of these. Save it as one to come back to it.");
    forget.hidden = !entry?.mine;
  };

  pick.addEventListener("change", () => {
    const entry = chosen();
    if (entry) {
      boxes.name.value = entry.name;
      boxes.emoji.value = entry.emoji;
      boxes.personality.value = entry.character;
      notice(ZogographI18n.t("ai.personality_filled", { name: entry.name }, "Filled in with {{name}}. Press Save to apply it."), true);
    }
    sync();
  });

  /*
   * Editing the boxes moves the dropdown to "your own wording".
   *
   * Otherwise it keeps naming a character that is no longer what is in the box,
   * and somebody comes back later believing they are running the built-in one.
   */
  const drifted = () => {
    const entry = chosen();
    if (!entry) return;
    const same = boxes.name.value === entry.name
      && boxes.emoji.value === entry.emoji
      && boxes.personality.value.trim() === entry.character.trim();
    if (!same) {
      pick.value = "";
      sync();
    }
  };
  for (const box of [boxes.name, boxes.emoji, boxes.personality]) {
    box.addEventListener("input", drifted);
  }

  const actions = document.createElement("div");
  actions.className = "inspect-actions";

  const keep = document.createElement("button");
  keep.type = "button";
  keep.className = "link";
  keep.textContent = ZogographI18n.t("ai.save_personality", {}, "Save these as a personality");
  keep.addEventListener("click", async () => {
    const label = await askTextDialog(
      ZogographI18n.t("ai.save_personality_title", {}, "Save personality"),
      ZogographI18n.t("ai.personality_name", {}, "Name"),
      boxes.name.value || ZogographI18n.t("ai.my_assistant", {}, "My assistant"),
      ZogographI18n.t("ai.personality_name_hint", {}, "This is the name people see in the list."));
    if (label === null) return;

    post("ai-personality-save", {
      label,
      name: boxes.name.value,
      emoji: boxes.emoji.value,
      personality: boxes.personality.value,
    }).then(fresh => {
      renderAiSettings(fresh);
      notice(ZogographI18n.t("ai.personality_saved", {}, "Saved. It is in the list now."), true);
    }).catch(error => notice(String(error.message || error)));
  });
  actions.appendChild(keep);

  const forget = document.createElement("button");
  forget.type = "button";
  forget.className = "link danger";
  forget.textContent = ZogographI18n.t("ai.delete_personality", {}, "Delete this personality");
  forget.hidden = true;
  forget.addEventListener("click", async () => {
    const entry = chosen();
    if (!entry?.mine) return;

    const yes = await askFirst(
      ZogographI18n.t("ai.delete_personality_confirm", { name: entry.name }, "Delete {{name}}?"),
      [ZogographI18n.t("ai.delete_personality_help", {}, "It goes from the list. The boxes keep what is in them, so whatever is in force stays in force until you change it.")],
      ZogographI18n.t("ai.delete_personality_action", {}, "Delete it"),
      true);
    if (!yes) return;

    try {
      renderAiSettings(await post("ai-personality-forget", { id: entry.id }));
      notice(ZogographI18n.t("ai.personality_deleted", {}, "Deleted."), true);
    } catch (error) {
      notice(String(error.message || error));
    }
  });
  actions.appendChild(forget);

  wrap.appendChild(actions);
  sync();

  return wrap;
}

/**
 * Whether it may make pictures, and which kinds.
 *
 * Off by default and inert without a key. Every option here costs money per
 * call except the reactions, which cost a search - so the hourly limit covers
 * all of it and the page says what has been used.
 */
function pictureFields(data) {
  const wrap = document.createDocumentFragment();
  const pictures = data.pictures;

  const form = document.createElement("div");
  form.className = "settings";

  const on = document.createElement("input");
  on.type = "checkbox";
  on.id = "aiPicturesOn";
  on.checked = pictures.enabled;
  form.appendChild(fieldRow("Let it make pictures", on,
    "Off means the picture tools are not offered at all. Each one costs money per call "
    + "and asks your permission every time."));

  const key = document.createElement("input");
  key.type = "password";
  key.id = "aiPictureKey";
  key.className = "wide-field";
  key.autocomplete = "off";
  key.placeholder = pictures.has_key ? "•".repeat(20) + " (unchanged)" : "your DeepAI key";
  form.appendChild(fieldRow("DeepAI key", key,
    pictures.has_key
      ? "A key is set. Leaving this blank keeps it."
      : "From deepai.org. Without one the picture tools stay hidden."));

  form.appendChild(fieldRow("Styles it may use", styleFinder(pictures),
    "Tick the ones it may choose from. There are over a hundred, and a model offered "
    + "twelve will use twelve — most of them are wrong for a monitoring dashboard, so "
    + "two or three is plenty. Type to narrow the list; the ones you have ticked stay "
    + "at the top whatever you search for."));

  const quality = document.createElement("select");
  quality.id = "aiQuality";
  for (const [key_, meta] of Object.entries(pictures.qualities)) {
    const option = document.createElement("option");
    option.value = key_;
    option.textContent = `${meta.label} — ${meta.what}`;
    option.selected = pictures.quality === key_;
    quality.appendChild(option);
  }
  form.appendChild(fieldRow("Quality", quality, ""));

  const shape = document.createElement("select");
  shape.id = "aiShape";
  for (const [key_, meta] of Object.entries(pictures.shapes)) {
    const option = document.createElement("option");
    option.value = key_;
    option.textContent = `${meta.label} (${meta.width}×${meta.height})`;
    option.selected = pictures.shape === key_;
    shape.appendChild(option);
  }
  form.appendChild(fieldRow("Shape", shape, ""));

  const perHour = document.createElement("input");
  perHour.type = "number";
  perHour.id = "aiPerHour";
  perHour.min = "0";
  perHour.max = "200";
  perHour.className = "days";
  perHour.value = String(pictures.per_hour);
  form.appendChild(fieldRow("At most, per hour", perHour,
    "Across everything on this panel. A model that finds something amusing will keep "
    + "doing it, and each one is billed — this is what stops a loop running up a bill "
    + "before anybody notices. Zero switches picture-making off without losing the rest "
    + "of these settings."
    + (pictures.budget
      ? ` ${pictures.budget.used} made in the last hour.`
      : "")));

  const self = document.createElement("input");
  self.type = "checkbox";
  self.id = "aiSelfPortrait";
  self.checked = pictures.self_portrait;
  form.appendChild(fieldRow("Let it redraw itself", self,
    "A novelty: it can generate its own portrait, squared off and shrunk to a thumbnail. "
    + "Shares the hourly limit and asks permission each time."));

  const reactions = document.createElement("input");
  reactions.type = "checkbox";
  reactions.id = "aiReactions";
  reactions.checked = pictures.reactions;
  form.appendChild(fieldRow("Let it react", reactions,
    "Short animated images, searched rather than generated, for the occasional aside. It "
    + "chooses a mood, not an image — what comes back is whatever the catalogue "
    + "returns."));

  /*
   * Which search service, as a choice rather than a brand baked into the code.
   *
   * There are three with the same shape and different terms, and which one an
   * install may use is not something this code can know - one of them may be
   * the only one an employer will approve. The endpoint is a field too, for the
   * same reason.
   */
  const service = document.createElement("select");
  service.id = "aiSearchService";
  for (const [key_, meta] of Object.entries(pictures.services)) {
    const option = document.createElement("option");
    option.value = key_;
    option.textContent = meta.label;
    option.selected = pictures.search_service === key_;
    service.appendChild(option);
  }
  const serviceNote = document.createElement("div");
  serviceNote.className = "muted small";
  form.appendChild(fieldRow("Search service", service, ""));
  form.appendChild(serviceNote);

  const searchKey = document.createElement("input");
  searchKey.type = "password";
  searchKey.id = "aiSearchKey";
  searchKey.className = "wide-field";
  searchKey.autocomplete = "off";
  searchKey.placeholder = pictures.has_search_key
    ? "•".repeat(20) + " (unchanged)" : "the key for that service";
  form.appendChild(fieldRow("Search key", searchKey,
    pictures.has_search_key
      ? "A key is set. Leaving this blank keeps it."
      : "Without one, reactions stay off."));

  const searchBase = document.createElement("input");
  searchBase.type = "text";
  searchBase.id = "aiSearchBase";
  searchBase.className = "wide-field";
  searchBase.spellcheck = false;
  searchBase.value = pictures.search_base || "";
  form.appendChild(fieldRow("Endpoint", searchBase, ""));

  const searchRate = document.createElement("input");
  searchRate.type = "number";
  searchRate.id = "aiSearchRate";
  searchRate.min = "0";
  searchRate.max = "100";
  searchRate.className = "days";
  searchRate.value = String(pictures.searches_per_hour);
  form.appendChild(fieldRow("Searches per hour", searchRate,
    "Separate from the picture limit above, because the two cost different things: a "
    + "search is a free read against somebody else's quota, a picture is a bill. A "
    + "hundred is what these services publish as their free allowance and is the most "
    + "this will do — going past it gets the key throttled, which breaks the feature for "
    + "everyone rather than costing money. Set it lower if you share the key."
    + (pictures.searches ? ` ${pictures.searches.used} in the last hour.` : "")));

  const syncService = () => {
    const meta = pictures.services[service.value];
    serviceNote.textContent = meta?.note ?? "";
    searchBase.placeholder = meta?.base ?? "";
  };
  service.addEventListener("change", syncService);
  syncService();

  const rating = document.createElement("select");
  rating.id = "aiRating";
  for (const [value, label] of [["g", "G only"], ["pg", "PG and under"],
                                ["pg-13", "PG-13 and under"]]) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    option.selected = pictures.rating === value;
    rating.appendChild(option);
  }
  form.appendChild(fieldRow("Rating", rating,
    "This appears unannounced in a browser, possibly at work, chosen by a language model "
    + "from a search term it invented. G is the sensible default and there is no good "
    + "argument against it."));

  /*
   * What the pictures cost, which is not one number.
   *
   * The plan is a monthly fee with an allowance and then credits, so a
   * per-image price is only true once the allowance is gone. Both are asked for
   * and the arithmetic is shown rather than hidden: inside the allowance a
   * picture adds nothing to the session total, after it the per-image price
   * applies, and the monthly fee is reported as a monthly fee rather than
   * smeared across whatever happened to be generated.
   */
  const money = document.createElement("div");
  money.className = "settings";

  const tiers = pictures.allowance?.tiers ?? {};
  const each = tier => (tiers[tier]?.each
    ? ` Currently ${(tiers[tier].each / 100).toFixed(6).replace(/0+$/, "")} `
      + `per picture — ${tiers[tier].used} of ${tiers[tier].allowance} used this month.`
    : "");

  for (const [id, label, value, hint] of [
    ["aiMonthlyCents", "The plan, per month", pictures.monthly_cents,
      "In cents. 495 for a $4.95 plan. This is divided by the allowances below to work "
      + "out what one picture costs."],
    ["aiIncludedStandard", "Standard images included", pictures.included_standard,
      "How many the plan covers each month at the standard quality. The plan cost divided "
      + "by this is what one is reported as costing."
      + each("standard")],
    ["aiIncludedGenius", "Top-quality images included", pictures.included_genius,
      "The separate allowance for the expensive tier, counted apart from the standard one "
      + "so that using one does not run the other out."
      + each("genius")],
    ["aiPriceStandard", "Each standard one past that", pictures.price_standard,
      "In cents. Once the allowance is gone the plan charges for credits, and this is a "
      + "real cost rather than a share of the fee."],
    ["aiPriceHd", "…at HD", pictures.price_hd, "In cents."],
    ["aiPriceGenius", "…at the top quality", pictures.price_genius, "In cents."],
  ]) {
    const box = document.createElement("input");
    box.type = "number";
    box.id = id;
    box.min = "0";
    box.step = "0.01";
    box.className = "days";
    box.value = String(value ?? 0);
    money.appendChild(fieldRow(label, box, hint));
  }

  form.appendChild(section("What they cost", money));

  /*
   * What the number means, said out loud.
   *
   * Dividing a fixed monthly fee among the pictures it covers is the right
   * figure for "what did this conversation cost" and the wrong one for "what
   * will one more cost" - nothing is saved by generating one fewer. Both tiers
   * divide the same fee, so a full month of both adds up to more than the fee.
   * That is a real limitation of attributing a fixed cost and is better said
   * than discovered.
   */
  form.appendChild(note(
    "A picture inside the allowance has no marginal cost — the fee was paid for exactly "
    + "this — so what a conversation reports is the fee divided by the allowance. It is "
    + "what that picture cost you, not what one more would cost, and because both tiers "
    + "divide the same fee a full month of both would add up to more than the fee. Past "
    + "the allowance the credit price applies and is a real marginal cost."
  ));

  wrap.appendChild(form);
  return wrap;
}

/**
 * A searchable list of the hundred-odd generator styles.
 *
 * A column of 123 tick boxes is not a control, it is a wall - and the three
 * somebody has chosen are somewhere in the middle of it. So: chosen ones first
 * and always visible, a box to type in, and a count of what is hidden. Nothing
 * is removed from the form when it is filtered out, only hidden, because a
 * filter that unticked things by narrowing the view would be a filter that
 * silently changes settings.
 */
function styleFinder(pictures) {
  const wrap = document.createElement("div");
  wrap.className = "style-finder";

  const search = document.createElement("input");
  search.type = "search";
  search.className = "wide-field";
  search.placeholder = "type to narrow — cyberpunk, watercolour, pixel…";
  search.spellcheck = false;
  wrap.appendChild(search);

  const said = document.createElement("div");
  said.className = "muted small";
  wrap.appendChild(said);

  const list = document.createElement("div");
  list.className = "style-list";
  wrap.appendChild(list);

  const entries = Object.entries(pictures.all_styles ?? {});
  const rows = [];

  /*
   * Chosen first, then everything else alphabetically by its shown name.
   *
   * Sorted once, at build time: re-sorting as somebody ticks would move the row
   * out from under the pointer they just clicked with.
   */
  entries.sort(([aKey, aName], [bKey, bName]) => {
    const aOn = pictures.styles.includes(aKey);
    const bOn = pictures.styles.includes(bKey);
    if (aOn !== bOn) return aOn ? -1 : 1;
    return String(aName).localeCompare(String(bName));
  });

  for (const [key, name] of entries) {
    const line = document.createElement("label");
    line.className = "scan-toggle style-row";

    const box = document.createElement("input");
    box.type = "checkbox";
    box.className = "picture-style";
    box.dataset.style = key;
    box.checked = pictures.styles.includes(key);
    line.appendChild(box);

    const label = document.createElement("span");
    label.textContent = ` ${name}`;
    line.appendChild(label);

    const id = document.createElement("span");
    id.className = "muted small";
    id.textContent = ` ${key}`;
    line.appendChild(id);

    list.appendChild(line);
    rows.push({ line, box, haystack: `${name} ${key}`.toLowerCase() });
  }

  const sync = () => {
    const wanted = search.value.trim().toLowerCase();
    let shown = 0;

    for (const row of rows) {
      // A ticked style is never hidden: it is a setting in force, and a setting
      // you cannot see is one you cannot turn off.
      const keep = row.box.checked || wanted === "" || row.haystack.includes(wanted);
      row.line.hidden = !keep;
      if (keep) shown++;
    }

    const chosen = rows.filter(row => row.box.checked).length;
    said.textContent = `${count(chosen, "style")} ticked · `
      + (wanted === ""
        ? `${humanCount(rows.length)} to choose from`
        : `${humanCount(shown)} of ${humanCount(rows.length)} match`);
  };

  search.addEventListener("input", sync);
  list.addEventListener("change", sync);
  sync();

  return wrap;
}


async function saveAiSettings(extra = {}) {
  const on = [...document.querySelectorAll("input.tool-on")]
    .filter(box => box.checked).map(box => box.dataset.tool).join(",");
  const ask = [...document.querySelectorAll("input.tool-ask")]
    .filter(box => box.checked).map(box => box.dataset.tool).join(",");

  try {
    const result = await post("ai-settings-save", {
      enabled: $("aiEnabled").checked ? "1" : "0",
      provider: $("aiProvider").value,
      base_url: $("aiBase").value.trim(),
      model: $("aiModel").value.trim(),
      api_key: $("aiKey").value,
      price_in: $("aiPriceIn").value,
      price_out: $("aiPriceOut").value,
      price_cached: $("aiPriceCached").value,
      max_seconds: $("aiMaxSeconds").value,
      max_cents: $("aiMaxCents").value,
      max_turns: $("aiMaxTurns").value,
      daily_cents: $("aiDailyCents").value,
      monthly_cents: $("aiSharedMonthlyCents").value,
      reasoning_effort: $("aiEffort").value,
      name: $("aiName").value.trim(),
      emoji: $("aiEmoji").value.trim(),
      personality: $("aiPersonality").value,
      pictures_on: $("aiPicturesOn").checked ? "1" : "0",
      picture_key: $("aiPictureKey").value,
      styles: [...document.querySelectorAll("input.picture-style:checked")]
        .map(box => box.dataset.style).join(","),
      quality: $("aiQuality").value,
      shape: $("aiShape").value,
      per_hour: $("aiPerHour").value,
      self_portrait: $("aiSelfPortrait").checked ? "1" : "0",
      reactions_on: $("aiReactions").checked ? "1" : "0",
      search_service: $("aiSearchService").value,
      search_key: $("aiSearchKey").value,
      search_base: $("aiSearchBase").value.trim(),
      searches_per_hour: $("aiSearchRate").value,
      rating: $("aiRating").value,
      monthly_cents: $("aiMonthlyCents").value,
      included_standard: $("aiIncludedStandard").value,
      included_genius: $("aiIncludedGenius").value,
      price_standard: $("aiPriceStandard").value,
      price_hd: $("aiPriceHd").value,
      price_genius: $("aiPriceGenius").value,
      context_tokens: $("aiContextTokens").value,
      compact_at: $("aiCompactAt").value,
      compact_automatically: $("aiCompactAuto").checked ? "1" : "0",
      explain_commands: $("aiExplain").checked ? "1" : "0",
      host_commands: $("aiHostCommands").checked ? "1" : "0",
      alert_mode: $("aiAlertMode").value,
      alert_floor: $("aiAlertFloor").value,
      alert_per_run: $("aiAlertPerRun").value,
      report_daily: $("aiDaily").checked ? "1" : "0",
      report_weekly: $("aiWeekly").checked ? "1" : "0",
      report_monthly: $("aiMonthly").checked ? "1" : "0",
      report_to: $("aiReportTo").value.trim(),
      tools_on: on,
      tools_ask: ask,
      ...extra,
    });

    notice(aiSettingsText("saved", "Saved."), true);
    if (result.who) {
      chatState.who = {
        name: result.who.name,
        emoji: result.who.emoji,
        portrait: result.who.portrait,
      };
      renderChatIdentity();
    }
    renderAiSettings(result);
  } catch (error) {
    notice(String(error.message || error));
  }
}

async function refreshAiSessions() {
  const body = $("aiSessionsBody");

  try {
    const data = await api("ai-sessions");

    if (!data.sessions.length) {
      body.replaceChildren(note(aiSettingsText("sessions_empty", "No conversations yet.")));
      return;
    }

    const parts = [];
    const totals = data.totals;

    parts.push(factGrid([
      [aiSettingsText("sessions_conversations", "Conversations"), humanCount(totals.sessions)],
      [aiSettingsText("sessions_turns", "Turns"), humanCount(totals.turns)],
      [aiSettingsText("sessions_tokens", "Tokens"), aiSettingsText("sessions_tokens_summary",
        "{{input}} in, {{output}} out", { input: humanCount(totals.tokens_in), output: humanCount(totals.tokens_out) })
        + (totals.tokens_cached ? aiSettingsText("sessions_tokens_cached", ", {{tokens}} cached", { tokens: humanCount(totals.tokens_cached) }) : "")],
      [aiSettingsText("sessions_spent", "Spent"), totals.spent],
    ]));

    const holder = document.createElement("div");
    holder.id = "aiSessionTable";
    parts.push(holder);
    body.replaceChildren(...parts);

    renderTable("aiSessionTable", data.sessions, [
      { label: aiSettingsText("sessions_started", "Started"), render: row => whenSpan(row.started_at) },
      { label: aiSettingsText("sessions_ran_for", "Ran for"), render: row => row.ran_for },
      {
        label: aiSettingsText("sessions_ended", "How it ended"),
        render: row => {
          const span = document.createElement("span");
          span.textContent = row.state;
          if (row.why_stopped) span.title = row.why_stopped;
          if (row.state === "failed") span.className = "band-crit";
          return span;
        },
      },
      { label: aiSettingsText("sessions_model", "Model"), className: "cmd", render: row => row.model },
      { label: aiSettingsText("sessions_turns", "Turns"), className: "size", render: row => String(row.turns) },
      { label: aiSettingsText("sessions_tokens", "Tokens"), className: "size", render: row => humanCount(row.tokens) },
      { label: aiSettingsText("sessions_cost", "Cost"), className: "size", render: row => row.spent },
    ], null, null, row => String(row.id));
  } catch (error) {
    body.replaceChildren(note(String(error.message || error)));
  }
}

/* --------------------------------------------------- things it can show -- */

/**
 * A progress bar with a clock on it.
 *
 * The clock is the point. "Seventy per cent" is not an answer to "how long will
 * this take" and never has been, and a bar without one invites somebody to
 * stand and watch it. Drawn from the tool call, so it survives re-renders and
 * so the number shown is always the number the model actually said.
 */
function chatProgressCard(message) {
  const args = message.arguments || {};
  const kind = ["time", "count", "working"].includes(args.kind) ? args.kind : "time";

  const card = document.createElement("div");
  card.className = "chat-progress";

  const head = document.createElement("div");
  head.className = "chat-progress-head";
  head.textContent = String(args.what || aiSettingsText("progress_working", "Working"));
  card.appendChild(head);

  const track = document.createElement("div");
  track.className = "chat-progress-track";
  const fill = document.createElement("div");
  fill.className = "chat-progress-fill";
  track.appendChild(fill);
  card.appendChild(track);

  const said = document.createElement("div");
  said.className = "muted small";

  if (kind === "working") {
    /*
     * No number at all, because there is not one.
     *
     * A bar that sweeps says "something is happening and I cannot tell you how
     * much is left", which is a true statement and the whole reason this mode
     * exists. Filling it to some invented fraction would be a lie with a
     * picture attached.
     */
    track.classList.add("indeterminate");
    said.textContent = aiSettingsText("progress_unknown", "Working — the size of this job is not known.");
  } else if (kind === "count") {
    const total = Math.max(1, Number(args.total) || 1);
    const done = Math.max(0, Math.min(total, Number(args.done) || 0));
    const unit = String(args.unit || aiSettingsText("progress_steps", "steps"));

    fill.style.setProperty("--fill", `${Math.round((done / total) * 100)}%`);
    said.textContent = aiSettingsText("progress_count", "{{done}} of {{total}} {{unit}} done", { done, total, unit });
  } else {
    const percent = Math.max(0, Math.min(100, Number(args.percent) || 0));
    const left = Number(args.seconds_left);

    fill.style.setProperty("--fill", `${percent}%`);
    said.textContent = `${percent}%`
      + (Number.isFinite(left) && left > 0
        ? aiSettingsText("progress_time_left", " · about {{duration}} left", { duration: humanSpan(left, true) })
        : "");
  }

  /*
   * A drawn bar is a moment, not a live thing.
   *
   * It does not animate and the model has to call the tool again to move it,
   * so the time it was drawn is worth saying - otherwise a bar from four
   * minutes ago reads as current. The sweeping one is exempt: it is honestly
   * saying nothing about how far along anything is.
   */
  said.title = kind === "working"
    ? aiSettingsText("progress_indeterminate_title", "Started {{time}}. The sweep is decoration; it does not track anything.", { time: humanTime(message.at) })
    : aiSettingsText("progress_drawn_title", "Drawn {{time}}. It does not move on its own.", { time: humanTime(message.at) });
  card.appendChild(said);

  return card;
}

/**
 * A reaction image, if one was found.
 *
 * Returns null when the search came back empty, because an empty box with a
 * caption under it is worse than the aside simply not happening.
 */
function chatReactionCard(message) {
  const card = document.createElement("div");
  card.className = "chat-reaction";

  const image = document.createElement("img");
  image.src = message.url;
  image.alt = String(message.arguments?.mood || ZogographI18n.t("image.reaction", {}, "A reaction"));
  image.loading = "lazy";
  card.appendChild(image);

  if (message.arguments?.why) {
    const caption = document.createElement("div");
    caption.className = "muted small";
    caption.textContent = message.arguments.why;
    card.appendChild(caption);
  }

  return card;
}

/**
 * The line in the conversation where its older half was summarised.
 *
 * Not a message - neither party said it - so it is drawn as a rule across the
 * log rather than as a bubble. Everything above it is still there and still
 * readable; what changed is that the model no longer receives those messages,
 * it receives the summary. Saying which is the whole job of this marker,
 * because a conversation that quietly loses its first half is one somebody
 * stops trusting.
 */
function chatSummaryCard(message, session) {
  const wrap = document.createElement("div");
  wrap.className = "chat-summary";

  const head = document.createElement("button");
  head.type = "button";
  head.className = "chat-summary-head";

  const covers = message.covers ?? {};
  head.textContent = covers.messages
    ? aiSettingsText("summary_marker_count", "— everything above here was summarised ({{messages}} messages) —", { messages: covers.messages })
    : aiSettingsText("summary_marker", "— everything above here was summarised —");
  head.title = aiSettingsText("summary_marker_title", "Still yours to read. From here on the model receives the summary instead. Click to see it.");

  head.addEventListener("click", () => showCompaction(message, session));
  wrap.appendChild(head);

  return wrap;
}

/** The summary itself, and what it stands in for. */
function showCompaction(message, session) {
  const covers = message.covers ?? {};
  const nodes = [];

  const what = document.createElement("p");
  what.className = "muted small";
  what.textContent = covers.messages
    ? aiSettingsText("summary_replaced_count", "{{messages}} earlier messages were replaced with the summary below, {{time}}.", { messages: covers.messages, time: whenLabel(message.at) })
    : aiSettingsText("summary_replaced", "The older part of this conversation was replaced with the summary below, {{time}}.", { time: whenLabel(message.at) });
  what.textContent += " " + aiSettingsText("summary_retained", "They are all still above this point in the panel and still in the database — nothing was deleted. What changed is what the model is sent: from here on it gets this summary instead of those messages.");
  nodes.push(what);

  const body = document.createElement("div");
  body.className = "day-entry";
  const title = document.createElement("strong");
  title.textContent = aiSettingsText("summary_title", "The summary the model now receives");
  body.appendChild(title);
  const text = document.createElement("div");
  text.appendChild(renderMarkdown(message.content));
  body.appendChild(text);
  nodes.push(body);

  /*
   * The messages it stands for, by id range.
   *
   * Enough to find them in the panel above, and enough to check the summary
   * against them - which is the point of being able to open this at all.
   */
  if (covers.from_message && covers.to_message) {
    const which = document.createElement("p");
    which.className = "muted small";
    which.textContent = aiSettingsText("summary_range", "It covers messages {{from}} to {{to}} in this conversation.", { from: covers.from_message, to: covers.to_message });
    nodes.push(which);
  }

  showListDialog(
    aiSettingsText("summary_dialog_title", "What was summarised"),
    nodes,
    aiSettingsText("summary_dialog_help", "Written by the model, from the messages it replaced. If it says something the conversation above does not, that is worth knowing — and is the reason this can be opened.")
  );
}

/** A generated picture, with what was asked for underneath it. */
function chatPictureCard(message) {
  const card = document.createElement("div");
  card.className = "chat-picture";

  const image = document.createElement("img");
  image.src = message.url;
  image.alt = String(message.arguments?.description || ZogographI18n.t("image.generated", {}, "A generated picture"));
  image.loading = "lazy";
  card.appendChild(image);

  const caption = document.createElement("div");
  caption.className = "muted small";
  /*
   * The prompt is shown, always.
   *
   * A generated image is not evidence of anything, and somebody who cannot see
   * what was asked for has no way to tell an illustration from a hallucination
   * with a frame around it.
   */
  caption.textContent = message.arguments?.portrait
    ? aiSettingsText("picture_portrait_caption", "{{name}}, as it describes itself: \"{{description}}\"", { name: chatState.who.name, description: message.arguments.description })
    : aiSettingsText("picture_caption", "Drawn from: \"{{description}}\"", { description: message.arguments?.description ?? "" });
  card.appendChild(caption);

  return card;
}

/* ------------------------------------------------- pictures for the model -- */

/**
 * A chart drawn inside the conversation.
 *
 * The point is that the assistant can show somebody something without moving them
 * off whatever page they are on, and without needing to know anything about
 * how the page is laid out. It names a chart; the browser draws it.
 */
async function drawChatChart(args) {
  /*
   * Rendered off-screen, only to produce the record.
   *
   * The visible card is built by renderChat from the tool call itself, so that
   * it survives every re-render - appending it here meant the next poll's
   * replaceChildren threw it away, which is exactly what happened. Both go
   * through renderNamedChart, so the picture kept and the picture shown are
   * the same picture.
   */
  const holder = document.createElement("div");
  holder.className = "offscreen-chart";
  const canvas = document.createElement("canvas");
  holder.appendChild(canvas);
  document.body.appendChild(holder);

  try {
    await renderNamedChart(canvas, args.chart, Number(args.hours) || 24);
    return { image: canvas.toDataURL("image/webp", 0.8) };
  } finally {
    holder.remove();
  }
}

/**
 * The visible card for a show_chart call, cached by the message it belongs to.
 *
 * Cached because renderChat runs on every poll - several times a second while a
 * turn is in flight - and refetching a series and redrawing a canvas at that
 * rate would be absurd. The element is simply moved back into place.
 */
function chatChartCard(message) {
  const cached = chatState.charts.get(message.id);
  if (cached) return cached;

  const card = document.createElement("div");
  card.className = "chat-chart";
  card.dataset.message = String(message.id);

  const head = document.createElement("div");
  head.className = "chat-chart-head";
  head.textContent = "…";
  card.appendChild(head);

  const canvas = document.createElement("canvas");
  canvas.className = "chat-chart-canvas";
  card.appendChild(canvas);

  const caption = document.createElement("div");
  caption.className = "muted small";
  caption.textContent = message.arguments.why || "";
  card.appendChild(caption);

  chatState.charts.set(message.id, card);

  /*
   * Drawn after it is in the document.
   *
   * drawLineChart measures the element, and a canvas with no width produces a
   * 300x150 default that is then stretched - the one mistake this codebase has
   * made four times now.
   */
  requestAnimationFrame(async () => {
    try {
      const drawn = await renderNamedChart(
        canvas,
        message.arguments.chart,
        Number(message.arguments.hours) || 24
      );
      head.textContent = `${drawn.name} · `
        + `${humanSpan(Number(message.arguments.hours) * 3600, true)}`;

      /*
       * Where this chart actually lives.
       *
       * A picture in a chat window is a dead end: it cannot be hovered for a
       * value, ranged, or compared against the one below it. The page it came
       * from can do all three, and is one click away.
       */
      if (drawn.page && VIEWS[drawn.page]) {
        const go = document.createElement("button");
        go.className = "link small";
        go.textContent = ZogographI18n.t("chart.open_on_page", { page: VIEWS[drawn.page].label }, "Open it on {{page}}");
        go.addEventListener("click", () => {
          location.hash = `#/${drawn.page}?range=${state.range}`;
        });
        card.appendChild(go);
      }

      if (!drawn.points) {
        caption.textContent = ZogographI18n.t("chart.no_data", {}, "Nothing was recorded in this period.") + " "
          + (caption.textContent || "");
      }
    } catch (error) {
      head.textContent = ZogographI18n.t("chart.could_not_draw", {}, "That chart could not be drawn");
      caption.textContent = ZogographI18n.t("chart.error", { error: String(error.message || error) }, "Could not draw this visual: {{error}}");
    }
  });

  return card;
}

/** A visual whose numbers came from the assistant, rather than a built-in chart. */
function chatAssistantVisualCard(message) {
  const cached = chatState.charts.get(message.id);
  if (cached) return cached;
  const card = document.createElement("div");
  card.className = "chat-chart";
  const head = document.createElement("div");
  head.className = "chat-chart-head";
  head.textContent = message.arguments.title || ZogographI18n.t("chart.assistant_visual", {}, "Assistant visual");
  const canvas = document.createElement("canvas");
  canvas.className = "chat-chart-canvas";
  const caption = document.createElement("div");
  caption.className = "muted small";
  caption.textContent = message.arguments.why || "";
  card.append(head, canvas, caption);
  chatState.charts.set(message.id, card);
  requestAnimationFrame(() => {
    try { drawAssistantVisual(canvas, message.arguments); }
    catch (error) { caption.textContent = ZogographI18n.t("chart.error", { error: String(error.message || error) }, "Could not draw this visual: {{error}}"); }
  });
  return card;
}

function drawAssistantVisual(canvas, args) {
  const data = JSON.parse(String(args.data || "{}"));
  if (args.kind === "pie") {
    const slices = (data.slices || []).slice(0, 12).map(row => ({
      label: String(row.label || ZogographI18n.t("chart.visual_item", {}, "item")).slice(0, 40), value: Number(row.value),
    })).filter(row => Number.isFinite(row.value) && row.value >= 0);
    if (!slices.length) throw new Error(ZogographI18n.t("chart.visual_pie_data_error", {}, "Pie data needs numeric slices."));
    drawPieChart(canvas, slices, { axis: plainAxis });
    return;
  }
  if (args.kind === "gauge") {
    const value = Number(data.value), max = Number(data.max);
    if (!Number.isFinite(value) || !Number.isFinite(max) || max <= 0) throw new Error(ZogographI18n.t("chart.visual_gauge_data_error", {}, "Gauge data needs a value and a positive maximum."));
    drawGauge(canvas, {
      value, max,
      plain: data.label ? `${data.label}: ${value} / ${max}` : `${value} / ${max}`,
    }, null);
    return;
  }
  const series = (data.series || []).slice(0, 6).map(row => ({
    key: String(row.key || ""), label: String(row.label || row.key || ZogographI18n.t("chart.visual_series", {}, "series")),
  })).filter(row => row.key);
  const rows = (data.points || []).slice(0, 500).map((row, i) => ({ ...row, at: Number(row.at) || i }));
  if (!series.length || !rows.length) throw new Error(ZogographI18n.t("chart.visual_line_data_error", {}, "Line data needs series and points."));
  drawLineChart(canvas, rows, series, { xKey: "at", axis: plainAxis, zeroBased: false });
}

/**
 * One chart, rendered off-screen, as an image for the model.
 *
 * Off-screen because the user is not being shown this - it is an answer to a
 * question the model asked, and moving the page around to produce it would be
 * a strange thing to do to somebody mid-sentence.
 */
async function renderChartImage(args) {
  const holder = document.createElement("div");
  holder.className = "offscreen-chart";
  const canvas = document.createElement("canvas");
  holder.appendChild(canvas);
  document.body.appendChild(holder);

  try {
    await renderNamedChart(canvas, args.chart, Number(args.hours) || 24);
    // WebP: a chart is flat colour and hard edges, which is the case WebP
    // handles far better than JPEG and rather better than PNG.
    return canvas.toDataURL("image/webp", 0.82);
  } finally {
    holder.remove();
  }
}

/**
 * A picture of the page, without a browser extension.
 *
 * There is no API that hands a page an image of itself - getDisplayMedia is the
 * only route, and it asks which surface to share, which is the permission
 * prompt doing its job rather than an obstacle. The frame is grabbed and the
 * track stopped immediately, so nothing keeps capturing afterwards.
 */
async function captureScreen() {
  if (!navigator.mediaDevices?.getDisplayMedia) {
    throw new Error(ZogographI18n.t("chart.screenshot_unsupported", {}, "This browser cannot take a screenshot from a page."));
  }

  const stream = await navigator.mediaDevices.getDisplayMedia({
    video: { displaySurface: "browser" },
    audio: false,
    preferCurrentTab: true,
  });

  try {
    const video = document.createElement("video");
    video.srcObject = stream;
    video.muted = true;
    await video.play();

    // One frame, once there is one: a capture started before the first frame
    // arrives produces a blank image.
    await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));

    const canvas = document.createElement("canvas");
    canvas.width = video.videoWidth || 1280;
    canvas.height = video.videoHeight || 720;
    canvas.getContext("2d").drawImage(video, 0, 0);

    video.pause();
    video.srcObject = null;

    return canvas;
  } finally {
    // Always, including on failure: a capture left running shows the browser's
    // sharing indicator for ever and is alarming.
    for (const track of stream.getTracks()) track.stop();
  }
}

/**
 * Lets somebody crop and censor a screenshot before it is sent anywhere.
 *
 * This is the difference between a feature people can use and one they cannot.
 * A screenshot of this dashboard contains paths, addresses, domain names and
 * whatever a log line happened to say, and it is about to go to somebody else's
 * service.
 *
 * Everything is a layer until Send is pressed, and that is the change from the
 * first version. Redactions used to be painted into the image as soon as they
 * were drawn, which made them impossible to move, resize or remove - a
 * misplaced box meant starting again - and cropping had to flatten them first,
 * which was its own source of trouble. Now the base image is never modified:
 * there is a list of boxes and an optional crop rectangle, and the picture is
 * assembled once, at the end, from those.
 *
 * What is finally sent is flat. There is no layer anybody could peel back; the
 * black rectangles are pixels.
 *
 * Resolves to a data URL, or null if the user changed their mind.
 */
function editScreenshot(source, why) {
  return new Promise(resolve => {
    const dialog = $("shotDialog");
    const canvas = $("shotCanvas");
    const ctx = canvas.getContext("2d");

    /*
     * Scaled down on the way in, once.
     *
     * A capture of a large display is several megabytes and a model reads a
     * 1400-pixel image about as well as a 3000-pixel one. Doing it here rather
     * than at the end means the editing happens at the size that will be sent,
     * so what somebody blacked out is exactly what is black.
     */
    const width = Math.min(1400, source.width);
    const scale = width / source.width;
    const height = Math.round(source.height * scale);

    const base = document.createElement("canvas");
    base.width = width;
    base.height = height;
    base.getContext("2d").drawImage(source, 0, 0, width, height);

    /*
     * The whole editing state, in base-image coordinates.
     *
     * `crop` is a window onto the base rather than a new image. Keeping it that
     * way is what lets a crop be undone and lets redactions drawn before it
     * survive it - the previous version rewrote the base image on every crop
     * and then had to leave `width` and `height` pointing at the old size,
     * which is why the selection stopped following the pointer afterwards.
     */
    const shot = {
      crop: { x: 0, y: 0, w: width, h: height },
      boxes: [],
      chosen: -1,
      mode: "redact",
    };

    let drag = null;

    /* ------------------------------------------------- coordinates ------- */

    /** Where a pointer event is, in base-image coordinates. */
    const at = event => {
      const box = canvas.getBoundingClientRect();
      const inCanvas = {
        x: ((event.clientX - box.left) / box.width) * canvas.width,
        y: ((event.clientY - box.top) / box.height) * canvas.height,
      };
      return {
        x: shot.crop.x + inCanvas.x,
        y: shot.crop.y + inCanvas.y,
      };
    };

    /** How many base pixels one screen pixel is, for hit tolerances. */
    const perPixel = () => {
      const box = canvas.getBoundingClientRect();
      return box.width ? canvas.width / box.width : 1;
    };

    const inside = (box, point) =>
      point.x >= box.x && point.x <= box.x + box.w
      && point.y >= box.y && point.y <= box.y + box.h;

    /** Which corner of a box a point is on, or null. */
    const cornerAt = (box, point, tolerance) => {
      const corners = [
        ["nw", box.x, box.y],
        ["ne", box.x + box.w, box.y],
        ["sw", box.x, box.y + box.h],
        ["se", box.x + box.w, box.y + box.h],
      ];

      for (const [name, x, y] of corners) {
        if (Math.abs(point.x - x) <= tolerance && Math.abs(point.y - y) <= tolerance) {
          return name;
        }
      }

      return null;
    };

    /* ------------------------------------------------- drawing ----------- */

    const draw = () => {
      canvas.width = Math.round(shot.crop.w);
      canvas.height = Math.round(shot.crop.h);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(
        base,
        shot.crop.x, shot.crop.y, shot.crop.w, shot.crop.h,
        0, 0, canvas.width, canvas.height
      );

      const shift = box => ({
        x: box.x - shot.crop.x,
        y: box.y - shot.crop.y,
        w: box.w,
        h: box.h,
      });

      shot.boxes.forEach((box, index) => {
        paintRedaction(ctx, shift(box));

        // The one being edited gets handles, so it is obvious which will move.
        if (index === shot.chosen) {
          const here = shift(box);
          ctx.save();
          ctx.strokeStyle = "#4c9aff";
          ctx.lineWidth = 2;
          ctx.setLineDash([4, 3]);
          ctx.strokeRect(here.x, here.y, here.w, here.h);
          ctx.setLineDash([]);
          ctx.fillStyle = "#4c9aff";
          for (const [x, y] of [
            [here.x, here.y],
            [here.x + here.w, here.y],
            [here.x, here.y + here.h],
            [here.x + here.w, here.y + here.h],
          ]) {
            ctx.fillRect(x - 4, y - 4, 8, 8);
          }
          ctx.restore();
        }
      });

      if (drag && drag.kind === "new") {
        const here = shift(drag.box);
        ctx.save();
        ctx.strokeStyle = shot.mode === "redact" ? "#f2616b" : "#4c9aff";
        ctx.lineWidth = 2;
        ctx.setLineDash([6, 4]);
        ctx.strokeRect(here.x, here.y, here.w, here.h);
        ctx.restore();
      }
    };

    /* ------------------------------------------------- pointer ----------- */

    const onDown = event => {
      event.preventDefault();
      const point = at(event);
      const tolerance = 8 * perPixel();

      /*
       * An existing box takes the press before a new one is started.
       *
       * Topmost first, so a box drawn over another is the one that responds -
       * which is the same order they are painted in, and therefore the one
       * somebody expects from looking at it.
       */
      if (shot.mode === "redact") {
        for (let i = shot.boxes.length - 1; i >= 0; i--) {
          const box = shot.boxes[i];
          const corner = cornerAt(box, point, tolerance);

          if (corner) {
            shot.chosen = i;
            drag = { kind: "resize", index: i, corner, from: point, was: { ...box } };
            canvas.setPointerCapture(event.pointerId);
            draw();
            syncTools();
            return;
          }

          if (inside(box, point)) {
            shot.chosen = i;
            drag = { kind: "move", index: i, from: point, was: { ...box } };
            canvas.setPointerCapture(event.pointerId);
            draw();
            syncTools();
            return;
          }
        }
      }

      shot.chosen = -1;
      drag = { kind: "new", from: point, box: { x: point.x, y: point.y, w: 0, h: 0 } };
      canvas.setPointerCapture(event.pointerId);
      syncTools();
    };

    const onMove = event => {
      if (!drag) return;
      const point = at(event);

      if (drag.kind === "new") {
        drag.box = {
          x: Math.min(drag.from.x, point.x),
          y: Math.min(drag.from.y, point.y),
          w: Math.abs(point.x - drag.from.x),
          h: Math.abs(point.y - drag.from.y),
        };
      } else if (drag.kind === "move") {
        const box = shot.boxes[drag.index];
        box.x = drag.was.x + (point.x - drag.from.x);
        box.y = drag.was.y + (point.y - drag.from.y);
      } else if (drag.kind === "resize") {
        const box = shot.boxes[drag.index];
        const was = drag.was;
        const left = drag.corner.includes("w") ? point.x : was.x;
        const top = drag.corner.includes("n") ? point.y : was.y;
        const right = drag.corner.includes("e") ? point.x : was.x + was.w;
        const bottom = drag.corner.includes("s") ? point.y : was.y + was.h;

        box.x = Math.min(left, right);
        box.y = Math.min(top, bottom);
        box.w = Math.abs(right - left);
        box.h = Math.abs(bottom - top);
      }

      draw();
    };

    const onUp = () => {
      if (!drag) return;

      if (drag.kind !== "new") {
        drag = null;
        draw();
        syncTools();
        return;
      }

      const box = drag.box;
      drag = null;

      // A stray click is not a selection. Anything smaller than this is one.
      if (box.w < 8 || box.h < 8) {
        draw();
        syncTools();
        return;
      }

      if (shot.mode === "redact") {
        shot.boxes.push(box);
        shot.chosen = shot.boxes.length - 1;
      } else {
        /*
         * A crop narrows the window; it does not rewrite the image.
         *
         * So it can be undone, and so the boxes drawn before it keep meaning
         * what they meant. The new window is clamped inside the old one -
         * dragging past the edge should stop at the edge rather than reveal
         * what was already cropped away.
         */
        shot.crop = {
          x: Math.max(shot.crop.x, box.x),
          y: Math.max(shot.crop.y, box.y),
          w: Math.min(box.w, shot.crop.x + shot.crop.w - Math.max(shot.crop.x, box.x)),
          h: Math.min(box.h, shot.crop.y + shot.crop.h - Math.max(shot.crop.y, box.y)),
        };
        shot.mode = "redact";
      }

      draw();
      syncTools();
    };

    canvas.addEventListener("pointerdown", onDown);
    canvas.addEventListener("pointermove", onMove);
    canvas.addEventListener("pointerup", onUp);

    /* ------------------------------------------------- tools ------------- */

    const syncTools = () => {
      const cropped = shot.crop.w < width || shot.crop.h < height;

      $("shotUndo").disabled = shot.boxes.length === 0 && !cropped;
      $("shotDrop").hidden = shot.chosen < 0;
      $("shotUncrop").hidden = !cropped;
      $("shotRedactMode").classList.toggle("chosen", shot.mode === "redact");
      $("shotCropMode").classList.toggle("chosen", shot.mode === "crop");

      $("shotHint").textContent = shot.mode === "redact"
        ? (shot.chosen >= 0
          ? "Drag it to move, drag a corner to resize, or press Delete to remove it."
          : "Drag a box over anything that should not be sent. You can move, resize or "
            + "remove it afterwards — nothing is fixed until you send.")
        : "Drag a box around the part worth sending. Everything outside it is left out, "
          + "and you can undo it.";

      $("shotCount").textContent = [
        shot.boxes.length ? `${count(shot.boxes.length, "area")} blacked out` : "",
        cropped ? `cropped to ${Math.round(shot.crop.w)}×${Math.round(shot.crop.h)}` : "",
      ].filter(Boolean).join(" · ");
    };

    const dropChosen = () => {
      if (shot.chosen < 0) return;
      shot.boxes.splice(shot.chosen, 1);
      shot.chosen = -1;
      draw();
      syncTools();
    };

    const onKey = event => {
      if (event.key === "Delete" || event.key === "Backspace") {
        if (shot.chosen >= 0) {
          event.preventDefault();
          dropChosen();
        }
      }
    };

    document.addEventListener("keydown", onKey);

    const finish = value => {
      canvas.removeEventListener("pointerdown", onDown);
      canvas.removeEventListener("pointermove", onMove);
      canvas.removeEventListener("pointerup", onUp);
      document.removeEventListener("keydown", onKey);
      dialog.close();
      resolve(value);
    };

    $("shotRedactMode").onclick = () => {
      shot.mode = "redact";
      syncTools();
    };
    $("shotCropMode").onclick = () => {
      shot.mode = "crop";
      shot.chosen = -1;
      draw();
      syncTools();
    };
    $("shotDrop").onclick = () => dropChosen();
    $("shotUncrop").onclick = () => {
      shot.crop = { x: 0, y: 0, w: width, h: height };
      draw();
      syncTools();
    };
    $("shotUndo").onclick = () => {
      if (shot.boxes.length) {
        shot.boxes.pop();
        shot.chosen = -1;
      } else {
        shot.crop = { x: 0, y: 0, w: width, h: height };
      }
      draw();
      syncTools();
    };
    $("shotCancel").onclick = () => finish(null);

    $("shotSend").onclick = () => {
      /*
       * Assembled and flattened here, once, and only here.
       *
       * Everything up to this point has been a description of what to do to the
       * image. This is where it happens: the cropped region is drawn, the
       * redactions are painted into those pixels, and what comes out has no
       * version of the hidden content in it at all.
       *
       * WebP because a screenshot of a dashboard is flat colour and hard edges,
       * which it compresses far better than JPEG - typically a third the size
       * at a quality nobody reading it would question.
       */
      const out = document.createElement("canvas");
      out.width = Math.round(shot.crop.w);
      out.height = Math.round(shot.crop.h);

      const flat = out.getContext("2d");
      flat.drawImage(
        base,
        shot.crop.x, shot.crop.y, shot.crop.w, shot.crop.h,
        0, 0, out.width, out.height
      );

      for (const box of shot.boxes) {
        paintRedaction(flat, {
          x: box.x - shot.crop.x,
          y: box.y - shot.crop.y,
          w: box.w,
          h: box.h,
        });
      }

      const webp = out.toDataURL("image/webp", 0.8);
      // A browser without WebP encoding silently returns a PNG; either is fine
      // and the server accepts both.
      finish(webp.startsWith("data:image/webp") ? webp : out.toDataURL("image/png"));
    };

    $("shotWhy").textContent = why
      ? `${chatState.who.name} asked for this: “${why}”`
      : `${chatState.who.name} asked for a screenshot.`;

    syncTools();
    dialog.showModal();

    /*
     * Painted after the dialog is on screen, not before.
     *
     * A canvas painted while its dialog is still display:none showed black
     * until something else invalidated it - which in practice meant it looked
     * broken until the first click. Two frames, because one is not always
     * enough for a dialog that has just been promoted to the top layer.
     */
    requestAnimationFrame(() => requestAnimationFrame(draw));
  });
}

/**
 * One blacked-out area, with a border and the word so nobody has to guess.
 *
 * Labelled because an unexplained black rectangle in an image sent to a model
 * reads as a rendering fault, and a model that thinks the page is broken will
 * say so. "Redacted" tells it something was deliberately withheld, which is
 * both true and useful to it.
 */
function paintRedaction(ctx, box) {
  ctx.save();

  ctx.fillStyle = "#000";
  ctx.fillRect(box.x, box.y, box.w, box.h);

  ctx.strokeStyle = "#f2616b";
  ctx.lineWidth = 2;
  ctx.strokeRect(box.x + 1, box.y + 1, box.w - 2, box.h - 2);

  // Only where it fits; a label spilling out of its box is worse than none.
  const size = Math.min(16, Math.max(9, box.h * 0.4));
  ctx.font = `${size}px system-ui, sans-serif`;
  const label = "Redacted";

  if (ctx.measureText(label).width + 10 < box.w && box.h > size + 4) {
    ctx.fillStyle = "#f2616b";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(label, box.x + box.w / 2, box.y + box.h / 2);
  }

  ctx.restore();
}


/* ----------------------------------------------------------- what is run -- */

/*
 * When work happens, on both collectors, in one place.
 *
 * Five things that looked separate and are one: what the host runs, what the
 * account runs, collecting more eagerly while somebody is looking, things worth
 * recording only while somebody is looking, and how hard to throttle anything
 * that leaves the machine. They interlock - a scan set to hourly that also
 * speeds up while browsing and also shares a per-run budget cannot be
 * configured on three pages without the settings contradicting each other.
 */
const scanState = { data: null };

/*
 * Named for the page it draws, not for what it is about.
 *
 * It was called refreshScans, which is also the name of the function that draws
 * the whole Storage page - and in JavaScript the second declaration simply
 * replaces the first. So Storage called this one, which writes into two panels
 * that are not on Storage, and every panel there came up empty while the API
 * was returning perfectly good data. Nothing errored; the page was just blank.
 */
async function refreshScanSchedule(side) {
  const body = $(side === "host" ? "hostScansBody" : "accountScansBody");

  if (!state.signedIn) {
    body.replaceChildren(note(ZogographI18n.t("common.sign_in_to_see", {}, "Sign in to see this.")));
    return;
  }

  if (formIsDirty(body)) {
    keepIfEditing(side === "host" ? "hostScansBody" : "accountScansBody", () => {});
    return;
  }

  try {
    const data = await api("scan-schedule");
    renderScans(data);
    markFormRendered($("accountScansBody"));
    markFormRendered($("hostScansBody"));
  } catch (error) {
    body.replaceChildren(note(String(error.message || error)));
  }
}

function renderScans(data) {
  scanState.data = data;

  for (const side of ["account", "host"]) {
    const body = $(side === "host" ? "hostScansBody" : "accountScansBody");
    if (!body) continue;

    const rows = data.scans.filter(scan => scan.side === side);
    const parts = [];

    if (side === "host" && !data.host_enabled) {
      const warning = note("The host collector is not enabled, so none of these run. ");
      const link = document.createElement("a");
      link.href = "./setup.php?section=host";
      link.textContent = ZogographI18n.t("host.open_setup", {}, "Open Host setup");
      warning.appendChild(link);
      parts.push(warning);
    }

    if (side === "account" && data.browsing) {
      parts.push(note(
        `Somebody has the dashboard open right now (last seen ${ago(data.last_browsed_at)}), `
        + "so anything set to speed up while browsing is currently on its shorter interval."
      ));
    }

    parts.push(scanTable(rows, data));

    const actions = document.createElement("div");
    actions.className = "inspect-actions";
    const save = document.createElement("button");
    save.type = "submit";
    save.textContent = ZogographI18n.t("setup.save", {}, "Save");
    save.disabled = !data.writable;
    actions.appendChild(save);

    if (!data.writable) {
      actions.appendChild(note(ZogographI18n.t("setup.config_not_writable", {}, "lib/config.php is not writable, so these cannot change.")));
    }
    parts.push(actions);

    body.replaceChildren(...parts);
  }

  renderThrottles(data);
}

function scanTable(rows, data) {
  const table = document.createElement("table");
  table.className = "retention";

  const head = table.createTHead().insertRow();
  for (const [key, fallback] of [["scan.what", "What"], ["scan.how_often", "How often"], ["scan.recommended", "Recommended"], ["scan.last_run", "Last run"], ["scan.next", "Next"], ["", ""]]) {
    const th = document.createElement("th");
    th.textContent = key ? ZogographI18n.t(key, {}, fallback) : fallback;
    head.appendChild(th);
  }

  const tbody = table.createTBody();

  for (const scan of rows) {
    const row = tbody.insertRow();

    const what = row.insertCell();
    what.className = "name";
    what.appendChild(document.createTextNode(scan.label));
    what.appendChild(helpIcon({
      title: scan.what,
      note: `${scan.cost} ${scan.why}`,
      mine: false,
    }));

    const often = row.insertCell();
    const select = document.createElement("select");
    select.className = "scan-every";
    select.name = `every_${scan.key.replace(/-/g, "_")}`;
    select.dataset.scan = scan.key;
    select.disabled = !data.writable;

    for (const [seconds, label] of Object.entries(data.intervals)) {
      const option = document.createElement("option");
      option.value = seconds;
      option.textContent = label;
      option.selected = Number(scan.every) === Number(seconds);
      select.appendChild(option);
    }
    often.appendChild(select);

    /*
     * The two switches only appear where they mean something.
     *
     * A disk walk that ran faster because somebody opened a page would be
     * actively harmful, so it is not offered the option - an unavailable
     * choice is better than one that is available and wrong.
     */
    if (scan.browse_boost > 0) {
      often.appendChild(toggleLine("boost", scan, data, ZogographI18n.t(
        "scan.boost_while_browsing", { interval: humanSpan(scan.browse_boost) },
        "speed up to every {{interval}} while somebody is looking")));
    }
    if (scan.live_only || scan.browse_boost > 0) {
      often.appendChild(toggleLine("live_only", scan, data,
        ZogographI18n.t("scan.only_while_browsing", {}, "only while somebody is looking")));
    }

    const suggested = row.insertCell();
    suggested.className = "muted";
    suggested.textContent = data.intervals[scan.recommended] ?? "";
    if (Number(scan.every) === Number(scan.recommended)) {
      suggested.className = "muted band-ok";
      suggested.textContent = ZogographI18n.t("scan.as_recommended", {}, "as recommended");
    }
    /*
     * "Only when asked" as a recommendation needs its reason attached.
     *
     * Otherwise it reads as a setting nobody filled in, and somebody helpfully
     * turns on an hourly walk of every filesystem on a shared machine.
     */
    if (scan.recommended === 0) {
      suggested.title = scan.why;
    }

    const last = row.insertCell();
    last.textContent = scan.last_at ? ago(scan.last_at) : ZogographI18n.t("scan.never", {}, "never");
    if (scan.last_at) last.title = humanTime(scan.last_at);

    const next = row.insertCell();
    next.className = "muted";
    next.textContent = scan.due ? ZogographI18n.t("scan.due_now", {}, "due now") : scan.due_why;
    if (scan.due) next.className = "band-warn";

    const actions = row.insertCell();
    actions.className = "row-actions";

    if (scan.pending) {
      const waiting = document.createElement("span");
      waiting.className = "band-warn small";
      waiting.textContent = ZogographI18n.t("scan.requested", { when: ago(scan.pending.requested_at) }, "asked {{when}}");
      actions.appendChild(waiting);

      const cancel = document.createElement("button");
      cancel.type = "button";
      cancel.className = "link danger";
      cancel.textContent = ZogographI18n.t("action.cancel", {}, "Cancel");
      cancel.addEventListener("click", async () => {
        cancel.disabled = true;
        try {
          await post("cancel-task", { task: scan.pending.task });
          notice(ZogographI18n.t("scan.request_withdrawn", {}, "Request withdrawn. The collector will not run it."), true);
          await refreshScanSchedule(scan.side);
        } catch (error) {
          notice(String(error.message || error));
          cancel.disabled = false;
        }
      });
      actions.appendChild(cancel);
    } else if (scan.goes_to) {
      const go = document.createElement("button");
      go.type = "button";
      go.className = "link";
      go.textContent = ZogographI18n.t("scan.set_up", {}, "Set one up");
      go.title = ZogographI18n.t("scan.set_up_title", {}, "This one needs choosing before it can be asked for");
      go.addEventListener("click", () => {
        location.hash = `#/${scan.goes_to}?range=${state.range}`;
      });
      actions.appendChild(go);
    } else if (scan.can_ask) {
      const ask = document.createElement("button");
      ask.type = "button";
      ask.className = "link";
      ask.textContent = ZogographI18n.t("scan.ask", {}, "Ask for one");
      ask.title = ZogographI18n.t("scan.ask_title", {}, "It happens on the collector's next pass, not now");
      ask.addEventListener("click", async () => {
        ask.disabled = true;
        try {
          /*
           * The catalogue names the action, not a raw task string.
           *
           * Two of these already had their own endpoint before this page
           * existed, and routing everything through one would have meant a
           * third way of asking for the same thing.
           */
          const [action, argument] = String(scan.task).split(":");
          await post(action, argument ? { task: argument } : {});
          notice("Asked. It runs on the host collector's next pass.", true);
          await refreshScanSchedule(scan.side);
        } catch (error) {
          notice(String(error.message || error));
        } finally {
          ask.disabled = false;
        }
      });
      actions.appendChild(ask);
    }
  }

  return table;
}

/** One of the two per-scan switches, as a line under its interval. */
function toggleLine(kind, scan, data, label) {
  const line = document.createElement("label");
  line.className = "scan-toggle muted small";

  const box = document.createElement("input");
  box.type = "checkbox";
  box.className = `scan-${kind}`;
  box.dataset.scan = scan.key;
  box.checked = Boolean(scan[kind]);
  box.disabled = !data.writable;
  line.appendChild(box);

  line.appendChild(document.createTextNode(" " + label));
  return line;
}

function renderThrottles(data) {
  const body = $("throttleBody");
  if (!body) return;

  const parts = [];
  const form = document.createElement("div");
  form.className = "settings";

  const fallback = document.createElement("input");
  fallback.type = "number";
  fallback.id = "throttleDefault";
  fallback.min = "1";
  fallback.max = "50";
  fallback.className = "days";
  fallback.value = String(data.throttle.default);
  fallback.disabled = !data.writable;
  form.appendChild(fieldRow("Anything not listed below", fallback,
    "Per collector run. One is the floor: a budget of zero would stop a queue for ever, "
    + "which is never what anybody means by “slow down”."));

  for (const command of data.throttle.commands) {
    const input = document.createElement("input");
    input.type = "number";
    input.className = "days throttle-command";
    input.dataset.command = command.command;
    input.min = "1";
    input.max = "50";
    input.value = String(command.per_run);
    input.disabled = !data.writable;
    form.appendChild(fieldRow(command.command, input, command.why));
  }

  parts.push(form);

  const actions = document.createElement("div");
  actions.className = "inspect-actions";
  const save = document.createElement("button");
  save.type = "submit";
  save.textContent = ZogographI18n.t("setup.save", {}, "Save");
  save.disabled = !data.writable;
  actions.appendChild(save);
  parts.push(actions);

  body.replaceChildren(...parts);
}

/**
 * Sends everything on both pages at once.
 *
 * Both forms save the whole set, because the settings interlock: saving one
 * page's half against a config the other page had already changed would
 * silently revert it.
 */
async function saveScans() {
  const values = {};

  for (const select of document.querySelectorAll("select.scan-every")) {
    values[select.name] = select.value;
  }

  values.boosted = [...document.querySelectorAll("input.scan-boost:checked")]
    .map(box => box.dataset.scan).join(",");
  values.live_only = [...document.querySelectorAll("input.scan-live_only:checked")]
    .map(box => box.dataset.scan).join(",");

  const fallback = $("throttleDefault");
  if (fallback) values.throttle_default = fallback.value;

  for (const input of document.querySelectorAll("input.throttle-command")) {
    values[`throttle_${input.dataset.command}`] = input.value;
  }

  try {
    renderScans(await post("scan-schedule-save", values));
    notice("Saved. The next collector run will use these.", true);
  } catch (error) {
    notice(String(error.message || error));
  }
}

/* ------------------------------------------------------------ chart names -- */

/*
 * Every chart says what it is, if you ask it.
 *
 * Three parties need a shared word for a chart: the person looking at it, the
 * model reasoning about it, and the code drawing it. Without one, a
 * conversation goes "the memory graph" - and there are four of those - or the
 * model asks for a picture of the whole window because it has no way to name
 * the part it wants.
 *
 * So each chart carries a small mark that names it on hover, along with the
 * range it is currently showing. It is deliberately quiet: a chart covered in
 * identifiers is worse for the ninety-nine per cent of the time nobody is
 * talking to anybody about it.
 *
 * The catalogue is fetched once from the server, which is where the definitions
 * live - the same list the model is given, so the two cannot drift.
 */
const chartNames = { known: null };

async function loadChartNames() {
  if (chartNames.known || !state.signedIn || disabledCoreRoutes.has("charts")) return chartNames.known;

  try {
    chartNames.known = (await api("charts")).charts;
  } catch {
    chartNames.known = {};
  }

  return chartNames.known;
}

/**
 * Puts the identity mark on every chart that has a name.
 *
 * Called after a view renders. Idempotent, because a redraw does not
 * necessarily rebuild the DOM around a canvas and a second mark would be worse
 * than none.
 */
function markCharts() {
  const known = chartNames.known;
  if (!known) return;

  const view = document.querySelector(".view:not([hidden])");
  if (!view) return;

  for (const canvas of view.querySelectorAll("canvas[id]")) {
    const chart = known[canvas.id];
    if (!chart) continue;

    const holder = canvas.parentElement;
    if (!holder || holder.querySelector(`.chart-id[data-for="${canvas.id}"]`)) continue;

    const mark = document.createElement("span");
    mark.className = "chart-id";
    mark.dataset.for = canvas.id;
    mark.textContent = "ⓘ";
    mark.tabIndex = 0;
    mark.setAttribute("role", "note");
    mark.title = chartIdentity(canvas.id, chart);
    mark.setAttribute("aria-label", mark.title);

    /*
     * Clicking copies the id.
     *
     * Because the point of naming a chart is telling somebody else which one,
     * and retyping "diskUsedChart" from a tooltip is exactly the friction that
     * stops people bothering.
     */
    mark.addEventListener("click", async event => {
      event.stopPropagation();
      try {
        await navigator.clipboard.writeText(canvas.id);
        mark.textContent = "✓";
        setTimeout(() => { mark.textContent = "ⓘ"; }, 1200);
      } catch {
        notice(`This chart is called ${canvas.id}.`, true);
      }
    });

    // Positioned against the panel, so it sits in the corner of the chart.
    if (getComputedStyle(holder).position === "static") {
      holder.classList.add("holds-chart");
    }
    holder.appendChild(mark);
  }
}

/** What the mark says: the id, the name, the range, and what it plots. */
function chartIdentity(id, chart) {
  const to = state.frozenAt || Math.floor(Date.now() / 1000);
  const from = to - state.range;

  return [
    `${chart.name}`,
    `id: ${id}`,
    `showing: ${humanTime(from)} to ${humanTime(to)} (${humanSpan(state.range, true)})`,
    `units: ${chart.units}`,
    state.frozenAt ? "pinned to a moment" : "up to now",
    "",
    chart.what,
    "",
    `Click to copy the id. You can tell ${chatState.who.name} which chart you mean by name.`,
  ].join("\n");
}

/**
 * Draws one of the named charts into a canvas, from data fetched for it.
 *
 * Shared by the in-chat card and the image tool, so what the model is told it
 * showed and what the user actually saw are the same picture.
 */
async function renderNamedChart(canvas, chartId, hours) {
  const known = await loadChartNames();
  const chart = known?.[chartId];
  if (!chart) throw new Error(`there is no chart called ${chartId}`);

  const data = await api("chart-series", { chart: chartId, hours });
  if (data.error) throw new Error(data.error);

  /*
   * Rebuilt into the shape drawLineChart wants.
   *
   * The server returns one list of points per measurement; the chart wants one
   * list of rows with a key per measurement. Merged on the timestamp, which is
   * the same bucket boundary for every series because they were bucketed
   * together.
   */
  const rows = new Map();
  const series = [];

  for (const one of data.series) {
    series.push({ key: one.measurement, label: one.label });
    for (const point of one.points) {
      const at = point.at;
      if (!rows.has(at)) rows.set(at, { at });
      // The highest in the bucket, not the average: a chart drawn from averages
      // hides exactly the spikes somebody is looking for.
      rows.get(at)[one.measurement] = point.high;
    }
  }

  const ordered = [...rows.values()].sort((a, b) => a.at - b.at);

  /*
   * The axis that matches what is being plotted.
   *
   * Everything except bytes was drawn on a plain number axis, so a CPU chart in
   * the conversation had a y-axis reading 0, 25, 50, 75 with no indication that
   * those were per cent - which on a dashboard where percentages are of the
   * account's allowance rather than the machine is exactly the ambiguity worth
   * avoiding.
   */
  const axis = {
    bytes: undefined,
    percent: percentAxis,
    count: countAxis,
    ms: msAxis,
    rate: rateAxis,
  }[data.units] ?? plainAxis;

  drawLineChart(canvas, ordered, series, {
    xKey: "at",
    axis,
    // A percentage has a floor and a ceiling, and drawing it without them makes
    // a wobble between 41 and 43 look like a crisis.
    zeroBased: data.units === "percent",
    max: data.units === "percent" ? 100 : undefined,
    empty: "Nothing recorded in this period",
    // No note marks on a chart drawn for a conversation: they belong to the
    // page, and here they would be unexplained.
    notes: [],
  });

  return { name: chart.name, points: ordered.length, page: data.page ?? chart.view };
}

/* ----------------------------------------------------------------- lookout -- */

/*
 * The chat, and the loop that drives it.
 *
 * There is no worker on the server, so the conversation advances one step per
 * request and this is what asks for the next one. Which sounds like a
 * compromise and is not: it means every intermediate state - thinking, running
 * a tool, waiting for permission - is a thing the panel can show, rather than a
 * minute of silence followed by an answer.
 *
 * The panel deliberately outlives the page it was opened from. The assistant's
 * most useful move is to take somebody to another view and keep talking about
 * what they are now looking at, and a chat that reset on navigation could not.
 */
const chatState = {
  session: null,
  polling: null,
  busy: false,
  open: false,
  /*
   * Tool runs already handled, so a poll arriving mid-flight cannot start the
   * same screenshot twice. The server would reject the second, but the camera
   * would already have flashed.
   */
  handled: new Set(),
  // Chart cards by the message that asked for them, so a poll does not redraw
  // every chart in the conversation several times a second.
  charts: new Map(),
  // A question this page is putting to the user for a tool, if there is one.
  prompt: null,
  // When each permission question runs out, by tool-run id. Kept outside the
  // prompt because the prompt is rebuilt on every poll and the clock must not
  // restart with it.
  deadlines: new Map(),
  // Name, emoji and portrait, refreshed with the session.
  who: { name: "Assistant", emoji: "✦", portrait: null },
};

const voiceState = { speak: false, listen: false, listenMode: "never", voice: "", rate: 1, pitch: 1, volume: 1, recognition: null, utterance: null, spoken: new Set() };

function configureUtterance(utterance) {
  utterance.lang = navigator.language || "en-US";
  utterance.rate = voiceState.rate;
  utterance.pitch = voiceState.pitch;
  utterance.volume = voiceState.volume;
  const selected = window.speechSynthesis?.getVoices().find(voice => voice.voiceURI === voiceState.voice);
  if (selected) utterance.voice = selected;
  return utterance;
}

function speakAssistantReply(session) {
  if (!voiceState.speak || !window.speechSynthesis) return;
  const last = [...(session.messages || [])].reverse().find(message => message.role === "assistant");
  if (!last || voiceState.spoken.has(last.id)) return;
  voiceState.spoken.add(last.id);
  const utterance = configureUtterance(new SpeechSynthesisUtterance(String(last.content || "").slice(0, 6000)));
  /* Do not let the microphone transcribe Zogograph's own reply. Stop rather
   * than merely ignoring results: recognition engines can queue audio and
   * submit it after speech has finished. */
  const resumeListening = voiceState.listen && voiceState.listenMode === "always";
  if (voiceState.listen) {
    voiceState.listen = false;
    voiceState.recognition?.stop();
  }
  voiceState.utterance = utterance;
  utterance.onend = utterance.onerror = () => {
    if (voiceState.utterance !== utterance) return;
    voiceState.utterance = null;
    if (resumeListening && voiceState.listenMode === "always" && !voiceState.listen) {
      try { toggleRecognition(); } catch (error) { notice(String(error.message || error)); }
    }
  };
  window.speechSynthesis.cancel();
  window.speechSynthesis.speak(utterance);
}

function toggleRecognition() {
  const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!Recognition) throw new Error("speech recognition is not available in this browser");
  if (voiceState.listen) {
    voiceState.listen = false;
    voiceState.recognition?.stop();
    $("chatListen").textContent = ZogographI18n.t("assistant.listen", {}, "Listen");
    return;
  }
  const recognition = voiceState.recognition ?? new Recognition();
  recognition.continuous = true;
  recognition.interimResults = false;
  recognition.lang = navigator.language || "en-US";
  recognition.onresult = event => {
    const text = event.results[event.results.length - 1][0].transcript.trim();
    if (text) sayToChat(text).catch(error => notice(String(error.message || error)));
  };
  recognition.onend = () => {
    if (voiceState.listen && voiceState.listenMode === "always") recognition.start();
  };
  recognition.onerror = event => {
    voiceState.listen = false;
    $("chatListen").textContent = voiceState.listenMode === "push"
      ? ZogographI18n.t("assistant.hold_to_talk", {}, "Hold to talk")
      : ZogographI18n.t("assistant.start_listening", {}, "Start listening");
    notice(`Microphone listening stopped: ${event.error || "browser error"}.`);
  };
  voiceState.recognition = recognition;
  voiceState.listen = true;
  recognition.start();
  $("chatListen").textContent = voiceState.listenMode === "push"
    ? ZogographI18n.t("assistant.listening", {}, "Listening…")
    : ZogographI18n.t("assistant.stop_listening", {}, "Stop listening");
}

function applyVoicePreferences(preferences) {
  const priorMode = voiceState.listenMode;
  voiceState.speak = preferences.speaking === "replies";
  voiceState.listenMode = preferences.listening;
  voiceState.voice = preferences.voice;
  voiceState.rate = preferences.rate;
  voiceState.pitch = preferences.pitch;
  voiceState.volume = preferences.volume;
  if (voiceState.listen && (preferences.listening === "never" || priorMode !== preferences.listening)) toggleRecognition();
  $("chatSpeak").textContent = voiceState.speak
    ? ZogographI18n.t("assistant.speaking", {}, "Speaking")
    : ZogographI18n.t("assistant.speak", {}, "Speak");
  $("chatListen").hidden = preferences.listening === "never";
  $("chatListen").textContent = preferences.listening === "push"
    ? ZogographI18n.t("assistant.hold_to_talk", {}, "Hold to talk")
    : ZogographI18n.t("assistant.start_listening", {}, "Start listening");
}

/** How often to ask, by what the session is doing. */
function chatPollDelay(state) {
  // Nothing is happening: slow, just enough to notice a session ended.
  if (state === "idle" || state === undefined) return 4000;
  // Waiting on a person: they are looking at the prompt, not at a clock.
  if (state === "waiting_permission") return 2000;
  // A step is due or in flight: fast enough to feel live, slow enough not to
  // hammer a database the collectors are also using.
  return 700;
}

function openChat() {
  if (!state.signedIn) {
    notice(`Sign in to ask ${chatState.who.name}.`);
    return;
  }

  chatState.open = true;
  $("chatPanel").hidden = false;
  $("chatText").focus();

  refreshChat().catch(error => notice(String(error.message || error)));
}

/**
 * Puts the chat panel on its own page, at full size.
 *
 * The panel is moved rather than copied. It is the same element, the same
 * conversation and the same code - a second implementation would be a second
 * set of bugs, and a second conversation would be worse than either. All this
 * page does is give it somewhere bigger to stand.
 */
function openChatFull() {
  const panel = $("chatPanel");
  const home = $("chatFull");
  if (!panel || !home) return;

  if (panel.parentElement !== home) {
    // What to go back to. Somebody who had the panel open keeps it open;
    // somebody who did not is not given one because they looked at a page.
    chatState.wasOpen = chatState.open;
    home.appendChild(panel);
    panel.classList.add("chat-wide");
  }

  panel.hidden = false;
  chatState.open = true;

  // Hiding it while it IS the page would leave an empty page and no way back.
  $("chatClose").hidden = true;

  sizeChatFull();

  refreshChat().catch(error => notice(String(error.message || error)));
  renderChat();
}

/**
 * Sizes the docked chat to what is actually left of the window.
 *
 * A calc() cannot know how much is above the view - the range controls, the
 * alert strip, the toast area - and on a short window that guess put the
 * message box below the fold. This reads where the panel starts and gives it
 * the rest, minus the room the corner button occupies, so the two never sit on
 * top of each other.
 */
function sizeChatFull() {
  const panel = $("chatPanel");
  if (!panel || !panel.classList.contains("chat-wide")) return;

  // Measured before the height is applied, or it measures its own last answer.
  panel.style.setProperty("--chat-full-height", "auto");
  const top = panel.getBoundingClientRect().top;

  /*
   * The corner button's own footprint.
   *
   * It is fixed to the bottom right and is not going anywhere, so the panel
   * stops short of it rather than being drawn underneath. Read from the button
   * rather than hard-coded, because it has a size the stylesheet decides.
   */
  const corner = $("noteButton")?.getBoundingClientRect();
  const gap = corner ? Math.round(window.innerHeight - corner.top) + 12 : 24;

  const height = Math.max(320, Math.round(window.innerHeight - top - gap));
  panel.style.setProperty("--chat-full-height", `${height}px`);
}

/**
 * Sends it back to the corner when the page is left.
 *
 * Whether it is then shown is whatever it was before: somebody who had the
 * panel open keeps it, somebody who did not is not given one because they
 * looked at a page.
 */
function undockChat(wasOpen) {
  const panel = $("chatPanel");
  const home = $("chatHome");
  if (!panel || !home || panel.parentElement === home) return;

  home.appendChild(panel);
  panel.classList.remove("chat-wide");
  panel.style.removeProperty("--chat-full-height");
  $("chatClose").hidden = false;

  panel.hidden = !wasOpen;
  chatState.open = wasOpen;
  renderChat();
}

/** Hides the panel. The conversation carries on. */
function hideChat() {
  chatState.open = false;
  $("chatPanel").hidden = true;
  /*
   * Polling continues, slowly.
   *
   * A conversation left running while the panel is closed will still finish,
   * and the badge on the button should say so - the alternative is coming back
   * to a session frozen mid-thought because nobody was asking.
   */
}

/*
 * A dock is useful until it covers the thing being discussed. Desktop users
 * can place and resize the same panel without creating a second chat layout;
 * phones retain the safe edge-to-edge layout.
 */
function installChatDrag() {
  const panel = $("chatPanel");
  const handle = $("chatDragHandle");
  if (!panel || !handle) return;

  let moving = null;
  handle.addEventListener("pointerdown", event => {
    if (event.button !== 0 || event.target.closest("button, select, input")) return;
    if (panel.classList.contains("chat-wide") || window.matchMedia("(max-width: 620px)").matches) return;

    const rect = panel.getBoundingClientRect();
    moving = { x: event.clientX - rect.left, y: event.clientY - rect.top };
    panel.style.left = `${Math.round(rect.left)}px`;
    panel.style.top = `${Math.round(rect.top)}px`;
    panel.style.right = "auto";
    panel.style.bottom = "auto";
    handle.setPointerCapture(event.pointerId);
    event.preventDefault();
  });

  handle.addEventListener("pointermove", event => {
    if (!moving) return;
    const left = Math.max(8, Math.min(window.innerWidth - panel.offsetWidth - 8,
      event.clientX - moving.x));
    const top = Math.max(8, Math.min(window.innerHeight - panel.offsetHeight - 8,
      event.clientY - moving.y));
    panel.style.left = `${Math.round(left)}px`;
    panel.style.top = `${Math.round(top)}px`;
  });

  const stop = event => {
    if (!moving) return;
    moving = null;
    if (handle.hasPointerCapture(event.pointerId)) handle.releasePointerCapture(event.pointerId);
  };
  handle.addEventListener("pointerup", stop);
  handle.addEventListener("pointercancel", stop);
}

async function refreshChat() {
  let data;
  try {
    data = await api("ai");
  } catch (error) {
    renderChatUnavailable(String(error.message || error));
    return;
  }

  if (!data.ready) {
    renderChatUnavailable(data.why);
    return;
  }

  chatState.session = data.session;
  if (data.who) chatState.who = data.who;
  renderChatIdentity();
  renderChat();
  scheduleChatPoll();
}

function renderChatUnavailable(why) {
  const log = $("chatLog");
  log.replaceChildren(note(
    why + " " + ZogographI18n.t("ai.unavailable_setup", { assistant: chatState.who.name }, "It is set up under System → {{assistant}}.")
  ));

  const go = document.createElement("button");
  go.className = "link";
  go.textContent = ZogographI18n.t("ai.set_up", {}, "Set it up");
  go.addEventListener("click", () => { location.hash = "#/sys-ai?range=" + state.range; });
  log.appendChild(go);

  $("chatStatus").textContent = "";
  $("chatSend").disabled = true;
  $("chatText").disabled = true;
}

/**
 * Asks the server what is happening, and drives whatever is due.
 *
 * One timer, rescheduled after each poll rather than an interval, so a slow
 * step cannot cause overlapping requests to pile up behind each other.
 */
function scheduleChatPoll() {
  if (chatState.polling) clearTimeout(chatState.polling);

  const session = chatState.session;
  if (!session || !session.exists) return;

  const finished = ["stopped", "ended", "failed"].includes(session.state);
  if (finished) return;

  chatState.polling = setTimeout(
    () => pollChat().catch(() => scheduleChatPoll()),
    chatPollDelay(session.state)
  );
}

async function pollChat() {
  const session = chatState.session;
  if (!session || !session.exists) return;

  if (chatState.busy) {
    scheduleChatPoll();
    return;
  }

  try {
    chatState.session = await api("ai-poll", {
      session: session.id,
      // Kept current as they move, so it knows what "this page" means.
      view: state.view ?? "",
    });
  } catch {
    // A failed poll is not worth a message: the next one usually works, and an
    // error toast every second would be worse than the silence.
    scheduleChatPoll();
    return;
  }

  renderChat();
  await driveChat();
  scheduleChatPoll();
}

/**
 * Does whatever the session is waiting on this browser to do.
 *
 * Stepping, navigating and screenshotting all live here so that there is one
 * place where the conversation moves forward, rather than three that can
 * disagree about whose turn it is.
 */
async function driveChat() {
  const session = chatState.session;
  if (!session?.exists || chatState.busy) return;

  if (session.state === "thinking") {
    chatState.busy = true;
    try {
      chatState.session = (await post("ai-step", { session: session.id })).session;
      renderChat();
    } catch (error) {
      $("chatStatus").textContent = String(error.message || error);
    } finally {
      chatState.busy = false;
    }
    return;
  }

  if (session.state === "waiting_browser" && session.browser_tool) {
    const run = session.browser_tool;
    if (chatState.handled.has(run.id)) return;
    chatState.handled.add(run.id);

    chatState.busy = true;
    try {
      await runBrowserTool(run);
    } finally {
      chatState.busy = false;
    }
  }
}

/**
 * The two things only the page can do.
 *
 * Navigation goes through the router rather than reloading, so the chat panel
 * and everything in it survives - which is the whole reason the assistant can
 * usefully move somebody around.
 */
async function runBrowserTool(run) {
  let result = {};

  try {
    if (run.tool === "set_time_range") {
      /*
       * The dashboard's own range picker, driven from the conversation.
       *
       * Through the same control the operator would use rather than by setting
       * state directly, so the dropdown, the route and the Live button all end
       * up agreeing - three of them have gone out of step in this file before
       * by somebody setting state.range on its own.
       */
      const seconds = { "10m": 600, "1h": 3600, "6h": 21600,
                        "24h": 86400, "7d": 604800, "30d": 2592000 }[run.arguments.range];

      if (!seconds) {
        result = { error: `There is no "${run.arguments.range}" range.` };
      } else {
        const picker = $("range");
        const has = [...picker.options].some(o => Number(o.value) === seconds);

        if (!has) {
          result = {
            error: `This dashboard does not offer a ${run.arguments.range} range. `
              + `It offers: ${[...picker.options].map(o => o.textContent).join(", ")}.`,
          };
        } else {
          picker.value = String(seconds);
          picker.dispatchEvent(new Event("change", { bubbles: true }));

          let live = false;
          if (run.arguments.live && seconds === LIVE_RANGE) {
            if (!state.live) $("live").click();
            live = state.live;
          }

          notice(
            `${chatState.who.name} switched the range to `
            + `${[...picker.options].find(o => Number(o.value) === seconds).textContent}`
            + (live ? ", live" : "")
            + (run.arguments.why ? ` — ${run.arguments.why}` : ""),
            true
          );

          result = {
            range: run.arguments.range,
            live,
            note: live
              ? "The dashboard is now taking a reading every few seconds. Say when they "
                + "can turn it off."
              : "The dashboard is showing that range now. The data tools are unaffected "
                + "by this - they take their own period as a parameter.",
          };
        }
      }
    } else if (run.tool === "show_progress") {
      // Drawn by renderChat from the tool call itself, like the chart cards -
      // so it survives every poll rather than being wiped by the next one.
      result = {};
    } else if (run.tool === "show_reaction") {
      /*
       * Found by the server, because the search needs a key.
       *
       * A failure here is not a failure of the turn: the image was decoration.
       * The tool result says it did not appear and the conversation carries on.
       */
      const found = await post("ai-reaction", {
        mood: run.arguments.mood,
        session: chatState.session?.id ?? 0,
      });
      // Sent on, so the server stores it as a message the chat draws - a map
      // on this side keyed by the tool run could not be found again from a
      // message id, which is how the first version lost every one of them.
      result = found.ok ? { image_url: found.url } : {};
    } else if (run.tool === "show_chart") {
      /*
       * Drawn for the user, and recorded as what they were shown.
       *
       * The model gets no image back - it gets a confirmation. What it showed
       * somebody is worth having in the transcript though, so a picture of the
       * card goes into the database rather than to the provider: months later,
       * "what did it actually show me" is answerable.
       */
      const card = await drawChatChart(run.arguments);
      result = { shown: card.image };
    } else if (run.tool === "present_visual") {
      /* The tool arguments are persisted with the tool call; the card renderer
       * rebuilds the exact visual from them on every transcript view. */
      result = { shown: "presented" };
    } else if (run.tool === "get_chart_image") {
      result = { image: await renderChartImage(run.arguments) };
    } else if (run.tool === "open_page") {
      const page = String(run.arguments.page || "");
      if (!VIEWS[page]) throw new Error(`there is no page called ${page}`);

      const hours = Number(run.arguments.hours);
      const range = Number.isFinite(hours) && hours > 0
        ? Math.min(31536000, Math.round(hours * 3600))
        : state.range;

      /*
       * The hash, not a reload.
       *
       * applyRoute picks this up and swaps the view in place; the chat panel is
       * outside the view container and is not touched. A location.assign here
       * would throw away the conversation to show somebody a page about it.
       */
      location.hash = `#/${page}?range=${range}`;
      result = {};
    } else if (run.tool === "request_tool_group") {
      const subject = String(run.arguments.subject || "");
      const label = TOOL_GROUP_NAMES[subject] ?? subject;
      notice(
        `${chatState.who.name} requested ${label} tools — review and save the choice.`,
        true
      );
      location.hash = "#/sys-ai-tools";
      result = { subject };
    } else if (run.tool === "offer_choices") {
      result = await runOfferChoices(run.arguments);
    } else if (run.tool === "ask_the_user") {
      result = await runAskTheUser(run.arguments);
    } else if (run.tool === "highlight_on_page") {
      result = highlightOnPage(run.arguments);
    } else if (run.tool === "request_from_host") {
      result = await runRequestFromHost(run.arguments);
    } else if (run.tool === "wait_for_new_readings") {
      result = await runWaitForReadings(run.arguments);
    } else if (run.tool === "take_screenshot") {
      /*
       * Through an editor, never straight out.
       *
       * A screenshot of this dashboard can contain paths, addresses, domain
       * names and whatever happens to be in a log line - and it is about to be
       * sent to somebody else's service. The user picks the part that matters
       * and blacks out anything that does not, and nothing leaves until they
       * press send.
       */
      const edited = await editScreenshot(await captureScreen(), run.why);
      if (edited === null) throw new Error("the user decided not to send a screenshot");
      result = { image: edited };
    } else if (run.tool === "inspect_current_page_html") {
      result = { html: await reviewCurrentPageHtml(run.why) };
    } else {
      throw new Error(`this browser does not know how to ${run.tool}`);
    }

    chatState.session = (await post("ai-tool-result", {
      run: run.id,
      ...result,
    })).session;
  } catch (error) {
    chatState.session = (await post("ai-tool-result", {
      run: run.id,
      error: String(error.message || error),
    })).session;
  }

  renderChat();
}

/** Lets the user inspect and redact page structure before it reaches a model. */
function reviewCurrentPageHtml(why) {
  return new Promise(resolve => {
    const clone = $("main").cloneNode(true);
    // The conversation and transient controls are not part of the page being diagnosed.
    clone.querySelectorAll("#toasts, #chatPanel, dialog, script, style").forEach(node => node.remove());
    redactReviewedPageHtml(clone);
    const said = document.createElement("p");
    said.className = "muted small";
    said.textContent = why
      ? `${chatState.who.name} asked for the page structure: ${why}`
      : `${chatState.who.name} asked for the current page structure.`;
    const help = document.createElement("p");
    help.className = "muted small";
    help.textContent = "Review this before sending it. Delete or replace any element or text you do not want shared.";
    const text = document.createElement("textarea");
    text.className = "wide terminal-editor";
    text.rows = 24;
    text.spellcheck = false;
    text.value = clone.outerHTML.slice(0, 300 * 1024);
    showFormDialog("Review page HTML", [said, help, text], async () => resolve(text.value));
  });
}

/*
 * A reviewed page is still a disclosure to the configured AI provider. Keep
 * the useful shape, labels, and accessible relationships, but never prefill
 * the review editor with form state. CSS/data hooks give feature authors a
 * simple escape hatch for values that are rendered as ordinary text instead.
 */
function redactReviewedPageHtml(root) {
  root.querySelectorAll("input, textarea, select, [contenteditable]").forEach(field => {
    field.removeAttribute("value");
    field.removeAttribute("checked");
    field.removeAttribute("selected");
    field.removeAttribute("aria-checked");
    if (field instanceof HTMLTextAreaElement || field.hasAttribute("contenteditable")) {
      field.replaceChildren();
    }
    field.setAttribute("data-review-redacted", "form-state");
  });
  root.querySelectorAll("[data-sensitive], [data-secret], [data-private]").forEach(node => {
    Array.from(node.attributes).forEach(attribute => node.removeAttribute(attribute.name));
    node.replaceChildren("[redacted]");
    node.setAttribute("data-review-redacted", "sensitive-content");
  });
}

/**
 * The name, the emoji and the portrait, wherever they appear.
 *
 * All three are the operator's to change, so nothing anywhere hard-codes them -
 * including the navigation entry, which is the one people forget and then have
 * a settings page that renames everything except the menu.
 */
function renderChatIdentity() {
  const who = chatState.who;

  const title = $("chatTitle");
  if (title) {
    title.replaceChildren();

    if (who.portrait) {
      const face = document.createElement("img");
      face.className = "chat-face";
      face.src = who.portrait.url;
      face.alt = "";
      face.title = `${who.name}, as it describes itself: "${who.portrait.as}"`;
      title.appendChild(face);
    } else {
      const mark = document.createElement("span");
      mark.className = "chat-emoji";
      mark.textContent = who.emoji;
      title.appendChild(mark);
    }

    const name = document.createElement("span");
    name.textContent = ` ${who.name}`;
    title.appendChild(name);
  }

  /*
   * The icon carries the mark, the label carries the name.
   *
   * Both were carrying the emoji, so the menu read the mark twice - and once
   * it had drawn itself a portrait, a thumbnail and an emoji as well.
   */
  const navIcon = document.querySelector('[data-nav="sys-ai"] .nav-icon');
  if (navIcon) navIcon.textContent = who.emoji;

  const nav = document.querySelector('[data-nav="sys-ai"] .nav-label');
  if (nav) nav.textContent = who.name;

  const ask = $("cornerChat");
  if (ask) ask.textContent = `${who.emoji} Ask ${who.name}`;

  /*
   * The name written into the page's own prose.
   *
   * Every heading and sentence that says it out loud carries this class, so a
   * rename reaches all of them. The alternative - and what was there - is a
   * settings page that renames the assistant everywhere except the four
   * places somebody actually reads.
   */
  for (const spot of document.querySelectorAll(".ai-name")) {
    spot.textContent = who.name;
  }

  /*
   * And the view registry, which is where the note dialog and the breadcrumbs
   * get their page names from. Somebody writing a note on this page was being
   * told "This page is Lookout" long after it had been renamed.
   */
  if (VIEWS["sys-ai"]) VIEWS["sys-ai"].label = who.name;
  if (VIEWS["sys-ai-data"]) VIEWS["sys-ai-data"].label = "Assistant data";

  const box = $("chatText");
  if (box && box.value === "") {
    box.placeholder = `What is going wrong?`;
  }
}

function renderChat() {
  const session = chatState.session;
  const log = $("chatLog");

  /*
   * Scrolling back to the bottom releases the hold, once.
   *
   * Bound here rather than at startup because the log element exists from the
   * beginning but this is the only code that cares.
   */
  if (!log.dataset.watching) {
    log.dataset.watching = "1";
    log.addEventListener("scroll", () => {
      if (log.scrollHeight - log.scrollTop - log.clientHeight < 60) {
        chatState.pinnedUp = false;
        const button = $("chatCatchUp");
        if (button) button.hidden = true;
      }
    });
  }

  if (!session?.exists) {
    log.replaceChildren(note(
      `Describe what is going wrong and ${chatState.who.name} will look into it. `
      + "It can read "
      + "this machine's measurements and logs, and can take you to the page that shows "
      + "what it found."
    ));
    $("chatStatus").textContent = "";
    $("chatCost").textContent = "";
    $("chatSend").disabled = false;
    $("chatText").disabled = false;
    return;
  }

  const parts = [];

  for (const message of session.messages) {
    const node = chatMessageNode(message, session);
    if (node) parts.push(node);
  }

  /*
   * Only follow the conversation if the reader is already at the end of it.
   *
   * renderChat runs on every poll - several times a second while a turn is in
   * flight - and scrolling to the bottom unconditionally meant scrolling up to
   * read something was impossible: the next poll dragged you straight back
   * down, every time, within about a second.
   *
   * Measured before the redraw, because replaceChildren resets scrollTop to
   * zero and the answer afterwards is always "no".
   */
  /*
   * An empty log is not somebody sitting at the top of the conversation.
   *
   * Coming back to this page rebuilds it, and a rebuilt log starts empty with
   * scrollTop at zero - which looked like "they were at the top, leave them
   * there", so returning to a conversation showed its opening message rather
   * than the last thing that was said.
   */
  const wasEmpty = log.childElementCount === 0;
  const wasAtEnd = wasEmpty || log.scrollHeight - log.scrollTop - log.clientHeight < 60;
  const wasAt = log.scrollTop;

  const newest = parts.length ? parts[parts.length - 1] : null;

  log.replaceChildren(...parts);

  if (wasAtEnd) {
    /*
     * A long answer is put at the TOP of the view, not the bottom.
     *
     * Scrolling to the end of a reply that is taller than the window lands you
     * on its last paragraph, and reading it means scrolling back up to find
     * where it started - every single time. Putting its first line just below
     * the top means the answer begins where the eye already is, and reading is
     * scrolling down, which is the direction reading goes.
     *
     * Only when it does not fit. A short answer read from the bottom is fine,
     * and moving it would leave a gap under it for no reason.
     */
    const tall = newest && newest.offsetHeight > log.clientHeight - 80;

    log.scrollTop = tall
      ? Math.max(0, newest.offsetTop - 24)
      : log.scrollHeight;

    chatState.pinnedUp = false;
  } else {
    /*
     * Put back where they were, not where the content now is.
     *
     * Close enough: the content above them has not changed, so the same offset
     * shows the same words. New content is appended below, which is exactly
     * what should not move them.
     */
    log.scrollTop = wasAt;
    chatState.pinnedUp = true;
  }

  renderChatCatchUp(log, session);

  renderChatStatus(session);
  speakAssistantReply(session);

  $("chatCost").textContent = session.spent.known
    ? `${session.spent.said} · ${humanCount(session.tokens.in + session.tokens.out)} tokens`
    : `${humanCount(session.tokens.in + session.tokens.out)} tokens`;
  $("chatCost").title = `In ${humanCount(session.tokens.in)}, out `
    + `${humanCount(session.tokens.out)}, of which ${humanCount(session.tokens.cached)} `
    + "was cached input."
    + (session.spent.known ? "" : " No prices are set, so the cost is not known.");

  renderChatRoom(session);
  renderChatEffort(session);

  const finished = ["stopped", "ended", "failed"].includes(session.state);
  const busy = ["thinking", "waiting_permission", "waiting_browser"].includes(session.state);

  /*
   * You can type while it is working.
   *
   * Watching a model spend four turns confidently investigating the wrong
   * subsystem, with the box greyed out, is the worst version of this. What is
   * typed goes into the transcript and the model reads it on its next turn -
   * an interruption, which is what it is.
   */
  $("chatSend").disabled = finished;
  $("chatText").disabled = finished;
  $("chatSend").textContent = busy ? "Add" : "Ask";
  $("chatSend").title = busy
    ? "It is working. This goes in now and it reads it on its next turn."
    : "";
  // Stop is meaningful only while PHP/the model is actually working. Leaving
  // it visible on an idle conversation made it look like a broken emergency
  // button rather than the way to halt an in-flight exchange.
  $("chatStop").hidden = !busy;
  $("chatInterrupt").hidden = finished || !busy;
}

/**
 * How full the model's context is, as a ring.
 *
 * An estimate, and it says so: the exact number is known only to the provider
 * and arrives after the request, which is too late to act on. Being right to
 * within ten per cent and available now beats exact and useless.
 *
 * The ring turns amber at the point where compaction will fire, not when the
 * window is actually full - that gap is deliberate, because summarising means
 * sending the part being summarised, and a limit that triggers with no room
 * left is a limit that cannot act.
 */
function renderChatRoom(session) {
  const spot = $("chatRoom");
  const room = session.context;

  if (!spot || !room) {
    if (spot) spot.hidden = true;
    return;
  }

  spot.hidden = false;
  spot.replaceChildren();

  const size = 18;
  const radius = 7;
  const circumference = 2 * Math.PI * radius;
  const share = Math.min(1, room.share);

  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", `0 0 ${size} ${size}`);
  svg.setAttribute("width", String(size));
  svg.setAttribute("height", String(size));
  svg.setAttribute("aria-hidden", "true");

  for (const [cls, dash, offset] of [
    ["dial-track", null, null],
    [room.full ? "dial-value dial-due" : "dial-value", circumference,
      circumference * (1 - share)],
  ]) {
    const ring = document.createElementNS("http://www.w3.org/2000/svg", "circle");
    ring.setAttribute("cx", String(size / 2));
    ring.setAttribute("cy", String(size / 2));
    ring.setAttribute("r", String(radius));
    ring.setAttribute("fill", "none");
    ring.setAttribute("stroke-width", "3");
    ring.setAttribute("class", cls);
    if (dash !== null) {
      ring.setAttribute("stroke-dasharray", String(dash));
      ring.setAttribute("stroke-dashoffset", String(offset));
      ring.setAttribute("transform", `rotate(-90 ${size / 2} ${size / 2})`);
    }
    svg.appendChild(ring);
  }
  spot.appendChild(svg);

  /*
   * What it means, on contact rather than after a second of nothing.
   *
   * A small ring with no label is a control nobody can guess at, and a native
   * `title` arrives about a second late - long enough for somebody to click it
   * to find out what it does, which on this particular control is the one thing
   * they should not do by accident.
   */
  const left = Math.max(0, room.soft - room.tokens);
  const towards = room.soft > 0
    ? Math.round((room.tokens / room.soft) * 100)
    : 0;

  const explains = room.full
    ? (room.automatic
      ? `Full. The older half gets summarised on the next turn, automatically.\n\n`
        + `Click to do it now instead.`
      : `Full, and automatic summarising is switched off — so this conversation will `
        + `eventually be refused by the provider.\n\nClick to summarise it now.`)
    : `About ${towards}% of the way to the point where the older half is summarised — `
      + `roughly ${humanCount(left)} more tokens.\n\nClick to summarise it now instead `
      + `of waiting.`;

  const full = `${explains}\n\nNothing is deleted: the messages stay in the panel and in `
    + `the record, and a marker shows where the model's view begins. `
    + `About ${humanCount(room.tokens)} of ${humanCount(room.window)} tokens are in use, `
    + `estimated from the length of the conversation rather than reported by the provider.`;

  spot.setAttribute("aria-label", full);
  spot.tabIndex = 0;
  spot.onpointerenter = () => showHelp(spot, full, false);
  spot.onpointerleave = () => { if (helpBubble?.dataset.pinned !== "yes") hideHelp(); };
  spot.onfocus = () => showHelp(spot, full, false);
  spot.onblur = () => { if (helpBubble?.dataset.pinned !== "yes") hideHelp(); };

  spot.onclick = async () => {
    if (!chatState.session?.exists) return;
    try {
      hideHelp();
      const result = await post("ai-compact-chat", { session: chatState.session.id });
      chatState.session = result.session;

      /*
       * Say what happened, in terms of what is still there.
       *
       * "28 messages replaced" reads as a loss. They are all still on screen -
       * what changed is what gets sent - and the marker in the log is the thing
       * to look at, so the message points at it.
       */
      notice(
        `${count(result.compacted, "message")} summarised. They are still in the `
        + "conversation — the dashed line shows where the model's view now begins, and "
        + "opens onto the summary.",
        true
      );
      renderChat();
    } catch (error) {
      notice(String(error.message || error));
    }
  };
}

/**
 * How hard it should think, for this conversation only.
 *
 * Down from the configured setting, never up. Most questions do not need the
 * expensive tier and the person asking usually knows which theirs is - but the
 * ceiling is a decision made once, in settings, by whoever pays the bill.
 */
function renderChatEffort(session) {
  const picker = $("chatEffort");
  if (!picker) return;

  const ceiling = session.effort_ceiling ?? "";
  const levels = session.effort_levels ?? [];

  if (ceiling === "" || !levels.length) {
    // Nothing configured means the provider's own default and no choice worth
    // offering; a control that changes nothing is worse than no control.
    picker.hidden = true;
    return;
  }

  picker.hidden = false;
  const upTo = levels.slice(0, levels.indexOf(ceiling) + 1);

  if (picker.dataset.built !== upTo.join(",")) {
    picker.replaceChildren();
    for (const level of upTo) {
      const option = document.createElement("option");
      option.value = level;
      option.textContent = level;
      picker.appendChild(option);
    }
    picker.dataset.built = upTo.join(",");
  }

  picker.value = session.effort || ceiling;
  picker.title = `Thinking: ${picker.value}. The setting allows up to ${ceiling}; `
    + "this turns it down for this conversation only.";
}


/**
 * A way back down, when somebody has scrolled up during a live turn.
 *
 * The panel stops following the conversation the moment they scroll away from
 * the bottom, which is right - but then new messages arrive out of sight and
 * nothing says so. A button that appears only while they are held back, and
 * says how much they have missed.
 */
function renderChatCatchUp(log, session) {
  let button = $("chatCatchUp");

  if (!button) {
    button = document.createElement("button");
    button.id = "chatCatchUp";
    button.className = "chat-catchup";
    button.type = "button";
    button.addEventListener("click", () => {
      log.scrollTop = log.scrollHeight;
      chatState.pinnedUp = false;
      button.hidden = true;
    });
    log.parentElement.insertBefore(button, log.nextSibling);
  }

  const behind = chatState.pinnedUp
    && log.scrollHeight - log.scrollTop - log.clientHeight > 60;

  button.hidden = !behind;
  if (behind) {
    const busy = ["thinking", "waiting_permission", "waiting_browser"]
      .includes(session.state);
    button.textContent = busy
      ? `${chatState.who.name} is still going — jump to the end ↓`
      : "Jump to the end ↓";
  }
}


/** What the model is doing, in words, plus anything it is waiting on. */
function renderChatStatus(session) {
  const status = $("chatStatus");
  status.replaceChildren();

  /*
   * The permission question is drawn in its own strip above the log.
   *
   * It stays there until it is answered - it is the one thing in this panel
   * that blocks everything else, and it used to scroll away under the message
   * box where it could not be clicked at all.
   */
  const ask = $("chatAsk");
  if (session.permission) {
    ask.replaceChildren(chatPermissionPrompt(session.permission));
    ask.hidden = false;
  } else if (chatState.prompt) {
    /*
     * A question the page is asking on a tool's behalf.
     *
     * Put back rather than rebuilt, because it owns a running countdown and a
     * half-filled answer box - rebuilding it every poll would reset both, which
     * is to say it would be unanswerable on any question that took longer than
     * a second to answer.
     */
    if (ask.firstElementChild !== chatState.prompt) ask.replaceChildren(chatState.prompt);
    ask.hidden = false;
  } else {
    ask.replaceChildren();
    ask.hidden = true;
  }

  if (session.permission || chatState.prompt) return;

  const said = {
    idle: "",
    thinking: "Thinking…",
    waiting_browser: "Doing something in this window…",
    stopped: `Stopped — ${session.stop_reason || "by you"}.`,
    ended: `Finished — ${session.stop_reason || "a limit was reached"}.`,
    failed: `Gave up — ${session.stop_reason || "the model could not be reached"}.`,
  }[session.state] ?? "";

  if (said) {
    const line = document.createElement("span");
    line.className = ["stopped", "ended", "failed"].includes(session.state)
      ? "muted"
      : "chat-thinking";
    line.textContent = said;
    status.appendChild(line);
  }

  /*
   * The way out that keeps the conversation.
   *
   * A session that hit a limit offered exactly one button: start a new one,
   * which throws away everything said so far. Somebody in the middle of a
   * diagnosis is answering "let this one finish", and making them choose
   * between that and losing the thread is not a choice anybody should be given.
   *
   * Only the limit that was actually hit. Offering all three would be asking
   * somebody to work out which one stopped it, which the page already knows.
   */
  if (session.limit_hit) {
    const more = document.createElement("button");
    more.className = "link";
    more.textContent = {
      time: "Give it longer",
      spend: "Let it spend more",
      turns: "Give it more turns",
    }[session.limit_hit] ?? "Raise the limit";

    more.title = "Doubles that one limit for THIS conversation only. The settings for "
      + "every future conversation are not touched.";

    more.addEventListener("click", async () => {
      try {
        const fresh = await post("ai-extend", {
          session: session.id,
          which: session.limit_hit,
        });
        chatState.session = fresh.session;
        notice("Raised, for this conversation. Carry on.", true);
        renderChat();
      } catch (error) {
        notice(String(error.message || error));
      }
    });

    status.appendChild(more);
  }

  if (["stopped", "ended", "failed"].includes(session.state)) {
    const again = document.createElement("button");
    again.className = "link";
    again.textContent = ZogographI18n.t("ai.start_new", {}, "Start a new one");
    again.addEventListener("click", () => startChat());
    status.appendChild(again);
  }
}

/* ------------------------------------------- what the new tools actually do -- */

/**
 * A fork in the conversation, put to the user.
 *
 * The default is named on the button strip before it is taken, not announced
 * afterwards. Somebody who sees "leaving it alone in 40s" and disagrees has
 * forty seconds to say so; somebody who is told afterwards has a decision they
 * did not make.
 */
async function runOfferChoices(args) {
  const choices = (args.choices || []).filter(c => c && c.key && c.label);

  if (!choices.length) {
    return { error: "no choices were given, so there was nothing to ask" };
  }

  const fallback = choices.find(c => c.key === args.default_key) ?? choices[0];

  const answer = await chatAsk({
    title: String(args.question || "Which way?"),
    seconds: args.seconds ?? 120,
    defaultLabel: `“${fallback.label}”`,
    confirmLabel: "Go with this",
    build: holder => chatChoiceForm(choices, holder),
  });

  if (!answer.answered) {
    return {
      chose: fallback.key,
      answered: false,
      note: "Nobody answered, so the default was taken. Say which way you are going and "
        + "why, so they can redirect you if they come back and disagree.",
    };
  }

  return { chose: answer.value, answered: true };
}

/** One typed question, and what came back. */
async function runAskTheUser(args) {
  const shape = ["choice", "checklist", "number", "text"].includes(args.answer)
    ? args.answer
    : "text";
  const options = (args.options || []).filter(o => o && o.key && o.label);

  if ((shape === "choice" || shape === "checklist") && !options.length) {
    return { error: `answer="${shape}" needs options, and none were given` };
  }

  const answer = await chatAsk({
    title: String(args.question || "A question"),
    seconds: args.seconds ?? 180,
    defaultLabel: "Carrying on without an answer",
    build: holder => buildAnswerField(shape, options, args, holder),
  });

  if (!answer.answered) {
    return {
      answered: false,
      note: "No answer. Carry on with what you can work out, say what you assumed, and "
        + "do not ask again.",
    };
  }

  return { answered: true, answer: answer.value };
}

/** The four shapes of answer, as form controls. */
function buildAnswerField(shape, options, args, holder) {
  if (shape === "choice") {
    return chatChoiceForm(
      options.map(o => ({ key: o.key, label: o.label, what_happens: "" })),
      holder
    );
  }

  if (shape === "checklist") {
    for (const option of options) {
      const line = document.createElement("label");
      line.className = "scan-toggle";

      const box = document.createElement("input");
      box.type = "checkbox";
      box.value = option.key;
      line.appendChild(box);

      const text = document.createElement("span");
      text.textContent = ` ${option.label}`;
      line.appendChild(text);

      holder.appendChild(line);
    }

    /*
     * An empty checklist is a real answer.
     *
     * "None of these" is exactly what a checklist is for, and treating it as
     * "you have not answered yet" would make it impossible to say. So it
     * returns a list, and an empty list is a list.
     */
    return () => [...holder.querySelectorAll("input:checked")].map(box => box.value);
  }

  if (shape === "number") {
    const row = document.createElement("div");
    row.className = "pattern-row";

    const box = document.createElement("input");
    box.type = "number";
    box.className = "days";
    if (args.minimum !== null && args.minimum !== undefined) box.min = String(args.minimum);
    if (args.maximum !== null && args.maximum !== undefined) box.max = String(args.maximum);
    row.appendChild(box);

    if (args.unit) {
      const unit = document.createElement("span");
      unit.className = "muted small";
      unit.textContent = String(args.unit);
      row.appendChild(unit);
    }

    holder.appendChild(row);
    box.focus();

    return () => (box.value.trim() === "" ? null : Number(box.value));
  }

  const box = document.createElement("textarea");
  box.rows = 3;
  box.className = "wide-field";
  box.spellcheck = true;
  holder.appendChild(box);
  box.focus();

  return () => box.value.trim() || null;
}

/**
 * Puts the user's eye on one thing.
 *
 * Searches the visible page only. Searching hidden views would find a match on
 * a page nobody is looking at and report success for a highlight that appeared
 * nowhere, which is worse than saying it was not found.
 *
 * Text nodes rather than elements, so that the smallest thing containing the
 * text is what gets outlined - matching on elements finds the whole table
 * first, and outlining a table to point at one row points at nothing.
 */
function highlightOnPage(args) {
  const find = String(args.find || "").trim().toLowerCase();
  if (!find) return { found: false, note: "nothing to look for" };

  const view = document.querySelector(".view:not([hidden])");
  if (!view) return { found: false, note: "no page is open" };

  const walker = document.createTreeWalker(view, NodeFilter.SHOW_TEXT, {
    acceptNode: node => (node.textContent || "").toLowerCase().includes(find)
      && node.parentElement
      && !node.parentElement.closest("[hidden]")
      ? NodeFilter.FILTER_ACCEPT
      : NodeFilter.FILTER_REJECT,
  });

  const node = walker.nextNode();
  if (!node) {
    return {
      found: false,
      page: state.view,
      note: `Nothing on the ${VIEWS[state.view]?.label ?? state.view} page contains that `
        + "text, so nothing was highlighted. The user may be on a different page — "
        + "open_page first — or it may not be shown there at all. Do not describe a "
        + "highlight that did not happen.",
    };
  }

  /*
   * The row, where there is one.
   *
   * A process name lives in a cell, and pointing at the cell leaves the figure
   * that makes it interesting outside the outline. The row is the unit somebody
   * reads.
   */
  const target = node.parentElement.closest("tr, li, .cap-list > div, .settings > div")
    ?? node.parentElement;

  target.classList.remove("pointed-at");
  // Reading offsetWidth restarts the animation; without it a second highlight
  // on the same element does nothing at all.
  void target.offsetWidth;
  target.classList.add("pointed-at");

  target.scrollIntoView({ block: "center", behavior: "smooth" });

  if (args.why) {
    notice(`${chatState.who.name}: ${args.why}`, true);
  }

  setTimeout(() => target.classList.remove("pointed-at"), 6000);

  return {
    found: true,
    page: state.view,
    showed: (target.textContent || "").replace(/\s+/g, " ").trim().slice(0, 160),
    note: "It is outlined and pulsing for a few seconds. Say what you are pointing at in "
      + "the same message; a highlight with no sentence is a poke.",
  };
}

/**
 * Asks the user to approve a job for root's collector, then queues it.
 *
 * Approval is per request, every time. These run as root on a machine that may
 * be shared and some of them cost minutes of I/O, so it is not the kind of
 * permission worth remembering - the right answer today is not the right answer
 * during a busy hour.
 */
async function runRequestFromHost(args) {
  const jobs = {
    "capabilities": {
      label: "Re-check what is installed on the host",
      cost: "Quick. Runs a handful of version checks.",
      task: "capabilities",
    },
    "disk-walk": {
      label: "Walk the whole filesystem as root",
      cost: "Expensive — minutes on a large disk, and it reads the whole time.",
      task: "disk-walk",
    },
  };

  const job = jobs[String(args.job || "")];
  if (!job) return { queued: false, error: `there is no host job called "${args.job}"` };

  const answer = await chatAsk({
    title: `${chatState.who.name} wants to ask root's collector: ${job.label}`,
    why: `${args.why ? `“${args.why}” — ` : ""}${job.cost} It runs on the collector's next `
      + "pass, not now.",
    seconds: args.seconds ?? 120,
    defaultLabel: "Treated as no",
    confirmLabel: "Ask the host",
    build: holder => {
      const said = document.createElement("div");
      said.className = "muted small";
      said.textContent = "This queues a job for the process running as root. Nothing runs "
        + "in this window and nothing runs now.";
      holder.appendChild(said);
      // Nothing to fill in: pressing the button is the answer.
      return () => "yes";
    },
  });

  if (!answer.answered) {
    return {
      queued: false,
      note: "Not approved — either declined or nobody answered. Treat it as a no, carry "
        + "on with what you can see from this account, and say what you cannot answer "
        + "because of it.",
    };
  }

  try {
    const queued = await post("host-request", { job: job.task, why: String(args.why || "") });
    return {
      queued: true,
      job: job.task,
      note: queued.note
        || "Queued. It runs on the collector's next pass — use get_pending_host_requests "
           + "to see whether it has landed, or wait_for_new_readings to wait for it. Do "
           + "not assume the answer is available yet.",
    };
  } catch (error) {
    return { queued: false, error: String(error.message || error) };
  }
}

/**
 * Waits for a collector to bring something new in.
 *
 * Polled from here rather than held open on the server: a request left hanging
 * for five minutes ties up a PHP worker, and on shared hosting there are not
 * many of those. The page already knows when readings land.
 */
async function runWaitForReadings(args) {
  const which = args.which === "host" ? "host" : "account";
  const seconds = Math.max(30, Math.min(1800, Number(args.seconds) || 300));
  if (disabledCoreRoutes.has("system")) {
    return {
      arrived: false,
      which,
      note: "Collector waiting is unavailable while the System health feature is disabled.",
    };
  }

  /*
   * The collectors' own last-run times, from the page that already reports them.
   *
   * Not `health`, which is the install's own self-check and carries no
   * timestamps at all - reading a field that is never there would have made
   * this wait out its full timeout every time and then report the collector as
   * stopped, which is a confident wrong answer rather than a missing one.
   */
  const wanted = which === "host" ? "Host collection" : "Readings";

  const at = async () => {
    try {
      const self = await api("self");
      const row = (self.collectors || []).find(c => c.name === wanted);
      return Number(row?.last_at) || 0;
    } catch {
      return 0;
    }
  };

  const before = await at();
  const until = Date.now() + seconds * 1000;

  const waiting = document.createElement("div");
  waiting.className = "chat-question";
  waiting.textContent = `Waiting for the ${which} collector…`;
  chatState.prompt = waiting;
  $("chatAsk").replaceChildren(waiting);
  $("chatAsk").hidden = false;

  try {
    while (Date.now() < until) {
      const left = Math.round((until - Date.now()) / 1000);
      waiting.textContent = `${chatState.who.name} is waiting for the ${which} collector `
        + `— up to ${humanSpan(left)} more.`;

      await new Promise(resolve => setTimeout(resolve, 5000));

      const now = await at();
      if (now > before) {
        return {
          arrived: true,
          which,
          waited: humanSpan(Math.round(seconds - (until - Date.now()) / 1000)),
          note: "New readings have landed. Anything you read before this is from before "
            + "them — call the tools again rather than reasoning from the old answers.",
        };
      }
    }

    return {
      arrived: false,
      which,
      waited: humanSpan(seconds),
      note: `Nothing new arrived from the ${which} collector in that time. That is a `
        + "finding: it is not running as often as it should, or at all. Say so rather "
        + "than waiting again.",
    };
  } finally {
    chatState.prompt = null;
    $("chatAsk").replaceChildren();
    $("chatAsk").hidden = true;
  }
}

/* ------------------------------------------------- past conversations -- */

const pastChats = { list: [], open: null, session: null };

async function refreshPastChats() {
  const body = $("pastChatsBody");
  if (!state.signedIn) {
    body.replaceChildren(note(aiSettingsText("past_conversations_sign_in", "Sign in to see past conversations.")));
    return;
  }

  try {
    const data = await api("ai-sessions");
    pastChats.list = data.sessions || [];
    renderPastChats();
  } catch (error) {
    body.replaceChildren(note(String(error.message || error)));
  }
}

function renderPastChats() {
  const body = $("pastChatsBody");

  if (!pastChats.list.length) {
    body.replaceChildren(note(ZogographI18n.t("ai.past_empty")));
    return;
  }

  const holder = document.createElement("div");
  holder.id = "pastChatsTable";
  body.replaceChildren(holder);

  renderTable("pastChatsTable", pastChats.list, [
    {
      label: ZogographI18n.t("ai.past_topic"),
      className: "name",
      render: row => {
        if (row.title) {
          const said = document.createElement("span");
          said.textContent = row.title;
          if (row.title_by === "assistant") {
            said.title = ZogographI18n.t("ai.past_named_by", { assistant: chatState.who.name });
          }
          return said;
        }
        const said = document.createElement("span");
        said.className = "muted";
        said.textContent = ZogographI18n.t("ai.past_no_topic");
        return said;
      },
    },
    { label: ZogographI18n.t("ai.past_started"), render: row => whenSpan(row.started_at) },
    { label: ZogographI18n.t("ai.past_turns"), className: "size", render: row => row.turns },
    { label: ZogographI18n.t("ai.past_cost"), className: "size", render: row => row.spent?.said ?? "" },
    {
      label: ZogographI18n.t("ai.past_ended"),
      render: row => row.state === "ended" || row.state === "stopped"
        ? (row.why_stopped || row.state)
        : row.state,
    },
    {
      label: ZogographI18n.t("ai.past_kept"),
      render: row => {
        if (!row.pinned) return "";
        const said = document.createElement("span");
        said.textContent = ZogographI18n.t("ai.past_pinned");
        said.className = "own-label";
        said.title = ZogographI18n.t("ai.past_pinned_tip");
        return said;
      },
    },
  ], row => openPastChat(row.id), null, row => String(row.id));
}

/** Opens one to read. */
async function openPastChat(id) {
  pastChats.open = id;

  try {
    const data = await api("ai-transcript", { session: id });
    pastChats.session = data.session;
    renderPastChat();
  } catch (error) {
    notice(String(error.message || error));
  }
}

function renderPastChat() {
  const panel = $("pastChatPanel");
  const session = pastChats.session;
  if (!session) { panel.hidden = true; return; }

  panel.hidden = false;

  const row = pastChats.list.find(one => one.id === pastChats.open);

  $("pastChatTitle").textContent = row?.title
    || `Conversation of ${whenLabel(session.started_at ?? row?.started_at ?? 0)}`;

  $("pastChatPin").textContent = row?.pinned ? "Unpin it" : "Pin it";
  $("pastChatResume").hidden = row ? !row.can_continue : false;

  /*
   * Read with the same code the live panel uses.
   *
   * A conversation that looks different when it is finished is a second
   * renderer to keep in step with the first, and the differences would be
   * exactly the details - a tool call, a chart card - that make it worth
   * reading at all.
   */
  const body = $("pastChatBody");
  const parts = [];

  for (const message of session.messages || []) {
    const node = chatMessageNode(message);
    if (node) parts.push(node);
  }

  const wrap = document.createElement("div");
  wrap.className = "chat-log past-chat";
  wrap.replaceChildren(...parts);
  body.replaceChildren(wrap);
}

/* ------------------------------------------------- questions with a clock -- */

/**
 * Puts a question to the user, with a countdown and a default.
 *
 * Every question a tool asks has to be answerable and has to be survivable.
 * Answerable means it sits above the log where it cannot scroll away.
 * Survivable means that if nobody answers - because they walked off, or the
 * page is on a second monitor nobody is looking at - the conversation carries
 * on rather than stopping dead in the middle of a diagnosis.
 *
 * So there is always a timeout and always a stated default, and the countdown
 * is visible from the first second: a question that silently expires is worse
 * than one that never got asked, because the user finds out afterwards that
 * something was decided without them.
 *
 * `build` gets a container to fill and returns a function that reads the answer
 * out of it. Resolves {answered, value} - answered false meaning nobody did.
 */
function chatAsk({ title, why, seconds, defaultLabel, build, confirmLabel = "Send" }) {
  const wrap = document.createElement("div");
  wrap.className = "chat-question";

  const head = document.createElement("div");
  head.className = "chat-question-head";
  head.textContent = title;
  wrap.appendChild(head);

  if (why) {
    const said = document.createElement("div");
    said.className = "muted small";
    said.textContent = why;
    wrap.appendChild(said);
  }

  const holder = document.createElement("div");
  holder.className = "chat-question-body";
  wrap.appendChild(holder);

  const read = build(holder);

  const actions = document.createElement("div");
  actions.className = "inspect-actions";

  const clock = document.createElement("span");
  clock.className = "muted small chat-countdown";
  actions.appendChild(clock);

  wrap.appendChild(actions);

  return new Promise(resolve => {
    let done = false;
    let left = Math.max(5, Number(seconds) || 120);

    const finish = answer => {
      if (done) return;
      done = true;
      clearInterval(timer);
      chatState.prompt = null;
      $("chatAsk").replaceChildren();
      $("chatAsk").hidden = true;
      resolve(answer);
    };

    const send = document.createElement("button");
    send.type = "button";
    send.textContent = confirmLabel;
    send.addEventListener("click", () => {
      const value = read();
      // A question with nothing filled in is not an answer; the countdown
      // carries on rather than sending an empty one as if it were.
      if (value === null || value === undefined || value === "") {
        notice("Nothing chosen yet.");
        return;
      }
      finish({ answered: true, value });
    });
    actions.insertBefore(send, clock);

    const skip = document.createElement("button");
    skip.type = "button";
    skip.className = "link";
    skip.textContent = ZogographI18n.t("action.skip", {}, "Skip");
    skip.title = "Carry on without answering — the same as letting the clock run out";
    skip.addEventListener("click", () => finish({ answered: false, value: null }));
    actions.insertBefore(skip, clock);

    const tick = () => {
      // The label names the default; this adds the clock. Keeping the two
      // apart is what stops "… in in 25s", which is what happened when the
      // caller supplied its own preposition.
      clock.textContent = left > 0
        ? `${defaultLabel} in ${humanSpan(left)}`
        : `${defaultLabel} — no answer`;
      // Under fifteen seconds it stops being background information.
      clock.classList.toggle("soon", left <= 15);
      if (left <= 0) finish({ answered: false, value: null });
      left -= 1;
    };

    const timer = setInterval(tick, 1000);
    tick();

    chatState.prompt = wrap;
    const ask = $("chatAsk");
    ask.replaceChildren(wrap);
    ask.hidden = false;

    // If the panel is hidden the question cannot be seen, and a countdown
    // running behind a closed panel is a decision made in secret.
    if (!chatState.open) openChat();
  });
}

/** The choices form: one of a small set of directions. */
function chatChoiceForm(choices, holder) {
  let chosen = null;

  for (const choice of choices) {
    const line = document.createElement("button");
    line.type = "button";
    line.className = "chat-choice";
    line.dataset.key = choice.key;

    const label = document.createElement("span");
    label.className = "chat-choice-label";
    label.textContent = choice.label;
    line.appendChild(label);

    if (choice.what_happens) {
      const what = document.createElement("span");
      what.className = "muted small";
      what.textContent = choice.what_happens;
      line.appendChild(what);
    }

    line.addEventListener("click", () => {
      chosen = choice.key;
      for (const other of holder.querySelectorAll(".chat-choice")) {
        other.classList.toggle("on", other.dataset.key === chosen);
      }
    });

    holder.appendChild(line);
  }

  return () => chosen;
}

/**
 * One message, as the node that shows it.
 *
 * Pulled out of renderChat so that reading a finished conversation and watching
 * a live one use the same code. Two renderers would drift, and the differences
 * would be exactly the details worth reading - the tool calls, the chart cards,
 * the compaction markers.
 *
 * Returns null for a message with nothing to draw.
 */
function chatMessageNode(message, session) {
    if (message.role === "summary") {
      return chatSummaryCard(message, session);
    }

    if (message.role === "picture") {
      return chatPictureCard(message);
    }

    if (message.role === "reaction") {
      return chatReactionCard(message);
    }

    if (message.role === "tool_call") {
      // A thing the model asked to show is the thing, not a line about it.
      if (message.tool === "show_chart") {
        return chatChartCard(message);
      }
      if (message.tool === "present_visual") {
        return chatAssistantVisualCard(message);
      }
      if (message.tool === "show_progress") {
        return chatProgressCard(message);
      }
      // The image arrives as its own message; the call itself says nothing.
      if (message.tool === "show_reaction") return null;

      const line = document.createElement("div");
      line.className = "chat-tool";
      line.textContent = `⚙ ${chatToolPhrase(message.tool, message.arguments)}`;
      line.title = JSON.stringify(message.arguments, null, 2);
      return line;
    }

    const bubble = document.createElement("div");
    bubble.className = `chat-line chat-${message.role}`;

    /*
     * Rendered as markdown, and still never as markup.
     *
     * Models write markdown whether or not you ask them to, so a plain-text
     * bubble showed literal asterisks and backticks around everything it meant
     * to emphasise - and a command it wanted somebody to run came out
     * indistinguishable from the prose around it.
     *
     * renderMarkdown builds nodes and never touches innerHTML, so the original
     * reasoning here still holds exactly: this is text from a model, a model
     * can be talked into producing anything, and nothing it produces becomes
     * markup. Only elements this code decided to create exist.
     */
    if (message.role === "assistant") {
      bubble.appendChild(renderMarkdown(message.content));
    } else {
      bubble.textContent = message.content;
    }
    return bubble;
}

/**
 * The prompt shown when the model wants to do something that asks first.
 *
 * The model's own reason is shown verbatim, because it is the only thing that
 * lets somebody judge the request - "it wants to take a screenshot" is not a
 * decision anybody can make, and "the chart shape will tell me more than the
 * numbers" is.
 */
function chatPermissionPrompt(run) {
  const wrap = document.createElement("div");
  wrap.className = "chat-permission";

  const what = document.createElement("div");
  what.textContent = `It wants to ${run.summary.replace(/\.$/, "")}.`;
  wrap.appendChild(what);

  if (run.why) {
    const why = document.createElement("div");
    why.className = "muted small";
    why.textContent = `“${run.why}”`;
    wrap.appendChild(why);
  }

  const actions = document.createElement("div");
  actions.className = "inspect-actions";

  for (const [text, allow, className] of [
    ["Allow", "1", ""],
    ["Not this time", "0", "danger"],
  ]) {
    const button = document.createElement("button");
    button.className = `link ${className}`;
    button.textContent = text;
    button.addEventListener("click", async () => {
      for (const other of actions.querySelectorAll("button")) other.disabled = true;
      try {
        chatState.session = (await post("ai-permit", { run: run.id, allow })).session;
        renderChat();
        await driveChat();
        scheduleChatPoll();
      } catch (error) {
        notice(String(error.message || error));
      }
    });
    actions.appendChild(button);
  }

  /*
   * A permission question that nobody answers is a refusal, eventually.
   *
   * Not immediately, and not silently: the countdown is visible from the first
   * second so that somebody who is reading it knows how long they have. But it
   * has to end, because a turn stuck waiting for a person who left is a
   * conversation that has to be started again from nothing - and every tool
   * that asks first is one the model can do without.
   *
   * Refuse rather than allow, always. The tools behind this question take
   * screenshots and spend money; the safe direction when nobody is there is
   * the one that does neither.
   */
  const clock = document.createElement("span");
  clock.className = "muted small chat-countdown";
  actions.appendChild(clock);

  /*
   * A deadline, not a counter.
   *
   * This prompt is rebuilt on every poll - several times a second while a turn
   * is in flight - so a countdown that started at 180 each time would never
   * reach zero. The deadline is set once, the first time this question is seen,
   * and every rebuild reads the same clock.
   */
  if (!chatState.deadlines.has(run.id)) {
    chatState.deadlines.set(run.id, Date.now() + PERMISSION_SECONDS * 1000);
  }
  const deadline = chatState.deadlines.get(run.id);

  const tick = async () => {
    // Answered by hand, replaced by a later render, or the question moved on.
    if (!wrap.isConnected || chatState.session?.permission?.id !== run.id) {
      clearInterval(timer);
      return;
    }

    const left = Math.max(0, Math.round((deadline - Date.now()) / 1000));

    clock.textContent = left > 0
      ? `Treated as no in ${humanSpan(left)}`
      : "No answer — carrying on without it";
    clock.classList.toggle("soon", left <= 15);

    if (left <= 0) {
      clearInterval(timer);
      for (const other of actions.querySelectorAll("button")) other.disabled = true;
      try {
        chatState.session = (await post("ai-permit", { run: run.id, allow: "0" })).session;
        notice(`Nobody answered, so ${chatState.who.name} was told no. It carries on `
          + "without whatever that would have told it.", true);
        renderChat();
        await driveChat();
        scheduleChatPoll();
      } catch (error) {
        notice(String(error.message || error));
      }
      chatState.deadlines.delete(run.id);
    }
  };

  const timer = setInterval(tick, 1000);
  tick();

  wrap.appendChild(actions);
  return wrap;
}

/**
 * How long a permission question waits.
 *
 * Long enough to read the reason and think about it, short enough that a
 * conversation left alone does not sit on one question until the session's own
 * time limit kills it.
 */
const PERMISSION_SECONDS = 180;

/** A tool call as a sentence rather than a function signature. */
function chatToolPhrase(tool, args) {
  const said = {
    get_current_status: "Checked how the machine is doing",
    get_collector_health: "Checked whether the monitoring is still running",
    get_measurement_history: `Looked at ${args.measurement} over ${args.hours} hours`,
    get_recent_alerts: "Read the recent alerts",
    get_recent_log_lines: "Read the recent log lines",
    get_repeated_log_lines: "Looked for repeated log messages",
    find_largest_paths: `Looked for the ${args.sort_by === "growth" ? "fastest-growing" : "largest"} files`,
    find_crowded_directories: "Looked for directories with the most files",
    get_busiest_processes: `Looked at what is running, by ${args.sort_by}`,
    get_site_check_results: "Checked whether the site is answering",
    get_network_summary: "Looked at ports and connections",
    get_recent_changes: "Checked what software has changed",
    get_action_history: "Read the action log",
    get_chart_data: `Read the numbers behind ${chartNames.known?.[args.chart]?.name ?? args.chart}`,
    get_chart_image: `Looked at ${chartNames.known?.[args.chart]?.name ?? args.chart}`,
    open_page: `Opened ${VIEWS[args.page]?.label ?? args.page}`,
    request_tool_group: `Requested ${TOOL_GROUP_NAMES[args.subject] ?? args.subject} tools`,
    take_screenshot: "Took a screenshot",
    inspect_current_page_html: "Reviewed the current page structure",
    present_visual: `Presented ${args.title || "a visual"}`,
    show_progress: `Showed progress on ${args.what ?? "something"}`,
    set_time_range: `Switched the view to the last ${args.range ?? "?"}`
      + (args.live ? ", live" : ""),
    what_the_terminal_can_run: "Checked which commands exist here",
    what_the_host_can_be_asked: "Checked what the host can be asked to do",
    get_pending_host_requests: "Checked what the host already has queued",
    get_collection_schedule: "Checked when the collectors run",
    recommend_command: "Put a command on the terminal page",
    remember: `Wrote down what it worked out about ${args.subject ?? "something"}`,
    recall: args.about
      ? `Looked up what it remembered about ${args.about}`
      : "Looked at what it remembered",
    show_reaction: "Reacted",
    make_picture: "Had a picture drawn",
    redraw_yourself: "Redrew itself",
  }[tool];

  return said ?? tool;
}

async function startChat() {
  try {
    chatState.handled.clear();
    chatState.charts.clear();
    chatState.session = (await post("ai-start", { from: state.view })).session;
    renderChat();
    scheduleChatPoll();
  } catch (error) {
    notice(String(error.message || error));
  }
}

async function sayToChat(text) {
  if (!chatState.session?.exists) {
    await startChat();
  }
  if (!chatState.session?.exists) return;

  $("chatText").value = "";

  try {
    const result = await post("ai-say", {
      session: chatState.session.id,
      text,
      // So it knows where the operator is looking when they said this.
      view: state.view ?? "",
    });
    chatState.session = result.session;
    renderChat();

    /*
     * A message added while it is working is not a new turn.
     *
     * It is already in the transcript and the model reads it on the turn it is
     * in the middle of. Driving here as well would start a second request
     * alongside the one in flight.
     */
    if (result.queued) {
      notice("Added. It will read that on its next turn.", true);
      scheduleChatPoll();
      return;
    }

    await driveChat();
    scheduleChatPoll();
  } catch (error) {
    notice(String(error.message || error));
  }
}

/* ---------------------------------------------------------- address names -- */

const rdnsState = { data: null };

async function refreshRdns() {
  const body = $("rdnsBody");

  if (!state.signedIn) {
    body.replaceChildren(note(ZogographI18n.t("common.sign_in_to_see", {}, "Sign in to see this.")));
    return;
  }

  try {
    renderRdns(await api("rdns"));
  } catch (error) {
    body.replaceChildren(note(String(error.message || error)));
  }
}

function renderRdns(data) {
  rdnsState.data = data;
  // Kept for every other page that shows an address, so a table can name one
  // without asking again.
  state.rdnsNames = Object.fromEntries(
    (data.known || []).filter(row => row.name).map(row => [row.address, row.name])
  );

  const body = $("rdnsBody");
  const parts = [];

  if (data.released > 0) {
    parts.push(note(
      `${count(data.released, "request")} had been taken by a collector that never came `
      + "back — a run killed mid-lookup — and have been put back in the queue."
    ));
  }

  const waiting = (data.waiting || []).filter(row => !row.taken);
  const taken = (data.waiting || []).filter(row => row.taken);

  if (waiting.length || taken.length) {
    const holder = document.createElement("div");
    holder.id = "rdnsQueue";
    parts.push(section(
      `${count(waiting.length, "address", "addresses")} waiting`
      + (taken.length ? `, ${taken.length} in progress` : ""),
      holder
    ));

    parts.push(note(
      `At ${data.per_run === 1 ? "one" : data.per_run} per collector run, the queue empties `
      + `in about ${humanSpan(Math.ceil(waiting.length / Math.max(1, data.per_run)) * 300)}. `
      + (data.host_enabled
        ? "Both collectors take one, so it may be quicker than that."
        : "")
    ));
  } else {
    parts.push(note("Nothing waiting."));
  }

  if (data.known?.length) {
    const holder = document.createElement("div");
    holder.id = "rdnsKnown";
    parts.push(section(`${count(data.known.length, "address", "addresses")} looked up`, holder));
  }

  body.replaceChildren(...parts);

  if (waiting.length || taken.length) {
    renderTable("rdnsQueue", data.waiting, [
      {
        label: "Address",
        className: "name",
        render: row => row.address,
      },
      { label: ZogographI18n.t("network.rdns_asked"), render: row => ZogographI18n.t("network.rdns_asked_by", { ago: ago(row.asked_at), by: row.asked_by }) },
      { label: ZogographI18n.t("network.rdns_waiting"), render: row => humanSpan(row.waited) },
      {
        label: "",
        render: row => {
          if (!row.taken) return "";
          const span = document.createElement("span");
          span.className = "band-warn";
          span.textContent = ZogographI18n.t("network.rdns_looking_now", { collector: row.taken_by });
          return span;
        },
      },
      {
        label: "",
        className: "row-actions",
        render: row => {
          const button = document.createElement("button");
          button.className = "link danger";
          button.textContent = ZogographI18n.t("action.cancel", {}, "Cancel");
          /*
           * Only while it is still waiting.
           *
           * Once a collector has taken it the lookup is running or done, and
           * offering to recall it would be a claim about something this page
           * does not control.
           */
          button.disabled = row.taken;
          button.title = row.taken
            ? ZogographI18n.t("network.rdns_taken_tip")
            : ZogographI18n.t("network.rdns_cancel_tip");
          button.addEventListener("click", async () => {
            button.disabled = true;
            try {
              renderRdns(await post("rdns-cancel", { id: row.id }));
            } catch (error) {
              notice(String(error.message || error));
              button.disabled = false;
            }
          });
          return button;
        },
      },
    ], null, row => (row.taken ? "row-off" : ""), row => String(row.id));
  }

  if (data.known?.length) {
    renderTable("rdnsKnown", data.known, [
      { label: "Address", className: "name", render: row => row.address },
      {
        label: ZogographI18n.t("network.rdns_called"),
        className: "name",
        render: row => {
          if (row.name) return row.name;
          const span = document.createElement("span");
          span.className = "muted";
          span.textContent = ZogographI18n.t("network.rdns_no_name");
          span.title = ZogographI18n.t("network.rdns_no_name_tip");
          return span;
        },
      },
      {
        label: ZogographI18n.t("network.rdns_looked_up"),
        render: row => {
          const span = document.createElement("span");
          span.textContent = ago(row.checked_at);
          if (row.stale) {
            span.className = "muted";
            span.title = ZogographI18n.t("network.rdns_stale_tip", { age: humanSpan(data.fresh_for) });
          }
          return span;
        },
      },
      { label: ZogographI18n.t("network.rdns_by"), render: row => row.resolved_by },
      {
        label: "",
        className: "row-actions",
        render: row => {
          const again = document.createElement("button");
          again.className = "link";
          again.textContent = ZogographI18n.t("action.ask_again", {}, "Ask again");
          again.title = ZogographI18n.t("network.rdns_ask_again_tip");
          again.addEventListener("click", async () => {
            again.disabled = true;
            try {
              /*
               * Forced, because rdnsRequest declines anything recent.
               *
               * Which is right for the automatic path and wrong here: somebody
               * pressing this has a reason to believe the stored answer is out
               * of date.
               */
              renderRdns(await post("rdns-ask", { addresses: row.address, force: "1" }));
              notice(ZogographI18n.t("network.rdns_address_queued", { address: row.address }), true);
            } catch (error) {
              notice(String(error.message || error));
            } finally {
              again.disabled = false;
            }
          });
          return again;
        },
      },
    ], null, null, row => row.address);
  }
}

/**
 * A name for an address, where one is known.
 *
 * Returns a node rather than a string so the address stays visible: a label is
 * a note about a fact, never a replacement for it, and that goes double for a
 * name that came from a PTR record somebody else controls.
 */
function withAddressName(address) {
  const name = state.rdnsNames?.[address];
  const mine = state.labelNames?.[address];

  const span = document.createElement("span");
  span.textContent = address;

  if (mine) {
    const yours = document.createElement("span");
    yours.className = "own-name";
    yours.textContent = ` (${mine})`;
    yours.title = "A name you gave this address, under Settings → Your own names.";
    span.appendChild(yours);
  }

  if (name) {
    const theirs = document.createElement("span");
    theirs.className = "muted small";
    theirs.textContent = ` ${name}`;
    theirs.title = "What the internet says this address is called — a PTR record, which "
      + "its owner controls and can say anything.";
    span.appendChild(theirs);
  }

  return span;
}

/* -------------------------------------------------------------- changes -- */

const changedState = { data: null, only: "" };

/**
 * What is installed, on its own page.
 *
 * The same request as "what changed" - one check fills both - but its own page,
 * because the two answer different questions and one of them is asked far more
 * often. "What version of OpenSSL is this" was buried under a chart of when it
 * last moved.
 */
async function refreshInstalled() {
  const body = $("installedBody");

  if (!state.signedIn) {
    body.replaceChildren(note(ZogographI18n.t("common.sign_in_to_see", {}, "Sign in to see this.")));
    return;
  }

  const to = state.frozenAt || Math.floor(Date.now() / 1000);

  try {
    /*
     * The period is sent although this page is a snapshot.
     *
     * The action wants one, and asking for the same window the other page uses
     * means the two share a cached answer rather than making the same call
     * twice with different arguments.
     */
    renderInstalled(await api("changed", {
      from: to - state.range,
      to,
      only: changedState.only,
    }));
  } catch (error) {
    body.replaceChildren(note(String(error.message || error)));
  }
}

async function refreshChanged() {
  const body = $("changedBody");

  if (!state.signedIn) {
    body.replaceChildren(note(ZogographI18n.t("common.sign_in_to_see", {}, "Sign in to see this.")));
    return;
  }

  const to = state.frozenAt || Math.floor(Date.now() / 1000);

  try {
    renderChanged(await api("changed", {
      from: to - state.range,
      to,
      only: changedState.only,
    }));
  } catch (error) {
    body.replaceChildren(note(String(error.message || error)));
  }
}

function renderChanged(data) {
  changedState.data = data;

  syncChangedFilter(data);
  drawChangedChart(data);
  renderChangedList(data);

  /*
   * The other page too, when it happens to be on screen.
   *
   * They are separate pages now but one request answers both, so a refresh of
   * either fills in whatever is visible rather than leaving the neighbour
   * stale until somebody navigates to it.
   */
  if (!$("installedBody").closest(".view")?.hidden) renderInstalled(data);
}

/** The filter offers only what has actually moved. */
function syncChangedFilter(data) {
  const select = $("changedOnly");
  const wanted = [["", "Everything"], ...data.names.map(row => [
    row.name,
    `${row.label} (${count(row.times, "change")})`,
  ])];

  const have = [...select.options].map(option => option.value);
  const same = have.length === wanted.length && have.every((v, i) => v === wanted[i][0]);
  if (same) return;

  const chosen = select.value;
  select.replaceChildren(...wanted.map(([value, label]) => {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    return option;
  }));
  if (wanted.some(([value]) => value === chosen)) select.value = chosen;
}

/**
 * When things changed, over the range.
 *
 * Not a line: a change is an event, not a quantity, and joining them with a
 * line would draw a slope between two upgrades that means nothing at all. So
 * a mark per event on a lane per thing, which also makes the shape people
 * actually look for visible - several things moving on the same afternoon,
 * which is a package update rather than a coincidence.
 */
function drawChangedChart(data) {
  const canvas = $("changedChart");
  if (!canvas) return;

  rememberDraw(canvas, () => drawChangedChart(changedState.data || data));

  const width = canvas.clientWidth;
  if (!width) return;

  const events = data.events || [];
  const lanes = [...new Set(events.map(event => event.name))].slice(0, 14);

  const pad = { left: 150, right: 14, top: 14, bottom: 34 };
  const laneH = 18;
  const height = Math.max(120, pad.top + pad.bottom + Math.max(1, lanes.length) * laneH);

  const dpr = window.devicePixelRatio || 1;
  canvas.width = Math.round(width * dpr);
  canvas.height = Math.round(height * dpr);
  canvas.style.height = height + "px";

  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);
  ctx.font = "11px system-ui, sans-serif";

  const plotW = Math.max(1, width - pad.left - pad.right);
  const from = data.from;
  const to = data.to;
  const span = Math.max(1, to - from);
  const x = at => pad.left + ((Math.max(from, Math.min(to, at)) - from) / span) * plotW;

  const axis = timeTicks(from, to, plotW, text => ctx.measureText(text).width);
  for (const tick of axis.ticks) {
    const at = pad.left + tick.x;
    ctx.strokeStyle = tick.ends ? "rgba(255,255,255,0.14)" : "rgba(255,255,255,0.06)";
    ctx.beginPath();
    ctx.moveTo(at, pad.top);
    ctx.lineTo(at, height - pad.bottom + 4);
    ctx.stroke();

    if (!tick.label) continue;
    ctx.fillStyle = tick.ends ? "#8b98a8" : "#66717f";
    ctx.textAlign = "center";
    ctx.fillText(tick.label, at, height - 12);
  }

  if (!events.length) {
    ctx.fillStyle = "#66717f";
    ctx.textAlign = "left";
    ctx.fillText("Nothing changed in this range.", pad.left + 8, pad.top + 20);
    $("changedChartNote").textContent = "";
    return;
  }

  lanes.forEach((name, i) => {
    const y = pad.top + i * laneH + laneH / 2;
    const label = events.find(event => event.name === name)?.label ?? name;

    ctx.fillStyle = "#8b98a8";
    ctx.textAlign = "right";
    ctx.fillText(label.length > 22 ? label.slice(0, 21) + "…" : label, pad.left - 10, y + 4);

    ctx.strokeStyle = "rgba(255,255,255,0.05)";
    ctx.beginPath();
    ctx.moveTo(pad.left, y);
    ctx.lineTo(pad.left + plotW, y);
    ctx.stroke();

    for (const event of events.filter(event => event.name === name)) {
      const at = x(event.at);
      /*
       * Hollow where the evidence is a fingerprint rather than a version.
       *
       * Both are changes and both belong on the chart, but one is "3.0.11
       * became 3.0.13" and the other is "the file is not the one that was
       * here", and drawing them identically would let somebody quote a hash
       * as a version number.
       */
      ctx.beginPath();
      ctx.arc(at, y, 4, 0, Math.PI * 2);
      if (event.by_fingerprint) {
        ctx.strokeStyle = "#d8b25e";
        ctx.lineWidth = 1.5;
        ctx.stroke();
      } else {
        ctx.fillStyle = event.kind === "software" ? "#4c9aff" : "#56c98a";
        ctx.fill();
      }
    }
  });

  ctx.textAlign = "left";

  const hidden = new Set(events.map(event => event.name)).size - lanes.length;
  $("changedChartNote").textContent =
    `${count(events.length, "change")} across ${count(lanes.length, "thing")}.`
    + (hidden > 0 ? ` ${count(hidden, "other")} not shown — use the filter.` : "")
    + " Blue is the system software, green a program this tool watches, and a hollow"
    + " ring means the change was noticed by fingerprint rather than by version.";
}

function renderChangedList(data) {
  const body = $("changedBody");

  if (!data.events.length) {
    body.replaceChildren(note(
      data.last_checked
        ? `Nothing has changed in this range. Last checked ${ago(data.last_checked)}.`
        : "Nothing has been checked yet. Press Check now, or open What the host allows."
    ));
    return;
  }

  const holder = document.createElement("div");
  holder.id = "changedTable";
  body.replaceChildren(holder);

  renderTable("changedTable", data.events, [
    { label: ZogographI18n.t("changed.noticed", {}, "Noticed"), render: row => whenSpan(row.at) },
    {
      label: ZogographI18n.t("changed.what", {}, "What"),
      className: "name",
      render: row => {
        const span = document.createElement("span");
        span.textContent = row.label;
        span.title = row.kind === "software"
          ? ZogographI18n.t("installed.system_software_tip")
          : ZogographI18n.t("installed.watched_program_tip", { group: row.group ? ` (${row.group})` : "" });
        return span;
      },
    },
    { label: ZogographI18n.t("changed.was", {}, "Was"), className: "cmd", render: row => row.from ?? "—" },
    { label: ZogographI18n.t("changed.became", {}, "Became"), className: "cmd", render: row => row.to },
    {
      label: "",
      render: row => {
        if (row.state_from && row.state_from !== row.state_to) {
          const span = document.createElement("span");
          span.className = row.state_to === "absent" ? "band-crit" : "band-ok";
          span.textContent = `${row.state_from} → ${row.state_to}`;
          return span;
        }
        if (row.by_fingerprint) {
          const span = document.createElement("span");
          span.className = "muted small";
          span.textContent = ZogographI18n.t("changed.by_fingerprint", {}, "by fingerprint");
          span.title = ZogographI18n.t("installed.fingerprint_change_tip");
          return span;
        }
        return "";
      },
    },
  ], null, null, row => `${row.at}|${row.name}`);
}

/** What everything is at right now, and how long it has been that way. */
function renderInstalled(data) {
  const body = $("installedBody");
  const parts = [];

  if (data.last_checked) {
    parts.push(note(ZogographI18n.t("installed.last_checked", { ago: ago(data.last_checked) })));
  }

  if (data.now.length) {
    parts.push(section(ZogographI18n.t("installed.system_software"), simpleTable(
      [ZogographI18n.t("installed.what"), ZogographI18n.t("installed.is"), ZogographI18n.t("installed.unchanged_for"), ZogographI18n.t("installed.why_it_matters")],
      data.now.map(row => [
        row.label,
        row.value,
        humanSpan(row.age),
        row.note || "",
      ]),
      ["name", "cmd", null, "muted"]
    )));
  } else {
    parts.push(note(
      ZogographI18n.t("installed.empty")
    ));
  }

  const watched = (data.capabilities || []).filter(row => row.version || row.fingerprint);
  if (watched.length) {
    parts.push(section(ZogographI18n.t("installed.watched_programs"), simpleTable(
      [ZogographI18n.t("installed.program"), ZogographI18n.t("installed.version"), ZogographI18n.t("installed.where")],
      watched.map(row => [
        row.name,
        row.version || (row.fingerprint ? ZogographI18n.t("installed.file_fingerprint", { fingerprint: row.fingerprint }) : "—"),
        row.path,
      ]),
      ["name", "cmd", "cmd"]
    )));
    parts.push(note(
      ZogographI18n.t("installed.fingerprint_note")
    ));
  }

  body.replaceChildren(...parts);
}

/* ---------------------------------------------------------------- notes -- */

/*
 * Notes are the only thing on this page that answers "why".
 *
 * Every chart answers "what happened". The why is that somebody upgraded PHP on
 * the Tuesday, and it is not in any of the data - so it has to be written down,
 * attached to the moment, and drawn back on the charts it belongs to.
 */
const noteState = { data: null, marks: [], forView: null, selected: new Set() };

/**
 * The notes that belong on the charts of the view being shown.
 *
 * Fetched alongside the view rather than with it, because every page draws
 * charts and threading a marks array through forty render functions would mean
 * thirty-nine of them eventually being forgotten. drawLineChart reads this the
 * same way it reads state.restarts.
 */
async function loadNoteMarks(view) {
  if (!state.signedIn) {
    noteState.marks = [];
    return;
  }

  try {
    /*
     * The window the charts are showing, not a fixed day.
     *
     * state.range is the span and state.frozenAt is where "now" is when the
     * page is pinned to a moment, which is exactly what the charts use.
     */
    const to = state.frozenAt || Math.floor(Date.now() / 1000);
    const data = await api("note-marks", {
      view,
      from: to - state.range,
      to,
    });
    noteState.marks = data.marks || [];
    noteState.forView = view;
  } catch {
    // A page that draws without its notes is a page missing annotations; a
    // page that fails to draw because the notes could not be fetched is worse.
    noteState.marks = [];
  }
}

/**
 * The marks for one chart: the page-wide ones plus any pinned to it.
 *
 * A pinned note names a comma-separated list of charts, because one event
 * frequently bends two of them and writing the note twice is not a thing
 * anybody was ever going to do.
 */
function marksForChart(chartId) {
  return noteState.marks
    .filter(mark => mark.scope !== "chart"
      || String(mark.chart ?? "").split(",").includes(chartId))
    .map(mark => ({ at: mark.at, label: mark.body }));
}

/**
 * The dialog for writing one.
 *
 * Opened from the button that follows you around, so the page and the moment
 * are already known - which is the whole point. Somebody who has to go
 * somewhere else and re-describe what they were looking at does not write the
 * note.
 */
async function showNoteDialog(preset = {}) {
  /*
   * The scopes and capture kinds come from the server, and until now they only
   * arrived when somebody opened the Notes page.
   *
   * Which meant the dialog opened from anywhere else offering one scope and no
   * captures at all - and then refusing the capture it had just let somebody
   * choose. Fetched once, here, rather than left to whichever page happened to
   * have been visited first.
   */
  if (!noteState.data) {
    try {
      noteState.data = await api("notes");
    } catch (error) {
      notice(String(error.message || error));
      return;
    }
  }

  const parts = [];
  const view = preset.view ?? state.view;

  const body = document.createElement("textarea");
  body.rows = 5;
  body.className = "wide";
  body.placeholder = "Upgraded PHP to 8.4 on the host. The memory step at 14:20 is that.";
  body.value = preset.body ?? "";
  parts.push(fieldRow("What happened", body, ""));

  /*
   * When it is about, which is not always now.
   *
   * Somebody writing up an incident the next morning wants the mark where the
   * incident was. Defaulting to now and letting it be moved is the right way
   * round: the common case needs no thought.
   */
  const when = document.createElement("input");
  when.type = "datetime-local";
  when.value = localDateTimeValue(preset.at ?? Math.floor(Date.now() / 1000));
  parts.push(fieldRow("When", when,
    "Defaults to now. Move it back if you are writing up something that already happened "
    + "— the mark belongs where the event was, not where the typing was."));

  const scope = document.createElement("select");
  const scopeNote = document.createElement("div");
  scopeNote.className = "muted small";

  const scopes = noteState.data.scopes;

  const charts = chartsOnPage();

  for (const [key, meta] of Object.entries(scopes)) {
    // Pinning to particular charts needs charts to pin to, and that is only
    // knowable from a page that has some.
    if (key === "chart" && !charts.length) continue;
    const option = document.createElement("option");
    option.value = key;
    option.textContent = meta.label;
    option.selected = (preset.scope ?? "page") === key;
    scope.appendChild(option);
  }
  parts.push(fieldRow("Where it shows", scope, ""));
  parts.push(scopeNote);

  /*
   * Which charts the mark goes on - more than one, if that is the truth.
   *
   * It was a single-choice list, which forced "the network chart and the disk
   * chart both bent here" to be written twice or flattened to the whole page.
   * The "every chart there is" tick at the top is the same thing as choosing
   * "Mark it everywhere" above, offered where somebody is already looking for
   * it rather than requiring them to go back up and change their mind.
   */
  const chartPick = tickList(
    "noteChart",
    [["*", "Every chart there is — the whole dashboard", true]]
      .concat(charts.map(([id, label]) => [id, label, false])),
    preset.chart ? String(preset.chart).split(",") : (charts[0] ? [charts[0][0]] : [])
  );
  const chartRow = fieldRow("Which charts", chartPick.node,
    "Ticking more than one puts the same mark on each of them.");
  parts.push(chartRow);

  const snapshot = document.createElement("select");
  const snapshotNote = document.createElement("div");
  snapshotNote.className = "muted small";

  const kinds = noteState.data.kinds;
  for (const [key, meta] of Object.entries(kinds)) {
    const option = document.createElement("option");
    option.value = key;
    option.textContent = meta.label;
    option.selected = (preset.snapshot ?? "none") === key;
    snapshot.appendChild(option);
  }
  parts.push(fieldRow("Also capture", snapshot, ""));
  parts.push(snapshotNote);

  /*
   * Pictures of the charts, as they look right now.
   *
   * Separate from where the mark goes, and it took somebody being confused by
   * the old dialog to see that they were two different questions wearing one
   * label. A mark is a line on a future chart; an image is what this chart
   * looked like at the moment somebody thought it was worth keeping - which
   * survives retention rolling the readings up underneath it.
   */
  let shots = null;
  if (charts.length) {
    shots = tickList("noteShot", charts.map(([id, label]) => [id, label, false]), []);
    parts.push(fieldRow("Keep pictures of", shots.node,
      "Saved with the note exactly as they are drawn now, so the picture still shows "
      + "what you saw after retention has rolled the readings up underneath it."));
  } else {
    /*
     * Said out loud rather than left as an empty list.
     *
     * An empty control reads as something that failed to load, and the person
     * looking at it cannot tell the difference between "this page has no
     * charts" and "the charts have not arrived yet".
     */
    parts.push(fieldRow("Keep pictures of", (() => {
      const said = document.createElement("div");
      said.className = "muted";
      said.textContent = "There are no charts on this page.";
      return said;
    })(), "The note itself is saved either way, and a mark on this page will show on "
      + "any chart added here later."));
  }

  /*
   * A picture of the page, taken with this dialog out of the way.
   *
   * The obvious problem with screenshotting from inside a modal is that the
   * modal is the biggest thing on the screen. Everything typed so far is put
   * back afterwards, so this is not a decision that has to be made before
   * starting to write.
   */
  const shotRow = document.createElement("div");
  shotRow.className = "settings-row";
  const shotHolder = document.createElement("div");
  let pageShot = preset.shot ?? null;

  const takeShot = document.createElement("button");
  takeShot.type = "button";
  takeShot.textContent = pageShot
    ? ZogographI18n.t("notes.take_another_screenshot", {}, "Take another")
    : ZogographI18n.t("notes.take_screenshot", {}, "Take a screenshot");
  takeShot.addEventListener("click", async () => {
    const typed = {
      body: body.value,
      scope: scope.value,
      at: Math.floor(new Date(when.value).getTime() / 1000),
      chart: chartPick.chosen().join(","),
      link: link.value,
      broadcast: broadcast.checked,
      audience: audience ? audience.chosen().join(",") : "",
      snapshot: snapshot.value,
    };

    $("noteDialog").close();

    try {
      // A frame, so the dialog is actually gone before the capture starts.
      await new Promise(resolve => requestAnimationFrame(
        () => requestAnimationFrame(resolve)));

      const shot = await editScreenshot(await captureScreen(), "for a note");
      showNoteDialog({ ...typed, view, shot: shot ?? pageShot });
    } catch (error) {
      notice(String(error.message || error));
      showNoteDialog({ ...typed, view, shot: pageShot });
    }
  });
  shotHolder.appendChild(takeShot);

  if (pageShot) {
    const thumb = document.createElement("img");
    thumb.className = "note-shot";
    thumb.src = pageShot;
    thumb.alt = ZogographI18n.t("image.note_screenshot", {}, "The screenshot that will be saved with this note");
    shotHolder.appendChild(thumb);

    const drop = document.createElement("button");
    drop.type = "button";
    drop.className = "link danger";
    drop.textContent = ZogographI18n.t("notes.discard_screenshot", {}, "Do not keep it");
    drop.addEventListener("click", () => {
      pageShot = null;
      thumb.remove();
      drop.remove();
      takeShot.textContent = ZogographI18n.t("notes.take_screenshot", {}, "Take a screenshot");
    });
    shotHolder.appendChild(drop);
  }

  const shotLabel = document.createElement("label");
  shotLabel.className = "settings-label";
  shotLabel.textContent = ZogographI18n.t("notes.screenshot", {}, "Screenshot");
  shotRow.appendChild(shotLabel);

  const shotWrap = document.createElement("div");
  shotWrap.appendChild(shotHolder);
  const shotHint = document.createElement("div");
  shotHint.className = "muted small";
  shotHint.textContent = ZogographI18n.t("notes.screenshot_help", {}, "This dialog closes while the picture is taken and everything you have typed comes back with it. You can crop and black out anything before it is kept.");
  shotWrap.appendChild(shotHint);
  shotRow.appendChild(shotWrap);
  parts.push(shotRow);

  const broadcast = document.createElement("input");
  broadcast.type = "checkbox";
  broadcast.checked = preset.broadcast === true;
  parts.push(fieldRow("Tell everyone", broadcast,
    "Shows this at the top of every page for anyone who opens the dashboard, until "
    + "somebody clears it. This is the difference between one person knowing about the "
    + "disk and three people finding out separately at two in the morning."));

  const audience = tickList("noteAudience", (noteState.data.groups || []).map(group => [
    group,
    group,
    (preset.audience || []).includes(group),
  ]), []);
  parts.push(fieldRow("Visible to groups", audience.node,
    "Leave every group unticked to share with everyone who may read notes. Ticking one or "
    + "more groups limits both this note and any broadcast made from it."));

  const link = document.createElement("input");
  link.type = "text";
  link.className = "wide";
  link.placeholder = "https://your-tracker/issue/412";
  link.value = preset.link ?? "";
  parts.push(fieldRow("Link", link, "Optional. A ticket, a changelog, a pull request."));

  /*
   * Which page this is about, as a labelled value.
   *
   * It was the sentence "This page is Over time." - which reads as a broken
   * template rather than a fact, because a page name is a name and does not
   * belong in the middle of a sentence. It is a row like every other row now.
   */
  const where = fieldRow("Page", (() => {
    const said = document.createElement("div");
    said.className = "muted";
    said.textContent = VIEWS[view]?.label ?? view;
    return said;
  })(), "Where the mark will be drawn.");
  parts.push(where);

  const actions = document.createElement("div");
  actions.className = "inspect-actions";

  const save = document.createElement("button");
  save.type = "submit";
  save.textContent = ZogographI18n.t("action.save", {}, "Save it");
  actions.appendChild(save);
  parts.push(actions);

  const sync = () => {
    scopeNote.textContent = scopes[scope.value]?.note ?? "";
    snapshotNote.textContent = kinds[snapshot.value]?.note ?? "";
    chartRow.hidden = scope.value !== "chart";
    where.hidden = scope.value === "plain" || scope.value === "site";
  };
  scope.addEventListener("change", sync);
  snapshot.addEventListener("change", sync);
  sync();

  $("noteFormBody").replaceChildren(...parts);
  $("noteDialogTitle").textContent = ZogographI18n.t("notes.write_title");

  const form = $("noteForm");
  form.onsubmit = async event => {
    event.preventDefault();
    save.disabled = true;
    save.textContent = snapshot.value === "none"
      ? ZogographI18n.t("notes.saving")
      : ZogographI18n.t("notes.saving_and_capturing");

    try {
      /*
       * "Every chart there is" is the site-wide scope by another name, so it
       * is turned into one here rather than being a second way of storing the
       * same fact.
       */
      const everywhere = scope.value === "chart" && chartPick.chosen().includes("*");

      const fields = {
        body: body.value,
        scope: everywhere ? "site" : scope.value,
        view,
        chart: everywhere || scope.value !== "chart"
          ? ""
          : chartPick.chosen().join(","),
        link: link.value.trim(),
        at: String(Math.floor(new Date(when.value).getTime() / 1000)),
        broadcast: broadcast.checked ? "1" : "0",
        audience: audience.chosen().join(","),
        snapshot: snapshot.value,
      };

      /*
       * The page's own data goes up with the note.
       *
       * Which sounds backwards - the server could fetch it again - but during
       * the incident this is for, a second later is a different answer. What
       * is wanted is what was on the screen.
       */
      if (snapshot.value === "page") fields.payload = pageSnapshot();

      /*
       * The pictures are taken here, from the live canvases, at the moment of
       * saving - not from anything cached. What is wanted is what is on the
       * screen.
       */
      const pictures = shots ? chartPictures(shots.chosen()) : [];
      if (pageShot) {
        pictures.push({
          chart: "",
          name: `The ${VIEWS[view]?.label ?? view} page`,
          width: 0,
          height: 0,
          range: state.range,
          at: Math.floor(Date.now() / 1000),
          data: pageShot,
        });
      }
      if (pictures.length) fields.images = JSON.stringify(pictures);

      const result = await post("note-save", fields);
      $("noteDialog").close();

      let said = "Note saved.";
      if (result.captured?.length) said += ` Captured ${result.captured.join(", ")}.`;
      if (result.problems?.length) said += ` Not captured: ${result.problems.join("; ")}.`;
      notice(said, !result.problems?.length);

      renderNotes(result);
      await loadNoteMarks(state.view);
      redrawCharts();
    } catch (error) {
      notice(String(error.message || error));
    } finally {
      save.disabled = false;
      save.textContent = ZogographI18n.t("action.save", {}, "Save it");
    }
  };

  $("noteDialog").showModal();
  body.focus();
}

/**
 * A datetime-local value for a moment, in the browser's own timezone.
 *
 * toISOString would be UTC, and an input that showed 14:20 as 18:20 would have
 * people writing notes an hour out and never noticing which way.
 */
function localDateTimeValue(seconds) {
  const at = new Date(seconds * 1000);
  const pad = n => String(n).padStart(2, "0");
  return `${at.getFullYear()}-${pad(at.getMonth() + 1)}-${pad(at.getDate())}`
    + `T${pad(at.getHours())}:${pad(at.getMinutes())}`;
}

/** Every chart on the page being shown, by id and by the heading above it. */
function chartsOnPage() {
  const view = document.querySelector(".view:not([hidden])");
  if (!view) return [];

  const found = [...view.querySelectorAll("canvas[id]")]
    .filter(canvas => canvas.offsetParent !== null)
    .map(canvas => {
      const panel = canvas.closest(".panel");
      const heading = panel?.querySelector("h2, h3")?.textContent?.trim();
      /*
       * The legend names what a chart plots, which is what tells two charts in
       * the same panel apart.
       *
       * Taking the panel heading alone gave both of them the same name, and a
       * list offering "Broken" twice is a list nobody can choose from.
       */
      const beside = canvas.nextElementSibling;
      const legend = beside?.classList.contains("legend")
        ? [...beside.querySelectorAll("span")]
            .map(node => node.textContent.trim())
            .filter(Boolean)
            .join(", ")
        : "";
      return [canvas.id, heading || canvas.id, legend];
    });

  const seen = new Map();
  for (const [, heading] of found) seen.set(heading, (seen.get(heading) ?? 0) + 1);

  return found.map(([id, heading, legend]) => [
    id,
    // Only disambiguated when it needs to be: "Response time (Broken)" on a
    // page with one chart would be noise.
    seen.get(heading) > 1 && legend ? `${heading} \u2014 ${legend}` : heading,
  ]);
}

/**
 * What this page currently holds, as one JSON document.
 *
 * Taken from the caches the page drew itself from rather than re-fetched, so
 * it is exactly what was on screen.
 */
function pageSnapshot() {
  const document_ = {
    at: Math.floor(Date.now() / 1000),
    view: state.view,
    range: { seconds: state.range, at: state.frozenAt || Math.floor(Date.now() / 1000) },
    data: {},
  };

  /*
   * Every page keeps its data in its own state object, and there is no
   * register of them. Rather than build one that would go stale, the ones
   * that exist are collected by name - and anything not listed simply is not
   * captured, which the "every page" snapshot covers properly.
   */
  for (const [name, holder] of Object.entries({
    url: typeof urlState !== "undefined" ? urlState : null,
    network: typeof networkState !== "undefined" ? networkState : null,
    store: typeof storeState !== "undefined" ? storeState : null,
    link: typeof linkState !== "undefined" ? linkState : null,
    fetch: typeof fetchState !== "undefined" ? fetchState : null,
    dns: typeof dnsState !== "undefined" ? dnsState : null,
  })) {
    if (holder && holder.data) document_.data[name] = holder.data;
  }

  document_.data.shared = {
    vitals: state.vitals ?? null,
    overview: state.overview ?? null,
    restarts: state.restarts ?? null,
  };

  try {
    return JSON.stringify(document_);
  } catch {
    // Circular references in a state object would otherwise lose the note.
    return JSON.stringify({ at: document_.at, view: state.view, error: "could not be encoded" });
  }
}

