function visiblePathName(path) {
  return String(path).replace(/ /g, "·").replace(/\t/g, "⇥").replace(/\r/g, "␍").replace(/\n/g, "␊");
}

function visiblePathNode(path) {
  const markers = { " ": ["·", "space"], "\t": ["⇥", "tab"], "\r": ["␍", "carriage return"], "\n": ["␊", "line feed"] };
  const node = document.createDocumentFragment();
  const parts = String(path).split("/");
  parts.forEach((part, index) => {
    if (index) {
      const separator = document.createElement("span");
      separator.className = "path-hygiene-separator";
      separator.textContent = index === 1 && parts[0] === "" ? "/ " : " / ";
      node.append(separator);
    }
    const segment = document.createElement("span");
    segment.className = index === parts.length - 1 ? "path-hygiene-offending" : "path-hygiene-prefix";
    for (const character of part) {
      const marker = markers[character];
      if (!marker) { segment.append(document.createTextNode(character)); continue; }
      const visible = document.createElement("span");
      visible.className = "path-hygiene-whitespace";
      visible.textContent = marker[0];
      visible.title = marker[1];
      visible.setAttribute("aria-label", marker[1]);
      segment.append(visible);
    }
    node.append(segment);
  });
  return node;
}

function renderPathHygiene(data) {
  const body = $("pathHygieneBody");
  if (!data.enabled) { body.replaceChildren(note("Install and enable Path-name hygiene in the Marketplace to use this check.")); return; }
  const last = data.last;
  if (!last) { body.replaceChildren(note("Enabled, but no completed account disk scan has recorded path names yet.")); return; }
  const parts = [factGrid([["Last scan", humanTime(last.checked_at)], ["Found", String(last.total)], ["Stored", String(last.findings.length)]])];
  if (!last.findings.length) parts.push(note("No shell-confusing path names were found in the latest scan."));
  else {
    const holder = document.createElement("div"); holder.id = "pathHygieneTable"; parts.push(holder);
    body.replaceChildren(...parts);
    renderTable("pathHygieneTable", last.findings, [
      { label: "Exact path", className: "name", render: row => { const code = document.createElement("code"); code.append(visiblePathNode(row.path)); code.title = row.path; return code; } },
      { label: "Why", render: row => row.reason },
      { label: "", className: "row-actions", render: row => {
        const wrap = document.createDocumentFragment();
        if (!data.can_change) return wrap;
        const rename = document.createElement("button"); rename.className = "link"; rename.textContent = ZogographI18n.t("action.rename", {}, "Rename");
        rename.addEventListener("click", () => showPathHygieneRename(row)); wrap.appendChild(rename); return wrap;
      } },
    ]);
    if (last.truncated) parts.push(note("The scan found more names than this page retains. Rename these, then run another disk scan."));
  }
  body.replaceChildren(...parts);
}

function showPathHygieneRename(row) {
  const name = document.createElement("input"); name.id = "pathHygieneRenameName"; name.className = "wide-field"; name.value = String(row.path).split("/").pop().trim();
  const feedback = document.createElement("div"); feedback.className = "small";
  const rowField = fieldRow("New name", name, `Current: ${visiblePathName(row.path)}`);
  rowField.lastElementChild.appendChild(feedback);
  showFormDialog("Rename path", [rowField], async () => {
    const result = await post("path-hygiene-rename", { path: row.path, name: name.value });
    $("noteDialog").close(); renderPathHygiene({ enabled: true, last: result.last, can_change: true });
    notice(`Renamed to ${result.result.to}.`, true);
  }, "Rename");
  const button = $("noteForm").querySelector("button[type=submit]");
  const validate = () => {
    const value = name.value;
    let why = "";
    if (!value || value === "." || value === ".." || value.includes("/") || value.includes("\0")) why = "Enter one file or directory name, without a slash.";
    else if (/[\u0000-\u001f\u007f]/.test(value)) why = "Control characters are not allowed.";
    else if (/^\s|\s$/u.test(value)) why = "Names cannot start or end with whitespace.";
    else if (value.startsWith("-")) why = "Names cannot start with a dash.";
    else if (/[?*[\]{}~$&;|<>()`'"!\\\\]/.test(value)) why = "Names cannot contain shell or wildcard characters.";
    name.setCustomValidity(why);
    name.classList.toggle("field-invalid", Boolean(why));
    feedback.className = why ? "small error" : "small muted";
    feedback.textContent = why || "This name is safe to rename.";
    button.disabled = Boolean(why);
  };
  name.addEventListener("input", validate);
  validate();
  name.focus();
}

