/*
 * Four forms, one Save.
 *
 * They are one set of settings split across four pages, so submitting any of
 * them saves all of it - which is why every page's button says so. The
 * alternative is somebody typing a name on Identity, going to Thresholds to
 * change a limit, and losing the name.
 */
for (const id of ["aiIdentityForm", "aiProvidersForm", "aiModelForm", "aiLimitsForm", "aiImagesForm",
                  "aiToolsForm"]) {
  const form = $(id);
  if (!form) continue;
  form.addEventListener("submit", event => {
    event.preventDefault();
    saveAiSettings();
  });
}

document.addEventListener("click", async event => {
  if (event.target?.id !== "aiTest") return;

  const button = $("aiTest");
  const said = $("aiTestResult");

  button.disabled = true;
  button.textContent = ZogographI18n.t("action.testing", {}, "Testing…");
  said.className = "muted small";
  said.textContent = "";

  try {
    const result = await post("ai-test", {
      provider: $("aiProvider").value,
      model: $("aiModel").value.trim(),
      base_url: $("aiBase").value.trim(),
      api_key: $("aiKey").value,
      reasoning_effort: $("aiEffort").value,
    });

    if (result.ok) {
      said.className = "band-ok small";
      said.textContent = `It answered \u201c${result.said}\u201d in ${result.ms} ms`
        + ` and accepted the tools. ${humanCount(result.tokens.in + result.tokens.out)} tokens`
        + (result.tokens.reasoning
          ? `, ${humanCount(result.tokens.reasoning)} of them thinking` : "")
        + `, about ${result.cost}.`;
    } else {
      said.className = "band-crit small";
      said.textContent = `${result.error}${result.hint ? " — " + result.hint : ""}`;
    }
  } catch (error) {
    said.className = "band-crit small";
    said.textContent = String(error.message || error);
  } finally {
    button.disabled = false;
    button.textContent = ZogographI18n.t("action.test_connection", {}, "Test the connection");
  }
});

