$("shareLink").addEventListener("click", async () => {
  /*
   * A link to exactly this, frozen at this moment.
   *
   * Without the timestamp the recipient opens the same view over the last day
   * *from when they clicked*, which is a different chart. Pinning it is the
   * difference between "look at this" and "look at roughly this".
   */
  state.frozenAt = state.frozenAt || Math.floor(Date.now() / 1000);
  writeRoute(true);

  try {
    await navigator.clipboard.writeText(location.href);
    notice("Link copied. It opens this view over this exact window.", true);
  } catch {
    notice(location.href);
  }
});

// The Live button starts disabled unless the page opens on the short range,
// so it can never be lit while nothing is being sampled.
syncLiveAvailability();
installChatDrag();

applyRoute();
writeRoute(true);
buildState.current = buildStorageGet(BUILD_IDENTITY_STORAGE_KEY);
const rememberedUpdate = rememberedBuildUpdate();
if (rememberedUpdate && buildIdentity(rememberedUpdate) !== buildState.current) {
  buildState.announced = buildIdentity(rememberedUpdate);
  buildState.update = rememberedUpdate;
  showBuildUpdate(rememberedUpdate);
}
schedule();
checkForBuildUpdate();
setInterval(checkForBuildUpdate, BUILD_POLL_MS);

/*
 * The dials advance themselves from here on.
 *
 * Started once, after the first route is applied, because there is nothing to
 * advance until something has been drawn.
 */
startDialTicker();
